window.__HRC_SHARD({"shard":"ffm-libya-2020","builtAt":"2026-09-03T11:43:29+00:00","documents":[{"rec_id":"recTrqnHHIhQpxntk","doc_id":"FFM Libya (2020) - Official report - 29.11.2021","symbol":"A/HRC/48/83","title":"Report of the Independent Fact-Finding Mission on Libya","type":"Official report","date":"2021-11-29","year":2021,"bodies":["FFM Libya (2020)"],"paragraphCount":144,"unnumbered":false,"gaps":[],"misprints":[],"source_md":"HUMAN RIGHTS COUNCIL MECHANISMS/2. Official Reports/FFM Libya (2020) - 29-11-2021 - Official report - A_HRC_48_83 - EN.md","extractor":"pdftotext -layout"},{"rec_id":"recaC5gtNvtAQyAXk","doc_id":"FFM Libya (2020) - Official report - 27.06.2022","symbol":"A/HRC/50/63","title":"Report of the Independent Fact-Finding Mission on Libya","type":"Official report","date":"2022-06-27","year":2022,"bodies":["FFM Libya (2020)"],"paragraphCount":114,"unnumbered":false,"gaps":[],"misprints":[],"source_md":"HUMAN RIGHTS COUNCIL MECHANISMS/2. Official Reports/FFM Libya (2020) - 27-06-2022 - Official report - A_HRC_50_63 - EN.md","extractor":"pdftotext -layout"},{"rec_id":"rec29IKNRtUDecvC8","doc_id":"FFM Libya (2020) - Unofficial Annex - 01.07.2022","symbol":"A/HRC/50/CRP.3","title":"Detailed findings on the situation in Tarhuna","type":"Unofficial Annex","date":"2022-07-01","year":2022,"bodies":["FFM Libya (2020)"],"paragraphCount":264,"unnumbered":false,"gaps":[],"misprints":[],"source_md":"HUMAN RIGHTS COUNCIL MECHANISMS/3. Annexes, CRPs and other materials/FFM Libya (2020) - 01-07-2022 - CRP - A_HRC_50_CRP.3 - EN.md","extractor":"pdftotext -layout"},{"rec_id":"recVilmxHdPgkesVQ","doc_id":"FFM Libya (2020) - Official report - 18.08.2022","symbol":"A/HRC/49/4","title":"Report of the Independent Fact-Finding Mission on Libya","type":"Official report","date":"2022-08-18","year":2022,"bodies":["FFM Libya (2020)"],"paragraphCount":98,"unnumbered":false,"gaps":[],"misprints":[],"source_md":"HUMAN RIGHTS COUNCIL MECHANISMS/2. Official Reports/FFM Libya (2020) - 18-08-2022 - Official document - A_HRC_49_4 - EN.md","extractor":"pdftotext -layout"},{"rec_id":"recsvi26SYPBMJd3q","doc_id":"FFM Libya (2020) - Official report - 03.03.2023","symbol":"A/HRC/52/83","title":"Report of the Independent Fact-Finding Mission on Libya","type":"Official report","date":"2023-03-03","year":2023,"bodies":["FFM Libya (2020)"],"paragraphCount":104,"unnumbered":false,"gaps":[],"misprints":[],"source_md":"HUMAN RIGHTS COUNCIL MECHANISMS/2. Official Reports/FFM Libya (2020) - 03-03-2023 - Official report - A_HRC_52_83 - EN.md","extractor":"pdftotext -layout"},{"rec_id":"recjWsYJzrxQZhNld","doc_id":"FFM Libya (2020) - Unofficial Annex - 24.03.2023","symbol":"A/HRC/52/CRP.8","title":"Detailed findings of the Independent Fact-Finding Mission on Libya","type":"Unofficial Annex","date":"2023-03-24","year":2023,"bodies":["FFM Libya (2020)"],"paragraphCount":277,"unnumbered":false,"gaps":[],"misprints":[{"n":238,"printed":"228"}],"source_md":"HUMAN RIGHTS COUNCIL MECHANISMS/2. Official Reports/FFM Libya (2020) - 24-03-2023 - Official report - A_HRC_52_CRP.8 - EN.md","extractor":"pdftotext -layout"}],"paragraphs":[{"id":"a-hrc-48-83-u0000","rec_id":"recTrqnHHIhQpxntk","symbol":"A/HRC/48/83","n":null,"seq":0,"section":null,"text":"* The present report was submitted after the deadline so as to reflect the most recent developments.\n** The annexes to the present report are circulated as received, in the language of submission only.","unnumbered":true},{"id":"a-hrc-48-83-p0001","rec_id":"recTrqnHHIhQpxntk","symbol":"A/HRC/48/83","n":"1","seq":1,"section":"I. Introduction","text":"Since the fall of the Gaddafi regime in 2011, the fragmentation of the State and the\nproliferation of weapons and of militias vying for control of territory and resources has\nseverely undermined the rule of law in Libya. Libya has also been the theatre of near-\nuninterrupted armed conflicts. State and non-State actors alike, from Libya and abroad, are\nalleged to have taken advantage of this context to perpetrate violations and abuses of\ninternational human rights law and international humanitarian law against the most\nvulnerable, including women, children, members of ethnic minorities, migrants, asylum\nseekers and internally displaced persons. The violence has also had a dramatic impact on the\nLibyan economic fabric as well as on civic space, particularly for women. With the recent\ninstallation of the Government of National Unity, Libya has entered a phase of national\ndialogue and unification of State institutions. Nevertheless, the situation of human rights\nremains alarming and the process of holding accountable perpetrators of violations and\nabuses faces significant challenges."},{"id":"a-hrc-48-83-p0002","rec_id":"recTrqnHHIhQpxntk","symbol":"A/HRC/48/83","n":"2","seq":2,"section":"I. Introduction","text":"The situation in Libya since 2011 has been the subject of investigations by two\nmechanisms mandated by the Human Rights Council.1 On 22 June 2020, at the request of the\nGovernment of Libya, the Council adopted resolution 43/39 requesting the United Nations\nHigh Commissioner for Human Rights to establish and dispatch a fact-finding mission to\nLibya. On 22 August 2020, the High Commissioner announced the appointment of Mohamed\nAuajjar, of Morocco, Tracy Robinson, of Jamaica, and Chaloka Beyani, of Zambia and the\nUnited Kingdom of Great Britain and Northern Ireland, as the members of the Independent\nFact-Finding Mission on Libya, hereinafter referred to as the Mission, with Mr. Auajjar as\nChair."},{"id":"a-hrc-48-83-p0003","rec_id":"recTrqnHHIhQpxntk","symbol":"A/HRC/48/83","n":"3","seq":3,"section":"I. Introduction","text":"The Mission was mandated to establish, in an independent and impartial manner, the\nfacts and circumstances of the human rights situation throughout Libya, to document alleged\nviolations and abuses of international human rights law and international humanitarian law\nby all parties in Libya since the beginning of 2016, including any gendered dimensions, and\nto preserve evidence with a view to ensuring that perpetrators of violations and abuses are\nheld accountable. The Mission was initially established for a period of one year and was\nrequested to present a comprehensive written report to the Human Rights Council at its forty-\nsixth session. The Council subsequently decided to postpone the presentation of the report\nuntil its forty-eighth session to account for the persistent impossibility of recruiting the\nsecretariat to support the work of the Mission. Despite the postponement of the report\ndeadline, it was only in June 2021 that the secretariat became fully operational."},{"id":"a-hrc-48-83-p0004","rec_id":"recTrqnHHIhQpxntk","symbol":"A/HRC/48/83","n":"4","seq":4,"section":"I. Introduction","text":"At this juncture, the Mission finds itself unable to submit a comprehensive report on\nthe human rights situation since 2016. A full determination on the violations and abuses\ncommitted throughout Libya over almost the past six years, including the identification of\npotential perpetrators, requires significantly more time. Nevertheless, since it was established,\nthe Mission has gathered hundreds of documents, interviewed more than 150 individuals, and\nconducted investigations in Libya, Tunisia and Italy. The present report summarizes the\nfindings which the Mission was able to reach on the basis of the information gathered, within\nthe word limit for reports submitted to the Human Rights Council."},{"id":"a-hrc-48-83-p0005","rec_id":"recTrqnHHIhQpxntk","symbol":"A/HRC/48/83","n":"5","seq":5,"section":"I. Introduction","text":"As Libya is making progress towards peace, a fully-fledged fact-finding exercise is\nmore than ever necessary. Past experience has shown that in post-conflict contexts, a\ncomprehensive human rights investigation is an effective tool to foster accountability, deter\nfurther violations and promote long-term peace and security. The Mission therefore\nrecommends the Human Rights Council to consider extending its mandate for a period of\ntime commensurate with the mandate’s breadth."},{"id":"a-hrc-48-83-p0006","rec_id":"recTrqnHHIhQpxntk","symbol":"A/HRC/48/83","n":"6","seq":6,"section":"1. Political situation","text":"In the first months of 2016, the parties to the Libyan Political Agreement worked\ntowards the establishment of the Government of National Accord, which the Security Council\nhad decided it would support as the sole legitimate government of Libya. However, the\nTobruk-based House of Representatives, with which the Libyan National Army and affiliated\narmed groups ostensibly aligned themselves, never agreed to the composition of the\nGovernment of National Accord. As a result of this political deadlock, the following years\nwere characterized by parallel institutions exercising control over different parts of the\ncountry."},{"id":"a-hrc-48-83-p0007","rec_id":"recTrqnHHIhQpxntk","symbol":"A/HRC/48/83","n":"7","seq":7,"section":"1. Political situation","text":"In January 2020, an international conference was held in Berlin, Germany, following\nwhich senior military officers from both the Government of National Accord and the Libyan\nNational Army engaged in United Nations-facilitated discussions within the framework of\nthe 5+5 Joint Military Commission. The discussions led to the conclusion of a ceasefire in\nOctober 2020. On the political front, a forum gathering representatives from all sides of the\nLibyan political spectrum adopted in November 2020 a road map providing for the\nestablishment of a government of national unity and the holding of presidential and\nparliamentary elections in December 2021. In March 2021, the Government of National\nUnity was installed following a vote of the House of Representatives. At the time of\nsubmission of the present report, laws for parliamentary and presidential elections were being\nprepared."},{"id":"a-hrc-48-83-p0008","rec_id":"recTrqnHHIhQpxntk","symbol":"A/HRC/48/83","n":"8","seq":8,"section":"2. Cooperation of the Libyan authorities","text":"In its resolution 43/39, the Human Rights Council urged the Libyan authorities to\ngrant the Mission unhindered access to all Libyan territory without delay and to allow it to\nvisit sites, and to meet and speak freely and privately, when it so requested, with whomever\nit wished to meet or speak with."},{"id":"a-hrc-48-83-p0009","rec_id":"recTrqnHHIhQpxntk","symbol":"A/HRC/48/83","n":"9","seq":9,"section":"2. Cooperation of the Libyan authorities","text":"With the cooperation of the Libyan authorities, the Mission was able to travel to Libya,\nheld discussions with Libyan authorities, and visited sites. Yet, significant delays were\nexperienced in obtaining the required visas, which interfered with planning and delayed the\narrival of the Mission. During a meeting held in Tripoli in August 2021, the Minister of\nForeign Affairs assured the Mission that the issuance of visas would be facilitated in the\nfuture. Special authorization procedures applicable to international organizations working in\nLibya impeded the Mission’s interactions with the authorities and also interfered with the\nMission’s site visits. Also, some requests to visit sites, in particular prisons and detention\ncentres for migrants, remained unanswered."},{"id":"a-hrc-48-83-p0010","rec_id":"recTrqnHHIhQpxntk","symbol":"A/HRC/48/83","n":"10","seq":10,"section":"2. Cooperation of the Libyan authorities","text":"Furthermore, several Libyan-based non-governmental organizations (NGOs) were\nreluctant to interact with the Mission in view of the Presidential Council’s decree of 2019\nregulating the work of NGOs in Libya. They felt that notifying governmental authorities\nabout their intent to meet with the Mission would expose them to retaliation. Consistent with\nthe investigative principle of “do no harm”, the Mission decided not to engage with NGOs\nbased in Libya."},{"id":"a-hrc-48-83-p0011","rec_id":"recTrqnHHIhQpxntk","symbol":"A/HRC/48/83","n":"11","seq":11,"section":"2. Cooperation of the Libyan authorities","text":"The recent installation of the Government of National Unity may, at least in part,\nexplain the delays and other difficulties faced by the Mission in Libya. Should the Mission’s\nmandate be extended, it is of paramount importance that the investigations be appropriately\nfacilitated by the Libyan authorities, including by granting access to all places and persons\nof interest. In particular, the Mission calls on Libyan authorities to ensure that anyone in\nLibya is free to approach the Mission, including NGOs. In this regard, the Mission invites\nLibya to review the decree regulating the work of NGOs in Libya."},{"id":"a-hrc-48-83-p0012","rec_id":"recTrqnHHIhQpxntk","symbol":"A/HRC/48/83","n":"12","seq":12,"section":"3. Challenges","text":"The Mission benefited from less time and resources than initially projected, which\ncurtailed its ability to conduct a comprehensive investigation. The secretariat supporting the\nwork of the Mission only became fully operational in June 2021, that is, three months before\nthe deadline for the submission of the present report. The delay was mainly due to the United\nNations regular budget liquidity crisis and the concomitant suspension of recruitment. The\ndeployment of the secretariat to Tunis was also temporarily delayed due to the prevailing\nCOVID-19 situation in Tunisia."},{"id":"a-hrc-48-83-p0013","rec_id":"recTrqnHHIhQpxntk","symbol":"A/HRC/48/83","n":"13","seq":13,"section":"3. Challenges","text":"The Mission was also confronted with difficulties in the gathering of information. The\ninvestigations took place in a fast-changing environment, with incidents falling within the\nMission’s mandate occurring as recently as September 2021. The current Libyan context was\nnot conducive to witnesses freely sharing information. Indeed, even when a secure channel\nof communication existed, several individuals declined to engage with the Mission on\naccount of fears of reprisals by State agents or militias. Furthermore, several victims\npreferred not to be interviewed to avoid reliving their trauma. In Libya, the security measures\naccompanying the Mission’s movements increased the investigators’ visibility on the ground\nand discouraged some witnesses from coming forward. For security reasons, the Mission was\nalso unable to visit the south of Libya."},{"id":"a-hrc-48-83-p0014","rec_id":"recTrqnHHIhQpxntk","symbol":"A/HRC/48/83","n":"14","seq":14,"section":"A. Scope of investigations","text":"As it was vested with a broad and general mandate (see annex I), the Mission was\nbound to circumscribe the scope of its investigations to the areas entailing the most serious\nviolations and abuses. The Mission identified the following areas of investigation (see below):\nconduct of hostilities; extrajudicial killings; violations in the context of deprivation of liberty;\nsexual and gender-based violence; and the respective situations of internally displaced\npersons, migrants, refugees and asylum seekers, women, and children. The allegations of\natrocity crimes committed in the town of Tarhuna warranted a particular focus."},{"id":"a-hrc-48-83-p0015","rec_id":"recTrqnHHIhQpxntk","symbol":"A/HRC/48/83","n":"15","seq":15,"section":"A. Scope of investigations","text":"The Mission documented certain trends and patterns and gathered information in\nrelation to some incidents within each of the above categories. The Mission prioritized for\ninvestigation those incidents which appeared the most serious and/or the most representative\nof broader patterns of violations and abuses. Mindful of the fact that the situation has been\nunder the scrutiny of other reporting or accountability mechanisms, the Mission also focused\non incidents which have not been the object of prior public reporting or which the Mission\ncould examine from a different legal perspective. In view of the evidentiary challenges\nrelated to passage of time, the report concentrates on more recent events."},{"id":"a-hrc-48-83-p0016","rec_id":"recTrqnHHIhQpxntk","symbol":"A/HRC/48/83","n":"16","seq":16,"section":"A. Scope of investigations","text":"The Mission’s findings are not exhaustive; they provide a basis that further\ninvestigations can build on with a view to comprehensively addressing the human rights\nsituation since 2016. The Mission considered that future investigations should substantiate\nthe overarching impact of the violations and abuses on, inter alia, the victims’ civil and\npolitical rights as well as on their economic, social and cultural rights."},{"id":"a-hrc-48-83-p0017","rec_id":"recTrqnHHIhQpxntk","symbol":"A/HRC/48/83","n":"17","seq":17,"section":"B. Methodology","text":"In keeping with resolution 43/39, in which the Human Rights Council requested the\nMission to conduct its investigations in an independent and impartial manner, the Mission\nestablished its own investigative priorities. It did not seek approval or instructions from any\nexternal stakeholders at any stage of its work. The investigations also focused on all actors\ninvolved – domestic and foreign – without distinction."},{"id":"a-hrc-48-83-p0018","rec_id":"recTrqnHHIhQpxntk","symbol":"A/HRC/48/83","n":"18","seq":18,"section":"B. Methodology","text":"Consistent with the approach taken by human rights investigations, the findings\ncontained in the present report meet the “reasonable grounds to believe” evidentiary standard.\nThe Mission found that an incident or a pattern of conduct had taken place whenever it\nobtained a reliable body of information, corroborated by at least one other independent source,\nwhich could lead a reasonable and ordinarily prudent person to believe that the incident or\npattern had occurred. The nature of certain violations is such that the Mission could only rely\non first-hand accounts of victims."},{"id":"a-hrc-48-83-p0019","rec_id":"recTrqnHHIhQpxntk","symbol":"A/HRC/48/83","n":"19","seq":19,"section":"B. Methodology","text":"While the aforementioned evidentiary standard did not require findings to be made to\nthe exclusion of other reasonable inferences, the Mission considered that the establishment\nof facts in a post-conflict context had to benefit, to the extent possible, from the perspectives\nof all parties to the conflict. The Mission began engaging with all sides, and the findings set\nout in the present report are made without prejudice to the receipt of further information."},{"id":"a-hrc-48-83-p0020","rec_id":"recTrqnHHIhQpxntk","symbol":"A/HRC/48/83","n":"20","seq":20,"section":"B. Methodology","text":"While the “reasonable grounds to believe” standard established a minimum\nevidentiary threshold, there were circumstances where a higher level of certainty was\nwarranted, in particular when a finding entailed a legal qualification that carried with it a\nhigher degree of stigma due to its gravity, such as crimes against humanity and torture. In\nrelation to such findings, the Mission exceeded the minimum evidentiary threshold."},{"id":"a-hrc-48-83-p0021","rec_id":"recTrqnHHIhQpxntk","symbol":"A/HRC/48/83","n":"21","seq":21,"section":"B. Methodology","text":"The Mission considered information from a variety of sources – which included\ninterviews with victims and other witnesses; summaries of accounts and analytical data\nincluded in reports of the United Nations and other reliable NGOs and media; investigators’\ndirect observations during site visits; domestic Libyan laws; information provided by the\nLibyan authorities, other States and reliable stakeholders working on Libya; authenticated\nsatellite imagery and audiovisual material; and verified open-source material. Further to a\ncall for submissions issued on 25 January 2021, civil society organizations and lawyers\nrepresenting victims filed with the Mission information relevant to the areas under\ninvestigation."},{"id":"a-hrc-48-83-p0022","rec_id":"recTrqnHHIhQpxntk","symbol":"A/HRC/48/83","n":"22","seq":22,"section":"B. Methodology","text":"The security situation did not provide for a safe space to hold in-person meetings with\nvictims and witnesses. The Mission therefore conducted interviews using other means of\ncommunication through secure channels. In certain cases, the Mission covered expenses\nincurred for the travel to a safe location outside Libya, clarifying to the interviewee that the\npayment was not a compensation for testimony."},{"id":"a-hrc-48-83-p0023","rec_id":"recTrqnHHIhQpxntk","symbol":"A/HRC/48/83","n":"23","seq":23,"section":"B. Methodology","text":"The Mission made its own assessment of the credibility and reliability of sources,\neven when they were introduced by reliable intermediaries. All sources relied upon in the\npresent report were deemed to be credible and reliable. The Mission sought from each person\nor entity it met their informed consent to use the information in the report and/or share it with\nexternal stakeholders for accountability or assistance purposes. The report does not disclose\nthe identity of the individuals interviewed by the Mission, except where consent was provided."},{"id":"a-hrc-48-83-p0024","rec_id":"recTrqnHHIhQpxntk","symbol":"A/HRC/48/83","n":"24","seq":24,"section":"B. Methodology","text":"The Mission paid the utmost attention to the safety and well-being of the individuals\nwith whom it interacted. In accordance with the well-established investigative principle of\n“do no harm”, the Mission ensured that their collaboration with the Mission did not put them\nin danger or retraumatize them. Where appropriate, the Mission directed victims and\nwitnesses to existing protection and assistance programmes."},{"id":"a-hrc-48-83-p0025","rec_id":"recTrqnHHIhQpxntk","symbol":"A/HRC/48/83","n":"25","seq":25,"section":"B. Methodology","text":"In keeping with the Mission’s mandate to preserve evidence for accountability\npurposes, the Secretariat kept a safe record of all the materials it gathered and developed a\nrecord-management system to streamline future investigations."},{"id":"a-hrc-48-83-p0026","rec_id":"recTrqnHHIhQpxntk","symbol":"A/HRC/48/83","n":"26","seq":26,"section":"A. Conduct of hostilities","text":"The period covered by the Mission’s mandate witnessed several armed confrontations\nthat reached a sustained level of intensity and involved organized armed groups as well as\nState armed forces. The hostilities have been widely documented and there is little doubt that\nthese confrontations amounted to non-international armed conflicts. The investigations\nindicated that the involvement of foreign States in the non-international armed conflicts was\nsuch that they were considered parties thereto. The involvement of a foreign State in a non-\ninternational armed conflict in support of a party to the conflict, rather than against the State,\ndoes not change the classification of the conflict. The investigations indicated that several\nparties to the conflicts violated international humanitarian law and potentially committed war\ncrimes. The present section sets out the findings that the Mission reached, with a particular\nfocus on: (a) the hostilities in Tripoli in 2019 and 2020; (b) the siege of Ganfouda in eastern\nLibya in 2016 and 2017; and (c) the military operations in southern Libya in 2019. The factual\nconsiderations underpinning the findings are without prejudice to evidence that may be later\nshared by other stakeholders."},{"id":"a-hrc-48-83-p0027","rec_id":"recTrqnHHIhQpxntk","symbol":"A/HRC/48/83","n":"27","seq":27,"section":"1. Tripoli","text":"From April 2019 to June 2020, the Government of National Accord and the Libyan\nNational Army, as well as their respective affiliated armed groups, and with the support of\nforeign States, were engaged in an armed conflict in Tripoli and its surrounds. The findings\nbelow provide only a limited insight into these hostilities and further investigations are\nrequired to examine other alleged violations."},{"id":"a-hrc-48-83-p0028","rec_id":"recTrqnHHIhQpxntk","symbol":"A/HRC/48/83","n":"28","seq":28,"section":"1. Tripoli","text":"Health-related facilities and objects. At least 47 health-related facilities and objects\nwere damaged during this period,3 with an immediate impact on health care (including access\nfor women to specialized services), and there are reasonable grounds to believe that the\nfollowing attacks amounted to violations of international humanitarian law 4 and war crimes.5\nThe evidence established that in May 2019, in Twaisha, near Tripoli, a weapon struck an\nambulance marked with the Red Crescent emblem on its door and seriously injured the driver.\nThe ambulance was transporting health personnel and was not engaged in a hostile purpose.\nThe investigations also established that in April 2020, Al-Khadra General Hospital, which\nwas Tripoli’s main centre for COVID-19 patients, was hit three times in airstrikes. The\nhospital was functioning as such prior to the attacks and it was not used to commit hostile\nacts. Further investigations are required in order to establish the responsibility for these\nattacks and for other similar attacks."},{"id":"a-hrc-48-83-p0029","rec_id":"recTrqnHHIhQpxntk","symbol":"A/HRC/48/83","n":"29","seq":29,"section":"1. Tripoli","text":"Schools. Schools were also subject to extensive damage and destruction. The Mission\ninvestigated the damage to three schools (Bab Ben Ghashir, Alkhalidoon and Attalieaa) as\nwell as the destruction of a warehouse storing millions of textbooks in April 2019. The\ninformation gathered did not allow the Mission to reach findings on whether the incidents\nconstituted violations of international humanitarian law. Additional investigations should be\nconducted into this specific aspect of the hostilities, noting that attacks against education-\nrelated facilities impact on children’s right to education."},{"id":"a-hrc-48-83-p0030","rec_id":"recTrqnHHIhQpxntk","symbol":"A/HRC/48/83","n":"30","seq":30,"section":"1. Tripoli","text":"Hadaba Military Academy. On the evening of 4 January 2020, a group of students\nwho had gathered in the courtyard of Hadaba Military Academy were hit by a missile, killing\n25 students6 and injuring at least 20, including 12 seriously. Some reports attributed the attack\nto the Libyan National Army."},{"id":"a-hrc-48-83-p0031","rec_id":"recTrqnHHIhQpxntk","symbol":"A/HRC/48/83","n":"31","seq":31,"section":"1. Tripoli","text":"A corollary of the absence of combatant status in non-international armed conflicts is\nthat no one may be attacked unless they are directly participating in hostilities. Although the\nrecruitment and training of personnel is crucial to the military capacity of a party to the\nconflict, the causal link with the harm inflicted on the adversary will generally remain indirect.\nOnly where persons are specifically recruited and trained for the execution of a\npredetermined hostile act can such activities be regarded as direct participation in hostilities.\nThe evidence indicated that the students were undergoing general training as per the usual\ncurriculum and the Mission received no evidence that they were undergoing preparations for\na specific hostile act."},{"id":"a-hrc-48-83-p0032","rec_id":"recTrqnHHIhQpxntk","symbol":"A/HRC/48/83","n":"32","seq":32,"section":"1. Tripoli","text":"All feasible precautions must be taken in determining whether a person is a civilian\nand, if so, whether that civilian is directly participating in hostilities. In case of doubt, the\nperson must be presumed to be protected against direct attack. In the current case, given that\nthe students were undergoing a drill in the courtyard without weapons, as is characteristic of\nfirst-year students, there were sufficient indicators that would give rise to doubt as to whether\nthey were training for a specific act. Their status and function as first-year students also\nindicate that they were not engaged in a continuous combat function. No evidence was found\nindicating that the building was used for other military purposes."},{"id":"a-hrc-48-83-p0033","rec_id":"recTrqnHHIhQpxntk","symbol":"A/HRC/48/83","n":"33","seq":33,"section":"1. Tripoli","text":"In light of the foregoing, there are reasonable grounds to believe that the attack may\nhave constituted a serious violation of international humanitarian law 7 and a war crime.8\nFurther investigations are necessary in order to ascertain the exact roles played by the Libyan\nNational Army and any other State in the attack."},{"id":"a-hrc-48-83-p0034","rec_id":"recTrqnHHIhQpxntk","symbol":"A/HRC/48/83","n":"34","seq":34,"section":"1. Tripoli","text":"Qasr Bin Ghashir. On 3 June 2020, four consecutive drone strikes killed at least 12\npeople in the town of Qasr Bin Ghashir, south of Tripoli. Reports alleged that the attack could\nbe attributed to the Government of National Accord."},{"id":"a-hrc-48-83-p0035","rec_id":"recTrqnHHIhQpxntk","symbol":"A/HRC/48/83","n":"35","seq":35,"section":"1. Tripoli","text":"The investigations established that those attacked were unarmed and included women\nand children. The weapons used were precise and were launched by a human-commanded\nunmanned aerial vehicle. The strikes were consecutive, they were aimed at the same group\nof unarmed people gathered in one location and they took place as the Libyan National Army\nwas retreating from the area. The Mission inferred from this that the attacks were\nintentionally directed against individual civilians not taking direct part in hostilities, thereby\npotentially amounting to a violation of international humanitarian law 9 and a war crime.10\nThere are also reasonable grounds to believe that the attack could be attributed to the\nGovernment of National Accord, given that: (a) a few days before the attack, the Government\nof National Accord had alerted civilians to leave the area of Qasr Bin Ghashir as shelling\nwould take place; and (b) the weapons and the unmanned aerial vehicle from which they\nwere launched had previously been used by the Government of National Accord in the same\narea. While the alert complied with the international humanitarian law obligation to give\nadvance warning 11 and may be regarded as a measure to minimize civilian losses, the\nprohibition against attacking civilians remained applicable even if civilians stayed behind\nafter the warning was issued. There are reports that: (a) Turkey concluded with the\nGovernment of National Accord a memorandum of understanding on security and military\ncooperation; (b) the weapons and unmanned aerial vehicle used in the attack were\nmanufactured in Turkey; (c) the unmanned aerial vehicle used in the attack had previously\nbeen spotted in Libyan military airbases to which Turkey had access; and (d) the distance\nbetween these bases and Qasr Bin Ghashir falls within the unmanned aerial vehicle’s range.\nNevertheless, the exact role played by Turkey in this attack, if any, has yet to be ascertained."},{"id":"a-hrc-48-83-p0036","rec_id":"recTrqnHHIhQpxntk","symbol":"A/HRC/48/83","n":"36","seq":36,"section":"1. Tripoli","text":"Mercenaries. Another feature of the hostilities in Tripoli was the involvement of\nmercenaries12 supporting the parties to the conflict. As mercenaries are not outlawed per se\nin international humanitarian law, international human rights law or international criminal\nlaw, but only under treaty law or domestic law for some States (including Libya), the\ninvestigations were limited to documenting violations, abuses or crimes committed by\nmercenaries, private military companies and foreign fighters, in keeping with the Mission’s\nmandate."},{"id":"a-hrc-48-83-p0037","rec_id":"recTrqnHHIhQpxntk","symbol":"A/HRC/48/83","n":"37","seq":37,"section":"1. Tripoli","text":"The Mission found evidence that Syrian nationals took part in combat operations in\nsupport of the Government of National Accord. Syrian fighters interviewed by the Mission\nstated that they had been recruited by their superiors in the Free Syrian Army, that Turkish\nnationals had been actively involved in their deployment to Libya and that the incentive for\nthem to deploy to Libya had been monetary gain. Investigations have yet to establish whether\nthese Syrian mercenaries committed any violations."},{"id":"a-hrc-48-83-p0038","rec_id":"recTrqnHHIhQpxntk","symbol":"A/HRC/48/83","n":"38","seq":38,"section":"1. Tripoli","text":"A reliable body of information indicated that individuals associated with ChVK\nWagner, a Russian private military company, had been present in Libya as mercenaries in\nsupport of the Libyan National Army. BBC News reported that in September 2019, Wagner\npersonnel had killed persons not taking a direct part in hostilities, in southern Tripoli.13 The\nevidence gathered by the Mission confirmed that Wagner personnel had fired gunshots\ndirectly at the victims following their capture and detention. There are thus reasonable\ngrounds to believe that Wagner personnel may have committed the war crime of murder.14"},{"id":"a-hrc-48-83-p0039","rec_id":"recTrqnHHIhQpxntk","symbol":"A/HRC/48/83","n":"39","seq":39,"section":"1. Tripoli","text":"Reliable sources also reported that civilians who had returned to their homes in\nsouthern Tripoli after the end of the hostilities in June 2020 had been killed or maimed by\nanti-personnel mines and that civilian houses had sustained damage. The investigations\nestablished that hundreds of landmines, most of which had been manufactured in the Russian\nFederation, had been planted in April and May 2020 next to houses and other civilian\nbuildings, with no warnings or markings. The Mission confirmed that landmines and other\nunexploded ordnance had been found in the 35 locations marked on a tablet left behind by\nWagner in Ain Zara (fig. 1). The investigations also established that these locations had been\nunder the Libyan National Army’s control prior to the discovery of the mines and that\nWagner personnel had been present in the area at that time. The loss of life, injuries and\ndamage was therefore excessive, as there was no longer a military advantage associated with\nanti-personnel mines remaining in civilian areas following the cessation of hostilities. In\nthese circumstances, there are reasonable grounds to believe that Wagner personnel and the\nLibyan National Army may have violated the international humanitarian law principle of\nproportionality 15 as well as the customary international humanitarian law obligations to\nminimize the indiscriminate effects of landmines and to remove them at the end of active\nhostilities.16 By not engaging in mine clearance, Wagner personnel and the Libyan National\nArmy may have also violated the right to life.17\nFigure 1"},{"id":"a-hrc-48-83-p0040","rec_id":"recTrqnHHIhQpxntk","symbol":"A/HRC/48/83","n":"40","seq":40,"section":"2. Ganfouda","text":"From mid-2016 until March 2017, in the context of the non-international armed\nconflict between the Libyan National Army and a coalition of armed groups known as the\nBenghazi Revolutionaries Shura Council, the Libyan National Army and its affiliated armed\ngroups surrounded the area of Ganfouda, near Benghazi. There are allegations that during the\nso-called siege on Ganfouda, civilians were killed and injured by strikes, civilian\ninfrastructure was damaged, hundreds of civilians were trapped, without adequate access to\nwater, food and medicine, and humanitarian aid was denied. There are also reports that in\nMarch 2017, the Libyan National Army did not allow the evacuation of males aged between\n15 and 65. Attacks were launched against civilians fleeing Ganfouda, women were not\nallowed to wear the niqab to prevent men from escaping and some civilians were arbitrarily\ndetained. The limited time available did not allow the Mission to ascertain the exact\ncircumstances of all these incidents and additional investigations are required in order to\ncomprehensively document the siege of Ganfouda."},{"id":"a-hrc-48-83-p0041","rec_id":"recTrqnHHIhQpxntk","symbol":"A/HRC/48/83","n":"41","seq":41,"section":"2. Ganfouda","text":"The evidence established that in October 2016, in the area of Ganfouda, houses in\nwhich persons not taking a direct part in hostilities were living were struck by weapons\nlaunched by the Libyan National Army, resulting in injuries and deaths, including of women\nand children from different families. In view of the circumstances of the attacks, there are\nreasonable grounds to believe that the perpetrators were aware or should have been aware of\nthe civilian status of the persons attacked. In conducting the airstrikes that resulted in civilian\ndeaths and damage to civilian objects, the Libyan National Army may have violated the\ninternational humanitarian law principles of distinction, proportionality, and precautions in\nattack.18 The investigations also established that in March 2017, in the area of Ganfouda,\ncorpses were desecrated and mutilated by fighters associated with the Libyan National Army.\nThis conduct may amount to a violation of international humanitarian law19 and a war crime.20\nThe evidence established that the top leadership of the Libyan National Army directed forces\nunder their control to show “no mercy” and to never consider “bringing a prisoner here”. The\nMission considered that these orders and statements may amount to violations of\ninternational humanitarian law principles prohibiting denial of quarter21 as well as to a war\ncrime.22"},{"id":"a-hrc-48-83-p0042","rec_id":"recTrqnHHIhQpxntk","symbol":"A/HRC/48/83","n":"42","seq":42,"section":"3. Southern Libya","text":"Tensions between the Al-Ahali and Tebu communities have been ongoing in southern\nLibya since 2011 and culminated in confrontations in 2019 between armed groups from both\ncommunities in the context of the broader non-international armed conflict between the\nGovernment of National Accord and the Libyan National Army. The Mission gathered\ncredible indications that during this period, violations were committed against members of\nboth communities, including abductions and mass killings. However, the evidence did not\nallow the Mission to reach definitive findings on all allegations and further investigations are\nneeded in order to ascertain the exact circumstances of the incidents."},{"id":"a-hrc-48-83-p0043","rec_id":"recTrqnHHIhQpxntk","symbol":"A/HRC/48/83","n":"43","seq":43,"section":"3. Southern Libya","text":"The investigations established that airstrikes conducted in August 2019 on a primarily\nTebu residential area of Murzuq resulted in 42 civilian fatalities and a number of casualties.\nOne airstrike hit very close to a civilian wedding location and was followed shortly\nafterwards by a second airstrike after first responders had attended. The building targeted\nwas a government building in which more than 200 local dignitaries had gathered, none of\nwhom were armed or directly participating in hostilities at the time of the attack. Two other\nairstrikes hit another district. It should have been obvious to the attackers that the area\ntargeted was a civilian area and that striking a congregation of civilians at night was likely to\nresult in a disproportionately high number of civilian casualties compared to any military\nadvantage. The evidence provided reasonable grounds to believe that the strikes could be\nattributed to the Libyan National Army, noting that the exact role played by other actors\nremained to be ascertained. On the basis of the foregoing, the Mission considered that with\nregard to these airstrikes, the Libyan National Army may not have respected the international\nhumanitarian law principles of distinction and proportionality and may not have taken\nappropriate precautions.23"},{"id":"a-hrc-48-83-p0044","rec_id":"recTrqnHHIhQpxntk","symbol":"A/HRC/48/83","n":"44","seq":44,"section":"B. Extrajudicial killings","text":"As part of the prevailing violence in Libya, State agents or affiliates routinely use\nkillings non-compliant with the rule of law as a means of punishment or silencing. Such\nkillings are a violation of the right to life, but they may also have a pervasive impact on other\nrights, such as the right to truth. The Mission noted that recently, a number of extrajudicial\nkillings had targeted individuals suspected of involvement in serious human rights violations.\nIn particular, the Mission investigated the killing in July 2021 of a suspect of and witness to\natrocity crimes in Tarhuna, Mohammad al-Kani, who was shot during a raid on his residence\nin Benghazi by members of the Tarek Bin Ziad Brigade, a part of the Libyan National Army.\nThere are reports that the Brigade was acting pursuant to an arrest warrant. Although Mr. Al-\nKani appears to have been deliberately shot, investigations are ongoing into whether he was\nresisting arrest, or otherwise posed a threat to the perpetrators that would justify their use of\nlethal force. If evidence comes to light that the use of force was not justified, there may be\nreasonable grounds to find that the killing of Mr. Al-Kani was a case of extrajudicial killing.24\nIn any case, his killing, like others, deprives victims of violations of the opportunity to have\nthe truth established. The Mission noted with concern that such incidents were taking place\nas Libya was making progress towards reconciliation. In the limited time available, the\nMission faced challenges in the investigation of other extrajudicial killings. Further\ninvestigations are therefore warranted in order to comprehensively document the commission\nof extrajudicial killings since 2016."},{"id":"a-hrc-48-83-p0045","rec_id":"recTrqnHHIhQpxntk","symbol":"A/HRC/48/83","n":"45","seq":45,"section":"C. Violations in the context of deprivation of liberty","text":"Several reports have noted that many prisons in Libya are used by the State and/or\narmed groups to arbitrarily detain people considered to be a threat to their interests or views,\nand that violence is widely and systematically used against these people. The prisons\ninvestigated by the Mission in the limited time available included the following official and\nunofficial detention facilities: Mitiga and Ghniwa (in the Tripoli area), Al-Koweifya,\nGernada and Tarik Bin Ziyed (in the Benghazi area), and Seket (ex-Ministry of Defence) and\nAl-Jawyah (ex-Ministry of Justice) (in the Misrata area). In addition to having reviewed\nreports from reliable sources, the Mission interviewed 31 men and 1 woman who had been\ndetained at different times in these prisons, as well as 6 relatives of detained persons."},{"id":"a-hrc-48-83-p0046","rec_id":"recTrqnHHIhQpxntk","symbol":"A/HRC/48/83","n":"46","seq":46,"section":"C. Violations in the context of deprivation of liberty","text":"The evidence established that large numbers of people ended up in the above-listed\nprisons after having been abducted. Most of these prisoners have never been charged,\nconvicted or sentenced to imprisonment following a fair and public hearing. Many are\ndetained incommunicado, some in secret prisons that officially do not exist, sometimes for\nyears without any prospect of release. The families of prisoners are not informed of the fate\nof their family member. Torture is an established feature of the prison system. The conditions\nof detention are characterized by a lack of hygiene, of adequate food and of medical care, as\nwell as no separation between children and adults. The Mission documented several cases of\ndeaths through summary execution, torture, starvation, unsanitary conditions and denial of\nmedical care. Sexual violence is prevalent, particularly during interrogations, and takes\ndifferent forms, including rape, the threat of rape, or coercion into engaging in sexual abuse\nagainst other inmates. Women find themselves particularly vulnerable, and the evidence also\nindicated that men were not spared from sexual violence."},{"id":"a-hrc-48-83-p0047","rec_id":"recTrqnHHIhQpxntk","symbol":"A/HRC/48/83","n":"47","seq":47,"section":"C. Violations in the context of deprivation of liberty","text":"The investigations established that the inhumane acts referred to above are committed\nagainst anyone considered to be a threat to the leadership of the State or to the interests and\nideologies (including the religious or moral views) of militias. The victims are mostly\ncivilians. The acts that they suffer within the prisons are not random incidents that can be\ntraced back to individual guards or particular facilities. Rather, violence is systematically\nused against prisoners. Reliable reports indicate that thousands of inmates are held in the\nabove-listed prisons, and it can reasonably be inferred from the testimonies received by the\nMission that large numbers of prisoners are victims of violence. Based on the testimonies\ngathered by the Mission, as corroborated by reliable reports, there are reasonable grounds to\nbelieve that the prisons listed above and many others located across the country constitute a\ncore element of a systematic and widespread attack against anyone opposing the interests of\nthose running the prisons.\nAA\nFigure 2"},{"id":"a-hrc-48-83-p0048","rec_id":"recTrqnHHIhQpxntk","symbol":"A/HRC/48/83","n":"48","seq":48,"section":"C. Violations in the context of deprivation of liberty","text":"The Mission received information indicating that some of the above-mentioned\nprisons were controlled by the State via networks of militias. Some prisons appear to operate\nindependently and others cooperate within informal networks. Regardless of the level of\ncoordination between prisons, those managing them all implement within their walls a pattern\nof widespread and systematic use of violence. In addition to having participated directly in\nthe commission of inhumane acts, Libyan authorities have abstained from holding\nperpetrators accountable for their conduct. Libya conceals violations in these prisons and\nmany others from its population and the international community. It can reasonably be\ninferred from this deliberate failure to take action that the State acquiesces in the commission\nof torture in the prisons."},{"id":"a-hrc-48-83-p0049","rec_id":"recTrqnHHIhQpxntk","symbol":"A/HRC/48/83","n":"49","seq":49,"section":"C. Violations in the context of deprivation of liberty","text":"There are thus reasonable grounds to believe that acts of murder, 25 torture, 26\nimprisonment, 27 rape 28 and enforced disappearance 29 committed in the above-mentioned\nLibyan prisons are committed on such a scale, and with such a level of organization, that they\namount, in and of themselves, to a systematic and widespread attack against the civilian\npopulation. As such, these acts may amount to crimes against humanity. Further\ninvestigations are required in order to establish the responsibility for these crimes."},{"id":"a-hrc-48-83-p0050","rec_id":"recTrqnHHIhQpxntk","symbol":"A/HRC/48/83","n":"50","seq":50,"section":"C. Violations in the context of deprivation of liberty","text":"In addition to the above, the Mission documented the presence of prisoners who had\nbeen captured from the frontlines by the State army or armed groups. The evidence\nestablished that these conflict-related prisoners were subjected to torture and other ill-\ntreatment, sometimes on a daily basis, especially during the interrogation phase. Given that\nconflict-related prisoners no longer take direct part in hostilities, there are reasonable grounds\nto believe that the harm they suffered may amount to the war crimes of cruel treatment and\ntorture.30"},{"id":"a-hrc-48-83-p0051","rec_id":"recTrqnHHIhQpxntk","symbol":"A/HRC/48/83","n":"51","seq":51,"section":"D. Sexual and gender-based violence","text":"Gender-based violence is any form of violence directed towards, or disproportionately\naffecting, someone because of their gender or sex. The investigations looked into the entire\nspectrum of gender-based violence in Libya, noting that such violence was deeply rooted and\noften hidden. The present section is concerned with sexual violence as a prominent form of\ngender-based violence. Other forms of gender-based violence are addressed in section G\nbelow."},{"id":"a-hrc-48-83-p0052","rec_id":"recTrqnHHIhQpxntk","symbol":"A/HRC/48/83","n":"52","seq":52,"section":"D. Sexual and gender-based violence","text":"As detailed elsewhere in the present report, vulnerable populations, such as migrants,\nasylum seekers, refugees and prisoners, are particularly at risk of sexual violence. Beyond\nthe detention environment, there are credible indications that sexual violence is also used by\nState agents or members of militias as a subjugation or humiliation tool to silence those\nperceived to speak against their interests or appearing to challenge social norms or acceptable\ngender roles. Illustrative of this, the Mission received several reports that rights activists had\nbeen abducted and subsequently subjected to sexual violence to deter them from participating\nin public life. A certain idea of sexual and gender “normality” also appears to drive violence\ndirected against people who identify themselves with a different sexual orientation or gender\nidentity, as evidenced by cases of beatings and rape of LGBTQI people reported to the\nMission. The evidence indicated that sexual violence took different forms: in addition to rape,\nwomen or men may be forced to strip naked, engage in sexual acts with others or witness\nothers engaging in rape. Sexual violence is compounded by laws that criminalize rape as a\ncrime against honour, or same-sex relations."},{"id":"a-hrc-48-83-p0053","rec_id":"recTrqnHHIhQpxntk","symbol":"A/HRC/48/83","n":"53","seq":53,"section":"D. Sexual and gender-based violence","text":"Unveiling sexual violence in the Libyan context is a trying task. Libya is a patriarchal\nsociety, whose culture overlaps with deeply rooted ideas of masculinity, militarism and\nelements of religious conservatism. As a corollary, sexuality is taboo and sexual violence\ncarries with it social stigma. Perpetrators appear to abuse this to humiliate their victims.\nSurvivors of sexual violence are scared or ashamed – and sometimes both – to report their\ncase to the authorities or share their experience with others. Despite credible reports received\nby the Mission, the limited time available did not allow the Mission to reach definitive\nfindings on cases and patterns of sexual violence outside the context of detention. Further\ninvestigations are required in order to fully document sexual violence in Libya."},{"id":"a-hrc-48-83-p0054","rec_id":"recTrqnHHIhQpxntk","symbol":"A/HRC/48/83","n":"54","seq":54,"section":"E. Internally displaced persons","text":"The prevailing insecurity in Libya has led to the internal displacement of hundreds of\nthousands of people who have ended up in areas ill-equipped to accommodate large\npopulation movements.31 For the present report, the Mission considered the situation of the\nTawerghan community. Internal displacement also affects other communities, such as the\nTebu and the Al-Ahali in southern Libya. The Mission received accounts that between\nFebruary and August 2019, confrontations between the two latter communities had resulted\nin the displacement of the majority of inhabitants of Murzuq. An extension of the Mission’s\nmandate would allow investigations into these allegations and the addressing of internal\ndisplacement as a whole, following the report of the Special Rapporteur on the human rights\nof internally displaced persons.32"},{"id":"a-hrc-48-83-p0055","rec_id":"recTrqnHHIhQpxntk","symbol":"A/HRC/48/83","n":"55","seq":55,"section":"E. Internally displaced persons","text":"Reports indicate that by mid-2011, the entire population of Tawergha, around 40,000\npeople, had fled attacks directed against them by militias of Misrata. The people of Tawergha,\nwho belong to the ethnic group of the same name, were perceived to be pro-Gaddafi. The\nmajority of Tawergha sought refuge in informal settlements around Tripoli and Benghazi.\nFull return to Tawergha has not yet materialized, despite an agreement reached to that effect\nbetween the Tawerghan and Misratan communities."},{"id":"a-hrc-48-83-p0056","rec_id":"recTrqnHHIhQpxntk","symbol":"A/HRC/48/83","n":"56","seq":56,"section":"E. Internally displaced persons","text":"The evidence established that internally displaced Tawerghans faced dire living\nconditions in camps where they were hosted. They lack access to adequate medical care, food,\nwater and sanitation, and their children have limited schooling opportunities. The\ninvestigations also established that in the camps where they stay, Tawerghans are subject to\nacts of violence (including killings, beatings, death threats, abductions, arbitrary detention\nand destruction of property) and that conditions for their return to Tawergha have not been\nmet. Allegations of sexual violence and early marriages remain to be investigated. The\nMission inferred from the enduring nature of the Tawergha situation that the State tolerates,\nacquiesces in and fails to provide protection from violence and abuses in camps. The Mission\nnoted that the State had still not taken adequate measures to ensure the safe return of\nTawerghans to their homes and that Tawerghans were still awaiting compensation for the\ndestruction of their town. The Mission also found that the Tawerghans were persecuted, as\nthe acts of violence described above had been motivated by a discriminatory purpose, due to\nthe perceived association of Tawerghans with the Gaddafi regime as well as to the fact that\nthey were Black Libyans. In the light of the foregoing, there are reasonable grounds to believe\nthat Libya failed to guarantee the rights of internally displaced Tawerghans under\ninternational law.33"},{"id":"a-hrc-48-83-p0057","rec_id":"recTrqnHHIhQpxntk","symbol":"A/HRC/48/83","n":"57","seq":57,"section":"F. Migrants","text":"Libya has long been both a destination country and a departure point for those fleeing\nviolence or poverty. Reports indicate that the human rights situation of migrants, asylum\nseekers and refugees34 in Libya has deteriorated since 2016. The evidence gathered by the\nMission, which included interviews with 50 migrants, established that from the moment that\nmigrants entered Libya destined for Europe, they were systematically subjected to a litany of\nabuses. However, in view of the time and resource constraints, the Mission focused on\nviolations and abuses committed in Libya. The present report documents, in particular, the\npattern of interceptions by the Libyan Coast Guard to ensure that disembarkation takes place\nin Libya, and the associated pattern of detaining migrants in detention centres run by the\nDepartment for Combating Illegal Migration (fig. 3), where they face intolerable conditions\ncalculated to cause suffering and the desire to utilize any means of escape, including by\npaying large sums of money to militias, criminal gangs, traffickers and smugglers who have\nlinks to the State and profit from this practice."},{"id":"a-hrc-48-83-p0058","rec_id":"recTrqnHHIhQpxntk","symbol":"A/HRC/48/83","n":"58","seq":58,"section":"F. Migrants","text":"Libyan law criminalizes irregular entry, stay and exit. The investigations established\nthat a migrant’s journey to Europe would normally start with the migrant paying money to a\nsmuggler, and subsequently boarding a boat. The Libyan Coast Guard would later proceed\nwith an interception that was violent or reckless, resulting at times in deaths. There are reports\nthat, on board, the Libyan Coast Guard confiscates belongings from migrants. Once\ndisembarked, migrants are either transferred to detention centres or go missing, 35 with reports\nthat people are sold to traffickers. Interviews with migrants formerly held in detention centres\nof the Department for Combating Illegal Migration established that all migrants – men and\nwomen, boys and girls – were kept in harsh conditions, some of whom die. Some children\nare held with adults, placing the children at high risk of abuse. Torture (such as electric shocks)\nand sexual violence (including rape and forced prostitution) are prevalent. Although the\ndetention of migrants is founded in Libyan domestic law, migrants are detained for indefinite\nperiods without an opportunity to have the legality of their detention reviewed, and the only\npracticable means of escape is by paying large sums of money to the guards or engaging in\nforced labour or sexual favours inside or outside the detention centre for the benefit of private\nindividuals. Several interviewees recounted that they had endured the same cycle of violence,\nin some cases up to 10 times, of paying guards to secure their release, taking part in an attempt\nat crossing the sea, being intercepted and subsequently being returned to detention in harsh\nand violent conditions, all while under the absolute control of the authorities, militias and/or\ncriminal networks. There is also evidence that most of the migrants detained are sub-Saharan\nAfricans and that they are treated in a harsher manner than other nationalities, which suggests\ndiscriminatory treatment."},{"id":"a-hrc-48-83-p0059","rec_id":"recTrqnHHIhQpxntk","symbol":"A/HRC/48/83","n":"59","seq":59,"section":"F. Migrants","text":"Migrants form an identifiable group of individual civilians defined by their\nvulnerability and absence of legal status within Libya. The commission of the above acts has\nbeen long-standing and on a massive scale. Based on reports of reliable organizations, the\nMission established that since 2016, some 87,000 migrants had been intercepted by the\nLibyan Coast Guard, and that there were currently close to 7,000 migrants in detention\ncentres of the Department for Combating Illegal Migration, including large percentages of\nchildren. Furthermore, the acts referred to above are not isolated incidents that can be\nattributed to rogue elements: they form part of a pattern characterized by dangerous\noperations at sea followed by a systematic transfer to a detention centre where migrants are\nkept for an indefinite period of time and where they are subjected to intolerable conditions\nthat cause suffering and prompt them to utilize any means of escape, including paying money."},{"id":"a-hrc-48-83-p0060","rec_id":"recTrqnHHIhQpxntk","symbol":"A/HRC/48/83","n":"60","seq":60,"section":"F. Migrants","text":"Since the inception of boat pullbacks in the Mediterranean Sea, Libyan authorities\nhave been on notice regarding the widespread and systematic nature of the reckless\ninterceptions at sea and the abuses within the centres. Rather than investigating incidents and\nreforming practices, the Libyan authorities have continued with interception and detention of\nmigrants. The absence of accountability for abuses against migrants evidences a State policy\nencouraging the deterrence of sea crossings, extortion against migrants in detention, and\nsubjection to violence and discrimination. Militias (some of which manage detention centres),\ncriminal networks, traffickers and smugglers contribute to the implementation of this policy."},{"id":"a-hrc-48-83-p0061","rec_id":"recTrqnHHIhQpxntk","symbol":"A/HRC/48/83","n":"61","seq":61,"section":"F. Migrants","text":"The foregoing provides reasonable grounds to believe that acts of murder, 36\nenslavement, 37 torture, 38 imprisonment, 39 rape, 40 persecution 41 and other inhumane acts 42\ncommitted against migrants form part of a systematic and widespread attack directed at this\npopulation, in furtherance of a State policy. As such, these acts may amount to crimes against\nhumanity. This finding is made notwithstanding the responsibility that may be borne by third\nStates, and further investigations are required in order to establish the role of all those\ninvolved, directly or indirectly, in these crimes."},{"id":"a-hrc-48-83-p0062","rec_id":"recTrqnHHIhQpxntk","symbol":"A/HRC/48/83","n":"62","seq":62,"section":"F. Migrants","text":"The Mission also investigated two incidents endangering the life of migrants. In May\nand July 2019, during the non-international armed conflict in Tripoli, a detention centre\nlocated next to the headquarters of the Daman Brigade in Tajoura was struck twice. Dozens\nof deaths were reported and the authorities failed to take any action after the first strike. By\nfailing to remove the prisoners from the vicinity of a potential military objective, the Daman\nBrigade and the Government of National Accord (with which the Brigade was affiliated) may\nhave violated their international humanitarian law obligation to protect civilians under their\ncontrol from the effects of attack.43 The latter may have also violated the right to life of the\nmigrants,44 by preventing them from seeking shelter following the first airstrike. Furthermore,\nthere are reasonable grounds to believe that the party responsible for the airstrikes may have\nviolated the principles of distinction and proportionality as well as the obligation to take\nprecautions in attack.45 On 20 June 2021, an accidental explosion in what was believed to be\nan ammunition depot in close proximity to the Abu Rashada detention centre in Gharyan\ncaused the death of dozens of detained persons. Given that the guards prevented migrants\nfrom fleeing the building following the explosion, thereby preventing them from seeking\nsafety, there are reasonable grounds to believe that the right to life of the migrants may have\nbeen violated.46\nFigure 3"},{"id":"a-hrc-48-83-p0063","rec_id":"recTrqnHHIhQpxntk","symbol":"A/HRC/48/83","n":"63","seq":63,"section":"G. Women","text":"Women in Libya have been disproportionately affected by the continuing conflict and\nthe proliferation of militias. 47 While women contribute positively to public life in Libya, there\nhave been several attempts to silence prominent women figures through violence (including\nthrough online incitement to violence), which have had a chilling effect on women’s\nengagement in civic space at a time where the future of Libya is being shaped. Libya has\nfailed to prevent and punish violent acts against women, an obligation which is incumbent\non it even for a private act. 48 Two cases falling within the Mission’s mandate have had a\nparticular resonance: the disappearance of Sihem Sergiwa and the killing of Hanan al-Barassi.\nThese cases appear to be part of a continuing pattern of singling out criticism coming from\nwomen as intolerable, however diverse their views are."},{"id":"a-hrc-48-83-p0064","rec_id":"recTrqnHHIhQpxntk","symbol":"A/HRC/48/83","n":"64","seq":64,"section":"G. Women","text":"On 17 July 2019, Sihem Sergiwa, a member of the House of Representatives, was\nabducted at her home by uniformed men. The evidence indicated that she had been abducted\nby either the Libyan National Army or affiliated armed groups, and that the latter had failed\nto provide information on her fate. The Mission received conflicting reports as to her fate,\nbut it was unable to verify such claims. Ms. Sergiwa’s abduction and the circumstances\nsurrounding it have removed her from the protection of the law, placing her life at serious\nand constant risk. In these circumstances, there are reasonable grounds to believe that she is\na victim of enforced disappearance.49 Furthermore, there was no evidence that the relevant\nauthorities had conducted an effective investigation into Ms. Sergiwa’s disappearance or that\nthey had adequately apprised the family of the efforts undertaken to find her, which had\ncaused anguish and distress. Likewise, there was no evidence that the relevant authorities had\nprovided effective protection for Ms. Sergiwa, whose life was at risk due to her profile and\nas a result of specific threats. The Mission therefore found that the relevant authorities had\nfailed to protect Ms. Sergiwa’s life, to protect her family from cruel and inhuman treatment,\nto protect her from arbitrary arrest, to ensure her right to be recognized as a person before the\nlaw and to protect her and her family from unlawful interference with their privacy. 50"},{"id":"a-hrc-48-83-p0065","rec_id":"recTrqnHHIhQpxntk","symbol":"A/HRC/48/83","n":"65","seq":65,"section":"G. Women","text":"On 10 November 2020, Hanan al-Barassi, a lawyer who was critical of the Libyan\nNational Army, among others, was gunned down in broad daylight in Benghazi by two\nunidentified masked men. No one has claimed responsibility for her killing. The evidence\ndid not lead the Mission to establish who the perpetrators had been and whether they had\nacted in an official capacity. Nevertheless, prior to her killing, her life was at risk because of\nher profile and as a result of specific threats received a few days before her killing. The\ninterior ministry of the government in the east of the country (Benghazi) ordered all security\nagencies to identify the perpetrators and the justice ministry of the Government of National\nAccord announced that the authorities would open an investigation. However, the\ninvestigation is not progressing and no one has been held accountable. The Mission noted\nwith concern that Ms. Al-Barassi’s daughter had been detained from 25 March to 28 June\n2021 by Libyan National Army-affiliated forces on allegations of involvement in the\nassassination of Mahmoud al-Werfalli. In these circumstances, there are reasonable grounds\nto believe that the State may have failed to meet its obligations under the International\nCovenant on Civil and Political Rights51 and the Convention on the Elimination of All Forms\nof Discrimination against Women52 by failing to provide effective protection for Ms. Al-\nBarassi and by not conducting, to date, an effective investigation and prosecuting those\nresponsible for her murder."},{"id":"a-hrc-48-83-p0066","rec_id":"recTrqnHHIhQpxntk","symbol":"A/HRC/48/83","n":"66","seq":66,"section":"H. Children","text":"Children of all ages have been impacted in different ways by the violence in Libya\nsince 2016. Children have been killed in hostilities, many schools have been destroyed and\nsome children have to live without the presence of parents who have been abducted.\nViolations and abuses suffered by children in Libya often remain unseen. The present report\nfocuses on two areas: the alleged recruitment and use of children by parties to conflicts, and\nthe arbitrary detention of children in hostilities. Other violations or abuses against children\nwill be the subject of future investigations."},{"id":"a-hrc-48-83-p0067","rec_id":"recTrqnHHIhQpxntk","symbol":"A/HRC/48/83","n":"67","seq":67,"section":"H. Children","text":"The evidence established that from late 2019, Turkey facilitated the recruitment of\nSyrian children between 15 and 18 years of age (which was evident based on their appearance)\nto fight alongside the Government of National Accord against the Libyan National Army in\nexchange for payment. These child mercenaries were utilized for different functions,\nincluding in combat units, and with some in support roles, such as guards. Many were\nconfined if they disobeyed, and some of them were wounded. There are reasonable grounds\nto believe that Libya may have failed to comply with its obligations under the African Charter\non the Rights and Welfare of the Child, which prohibits both the recruitment of children and\nthe direct participation of children in hostilities, including into groups not part of the State’s\narmed forces. There are also reasonable grounds to believe that Libya may have failed to\ncomply with its obligations under the Optional Protocol to the Convention on the Rights of\nthe Child on the involvement of children in armed conflict, which mandates States parties to\ntake all feasible measures to ensure that children under their jurisdiction who are used in\nhostilities are demobilized or released from service. 53 Furthermore, both Libya and Turkey\nmay have violated their obligations, under the Optional Protocol to the Convention on the\nRights of the Child on the involvement of children in armed conflict, to prevent the\nrecruitment and use of children to take part in hostilities.54 The Mission came across further\nallegations of child recruitment and direct participation in hostilities, but additional time\nwould be required for investigations."},{"id":"a-hrc-48-83-p0068","rec_id":"recTrqnHHIhQpxntk","symbol":"A/HRC/48/83","n":"68","seq":68,"section":"H. Children","text":"In the course of its investigations into the Libyan prison system, the Mission paid\nparticular attention to the fate of children held in detention, including children of parents\nassociated with the Da’esh group, many of whom had been arbitrarily detained since 2016,\ndue to, inter alia, the refusal of their country of origin to accept them back. The evidence\nestablished that across Libya, children were detained together with adults (thereby increasing\nrisks of violence, including sexual violence), were subjected to the same harsh conditions of\ndetention (with an impact on their growth), and suffered beatings and torture. Several\nchildren have been held for prolonged periods without charge or trial. Some have also been\ndenied regular contact with their mothers held in the women’s wing. Such treatment may\namount to violations of the principle of the best interests of the child, and of a number of\nprovisions of the Convention on the Rights of the Child relating to the arbitrary detention of\nchildren,55 to the prohibition of torture56 and to separation from adults,57 as well as violations\nof the United Nations Standard Minimum Rules for the Treatment of Prisoners (the Nelson\nMandela Rules) and the United Nations Rules for the Treatment of Women Prisoners and\nNon-custodial Measures for Women Offenders (the Bangkok Rules)."},{"id":"a-hrc-48-83-p0069","rec_id":"recTrqnHHIhQpxntk","symbol":"A/HRC/48/83","n":"69","seq":69,"section":"I. Tarhuna","text":"Several reports have emerged regarding crimes committed in recent years in the town\nof Tarhuna (south-east of Tripoli), which have included widespread abductions, systematic\ntorture and mass murders, including of women targeted for their family links. These reports\nimplicate members of the family who ruled the town until recently, the Al-Kaniyat. The Al-\nKaniyat led an armed faction, which first aligned with the Tripoli government (in 2014–2018)\nand subsequently with the Libyan National Army (in 2019 and 2020). Some leading figures\nof Al-Kaniyat have been reported dead, as documented above in paragraph 53."},{"id":"a-hrc-48-83-p0070","rec_id":"recTrqnHHIhQpxntk","symbol":"A/HRC/48/83","n":"70","seq":70,"section":"I. Tarhuna","text":"The Mission considered the events of Tarhuna to be a priority area of investigation. It\nconducted a site visit in July 2021, interviewed first-hand witnesses and gathered\ndocumentary evidence, including forensic reports and satellite imagery. The information\ncollected revealed an extremely complex setting. The period that witnessed the alleged\ncrimes spanned many years and also coincided with the armed confrontations that took place\nin the broader Tripoli area in 2019 and 2020. The Mission received credible indications that\nthe crimes had resulted in a high number of victims, including women and children. In the\ncontext of a patriarchal society, several families continue to suffer from the absence of\nrelatives reported missing, with women having become heads of households and\nbreadwinners and children bearing the loss of their parents. The motivations underlying the\ncrimes appear to be multifaceted and must be understood against the backdrop of the shifting\nalliances of Al-Kaniyat."},{"id":"a-hrc-48-83-p0071","rec_id":"recTrqnHHIhQpxntk","symbol":"A/HRC/48/83","n":"71","seq":71,"section":"I. Tarhuna","text":"The Mission documented a number of disappearances, including that of Abubaker\nNaama, who was abducted in November 2019 by men linked to Al-Kaniyat. His whereabouts\nremained unknown to his family until recently when Libyan forensic experts identified his\nbody buried in what appeared to be a mass grave. The Mission independently reviewed the\nforensic report and found reasonable grounds to believe that Mr. Naama had been blindfolded\nand summarily executed. In connection with this, the Mission identified seven sites in the\narea of Tarhuna where there appeared to have been soil disturbance for short periods of time\ntowards the end of 2019 and in the beginning of 2020 (fig. 4),58 which strongly suggests the\ndigging of graves. The Mission received information indicating a number of disappearances\nduring the same time frame. It also obtained information regarding other potential mass grave\nsites."},{"id":"a-hrc-48-83-p0072","rec_id":"recTrqnHHIhQpxntk","symbol":"A/HRC/48/83","n":"72","seq":72,"section":"I. Tarhuna","text":"The Mission collected detailed accounts of persons who, following their abduction by\nAl-Kaniyat associates, had been kept against their will in places where they had endured\nsevere beatings and lived under harsh conditions. The Mission additionally gathered\ninformation regarding abductions and killings of children and the recruitment of children to\ndirectly participate in hostilities."},{"id":"a-hrc-48-83-p0073","rec_id":"recTrqnHHIhQpxntk","symbol":"A/HRC/48/83","n":"73","seq":73,"section":"I. Tarhuna","text":"While the above provides credible indications that widespread and systematic human\nrights violations were committed in Tarhuna, further investigations are needed in order to\nestablish the exact circumstances of the incidents and identify the perpetrators. Libyan\nauthorities are currently investigating the Tarhuna events, and the situation has also garnered\nthe attention of other reporting and accountability mechanisms. The gravity of the allegations\ncalls for concerted investigative efforts on the part of the international community.\nFigure 4"},{"id":"a-hrc-48-83-p0074","rec_id":"recTrqnHHIhQpxntk","symbol":"A/HRC/48/83","n":"74","seq":74,"section":"IV. Accountability","text":"The Mission engaged with Libyan judicial authorities – civil and military – with a\nview to reporting on the efforts of Libya to ensure accountability for violations of\ninternational human rights law and international humanitarian law. The Mission noted that a\nnumber of arrest warrants had been issued in respect of violations, abuses and crimes\ncommitted since 2016, evincing an intent to bring alleged perpetrators to justice. Yet, political\nconsiderations appear to hamper the enforcement of these warrants. Moreover, when asked\nwhether they had laid complaints, several victims expressed fears for their safety and that of\ntheir families."},{"id":"a-hrc-48-83-p0075","rec_id":"recTrqnHHIhQpxntk","symbol":"A/HRC/48/83","n":"75","seq":75,"section":"IV. Accountability","text":"Challenges in ensuring accountability are also structural. Divisions between\ngovernmental and security apparatuses in the west and the east, a security vacuum in the\nsouth, the presence of criminal groups throughout the country, and the Government’s lack of\ncapacity and limited reach outside of western Libya, have severely weakened the judicial\nsystem and have inhibited the ability of Libya to prosecute human rights violations. 59 The\nMission also noted that in certain cases, the civil and military judicial authorities claimed\nconcurrent jurisdiction over the same incidents, thus leading to overlaps and duplication of\nefforts."},{"id":"a-hrc-48-83-p0076","rec_id":"recTrqnHHIhQpxntk","symbol":"A/HRC/48/83","n":"76","seq":76,"section":"IV. Accountability","text":"Furthermore, accountability encompasses the right to an effective remedy for human\nrights violations. Although the Constitutional Declaration of 2011 provided the right to\nrecourse to the judiciary for each Libyan citizen, the Libyan judicial system still does not\nhave the capacity to provide citizens with access to civil remedies for human rights\nviolations.60"},{"id":"a-hrc-48-83-p0077","rec_id":"recTrqnHHIhQpxntk","symbol":"A/HRC/48/83","n":"77","seq":77,"section":"IV. Accountability","text":"With the recent installation of the Government of National Unity, the time is ripe for\naccountability to become effective. Libyan authorities have advised the Mission that they are\nin need of technical assistance and cooperation to increase their capacity to prosecute human\nrights violations and international crimes."},{"id":"a-hrc-48-83-p0078","rec_id":"recTrqnHHIhQpxntk","symbol":"A/HRC/48/83","n":"78","seq":78,"section":"V. Conclusions","text":"The violence which has plagued Libya since 2011, and which has continued almost\nunabated since 2016, has enabled the commission of serious violations, abuses and crimes,\nincluding crimes against humanity and war crimes, against the most vulnerable. The Mission\nnoted with concern that several incidents had taken place since it had been established in June\n2020. For the present report, the Mission focused its investigations on certain incidents\nrepresentative of broader trends and patterns of violations and crimes. Despite the limited\nscope of the Mission’s investigations to date, the findings unveil a dire human rights situation,\nsome aspects of which are rooted in causes beyond the armed conflicts. A comprehensive\ninvestigation into the human rights situation by the Mission as a whole is urgently needed."},{"id":"a-hrc-48-83-p0079","rec_id":"recTrqnHHIhQpxntk","symbol":"A/HRC/48/83","n":"79","seq":79,"section":"V. Conclusions","text":"Mindful of the need to ensure justice for victims, the Mission has identified\nindividuals and groups (both Libyan and foreign actors) who may bear responsibility for the\nviolations and abuses under investigation. In view of the complexity of the situation,\nadditional time and resources are required in order to establish individual and State\nresponsibility for all violations occurring since 2016."},{"id":"a-hrc-48-83-p0080","rec_id":"recTrqnHHIhQpxntk","symbol":"A/HRC/48/83","n":"80","seq":80,"section":"VI. Recommendations","text":"The Mission calls upon Libya to:\n(a)    Ensure that: (i) all reported cases of enforced disappearance are\ninvestigated effectively; (ii) families are apprised of the whereabouts of their relatives\nwho have been reported missing; (iii) missing persons are released; (iv) perpetrators\nare held accountable; and (v) victims and families are compensated for the damage they\nhave suffered;\n(b)    Ensure that: (i) internally displaced persons can safely return to their\nplaces of origin; (ii) internally displaced persons benefit from support in the areas they\nhave been displaced to; (iii) perpetrators of violations against internally displaced\npersons are held accountable; and (iv) internally displaced persons have access to\ncompensation for property losses;\n(c)    Ensure that operations at sea are conducted in accordance with\ninternational law; amend the law criminalizing illegal entry, stay and exit; release all\nmigrants arbitrarily detained and explore non-custodial alternatives to detention of\nmigrants; ensure that migrants are protected from all forms of violence, including\nsexual violence; and ensure that the perpetrators of violations against migrants are held\naccountable;\n(d)    Ensure that everyone is protected from sexual violence; hold to account\nperpetrators of sexual violence; and remove legal impediments preventing survivors\nfrom reporting incidents;\n(e)   Hold to account perpetrators of killings and enforced disappearances of\nwomen; and ensure protection for human rights defenders, journalists and activists;\n(f)     Ensure that: (i) the management of all prisons falls under the\nresponsibility of the State; (ii) prisoners can have their detention reviewed in\naccordance with the law; (iii) prisoners are held in dignified conditions and protected\nfrom violence; and (iv) perpetrators of violations committed against prisoners are held\naccountable;\n(g)   Immediately end the arbitrary detention of all children in Libya; release\nfrom detention, and facilitate, to the extent possible, the voluntary return of women and\nchildren allegedly associated with Da’esh; criminalize the recruitment and use of\nchildren by armed groups; prevent the recruitment and use of child mercenaries; and\nensure that no children take direct part in hostilities;\n(h)    Provide effective remedies to victims, including reparations;\n(i)   Ensure that perpetrators of violations of international humanitarian law\nand war crimes are prosecuted;\n(j)    Ensure compliance with international humanitarian law during the\nconduct of hostilities, by all parties;\n(k)   Ensure that all those present in Libya as mercenaries or foreign fighters\nare held accountable for violations they have committed; and refrain from further\nrecruitment and use of mercenaries, in keeping with the international treaty obligations\nof Libya;\n(l)      Ensure that: (i) all anti-personnel mines and booby traps are removed;\nand (ii) all those who have violated international humanitarian law with respect to such\nweapons are held accountable;\n(m) Take steps to ratify the International Convention for the Protection of All\nPersons from Enforced Disappearance, the Convention relating to the Status of\nRefugees, of 1951, the Anti-Personnel Landmines Convention, of 1999, and the Rome\nStatute of the International Criminal Court; and ensure that national legislation is\naligned with their provisions;\n(n)    Reform the Penal Code to encompass violations of international\nhumanitarian law and war crimes; and revise the decree regulating the work of NGOs;\n(o)    Ensure that accountability forms part of the reconciliation process."},{"id":"a-hrc-48-83-p0081","rec_id":"recTrqnHHIhQpxntk","symbol":"A/HRC/48/83","n":"81","seq":81,"section":"VI. Recommendations","text":"The Mission additionally calls upon the members of the international community\nto:\n(a)   Bring to justice all individuals under their jurisdiction who are suspected\nof having committed violations in Libya, including mercenaries and foreign fighters;\n(b)     Provide technical support to the Libyan authorities in the prosecution of\nviolations, including in particular the Tarhuna crimes;\n(c)    Ensure that all agreements with Libyan authorities comply with\ninternational human rights law and international humanitarian law, particularly on the\nissue of migration."},{"id":"a-hrc-48-83-p0082","rec_id":"recTrqnHHIhQpxntk","symbol":"A/HRC/48/83","n":"82","seq":82,"section":"VI. Recommendations","text":"The Mission finally urges the Human Rights Council to:\n(a)    Consider extending the Mission’s mandate for a period of time\ncommensurate with the mandate’s breadth; and encourage Libya to continue to fully\ncooperate with the Mission."},{"id":"a-hrc-48-83-p0001-a1","rec_id":"recTrqnHHIhQpxntk","symbol":"A/HRC/48/83","n":"1","seq":83,"section":"Annex I","text":"Ratione materiae: The Human Rights Council (“Council”) requested the Mission to\ninvestigate violations and abuses of both international human rights law (“IHRL”) and\ninternational humanitarian law (“IHL”). Resolution 43/39 made no mention of crimes under\ninternational criminal law (“ICL”); however, IHRL and IHL underpin this body of law, and\nthe Mission considered it crucial to the fulfilment of its mandate to additionally investigate\ncrimes punishable under ICL (A/HRC/12/48, para.286; A/HRC/38/CRP.1, para.8). In this\nregard, the Mission noted that the Office of the Prosecutor of the International Criminal Court\n(“ICC”) has investigated the situation in Libya since 15 February 2011 further to a referral\nby the United Nations Security Council and that its investigations extend to events falling\nwithin the Mission’s temporal mandate.","annex":1},{"id":"a-hrc-48-83-p0002-a1","rec_id":"recTrqnHHIhQpxntk","symbol":"A/HRC/48/83","n":"2","seq":84,"section":"Annex I","text":"Ratione temporis: The Council mandated the Mission to focus on alleged violations\nand abuses “since the beginning of 2016”. The Mission considered that its mandate also\nencompassed the investigation of continuing violations and abuses that commenced before\n2016.","annex":1},{"id":"a-hrc-48-83-p0003-a1","rec_id":"recTrqnHHIhQpxntk","symbol":"A/HRC/48/83","n":"3","seq":85,"section":"Annex I","text":"Ratione loci: Resolution 43/39 provided that the Mission should document violations\nand abuses committed “in Libya”. The Mission interpreted this to mean that it had a mandate\nto investigate, first and foremost, violations and abuses committed on Libyan territory, which\nincludes its territorial sea. Noting the methodology adopted by previous fact-finding\nmechanisms (A/HRC/25/CRP.1, para.20 and fn.8), the Mission considered that its mandate\nalso extended to the documentation of acts that commenced beyond Libyan borders but\ncontinued inside Libyan territory.","annex":1},{"id":"a-hrc-48-83-p0004-a1","rec_id":"recTrqnHHIhQpxntk","symbol":"A/HRC/48/83","n":"4","seq":86,"section":"Annex I","text":"Ratione personae: Resolution 43/39 referred to violations and abuses committed by\n“all parties”. In view of this, the Mission considered that its investigations should cover the\nconduct of both State and non-State actors, including foreign State and non-State actors.","annex":1},{"id":"a-hrc-48-83-p0005-a1","rec_id":"recTrqnHHIhQpxntk","symbol":"A/HRC/48/83","n":"5","seq":87,"section":"Annex I","text":"Noting that the Council called on the Mission to preserve evidence “with a view to\nensuring that perpetrators […] are held accountable”, the Mission considered it part of its\nmandate to identify those who could bear responsibility for the violations and abuses under\ninvestigation. Additionally, the mandate allowed for a focus not only on individual\nresponsibility but also on State responsibility, as the latter remains at the forefront of IHRL.","annex":1},{"id":"a-hrc-48-83-p0006-a1","rec_id":"recTrqnHHIhQpxntk","symbol":"A/HRC/48/83","n":"6","seq":88,"section":"Annex I","text":"Finally, the Council requested the Mission to document the gendered dimensions of\nthe violations and abuses under investigation. Gender analysis strengthens human rights\ninvestigations in making visible violations and abuses that are otherwise invisible due to the\npersistence of gendered discrimination or stereotypes, in uncovering the deeper roots and\neffects of violence, and in formulating recommendations that are tailored to the needs of those\nimpacted by violations by virtue of their gender or sexual orientation. The Mission applied a\ngender sensitive approach to all aspects of its work, giving due regard to the fact that the root\ncauses of violence may be multifactorial.","annex":1},{"id":"a-hrc-48-83-p0001-a2","rec_id":"recTrqnHHIhQpxntk","symbol":"A/HRC/48/83","n":"1","seq":89,"section":"Annex II","text":"International human rights law (“IHRL”) is the body of international law, stemming\nfrom treaties or custom, which requires States to respect, protect and fulfil human rights at\nall times. Libya is party to twelve of the eighteen core human rights treaties as well as to a\nnumber of regional instruments (Annex III). Some soft law instruments also assist in\ndelineating human rights obligations (Annex IV). While IHRL obligations apply to States in\nthe first instance, the Mission concurred with the approach of the International Commission\nof Inquiry on Libya, which examined human rights violations by non-State actors noting that\n“it is increasingly accepted that where non-State groups exercise de facto control over\nterritory, they must respect fundamental human rights of persons in that territory”\n(A/HRC/17/44, para. 62).","annex":2},{"id":"a-hrc-48-83-p0002-a2","rec_id":"recTrqnHHIhQpxntk","symbol":"A/HRC/48/83","n":"2","seq":90,"section":"Annex II","text":"International humanitarian law (“IHL”) is the body of international law, stemming\nfrom treaties or custom, that regulates the conduct of all parties engaged in an armed conflict.\nLibya is a party to the instruments listed in Annex V. Given that the alleged violations of IHL\nall took place in the context of either an armed conflict opposing the Libyan state’s armed\nforces against a non-State armed group, or an armed conflict involving two or more non-State\narmed groups, the Mission considered customary and treaty rules of IHL as applicable to\nnon-international armed conflicts.","annex":2},{"id":"a-hrc-48-83-p0003-a2","rec_id":"recTrqnHHIhQpxntk","symbol":"A/HRC/48/83","n":"3","seq":91,"section":"Annex II","text":"International criminal law (“ICL”) establishes individual criminal responsibility for\ncategories of conduct constituting international crimes, such as genocide, crimes against\nhumanity and war crimes. These crimes descend from IHRL and/or IHL and are notably\ndefined in the Rome Statute of the International Criminal Court (“ICC”). As noted in the\nreport, the Libyan situation is currently investigated by the Office of the Prosecutor of the\nICC. Considering the convergences between the ICC’s jurisdiction and the Mission’s\nmandate, the Mission rooted its analysis of potential international crimes in accordance with\nthe Rome Statute and the ICC Elements of Crimes.\nCrimes against humanity","annex":2},{"id":"a-hrc-48-83-p0004-a2","rec_id":"recTrqnHHIhQpxntk","symbol":"A/HRC/48/83","n":"4","seq":92,"section":"Annex II","text":"The crime of murder under ICL requires unlawfully causing the death of a person.\nThe perpetrator must either act with the intent to cause such death or serious injury or with\nawareness that death will be the consequence of his/her conduct. Murder may encompass\nexecutions, but also deaths resulting from torture, starvation, unsanitary conditions and denial\nof medical care.","annex":2},{"id":"a-hrc-48-83-p0005-a2","rec_id":"recTrqnHHIhQpxntk","symbol":"A/HRC/48/83","n":"5","seq":93,"section":"Annex II","text":"Enslavement is understood to be the exercise of any or all of the powers attaching to\nthe right of ownership over a person and includes the exercise of such power in the course of\ntrafficking in persons, in particular women and children.","annex":2},{"id":"a-hrc-48-83-p0006-a2","rec_id":"recTrqnHHIhQpxntk","symbol":"A/HRC/48/83","n":"6","seq":94,"section":"Annex II","text":"Imprisonment in violation of fundamental rules of international law includes\ndetention that fails to respect the basic principles of due process. These principles are\nenshrined in Articles 9 and 14 of the International Covenant on Civil and Political Rights.\nThe requisite level of gravity is reached when persons are detained for long periods of time\nwithout ever being brought before an independent judge or being charged, tried or duly\nconvicted for any crime.","annex":2},{"id":"a-hrc-48-83-p0007-a2","rec_id":"recTrqnHHIhQpxntk","symbol":"A/HRC/48/83","n":"7","seq":95,"section":"Annex II","text":"The Rome Statute defines torture as the intentional infliction of severe pain or\nsuffering, whether physical or mental, upon a person in the custody or under the control of\nthe perpetrator. Intentionally subjecting persons to extremely inhumane conditions of\ndetention with the intention of intimidating and punishing them may reach the threshold of\ntorture.","annex":2},{"id":"a-hrc-48-83-p0008-a2","rec_id":"recTrqnHHIhQpxntk","symbol":"A/HRC/48/83","n":"8","seq":96,"section":"Annex II","text":"The Rome Statute criminalizes rape, sexual slavery, enforced prostitution, forced\npregnancy, enforced sterilization, or any other form of sexual violence of comparable gravity.","annex":2},{"id":"a-hrc-48-83-p0009-a2","rec_id":"recTrqnHHIhQpxntk","symbol":"A/HRC/48/83","n":"9","seq":97,"section":"Annex II","text":"Persecution requires the conduct to have been committed in connection with another\ncrime against humanity and that the perpetrator targeted the victims on political, racial,\nnational, ethnic, cultural, religious, gender or other grounds that are universally recognized\nas impermissible under international law.","annex":2},{"id":"a-hrc-48-83-p0010-a2","rec_id":"recTrqnHHIhQpxntk","symbol":"A/HRC/48/83","n":"10","seq":98,"section":"Annex II","text":"ICL defines enforced disappearance as the arrest, detention or abduction of persons\nby or with the authorization, support or acquiescence of a state or a political organization,\nfollowed by a refusal to acknowledge that deprivation of freedom or to give information on\nthe fate or whereabouts of those persons, with the intention of removing them from the\nprotection of the law for a prolonged period of time.","annex":2},{"id":"a-hrc-48-83-p0011-a2","rec_id":"recTrqnHHIhQpxntk","symbol":"A/HRC/48/83","n":"11","seq":99,"section":"Annex II","text":"The category of ‘other inhumane acts’ requires the same threshold of the other listed\ncrimes in terms of nature, scale and gravity. The Mission considered that actions preventing\nmigrants to leave Libya, which infringe on the internationally recognized right to leave and\nmay cause great suffering, may be categorized as other inhumane acts within the meaning of\narticle 7 of the Rome Statute. The Mission adopted a similar view regarding omissions in\nrendering assistance to migrants in distress at sea, which highlight a failure to comply with\nthe duty to protect the lives of individuals under the State’s control and may result in great\nharm to the victims.\nMercenarism","annex":2},{"id":"a-hrc-48-83-p0012-a2","rec_id":"recTrqnHHIhQpxntk","symbol":"A/HRC/48/83","n":"12","seq":100,"section":"Annex II","text":"Two specific mercenary international conventions regulate ‘mercenarism’: the\nInternational Convention against the Recruitment, Use, Financing, and Training of\nMercenaries (to which Libya accessed in September 2000) (“UN Mercenary Convention”)\nand the Convention for the Elimination of Mercenarism in Africa (to which Libya accessed\nin May 2005) (“African Mercenary Convention”). The purpose of these conventions is not to\nregulate the behaviour and status of mercenaries but to eliminate them via criminalization.\nUnder the UN Mercenary Convention, a ‘mercenary’ is a person who: (i) is specially\nrecruited locally or abroad in order to fight in an armed conflict; (ii) is motivated to take part\nin the hostilities essentially by the desire for private gain; (iii) is not a national of a party to\nthe conflict; (iv) is not a member of the armed forces of a party to the conflict; and (v) has\nnot been sent by a State which is not a party to the armed conflict on official duty as a member\nof its armed forces. The African Mercenary Convention additionally requires direct\nparticipation in hostilities.\nExtrajudicial killings","annex":2},{"id":"a-hrc-48-83-p0013-a2","rec_id":"recTrqnHHIhQpxntk","symbol":"A/HRC/48/83","n":"13","seq":101,"section":"Annex II","text":"An extrajudicial killing occurs when: (1) a public official or other person acting at the\ninstigation of or with the consent or acquiescence of a public official or other person acting\nin an official capacity; (2) whose acts were intentional or negligent; and (3) resulted in one\nor more deaths; and (4) who knew or should have known that death may result from their\nacts; and (5) who failed to comply with any relevant standards regarding the use of force,\nincluding the principles of necessity, distinction, proportionality, and precaution; and (6)\nwhose acts were not authorized by legal process or complied with the rule of law.\nEnforced disappearances","annex":2},{"id":"a-hrc-48-83-p0014-a2","rec_id":"recTrqnHHIhQpxntk","symbol":"A/HRC/48/83","n":"14","seq":102,"section":"Annex II","text":"Libya is not party to the International Convention for the Protection of All Persons\nfrom Enforced Disappearance. However, it is party to the International Covenant on Civil\nand Political Rights and the Convention against Torture, which protect a number of rights\nthat are constitutive of enforced disappearance. The Covenant and the Convention impose a\nduty on Libya to criminalize, investigate, prosecute, punish, and provide reparation and\nremedies for such violations. While the Covenant does not explicitly use the term “enforced\ndisappearance” in any of its articles, enforced disappearance constitutes a unique and\nintegrated series of acts that represents a continuing violation of various rights, such as the\nright to life, the right not to be subjected to torture or other cruel, inhuman or degrading\ntreatment or punishment, and the right to liberty and security of person. The Mission applied\nthe following definition of ‘enforced disappearance’: (1) the arrest, detention or abduction of\npersons; (2) by, or with the authorization, support or acquiescence of, a State or a political\norganization; (3) followed by a refusal to acknowledge that deprivation of freedom or to give\ninformation on the fate or whereabouts of those persons; (4) with the intention of removing\nthem from the protection of the law for a period of time. De facto authorities whose authority\nis comparable to governmental authorities exercising effective control over a territory may\nbe considered potential perpetrators of enforced disappearances under IHRL.\nViolence against women","annex":2},{"id":"a-hrc-48-83-p0015-a2","rec_id":"recTrqnHHIhQpxntk","symbol":"A/HRC/48/83","n":"15","seq":103,"section":"Annex II","text":"In a recent case concerning a Libyan woman, the Committee on the Elimination of\nDiscrimination against Women (“Committee”) recalled that under article 2-e of the\nConvention on the Elimination of All Forms of Discrimination against Women, States parties\nmay also be responsible for private acts if they fail to act with due diligence to prevent\nviolations of rights or to investigate and punish acts of violence, and for providing\ncompensation (CEDAW/C/78/D/130/2018, para. 6.3). The Committee further expanded that\n“[t]he failure of a State party to take all appropriate measures to prevent acts of gender-based\nviolence against women in cases in which its authorities are aware or should be aware of the\nrisk of such violence, or the failure to investigate, prosecute and punish perpetrators and\nprovide reparations to victims/survivors of such acts, provides tacit permission or\nencouragement to perpetrate acts of gender-based violence against women. Such failures or\nomissions constitute human rights violations” (ibid.).\nMigrants, refugees and asylum seekers","annex":2},{"id":"a-hrc-48-83-p0016-a2","rec_id":"recTrqnHHIhQpxntk","symbol":"A/HRC/48/83","n":"16","seq":104,"section":"Annex II","text":"Consistent with the methodology of the Office of the United Nations High\nCommissioner for Human Rights (“OHCHR”), the Mission used the expression ‘migrant’ to\ncover the categories of migrant, refugee or asylum seeker, as well as any person who is\noutside a State of which s/he is a citizen or national, or, in the case of a stateless person, his\nor her State of birth or habitual residence, trafficked persons, smuggled migrants, and other\ncategories, unless specified otherwise (“Desperate and Dangerous: Report on the human\nrights situation of migrants and refugees in Libya”, 20 December 2018, available at:\nhttps://www.ohchr.org/Documents/Countries/LY/LibyaMigrationReport.pdf (last accessed\non 6 October 2021)).","annex":2},{"id":"a-hrc-48-83-p0001-a3","rec_id":"recTrqnHHIhQpxntk","symbol":"A/HRC/48/83","n":"1","seq":105,"section":"Annex III","text":"International Convention on the Elimination of all Forms of Racial Discrimination\n(since 1968);","annex":3},{"id":"a-hrc-48-83-p0002-a3","rec_id":"recTrqnHHIhQpxntk","symbol":"A/HRC/48/83","n":"2","seq":106,"section":"Annex III","text":"International Covenant on Civil and Political Rights (since 1970);","annex":3},{"id":"a-hrc-48-83-p0003-a3","rec_id":"recTrqnHHIhQpxntk","symbol":"A/HRC/48/83","n":"3","seq":107,"section":"Annex III","text":"OAU Convention Governing the Specific Aspects of Refugee Problems in Africa\n(since 1981);","annex":3},{"id":"a-hrc-48-83-p0004-a3","rec_id":"recTrqnHHIhQpxntk","symbol":"A/HRC/48/83","n":"4","seq":108,"section":"Annex III","text":"Optional Protocol to the International Covenant on Civil and Political Rights (since\n1989);","annex":3},{"id":"a-hrc-48-83-p0005-a3","rec_id":"recTrqnHHIhQpxntk","symbol":"A/HRC/48/83","n":"5","seq":109,"section":"Annex III","text":"International Covenant on Economic, Social and Cultural Rights (since 1970);","annex":3},{"id":"a-hrc-48-83-p0006-a3","rec_id":"recTrqnHHIhQpxntk","symbol":"A/HRC/48/83","n":"6","seq":110,"section":"Annex III","text":"African Charter on Human and Peoples’ Rights (since 1986);","annex":3},{"id":"a-hrc-48-83-p0007-a3","rec_id":"recTrqnHHIhQpxntk","symbol":"A/HRC/48/83","n":"7","seq":111,"section":"Annex III","text":"Convention on the Elimination of All Forms of Discrimination against Women (since\n1989);","annex":3},{"id":"a-hrc-48-83-p0008-a3","rec_id":"recTrqnHHIhQpxntk","symbol":"A/HRC/48/83","n":"8","seq":112,"section":"Annex III","text":"Optional Protocol to the Convention on the Elimination of All Forms of\nDiscrimination against Women (since 2004);","annex":3},{"id":"a-hrc-48-83-p0009-a3","rec_id":"recTrqnHHIhQpxntk","symbol":"A/HRC/48/83","n":"9","seq":113,"section":"Annex III","text":"Convention against Torture and Other Cruel Inhuman or Degrading Treatment or\nPunishment (since 1989);","annex":3},{"id":"a-hrc-48-83-p0010-a3","rec_id":"recTrqnHHIhQpxntk","symbol":"A/HRC/48/83","n":"10","seq":114,"section":"Annex III","text":"Convention on the Rights of the Child (since 1993);","annex":3},{"id":"a-hrc-48-83-p0011-a3","rec_id":"recTrqnHHIhQpxntk","symbol":"A/HRC/48/83","n":"11","seq":115,"section":"Annex III","text":"African Charter on the Rights and Welfare of the Child (since 2000);","annex":3},{"id":"a-hrc-48-83-p0012-a3","rec_id":"recTrqnHHIhQpxntk","symbol":"A/HRC/48/83","n":"12","seq":116,"section":"Annex III","text":"Optional Protocol to the Convention on the Rights of the Child on the Involvement of\nChildren in Armed Conflict (since 2004);","annex":3},{"id":"a-hrc-48-83-p0013-a3","rec_id":"recTrqnHHIhQpxntk","symbol":"A/HRC/48/83","n":"13","seq":117,"section":"Annex III","text":"Optional Protocol to the Convention on the Rights of the Child on the Sale of Children,\nChild Prostitution and Child Pornography (since 2004);","annex":3},{"id":"a-hrc-48-83-p0014-a3","rec_id":"recTrqnHHIhQpxntk","symbol":"A/HRC/48/83","n":"14","seq":118,"section":"Annex III","text":"International Convention on the Protection of the Rights of All Migrant Workers and\nTheir Families (since 2004);","annex":3},{"id":"a-hrc-48-83-p0015-a3","rec_id":"recTrqnHHIhQpxntk","symbol":"A/HRC/48/83","n":"15","seq":119,"section":"Annex III","text":"Convention on the Rights of Persons with Disabilities (since 2018).","annex":3},{"id":"a-hrc-48-83-p0001-a4","rec_id":"recTrqnHHIhQpxntk","symbol":"A/HRC/48/83","n":"1","seq":120,"section":"Annex IV","text":"Declaration on the Protection of Women and Children in Emergency and Armed\nConflict (1974);","annex":4},{"id":"a-hrc-48-83-p0002-a4","rec_id":"recTrqnHHIhQpxntk","symbol":"A/HRC/48/83","n":"2","seq":121,"section":"Annex IV","text":"Cairo Declaration on Human Rights in Islam (1990);","annex":4},{"id":"a-hrc-48-83-p0003-a4","rec_id":"recTrqnHHIhQpxntk","symbol":"A/HRC/48/83","n":"3","seq":122,"section":"Annex IV","text":"Basic Principles on the Use of Force and Firearms by Law Enforcement Officials\n(1990);","annex":4},{"id":"a-hrc-48-83-p0004-a4","rec_id":"recTrqnHHIhQpxntk","symbol":"A/HRC/48/83","n":"4","seq":123,"section":"Annex IV","text":"Declaration on the Protection of all Persons from Enforced Disappearance (1992);","annex":4},{"id":"a-hrc-48-83-p0005-a4","rec_id":"recTrqnHHIhQpxntk","symbol":"A/HRC/48/83","n":"5","seq":124,"section":"Annex IV","text":"Guiding Principles on Internal Displacement (1998);","annex":4},{"id":"a-hrc-48-83-p0006-a4","rec_id":"recTrqnHHIhQpxntk","symbol":"A/HRC/48/83","n":"6","seq":125,"section":"Annex IV","text":"Declaration on the Right and Responsibility of Individuals, Groups and Organs of\nSociety to Promote and Protect Universally Recognized Human Rights and Fundamental\nFreedoms (Declaration on Human Rights Defenders) (1999);","annex":4},{"id":"a-hrc-48-83-p0007-a4","rec_id":"recTrqnHHIhQpxntk","symbol":"A/HRC/48/83","n":"7","seq":126,"section":"Annex IV","text":"Protocol to Prevent, Suppress and Punish Trafficking in Persons Especially Women\nand Children, supplementing the United Nations Convention against Transnational\nOrganized Crime (2000);","annex":4},{"id":"a-hrc-48-83-p0008-a4","rec_id":"recTrqnHHIhQpxntk","symbol":"A/HRC/48/83","n":"8","seq":127,"section":"Annex IV","text":"Protocol against the Smuggling of Migrants by Land, Sea and Air, supplementing the\nUnited Nations Convention against Transnational Organized Crime (2000);","annex":4},{"id":"a-hrc-48-83-p0009-a4","rec_id":"recTrqnHHIhQpxntk","symbol":"A/HRC/48/83","n":"9","seq":128,"section":"Annex IV","text":"Updated Set of Principles for the Protection and Promotion of Human Rights through\nAction to Combat Impunity (2005);","annex":4},{"id":"a-hrc-48-83-p0010-a4","rec_id":"recTrqnHHIhQpxntk","symbol":"A/HRC/48/83","n":"10","seq":129,"section":"Annex IV","text":"Basic Principles and Guidelines on the Right to a Remedy and Reparation for Victims\nof Gross Violations of International Human Rights Law and Serious Violations of\nInternational Humanitarian Law (2005);","annex":4},{"id":"a-hrc-48-83-p0011-a4","rec_id":"recTrqnHHIhQpxntk","symbol":"A/HRC/48/83","n":"11","seq":130,"section":"Annex IV","text":"United Nations Rules for the Treatment of Women Prisoners and Non-Custodial\nMeasures for Women Offenders (the Bangkok Rules) (2010);","annex":4},{"id":"a-hrc-48-83-p0012-a4","rec_id":"recTrqnHHIhQpxntk","symbol":"A/HRC/48/83","n":"12","seq":131,"section":"Annex IV","text":"United Nations Standard Minimum Rules for the Treatment of Prisoners (the Nelson\nMandela rules) (2015).","annex":4},{"id":"a-hrc-48-83-p0001-a5","rec_id":"recTrqnHHIhQpxntk","symbol":"A/HRC/48/83","n":"1","seq":132,"section":"Annex V","text":"Convention for the Protection of Cultural Property in the Event of Armed Conflict\n(since 1954);","annex":5},{"id":"a-hrc-48-83-p0002-a5","rec_id":"recTrqnHHIhQpxntk","symbol":"A/HRC/48/83","n":"2","seq":133,"section":"Annex V","text":"Convention (I) for the Amelioration of the Condition of the Wounded and Sick in\nArmed Forces in the Field (since 1956);","annex":5},{"id":"a-hrc-48-83-p0003-a5","rec_id":"recTrqnHHIhQpxntk","symbol":"A/HRC/48/83","n":"3","seq":134,"section":"Annex V","text":"Convention (II) for the Amelioration of the Condition of Wounded, Sick and\nShipwrecked Members of Armed Forces at Sea (since 1956);","annex":5},{"id":"a-hrc-48-83-p0004-a5","rec_id":"recTrqnHHIhQpxntk","symbol":"A/HRC/48/83","n":"4","seq":135,"section":"Annex V","text":"Convention (III) relative to the Treatment of Prisoners of War (since 1956);","annex":5},{"id":"a-hrc-48-83-p0005-a5","rec_id":"recTrqnHHIhQpxntk","symbol":"A/HRC/48/83","n":"5","seq":136,"section":"Annex V","text":"Convention (IV) relative to the Protection of Civilian Persons in Time of War (since\n1956);","annex":5},{"id":"a-hrc-48-83-p0006-a5","rec_id":"recTrqnHHIhQpxntk","symbol":"A/HRC/48/83","n":"6","seq":137,"section":"Annex V","text":"Protocol for the Protection of Cultural Property in the Event of Armed Conflict (since\n1957);","annex":5},{"id":"a-hrc-48-83-p0007-a5","rec_id":"recTrqnHHIhQpxntk","symbol":"A/HRC/48/83","n":"7","seq":138,"section":"Annex V","text":"Protocol for the Prohibition of the Use of Asphyxiating, Poisonous or Other Gases,\nand of Bacteriological Methods of Warfare (since 1971);","annex":5},{"id":"a-hrc-48-83-p0008-a5","rec_id":"recTrqnHHIhQpxntk","symbol":"A/HRC/48/83","n":"8","seq":139,"section":"Annex V","text":"Protocol Additional to the Geneva Conventions of 12 August 1949, and relating to the\nProtection of Victims of International Armed Conflicts (Protocol I) (since 1978);","annex":5},{"id":"a-hrc-48-83-p0009-a5","rec_id":"recTrqnHHIhQpxntk","symbol":"A/HRC/48/83","n":"9","seq":140,"section":"Annex V","text":"Protocol Additional to the Geneva Conventions of 12 August 1949, and relating to the\nProtection of Victims of Non-International Armed Conflicts (Protocol II) (since 1978);","annex":5},{"id":"a-hrc-48-83-p0010-a5","rec_id":"recTrqnHHIhQpxntk","symbol":"A/HRC/48/83","n":"10","seq":141,"section":"Annex V","text":"Convention on the Prohibition of the Development, Production and Stockpiling of\nBacteriological (Biological) and Toxin Weapons and on their Destruction (since 1982);","annex":5},{"id":"a-hrc-48-83-p0011-a5","rec_id":"recTrqnHHIhQpxntk","symbol":"A/HRC/48/83","n":"11","seq":142,"section":"Annex V","text":"Convention on the Prohibition of the Development, Production, Stockpiling and Use\nof Chemical Weapons and on their Destruction (since 2004);","annex":5},{"id":"a-hrc-48-83-p0012-a5","rec_id":"recTrqnHHIhQpxntk","symbol":"A/HRC/48/83","n":"12","seq":143,"section":"Annex V","text":"Second Protocol to the Hague Convention of 1954 for the Protection of Cultural\nProperty in the Event of Armed Conflict (since 2011).","annex":5},{"id":"a-hrc-50-63-u0000","rec_id":"recaC5gtNvtAQyAXk","symbol":"A/HRC/50/63","n":null,"seq":0,"section":null,"text":"* The present report was submitted after the deadline so as to reflect the most recent developments.\n** The annexes to the present report are circulated as received, in the language of submission only.","unnumbered":true},{"id":"a-hrc-50-63-p0001","rec_id":"recaC5gtNvtAQyAXk","symbol":"A/HRC/50/63","n":"1","seq":1,"section":"I. Introduction","text":"The present report is submitted pursuant to Human Rights Council resolution 48/25,\nin which the Council extended the mandate of the Fact-Finding Mission on Libya and\nrequested it to present a comprehensive report at the Council’s fiftieth session. It should be\nread in conjunction with the Mission’s first two reports. 1 The Mission submits further\ndetailed findings on violations committed in the town of Tarhuna in the form of a conference\nroom paper.2"},{"id":"a-hrc-50-63-p0002","rec_id":"recaC5gtNvtAQyAXk","symbol":"A/HRC/50/63","n":"2","seq":2,"section":"I. Introduction","text":"Established pursuant to Human Rights Council resolution 43/39, the Mission was\nmandated to establish, in an independent and impartial manner, the facts and circumstances\nof the human rights situation throughout Libya, to document alleged violations and abuses of\ninternational human rights law and international humanitarian law by all parties in Libya\nsince the beginning of 2016, including any gendered dimensions thereof, and to preserve\nevidence with a view to ensuring that perpetrators of violations and abuses are held\naccountable."},{"id":"a-hrc-50-63-p0003","rec_id":"recaC5gtNvtAQyAXk","symbol":"A/HRC/50/63","n":"3","seq":3,"section":"I. Introduction","text":"The Mission comprised three members: Mohamed Auajjar, of Morocco, Tracy\nRobinson, of Jamaica, and Chaloka Beyani, of Zambia and the United Kingdom of Great\nBritain and Northern Ireland."},{"id":"a-hrc-50-63-p0004","rec_id":"recaC5gtNvtAQyAXk","symbol":"A/HRC/50/63","n":"4","seq":4,"section":"I. Introduction","text":"The Mission was established at the request of the Government of Libya to support the\nLibyan people’s aspirations for justice, national reconciliation, respect for human rights and\nthe rule of law. It has achieved considerable progress in fulfilling its mandate and reached\nimportant conclusions. However, its investigative work is incomplete. The Mission continues\nto await access to prisons and wishes to highlight the delays by the authorities in the west\nand the east to allow it to visit Sebha (south). Further investigations on the ground in other\nregions, including the east, are also essential. Furthermore, the true operational duration of\nthe Mission has been significantly limited by the COVID-19 pandemic, a United Nations\nbudgetary freeze and other administrative matters, including the recruitment of staff. 3 The\nMission needs additional time to discharge its mandate fully."},{"id":"a-hrc-50-63-p0005","rec_id":"recaC5gtNvtAQyAXk","symbol":"A/HRC/50/63","n":"5","seq":5,"section":"I. Introduction","text":"Libya’s request for the Mission to support national authorities in uncovering the truth\nof what occurred since 2016 reflects a welcomed willingness by the Libyan government. The\nMission remains ready to support the Libyan authorities in fulfilling their primary\nresponsibility to protect human rights, hold perpetrators of gross human rights violations\naccountable, and achieve reconciliation. Its recommendations include the development of a\nLibyan-led National Human Rights Plan of Action, with international technical support, as a\nsustainable contribution to achieving truth, accountability and reconciliation."},{"id":"a-hrc-50-63-p0006","rec_id":"recaC5gtNvtAQyAXk","symbol":"A/HRC/50/63","n":"6","seq":6,"section":"II. Political and security situation","text":"The start of the Mission’s temporal mandate coincided with the direct aftermath of the\nLibyan Political Agreement (LPA) meant to provide a way out of the conflict that had divided\nLibya into two rival sets of parliaments, governments, and military coalitions since July 2014.\nHowever, efforts to fully implement the LPA over the following years have been\nunsuccessful, with the Government of National Accord (GNA), created by the LPA,\nstruggling to consolidate its authority. In particular, the Libyan legislature, the House of\nRepresentatives, never endorsed the composition of the GNA."},{"id":"a-hrc-50-63-p0007","rec_id":"recaC5gtNvtAQyAXk","symbol":"A/HRC/50/63","n":"7","seq":7,"section":"II. Political and security situation","text":"The lack of political stability also influenced the resurgence of military confrontations\nand hostilities of varying intensity, in the east, west and south of the country, including a non-\ninternational armed conflict from April 2019 to June 2020 between the Libyan National\nArmy (LNA) and the GNA, both supported by a variety of foreign actors. Ultra-local\ndynamics became subsumed into this conflict and pre-existing rifts between armed groups in\nall regions of Libya crystallised along the LNA/GNA divide leading to numerous armed\nconfrontations throughout the country. On 3 October 2020, the forces affiliated with the GNA\nand the LNA signed an Agreement for a Complete and Permanent Ceasefire."},{"id":"a-hrc-50-63-p0008","rec_id":"recaC5gtNvtAQyAXk","symbol":"A/HRC/50/63","n":"8","seq":8,"section":"II. Political and security situation","text":"On 15 November 2020, the Libyan Political Dialogue Forum (LPDF) adopted a\npolitical road map, providing for the establishment of a Government of National Unity (GNU)\nand the holding of presidential and parliamentary elections on 24 December 2021. However,\ntwo days prior to the scheduled date, the High National Elections Commission (HNEC)\ndeclared its inability to organise elections citing inadequacies in the electoral legislation and\nirregularities in the judicial process relating to the eligibility of candidates."},{"id":"a-hrc-50-63-p0009","rec_id":"recaC5gtNvtAQyAXk","symbol":"A/HRC/50/63","n":"9","seq":9,"section":"II. Political and security situation","text":"The House of Representatives, considering that the GNU’s mandate had expired,\nappointed a new Government of National Stability (GNS) headed by former interior minister\nFathi Bashaga in February 2022, leading to another deadlock between two rival governments,\nthe internationally recognised GNU led by Abdul Hamid Dbeibah and the GNS. At the time\nof writing, this political stalemate persists."},{"id":"a-hrc-50-63-p0010","rec_id":"recaC5gtNvtAQyAXk","symbol":"A/HRC/50/63","n":"10","seq":10,"section":"II. Political and security situation","text":"These developments occurred against a backdrop of persistent insecurity with armed\ngroups and militias assuming various degrees of control over territory, infrastructure and\nsecurity institutions throughout the country. Political allegiances of such groups often shift\nin their pursuit of official mandates, legitimacy, and funds. At the time of writing, localised\ntensions persist, and some key issues continue to contribute to insecurity and ongoing human\nrights violations in the country. They include the continued presence of Da’esh-affiliated\ngroups, as well as mercenaries, private military companies, and foreign fighters. Libya’s\nlimited capacity to conduct operations to clear landmines and other explosives is also a\ncontributing factor."},{"id":"a-hrc-50-63-p0011","rec_id":"recaC5gtNvtAQyAXk","symbol":"A/HRC/50/63","n":"11","seq":11,"section":"III. Cooperation of the Libyan authorities","text":"In its resolution 43/39, the Human Rights Council urged the Libyan authorities to\ngrant the Mission unhindered access to all Libyan territory without delay and to allow it to\nvisit sites, and to meet and speak freely and privately, when it so requested, with whomever\nit wished."},{"id":"a-hrc-50-63-p0012","rec_id":"recaC5gtNvtAQyAXk","symbol":"A/HRC/50/63","n":"12","seq":12,"section":"III. Cooperation of the Libyan authorities","text":"The Mission expresses its appreciation to the Libyan Permanent Mission to the United\nNations in Geneva, the Ministry of Foreign Affairs and the Libyan authorities in Tripoli and\nBenghazi for their cooperation. The Mission expresses its regret for not receiving the\nnecessary security clearance and permission for road movements from Tripoli to Sebha,\nwhich prevented it from conducting an important mission to southern Libya in May 2022,\ndespite having finalized all logistic and security arrangements."},{"id":"a-hrc-50-63-p0013","rec_id":"recaC5gtNvtAQyAXk","symbol":"A/HRC/50/63","n":"13","seq":13,"section":"III. Cooperation of the Libyan authorities","text":"The Mission continued to observe that many individuals and non-governmental\norganizations (NGOs) based in Libya did not feel able to meet and speak freely and privately\nwith it. In particular, and despite calls from the Mission to repeal it, Presidential Council\ndecree 286 of 2019 regulating the work of civil society organizations (CSOs) in Libya\nremains in force at the time of writing."},{"id":"a-hrc-50-63-p0014","rec_id":"recaC5gtNvtAQyAXk","symbol":"A/HRC/50/63","n":"14","seq":14,"section":"A. Applicable law","text":"Factual and legal findings are made in accordance with international human rights\nlaw, international humanitarian law and international criminal law. The Mission also\nconsiders Libyan law where relevant to its findings."},{"id":"a-hrc-50-63-p0015","rec_id":"recaC5gtNvtAQyAXk","symbol":"A/HRC/50/63","n":"15","seq":15,"section":"A. Applicable law","text":"International human rights law establishes obligations for states to protect persons\nwithin their jurisdiction. International humanitarian law applies to the conduct of all parties\nto an armed conflict, including non-State actors, who are bound by the relevant customary\ninternational humanitarian law rules. It complements international human rights law during\ntimes of armed conflict and, of the two bodies of law, is the only one applicable in peacetime."},{"id":"a-hrc-50-63-p0016","rec_id":"recaC5gtNvtAQyAXk","symbol":"A/HRC/50/63","n":"16","seq":16,"section":"A. Applicable law","text":"Given its mandate to document all violations of international human rights law and\ninternational humanitarian law by all parties in Libya, and its accountability function, the\nMission has regard to the rules and definitions of international criminal law."},{"id":"a-hrc-50-63-p0017","rec_id":"recaC5gtNvtAQyAXk","symbol":"A/HRC/50/63","n":"17","seq":17,"section":"B. Scope of investigations","text":"The Libyan context - in which gross violations of human rights and serious violations\nof international humanitarian law have occurred over a prolonged period - poses a challenge.\nMindful of the broad nature of its mandate, the Mission chose to adopt three objective criteria\nto inform, and circumscribe, the scope of its investigations. They include: i) grave and\nwidespread or systematic violations; ii) violations, abuses and crimes against vulnerable\ngroups that are subjected to multiple forms of victimization; and iii) violations, abuses and\ncrimes that especially hamper transition to rule of law and democratic elections. 4 The\nthematic categories included in the Findings section below reflect these guiding criteria."},{"id":"a-hrc-50-63-p0018","rec_id":"recaC5gtNvtAQyAXk","symbol":"A/HRC/50/63","n":"18","seq":18,"section":"B. Scope of investigations","text":"The Mission has endeavoured to investigate all geographical regions in Libya, as well\nas incidents that have occurred throughout its temporal mandate. However, there is a need\nfor additional investigations on the ground in several regions."},{"id":"a-hrc-50-63-p0019","rec_id":"recaC5gtNvtAQyAXk","symbol":"A/HRC/50/63","n":"19","seq":19,"section":"B. Scope of investigations","text":"The Mission’s findings described in this report are not exhaustive and should not\npreclude further findings, by this or other accountability mechanisms, that other violations\nand abuses have occurred in Libya since 2016."},{"id":"a-hrc-50-63-p0020","rec_id":"recaC5gtNvtAQyAXk","symbol":"A/HRC/50/63","n":"20","seq":20,"section":"C. Methods of work","text":"Despite encountering several operational difficulties, the Mission was able to gather\na substantial body of evidence and information to support its findings. Consistent with the\npractice of most United Nations fact-finding bodies, the Mission employs the “reasonable\ngrounds to believe” standard in making factual and legal determinations.5"},{"id":"a-hrc-50-63-p0021","rec_id":"recaC5gtNvtAQyAXk","symbol":"A/HRC/50/63","n":"21","seq":21,"section":"C. Methods of work","text":"Over the course of its mandate, the Mission gathered and examined a large amount of\ninformation and evidence through desk-based research, including review of laws and\nregulations, court documents, medical and forensic reports, public calls for submissions,6 in-\nperson and remote interviews, medical examinations by the Mission’s forensic physician, as\nwell as in-person investigative missions. In all its investigative activities, the Mission\nremained guided by the principles of “do no harm”, confidentiality, voluntary participation,\nand informed consent."},{"id":"a-hrc-50-63-p0022","rec_id":"recaC5gtNvtAQyAXk","symbol":"A/HRC/50/63","n":"22","seq":22,"section":"C. Methods of work","text":"Where the Mission found information pointing to the responsibility of an armed force,\narmed group or security force for specific violations, that entity was identified. Where the\nMission established a link between specific acts and alleged perpetrators that would be\nsufficient to warrant future criminal investigations or prosecutions, such evidence was\ncollected and preserved on a strictly confidential basis."},{"id":"a-hrc-50-63-p0023","rec_id":"recaC5gtNvtAQyAXk","symbol":"A/HRC/50/63","n":"23","seq":23,"section":"C. Methods of work","text":"The Mission conducted over 300 interviews since it started operating and organised\neight investigative missions to Libya7 and in third States.8 The Mission regrets not being able\nto travel to Sebha despite its extensive preparations. Given the significant interest in engaging\nwith the Mission expressed by stakeholders there, additional time to conduct this visit would\nallow exploration of crucial investigative opportunities to appropriately address allegations\nof violations in the south."},{"id":"a-hrc-50-63-p0024","rec_id":"recaC5gtNvtAQyAXk","symbol":"A/HRC/50/63","n":"24","seq":24,"section":"C. Methods of work","text":"Throughout its mandate, the Mission made specific efforts to integrate a gender\nmainstreaming lens into its methods of work in line with Resolution 43/39’s emphasis on the\nimpact of violations and abuses on women and the importance of capturing the gendered\ndimensions of such violations and abuses. The Mission also paid specific attention to\nviolations committed against children."},{"id":"a-hrc-50-63-p0025","rec_id":"recaC5gtNvtAQyAXk","symbol":"A/HRC/50/63","n":"25","seq":25,"section":"C. Methods of work","text":"The Mission wishes to express its appreciation to Libyan authorities, United Nations\nentities, civil society organizations, and other States who have provided it with valuable\nassistance. The Mission also wishes to express its deepest gratitude to all who provided it\nwith information, in particular witnesses, victims and their families who consented to share\ntheir traumatic experiences, some of whom were children at the time of the violations."},{"id":"a-hrc-50-63-p0026","rec_id":"recaC5gtNvtAQyAXk","symbol":"A/HRC/50/63","n":"26","seq":26,"section":"A. International humanitarian law violations","text":"In addition to incidents previously investigated by the Mission, such as the 2019\nstrikes against a migrant detention centre in Tajoura and the January 2020 attack against the\nHadaba Military Academy,9 the Mission continued its investigations of alleged violations of\ninternational humanitarian law. These included both direct and indiscriminate attacks on\ncivilians and civilian objects, including homes, health facilities, schools, and cultural\nproperty, failure to respect the principle of proportionality, failure to exercise precaution in\nattack and to protect civilians from the effects of hostilities, and the use of indiscriminate\nweapons. The Mission learned of hundreds of incidents resulting in civilian casualties and/or\nin the destruction or damage of civilian objects. The destruction of essential civilian\ninfrastructure has further impacted on a range of economic, social and cultural rights such as\nthe right to housing, food, water and sanitation, health, and education. The Mission reviewed\ninformation, for instance, regarding the three-month suspension of all health services at the\nWeryemma polyclinic, the only maternal health facility for a population of 48,000 in Tajoura\nmunicipality of Tripoli, after it was hit by grad rockets in April 2020."},{"id":"a-hrc-50-63-p0027","rec_id":"recaC5gtNvtAQyAXk","symbol":"A/HRC/50/63","n":"27","seq":27,"section":"A. International humanitarian law violations","text":"The Mission’s continued investigations of alleged violations of international law that\noccurred within the non-international armed conflict in and around Murzuq in 2019\nuncovered further allegations, including the potential war crimes of forced displacement,\nmurder, and torture. The need for additional investigations of these violations is manifest.\nUnder customary international law, Libya has a duty to investigate war crimes allegedly\ncommitted by its nationals or armed forces, or on its territory, however, few such\ninvestigations have taken place."},{"id":"a-hrc-50-63-p0028","rec_id":"recaC5gtNvtAQyAXk","symbol":"A/HRC/50/63","n":"28","seq":28,"section":"A. International humanitarian law violations","text":"Murzuq drone strikes: The Mission continued to investigate a series of drone strikes\nthat occurred in Murzuq around 4 August 2019 focusing on two LNA strikes that hit an area\nwhere people had gathered in the Blad District/Al Qalaa neighborhood. These strikes resulted\nin at least 43 deaths and 51 wounded, including men, women, and children. The Mission has\nreasonable grounds to believe that the weapon used was a BA-7 Blue Arrow missile launched\nfrom the Wing Loong II unmanned combat air vehicle (UCAV)10 and that the victims were\nnot taking a direct part in hostilities. Although there are indications that some were armed,\nas is common in the south, the Mission found no evidence that those individuals were\npreparing for a specific hostile act. There is also no evidence that the location that was hit\nwas used for military purposes."},{"id":"a-hrc-50-63-p0029","rec_id":"recaC5gtNvtAQyAXk","symbol":"A/HRC/50/63","n":"29","seq":29,"section":"A. International humanitarian law violations","text":"The Mission therefore has reasonable grounds to believe that, in relation to these\nairstrikes, the LNA perpetrated direct attacks on civilians, amounting to war crimes. 11 Even\nif some of the victims were found to have been directly participating in hostilities, there\nwould be reasonable grounds to believe that the attack violated the principle of\nproportionality, in which case the LNA would be considered responsible for violations of\ninternational humanitarian law.12"},{"id":"a-hrc-50-63-p0030","rec_id":"recaC5gtNvtAQyAXk","symbol":"A/HRC/50/63","n":"30","seq":30,"section":"A. International humanitarian law violations","text":"Gharyan Hospital: The Mission examined the alleged execution of 43 LNA wounded\ncombatants inside the premises of Gharyan hospital, on 26 June 2019, reportedly committed\nby GNA forces who had gained control over the city that day. Based on witness and\ndocumentary evidence thus far gathered by the Mission, it could not determine to the requisite\nstandard of proof whether the victims had been killed during combat operations, or whether\nthey were hors de combat at the time of the violations and thus victims of war crimes. These\ngrave allegations merit a full investigation."},{"id":"a-hrc-50-63-p0031","rec_id":"recaC5gtNvtAQyAXk","symbol":"A/HRC/50/63","n":"31","seq":31,"section":"A. International humanitarian law violations","text":"The Mission also takes this opportunity to update the Council on two important\nmatters of grave impact on protracting the conflict and on inflicting indiscriminate harm\nagainst civilians, respectively: violations by mercenaries, private military and security\ncompanies, and foreign fighters, as well as the presence of landmines and unexploded\nordnances. There has been a decrease in the number of foreign fighters and mercenaries in\nLibya, yet a full withdrawal has not yet taken place. 13 Mercenaries in Libya have been\nassociated with violations of international humanitarian law, and the OAU Convention for\nthe Elimination of Mercenarism in Africa considers mercenarism a crime.14 In this regard,\nfurther investigations into such allegations are warranted."},{"id":"a-hrc-50-63-p0032","rec_id":"recaC5gtNvtAQyAXk","symbol":"A/HRC/50/63","n":"32","seq":32,"section":"A. International humanitarian law violations","text":"With respect to landmines and other unexploded ordnances, recent reporting suggests\nthat between May 2020 and March 2022, 130 people died and 196 were injured by mines and\nexplosive devices across Libya, mostly in southern Tripoli, but also in Benghazi, Sirte and\nsouthern Libya.15 The victims, aged 4 to 70, included 299 men and boys, and 26 women and\ngirls. In its October 2021 report, the Mission reported that landmines and other unexploded\nordnances had been found in 35 locations marked on a tablet left behind by the private\nmilitary company Wagner Group in Ain Zara, in locations that had been under the LNA’s\ncontrol and in which Wagner personnel had been present at that time. Further information\ngathered since confirms this conclusion. There are reasonable grounds to believe that Wagner\npersonnel and the LNA violated their international humanitarian law obligations by i) failing\nto take precautions in attack, and failing to minimize the indiscriminate effects of landmines,\nwith respect to laying mines in civilian areas; and ii) by failing to remove them at the end of\nactive hostilities.16"},{"id":"a-hrc-50-63-p0033","rec_id":"recaC5gtNvtAQyAXk","symbol":"A/HRC/50/63","n":"33","seq":33,"section":"B. Deprivation of liberty","text":"As previously reported, the Mission has identified clear patterns of human rights\nviolations and abuses in places of detention, both official and unofficial. While there is no\ncomprehensive official statistical data on Libya’s prisons, the evidence collected by the\nMission over the course of its mandate relates to over 27 such places of detention located in\nthe east and the west of Libya and reportedly holding thousands of inmates, including secret\nand extra-legal prisons.17"},{"id":"a-hrc-50-63-p0034","rec_id":"recaC5gtNvtAQyAXk","symbol":"A/HRC/50/63","n":"34","seq":34,"section":"B. Deprivation of liberty","text":"Based on a substantial body of evidence, including over 80 interviews with former\nand current detainees from the east, west and south of the country, victims’ relatives and\ninsider witnesses, the Mission has reasonable grounds to believe that the crimes against\nhumanity of murder, torture, imprisonment, rape, enforced disappearance and other\ninhumane acts have been committed in several places of detention in Libya since 2016."},{"id":"a-hrc-50-63-p0035","rec_id":"recaC5gtNvtAQyAXk","symbol":"A/HRC/50/63","n":"35","seq":35,"section":"B. Deprivation of liberty","text":"In the more recent period, the Mission focused on four specific armed groups or units\nin control of places of detention of parts thereof: Radaa/Special Deterrence Force, now\nknown as the Deterrence Apparatus for Combating Organized Crime and Terrorism\n(DACOT), the Tarek Bin Ziyad Brigade (TBZ) of the LNA, the Stability Support Apparatus\n(SSA) and the Internal Security Agency (ISA) in the East.18"},{"id":"a-hrc-50-63-p0036","rec_id":"recaC5gtNvtAQyAXk","symbol":"A/HRC/50/63","n":"36","seq":36,"section":"B. Deprivation of liberty","text":"For instance, the Mission has collected over 40 first-hand accounts of widespread\nviolations perpetrated by Radaa in Mitiga, the largest prison in western Libya, estimated to\nhold up to 5,000 detainees. All the victims interviewed testified that they and fellow detainees\nhad been arrested and detained without due process, in contravention of the Libyan Code of\nCriminal Procedure, 19 as well as international law, 20 and subjected to cruel and inhuman\ntreatment as a result of the conditions of detention. Many were detained for prolonged periods,\nsome up to seven years, and been subjected to torture. Some had endured a string of detention\nperiods in multiple prisons controlled by other armed groups, prior to their detention in\nMitiga. Many former detainees remain with psychological and physical scars, including\ndisabilities."},{"id":"a-hrc-50-63-p0037","rec_id":"recaC5gtNvtAQyAXk","symbol":"A/HRC/50/63","n":"37","seq":37,"section":"B. Deprivation of liberty","text":"Many of the victims interviewed have languished in detention, losing years of their\nlives, imprisoned simply because they were perceived to be members or supporters of an\nopposing political or religious ideology or as punishment for the acts of their family members.\nGiven the sheer number of corroborative testimonies obtained, it is highly improbable that\nthis course of conduct is random, accidental, or perpetrated by rogue elements. Mitiga prison\noperates without judicial oversight, and orders of release and acquittal issued by judicial\nauthorities are often not implemented."},{"id":"a-hrc-50-63-p0038","rec_id":"recaC5gtNvtAQyAXk","symbol":"A/HRC/50/63","n":"38","seq":38,"section":"B. Deprivation of liberty","text":"There are reasonable grounds to believe that some of the acts committed in Mitiga\nprison against detainees belonging to or affiliated with the LNA also amount to war crimes\ncommitted in the context of the non-international armed conflict that took place in and around\nTripoli from April 2019 to June 2020, especially when individuals linked to the LNA were\ntortured when its forces advanced on Tripoli."},{"id":"a-hrc-50-63-p0039","rec_id":"recaC5gtNvtAQyAXk","symbol":"A/HRC/50/63","n":"39","seq":39,"section":"B. Deprivation of liberty","text":"The Mission has also collected evidence regarding places of detention run by the SSA.\nThe evidence collected, including testimonies of former detainees, their families, and former\nSSA members provides reasonable grounds to believe that individuals are systematically\narbitrarily detained, forcibly disappeared, and tortured. The Mission found evidence of\nprisoner transfers between secret prisons run by SSA and Mitiga prison, including direct\ntestimonies from detainees recounting how they were first held in secret detention locations\nwhere they were subjected to torture before being moved to Mitiga."},{"id":"a-hrc-50-63-p0040","rec_id":"recaC5gtNvtAQyAXk","symbol":"A/HRC/50/63","n":"40","seq":40,"section":"B. Deprivation of liberty","text":"The Mission investigated several LNA-controlled prisons, including official prisons\nsuch as al-Kwaifiya and Qernada, and extra-legal detention sites run by ISA in the East, and\nby the Tarek Bin Ziyad Brigade, sometimes located within such official prisons. Evidence\ngathered demonstrates the systematic use of prolonged arbitrary detention as well as acts of\nmurder, torture, rape and other inhumane acts against the predominantly civilian populations\nof these prisons, including vulnerable groups. The Mission has reasonable grounds to believe\ncrimes against humanity are occurring in these prisons in the context of a systematic attack\nagainst those suspected of being members of terrorist organizations, or to repress freedom of\nexpression, thought, and association with the aim to silence ideological opponents, journalists,\nactivists and actual or perceived critics of the LNA."},{"id":"a-hrc-50-63-p0041","rec_id":"recaC5gtNvtAQyAXk","symbol":"A/HRC/50/63","n":"41","seq":41,"section":"B. Deprivation of liberty","text":"There are reasonable grounds to believe that the leadership of the aforementioned\ngroups are responsible for these crimes by virtue of their authority and effective control over\nthe direct perpetrators. These groups have a clear and demonstrable hierarchical structure,\ngiving rise to the inference that these crimes have occurred with, at least the tacit approval of\ntheir leadership in Tripoli and in the east. Given the widespread and systematic nature of the\nacts, occurring in defined locations with the same modus operandi, they have known or\nshould have known of the crimes taking place in these places of detention. Nonetheless, and\ndespite the Mission’s two previous reports serving to place these groups on notice,\nperpetrators remain unpunished, and continue to commit violations with total impunity. The\nabsence of security sector reform, and the lack of investigations and prosecutions, perpetuates\nthis cycle of violence. Access to these prisons remains critical to the Mission’s investigations\nand to devising a path to meaningful reform."},{"id":"a-hrc-50-63-p0042","rec_id":"recaC5gtNvtAQyAXk","symbol":"A/HRC/50/63","n":"42","seq":42,"section":"C. Extrajudicial killings","text":"The Mission continued its investigations of extrajudicial killings in relation to\nviolations of the right to life associated with the mass graves discovered in and around\nTarhuna, in western Libya. The Mission found reasonable grounds to believe that the al-\nKaniyat militia was responsible for crimes against humanity against men, women and\nchildren, through imprisonment, enforced disappearance, extermination, torture and\npersecution, committed as part of a widespread and systematic attack on actual and perceived\nopponents and critics and their relatives. Using technological capacities, the Mission\nuncovered new potential locations of mass graves that will be shared as part of technically\nsupporting the Libyan authorities’ accountability efforts and contributing to the victims’ right\nto know the truth. The Mission’s detailed findings on Tarhuna are presented in the conference\nroom paper accompanying this report.21"},{"id":"a-hrc-50-63-p0043","rec_id":"recaC5gtNvtAQyAXk","symbol":"A/HRC/50/63","n":"43","seq":43,"section":"C. Extrajudicial killings","text":"The Mission also documented international crimes committed near al-Abyar,\napproximately 50 kilometres east of Benghazi. On the morning of 26 October 2017, local\nauthorities were alerted to the bodies of 36 men at an execution site. The Mission believes\nthat the men had been systematically arrested and detained without due process by armed\ngroups affiliated with the LNA. These violent abductions occurred at different times during\n2017, from over a month to just the day before the bodies of all 36 victims were discovered.\nFamily members interviewed by the Mission witnessed their relatives being beaten and\nabducted from their homes. Some perpetrators threatened to shoot family members if they\ntried to intervene."},{"id":"a-hrc-50-63-p0044","rec_id":"recaC5gtNvtAQyAXk","symbol":"A/HRC/50/63","n":"44","seq":44,"section":"C. Extrajudicial killings","text":"According to evidence collected by the Mission, including interviews with individuals\nwho first discovered the bodies, and material examined by the Mission’s forensics expert, all\nthe victims were handcuffed, had gunshot wounds, and were lying in fresh pools of blood.\nSome showed signs of torture. Family members interviewed by the Mission verified seeing\nsigns of torture (such as broken ribs, dislocated joints, and significant bruising) and one or\nmore gunshot wounds (primarily to the head, face, and neck areas but also to other body areas)\nwhen they inspected the bodies at the morgue. The victims were all civilians, including a Sufi\nsheikh, perceived members of the Shura Council and Da’esh."},{"id":"a-hrc-50-63-p0045","rec_id":"recaC5gtNvtAQyAXk","symbol":"A/HRC/50/63","n":"45","seq":45,"section":"D. Enforced disappearances","text":"Enforced disappearances are a continuous and complex human rights violation,\nencompassing violations of the right to life, the right not to be subjected to torture or cruel\ntreatment, and the right to liberty. The Mission’s previous reports and more recent\ninvestigations reflect reporting by other United Nations entities and civil society actors that\nthe State widely employs, directly or through affiliated armed groups, enforced\ndisappearances as a tactic to silence critics and intimidate opponents and their families."},{"id":"a-hrc-50-63-p0046","rec_id":"recaC5gtNvtAQyAXk","symbol":"A/HRC/50/63","n":"46","seq":46,"section":"D. Enforced disappearances","text":"The Mission reiterates its great concern regarding the continued disappearance of\nHouse of Representatives member Sihem Sergiwa who was abducted in July 2019 in a LNA\ncontrolled area, with the latter failing to provide information on her fate. There are reasonable\ngrounds to believe that she is a victim of enforced disappearance. Since the establishment of\nthe Mission, there does not appear to have been any developments in the Libyan authorities’\ninvestigation. Her family has the right to know what happened to her, and the authorities in\nBenghazi are under the obligation to disclose to them all available information on the\nprogress of their investigation."},{"id":"a-hrc-50-63-p0047","rec_id":"recaC5gtNvtAQyAXk","symbol":"A/HRC/50/63","n":"47","seq":47,"section":"D. Enforced disappearances","text":"The Mission has collected information on cases of enforced disappearance in Tripoli,\nBenghazi, Murzuq, and elsewhere. Many cases of enforced disappearances documented by\nthe Mission started with violent abductions and arbitrary detention and were frequently\naccompanied by torture and ill-treatment, including the case of Mansour Mahmoud Atti, a\nhuman rights activist, head of the Red Crescent Committee and Civil Society Commission of\nAdjabiyah, and a producer of a popular TV series. On 3 June 2021, Mr. Atti was abducted\nand detained by LNA Brigade 302. His family requested information from the Brigade, to no\navail. In August 2021, the General Command of the LNA finally informed Mr. Atti’s family\nthat they detained him, that he was alive and that he would not be released until after the\nelection set to occur in December 2021. Mr. Atti was subsequently released on 2 April 2022."},{"id":"a-hrc-50-63-p0048","rec_id":"recaC5gtNvtAQyAXk","symbol":"A/HRC/50/63","n":"48","seq":48,"section":"D. Enforced disappearances","text":"The Mission confirmed the manner of his abduction, including that he was blindfolded\nand handcuffed. He was detained, without due process, in a Brigade 302 prison in Ganfouda,\nkept in solitary confinement, and in inhumane conditions. He was never charged nor brought\nbefore a judge. He was then transferred to a prison operated by the Tarek Ben Ziad brigade\nwhere he was arbitrarily detained for approximately six months, in solitary confinement.\nAccordingly, there are reasonable grounds to believe that Mr. Atti was a victim of arbitrary\ndetention, torture and enforced disappearance, in contravention of international human rights\nlaw. His family was also deprived the right to know about his fate and whereabouts until two\nmonths after his abduction."},{"id":"a-hrc-50-63-p0049","rec_id":"recaC5gtNvtAQyAXk","symbol":"A/HRC/50/63","n":"49","seq":49,"section":"D. Enforced disappearances","text":"The emblematic cases of extra-judicial killings and enforced disappearances included\nin this and previous reports highlight how impunity continues to prevail in Libya.\nInvestigations and prosecutions of such gross violations of human rights are urgently needed.\nE.        Sexual and gender-based violence22"},{"id":"a-hrc-50-63-p0050","rec_id":"recaC5gtNvtAQyAXk","symbol":"A/HRC/50/63","n":"50","seq":50,"section":"D. Enforced disappearances","text":"As previously reported, uncovering sexual violence in the Libyan context is a difficult\ntask. However, the Mission has made progress in this respect: the occurrence of sexual and\ngender-based violence was mentioned or addressed in at least 63 interviews conducted by the\nMission over the course of its mandate. The Mission also received information from\norganizations and legal and health professionals who provide assistance to survivors in and\noutside Libya."},{"id":"a-hrc-50-63-p0051","rec_id":"recaC5gtNvtAQyAXk","symbol":"A/HRC/50/63","n":"51","seq":51,"section":"D. Enforced disappearances","text":"Sexual and gender-based violence happens in a multitude of settings, including in the\nfamily, the community, the workplace, the public sphere, in places of detention and in IDP\ncamps. Such violence is committed by state officials, by armed groups and militias, or private\nindividuals, and is fuelled by patriarchy, religious and cultural conservatism as well as sexism,\nmisogyny and homophobia."},{"id":"a-hrc-50-63-p0052","rec_id":"recaC5gtNvtAQyAXk","symbol":"A/HRC/50/63","n":"52","seq":52,"section":"D. Enforced disappearances","text":"Of great concern to the Mission is the fact that the domestic legal framework fails to\nprovide for the protection of survivors of sexual violence, and, at times, exacerbates the\nproblem.23 Similarly, the lack of structures to support survivors of sexual violence, such as\nshelters, needs to be highlighted."},{"id":"a-hrc-50-63-p0053","rec_id":"recaC5gtNvtAQyAXk","symbol":"A/HRC/50/63","n":"53","seq":53,"section":"D. Enforced disappearances","text":"The Mission has identified the deprivation of liberty, including by armed groups\nassociated with the state, weak institutions and prevailing lawlessness as key factors\nfacilitating the occurrence of sexual violence."},{"id":"a-hrc-50-63-p0054","rec_id":"recaC5gtNvtAQyAXk","symbol":"A/HRC/50/63","n":"54","seq":54,"section":"D. Enforced disappearances","text":"The Mission has received consistent reports of male and female detainees in all parts\nof Libya being threatened with sexual violence against them or their relatives, being stripped\nnaked for prolonged periods of time or subjected to intrusive body search amounting to rape.\nIt has also received reports of threats of rape or other sexual violence during interrogation\nand has documented instances of sexualized torture, including electricity being applied to\ngenital areas and rape. The Mission is also concerned by reports of women being arrested\nand subjected to sexual violence, or the threat of it, in order to force male family members to\nhand themselves over."},{"id":"a-hrc-50-63-p0055","rec_id":"recaC5gtNvtAQyAXk","symbol":"A/HRC/50/63","n":"55","seq":55,"section":"D. Enforced disappearances","text":"Several migrants interviewed by the Mission described experiencing sexual violence\nat the hands of traffickers and smugglers, often with the aim of extorting families, as well as\nstate officials in detention centres, employers, or other migrants. The known risk of sexual\nviolence in Libya is such that some migrant women and girls get fitted with a contraceptive\nimplant before travelling there to avoid unwanted pregnancy due to such violence."},{"id":"a-hrc-50-63-p0056","rec_id":"recaC5gtNvtAQyAXk","symbol":"A/HRC/50/63","n":"56","seq":56,"section":"D. Enforced disappearances","text":"The Mission has also documented cases of rape in places of detention or captivity\nwhereby migrant women are forced to have sex in order to survive, in exchange for food or\nother essential items. A coercive environment such as a detention centre negates the ability\nto give consent and such practices amount to rape. A female migrant interviewed by the\nMission, who had been held captive in Ajdabiya, described how her captors demanded sex\nin exchange for access to water she direly needed to wash her six-month old sick child’s\nsoiled clothes. According to the victim: “I let them rape me. I had no choice. It was for my\ndaughter. I could not leave her like that.”"},{"id":"a-hrc-50-63-p0057","rec_id":"recaC5gtNvtAQyAXk","symbol":"A/HRC/50/63","n":"57","seq":57,"section":"D. Enforced disappearances","text":"The Mission received first-hand accounts of individuals being targeted for arrest and\nabuse, including sexual violence, solely because of their sexual orientation, gender identity\nor gender expression. The Mission received such reports from different parts of Libya and\nhas conducted detailed interviews with 10 individuals. Since November 2021, the Mission\nhas also monitored with great concern the arrests of men, including activists, by security\nagencies on the ground of their perceived sexual identity."},{"id":"a-hrc-50-63-p0058","rec_id":"recaC5gtNvtAQyAXk","symbol":"A/HRC/50/63","n":"58","seq":58,"section":"D. Enforced disappearances","text":"In at least three separate cases documented by the Mission over the course of its\nmandate, men and teenagers were accosted or arrested by members of armed groups and their\nmobile phones checked. These men and teenagers ended up in Mitiga prison where they were\nharassed and intimidated. In at least one case documented by the Mission, a young detainee\nhad to undergo forced anal examination. Such examinations have no scientific validity and\namount to torture and other ill-treatment.24"},{"id":"a-hrc-50-63-p0059","rec_id":"recaC5gtNvtAQyAXk","symbol":"A/HRC/50/63","n":"59","seq":59,"section":"D. Enforced disappearances","text":"The emblematic cases highlighted in this and previous reports reveal grave and\nendemic sexual and gender-based violence. The inadequate legal framework and weak\ncapacity for investigations and prosecution exacerbate impunity."},{"id":"a-hrc-50-63-p0060","rec_id":"recaC5gtNvtAQyAXk","symbol":"A/HRC/50/63","n":"60","seq":60,"section":"F. Violations of the rights to freedom of expression, association, peaceful","text":"Civil society organizations are a vital component of any democratic society. Yet, the\nMission’s investigations in Libya reveal a gradually shrinking civic space characterized by\nincreasingly draconian laws and regulations."},{"id":"a-hrc-50-63-p0061","rec_id":"recaC5gtNvtAQyAXk","symbol":"A/HRC/50/63","n":"61","seq":61,"section":"F. Violations of the rights to freedom of expression, association, peaceful","text":"Of great concern is the role played by the Civil Society Commission in the registration\nand oversight on civil society organizations. The Mission has reviewed several statements\nissued by the Tripoli-based Commission. Besides the inflammatory tone of some of them,\nthe Commission’s announcement in April 2022 that organizations that had not sought re-\nregistration were considered shut sent a chilling message to all civil society organizations.\nThe Commission also demanded that prior authorization is obtained before undertaking any\nactivities, participating in conferences, workshops and training even if outside Libya. The\nMission received concerning reports regarding the opening of the Commission’s membership\nto representatives of intelligence agencies and the Central Bank."},{"id":"a-hrc-50-63-p0062","rec_id":"recaC5gtNvtAQyAXk","symbol":"A/HRC/50/63","n":"62","seq":62,"section":"F. Violations of the rights to freedom of expression, association, peaceful","text":"Civil society activists and citizens attempting to exercise their freedom of expression\nare denigrated and vilified online and in statements made by state officials and armed groups.\nThey can be labelled as foreign agents and their religious beliefs, feminist stance and morality\nare questioned. The threats they encounter in the digital space translate into physical violence\noffline."},{"id":"a-hrc-50-63-p0063","rec_id":"recaC5gtNvtAQyAXk","symbol":"A/HRC/50/63","n":"63","seq":63,"section":"F. Violations of the rights to freedom of expression, association, peaceful","text":"Throughout the Mission’s mandate, journalists, members of the legal profession, civil\nsociety organizations and activists, including human rights defenders, have been targeted for\nabduction, arrest, arbitrary detention, torture, including sexual violence, enforced\ndisappearances and even killings. Activists interviewed by the Mission recounted their\nexperience of intimidation, threats and harassment. Some had to leave the country, for\nprolonged periods of time, or to live in exile."},{"id":"a-hrc-50-63-p0064","rec_id":"recaC5gtNvtAQyAXk","symbol":"A/HRC/50/63","n":"64","seq":64,"section":"F. Violations of the rights to freedom of expression, association, peaceful","text":"In a case documented by the Mission, an activist was summoned by ISA in the East\nin 2020, for questioning. During her interrogation which lasted an entire day, the activist was\nasked about the human rights organization she established, their activities, including on\nwomen’s rights and elections, the origin of their funding as well as her travels. She described\nto the Mission having been beaten, asked to remove her shirt and burned with a hot metal rod,\ninsulted and being called “damaged”. Her morality was questioned, and she described having\nbeen sexually harassed. After a day of questioning, she was released. Following her release,\nshe received threats and pornographic messages and images on her phone and Facebook\naccount."},{"id":"a-hrc-50-63-p0065","rec_id":"recaC5gtNvtAQyAXk","symbol":"A/HRC/50/63","n":"65","seq":65,"section":"F. Violations of the rights to freedom of expression, association, peaceful","text":"The Mission also wishes to bring the Council’s attention to the recent arrest and\ndetention by the Tripoli-based ISA of seven young activists, including a migrants’ rights\ndefender.25 Between November 2021 and March 2022, their “confessions” were recorded on\nvideo and posted on the Tripoli-based ISA’s Facebook page and website. In the videos\nreviewed by the Mission and believed to have been obtained under duress, the men\nincriminate themselves and state that they are members of Tanweer (Enlightenment), 26\natheists, agnostics, feminists, and seculars. These videos sent shockwaves among activists,\nwith the Mission also documenting several ensuing cases of activists going into hiding or\nfleeing the country. The Mission has been able to confirm that at least some of the individuals\narrested in the crackdown are currently held in Mitiga Prison. Following their arrests, they\nwere presented to the Office of the Public Prosecutor acting on instruction of the Attorney\nGeneral and are now facing trial on charges of “Promoting actions against the principles and\nvalues of the State” (article 207 of the Penal Code), “Insulting and offending the Islamic\nreligion” (article 291 of the Penal Code) and “Misuse of Internet networks” (article 35 of the\nLaw No. (22) of 2010 on communications). According to information available to the\nMission, some of them were due to stand trial inside Mitiga Prison on 8 June 2022 but were\nnot presented to court."},{"id":"a-hrc-50-63-p0066","rec_id":"recaC5gtNvtAQyAXk","symbol":"A/HRC/50/63","n":"66","seq":66,"section":"F. Violations of the rights to freedom of expression, association, peaceful","text":"The Mission has also received credible information regarding instances of violations\nof press freedom and freedom of expression in the country since 2016, including details on\ncases of arbitrary detentions, extrajudicial killings and other attacks of journalists, as well as\nmedia outlets. In February 2022, the Mission documented the case of an anchor woman who\nwas beaten by a group of young men who warned her that the LNA leadership was a red line\nnot to be crossed. The day before the assault, the TV network for which she worked had\nbroadcast a programme on corruption mentioning the involvement of the inner circle of the\nLNA leadership. In another case, a journalist was abducted in December 2019 at Mitiga\nAirport by the al-Nawasi Brigade, arbitrarily detained and subjected to ill-treatment. After\nfive days, he was presented to the General Attorney on accusations of practicing journalism\nwithout authorisation and having contacts with international organizations without state\npermission. He was released seven days later."},{"id":"a-hrc-50-63-p0067","rec_id":"recaC5gtNvtAQyAXk","symbol":"A/HRC/50/63","n":"67","seq":67,"section":"F. Violations of the rights to freedom of expression, association, peaceful","text":"Finally, in Sirte, the Mission continued to follow with concern successive waves of\nabductions, arrests and arbitrary detentions by armed groups and militias in the context of\nseveral peaceful demonstrations and gatherings."},{"id":"a-hrc-50-63-p0068","rec_id":"recaC5gtNvtAQyAXk","symbol":"A/HRC/50/63","n":"68","seq":68,"section":"F. Violations of the rights to freedom of expression, association, peaceful","text":"These and previous conclusions from the Mission, regarding repeated attacks on\nfreedoms of expression, association and assembly, as well as attacks and threats directed at\nelection candidates, officials and infrastructures cast doubts on the Libyan authorities’ ability\nto guarantee citizens’ rights to participate in public life where individuals are able to seek\nand receive information, peacefully organise with others, discuss public interest issues, run\nfor elections and cast their ballots without intimidation, harassment or threats to their safety."},{"id":"a-hrc-50-63-p0069","rec_id":"recaC5gtNvtAQyAXk","symbol":"A/HRC/50/63","n":"69","seq":69,"section":"G. Migrants","text":"Throughout its mandate, the Mission has reported on widespread and systematic\nhuman rights violations against migrants – a term used to encompass migrants, refugees, and\nasylum seekers. In investigations conducted remotely, in Libya, and in third states, the\nMission has collected significant amounts of evidence, including over 80 interviews of\nmigrants of diverse backgrounds and circumstances, demonstrating that migrants are\nroutinely subjected to gross and systematic human rights violations."},{"id":"a-hrc-50-63-p0070","rec_id":"recaC5gtNvtAQyAXk","symbol":"A/HRC/50/63","n":"70","seq":70,"section":"G. Migrants","text":"Since its first report, the Mission’s investigations provided a strong basis to confirm\nthat acts of murder, enslavement, torture, imprisonment, rape, and other inhumane acts are\ncommitted against migrants. They also show that little has been done by Libyan authorities\nto reform their practices and address these crimes, or by their international partners, including\nItaly and Malta who have cooperation agreements with Libya in the field of migration\ncontrol.27"},{"id":"a-hrc-50-63-p0071","rec_id":"recaC5gtNvtAQyAXk","symbol":"A/HRC/50/63","n":"71","seq":71,"section":"G. Migrants","text":"Over the period covered by the Mission’s mandate, the number of migrants held in\ncentres run by the Directorate for Combatting Illegal Migration (DCIM) has varied from a\ncouple thousands to nearly 20,000, with thousands more believed to be detained in facilities\ncontrolled by non-State armed groups or held captive by traffickers.28 Although the Mission\nobserved positive efforts by the Libyan authorities to conduct raids of places of captivity\noperated by traffickers, migrants are often simply transferred to DCIM facilities where they\ncontinue to be subjected to abuse."},{"id":"a-hrc-50-63-p0072","rec_id":"recaC5gtNvtAQyAXk","symbol":"A/HRC/50/63","n":"72","seq":72,"section":"G. Migrants","text":"The specific involvement and level of cooperation between actors, including state\nauthorities, such as the Libyan Coast Guard (LCG), involved in the interception of migrants\nat sea, and DCIM detention officials, armed groups with unclear official mandates, traffickers,\nsmugglers, and other individuals attempting to profit from this system, have been\ndocumented but not always clearly defined."},{"id":"a-hrc-50-63-p0073","rec_id":"recaC5gtNvtAQyAXk","symbol":"A/HRC/50/63","n":"73","seq":73,"section":"G. Migrants","text":"For instance, in interviews with the Mission, several migrants mentioned collusion\nbetween smugglers, traffickers, and state officials, be it the DCIM or LCG. One of the\nmigrants explained that he recognized the smugglers that had put them on a boat onboard an\nLCG ship that later intercepted them: “this happened to me twice. If we tell them that we\nrecognize them, they beat us.” As previously noted by the Mission, there are also reports that\nmigrants have disappeared after having been intercepted and disembarked in Libya, raising\nconcerns that significant numbers of migrants may have been returned to smugglers and\ntraffickers who further abuse them."},{"id":"a-hrc-50-63-p0074","rec_id":"recaC5gtNvtAQyAXk","symbol":"A/HRC/50/63","n":"74","seq":74,"section":"G. Migrants","text":"The Mission has also collected evidence regarding the role of the SSA, an entity\nalready implicated in gross human rights violations,29 in both the interception of migrants at\nsea and their subsequent detention in the al-Mayah detention centre. Migrants interviewed by\nthe Mission reported being subjected to cruel treatment including undressing during searches,\nbeating by guards, denial of medical care, starvation and enslavement practices in al-Mayah."},{"id":"a-hrc-50-63-p0075","rec_id":"recaC5gtNvtAQyAXk","symbol":"A/HRC/50/63","n":"75","seq":75,"section":"G. Migrants","text":"The Mission has reasonable grounds to believe that crimes against humanity are being\ncommitted against migrants in Libya. Migrants are subjected to widespread and systematic\narbitrary detention. Acts of murder, enforced disappearance, torture, enslavement, sexual\nviolence, rape, and other inhumane acts, are being committed in connection with their\narbitrary detention. The ongoing, systematic and widespread character of these practices by\nDCIM and other actors involved reflects that mid- to senior level officials are participating\nin the migration cycle of violence."},{"id":"a-hrc-50-63-p0076","rec_id":"recaC5gtNvtAQyAXk","symbol":"A/HRC/50/63","n":"76","seq":76,"section":"G. Migrants","text":"Torture and rape are a feature of immigration detention and captivity in Libya,\nroutinely employed as a means of intimidation, punishment, humiliation, gratification, or\nexploitation, with migrants being subjected to electric shocks, extinguishing cigarettes,\nburning, regular beatings, rape and sexual violence against men, women, boys and girls,\nand/or other brutal inflictions of physical and psychological torture, such as witnessing the\nrape or execution of fellow detainees. Many of the female migrants interviewed by the\nMission corroborated that they, including some underage girls, were either raped, witnessed\nsomebody else being raped, or saw fellow female detainees return to their cells in tears after\nbeing taken away by their guards or captors. Some migrant women told the Mission that they\nhad sex with guards and other detention officials in exchange for food, water, or other\nbasics.30 The Mission also received reports of men and boys experiencing sexual violence in\ndetention centres."},{"id":"a-hrc-50-63-p0077","rec_id":"recaC5gtNvtAQyAXk","symbol":"A/HRC/50/63","n":"77","seq":77,"section":"G. Migrants","text":"The Mission received regular reports of enslavement of migrants. In this regard, there\nis ample evidence that migrants are treated like commodities in various ways by their captors.\nWhilst in detention and without receiving compensation, skilled migrants are sometimes\nforced to work outside the detention facility for individuals or companies whereas others,\nincluding unaccompanied children, are forced to work on farms, factories, or other menial\nlabour situations, often without adequate food or water."},{"id":"a-hrc-50-63-p0078","rec_id":"recaC5gtNvtAQyAXk","symbol":"A/HRC/50/63","n":"78","seq":78,"section":"G. Migrants","text":"The SSA’s recent involvement, in the second half of 2021, in migrant detention and\nexploitation highlights how persistent impunity perpetuates cycles of violence and\nencourages new actors to engage in such activities in their pursuit of further legitimacy and\nfunds. Such impunity is further reinforced by the weaknesses in Libya’s institutions, domestic\nlegal framework, and judicial system."},{"id":"a-hrc-50-63-p0079","rec_id":"recaC5gtNvtAQyAXk","symbol":"A/HRC/50/63","n":"79","seq":79,"section":"H. Internally displaced persons","text":"Mass internal displacement from locations like Tripoli, Benghazi, and Misrata caused\nby conflict and persecution have resulted in a number of human rights issues including loss\nof property and livelihood, severe psychological trauma, and high rates of exposure to violent\ncriminality in IDP camps. 31 The Mission also received reports of increased early marriages\namong IDP communities but was not able to obtain specific data."},{"id":"a-hrc-50-63-p0080","rec_id":"recaC5gtNvtAQyAXk","symbol":"A/HRC/50/63","n":"80","seq":80,"section":"H. Internally displaced persons","text":"By January 2022, the International Organization for Migration accounted for 168,011\nIDPs in Libya. Of these, 37,896 are displaced across the five municipalities of Benghazi\nregion, the largest number of IDPs in Libya. A majority of these IDPs in the east face\nprotracted displacement as they have been displaced since 2017 or earlier from areas affected\nby armed conflict.32"},{"id":"a-hrc-50-63-p0081","rec_id":"recaC5gtNvtAQyAXk","symbol":"A/HRC/50/63","n":"81","seq":81,"section":"H. Internally displaced persons","text":"The plight of the Tawergha community, which the Mission previously reported on,\nhas not improved. A survey published in December 2021 concluded that only a “trickle” of\nTawerghans have actually returned and that their homeland was “largely uninhabitable”.33\nThe Mission also learned about the forced eviction of displaced Tawergha families from two\ncamps in early May 2022 following instructions from the Attorney General. On 30 May,\narmed individuals reportedly entered the last remaining Tawergha IDP camp in Tripoli and\ngave its residents an ultimatum to leave within 24 hours."},{"id":"a-hrc-50-63-p0082","rec_id":"recaC5gtNvtAQyAXk","symbol":"A/HRC/50/63","n":"82","seq":82,"section":"H. Internally displaced persons","text":"The Mission previously signalled its intention to investigate the predicament of\ncivilians displaced by the 2019 conflict between the Tebu and the Al-Ahali communities in\nsouthern Libya. The Mission learned that approximately 35,000 civilians, more than half of\nthe local population, were displaced by this conflict, including a near full displacement of\nAl-Ahalis from Murzuq. While the situation has stabilized, tensions between the two groups\nremains and has hindered the return of IDPs. According to sources on the ground, and despite\nexplicit provisions on the matter, peacebuilding and reconciliation agreements agreed to by\nboth sides in February and March 2022 have not yet resulted in the return of IDPs to the area."},{"id":"a-hrc-50-63-p0083","rec_id":"recaC5gtNvtAQyAXk","symbol":"A/HRC/50/63","n":"83","seq":83,"section":"H. Internally displaced persons","text":"The Mission believes that displacement presents a serious yet underappreciated\nhuman rights issue that is negatively affecting efforts to forge stability in Libya, as well as\ninhibiting the country’s efforts to transition to democracy and the rule of law. The possibility\nfor IDP populations to have their voices heard during any upcoming elections is critical in\nthis regard.34 Libya should take appropriate steps to provide comprehensive solutions to the\nmany challenges IDPs currently encounter in Libya."},{"id":"a-hrc-50-63-p0084","rec_id":"recaC5gtNvtAQyAXk","symbol":"A/HRC/50/63","n":"84","seq":84,"section":"I. Women and girls","text":"Women and girls in Libya have been confronted with a barrage of challenges and\nobstacles that victimize them and prevent them from fully enjoying their human rights and\nmeaningfully participating in public life. Over the course of the Mission’s mandate, the\nsituation has been compounded by the militarization of Libya, the proliferation of armed\ngroups and their increasing power, as well as the weakening of state institutions."},{"id":"a-hrc-50-63-p0085","rec_id":"recaC5gtNvtAQyAXk","symbol":"A/HRC/50/63","n":"85","seq":85,"section":"I. Women and girls","text":"While some positive developments such as the establishment of two dedicated courts\nfor cases of violence against women and children are to be noted,35 violence against women\nremains vastly underreported, due to factors ranging from cultural/societal and legal hurdles\nto a lack of trust in state institutions such as the police and the judiciary."},{"id":"a-hrc-50-63-p0086","rec_id":"recaC5gtNvtAQyAXk","symbol":"A/HRC/50/63","n":"86","seq":86,"section":"I. Women and girls","text":"The Mission found that the very term of “feminist” has not only become a slur but\nalso a ground for investigation and arrest, including by the Tripoli-based ISA. For example,\nin all the videoed confessions reviewed by the Mission with respect to the case of the seven\nyoung activists arrested between November 2021 and March 2022 and mentioned above, 36\nthe men were forced to confess they were feminists or interested in feminism, among other\nthings. In another case documented by the Mission, in which a young activist was abducted\nand disappeared for over two years, and subjected to ill-treatment and torture in detention,\nthe victim explained to the Mission that part of his interrogators’ focus was on his perceived\nefforts to “liberate women”."},{"id":"a-hrc-50-63-p0087","rec_id":"recaC5gtNvtAQyAXk","symbol":"A/HRC/50/63","n":"87","seq":87,"section":"I. Women and girls","text":"Online, the increasing use of platforms and applications has provided spaces and\nmeans for women to freely receive information, express their views, organise and assert\nthemselves in Libya’s public life. However, it has also turned into a potent tool to\ndelegitimize them and their activism, terrorize and silence them. 37 Violence online often\ninduces self-censorship, silencing, and leads to psychological harm, if not physical\nviolence.38"},{"id":"a-hrc-50-63-p0088","rec_id":"recaC5gtNvtAQyAXk","symbol":"A/HRC/50/63","n":"88","seq":88,"section":"I. Women and girls","text":"The Mission has reviewed several threatening and denigrating messages received by\nwomen activists and public figures via WhatsApp, Club House, Messenger and Facebook. It\nwas also informed of the existence of dedicated rooms on Club House or Facebook pages\nwhich impersonate women activists and contain provocative political statements, which in\nthe polarized context of Libya, can endanger their lives. In a December 2021 report, Meta\nidentified the creation of Facebook Pages purporting to be run by Libyan female public\nfigures “to make inflammatory statements on their behalf”, likely to encourage harassment.39\nIn this respect, women shared with the Mission their frustration that social media companies\ndo not sufficiently moderate debates or proactively monitor them. They also mentioned the\nneed for social media platforms to have Arabic speakers in their teams, specifically people\nwho understand the Libyan context and dialect to truly grasp the nature and seriousness of\nthreats levelled against them. The Mission reviewed several messages in which harassers\nused a mix of Arabic and English letters, signs and numbers to avoid detection by content\nmoderation algorithms."},{"id":"a-hrc-50-63-p0089","rec_id":"recaC5gtNvtAQyAXk","symbol":"A/HRC/50/63","n":"89","seq":89,"section":"I. Women and girls","text":"Women have sometimes been targeted for killing or arrest for their political beliefs.\nOn such case is that of Iftikhar Boudraa who was sentenced, on appeal, to 10 years in prison,\nfor social media posts critical of LNA leadership. She and her family had been abducted from\nher home in November 2018 by the ISA in the East. Reports received by the Mission indicate\nthat she has been subjected to torture and ill-treatment in al-Kwaifiya prison where she is\ndetained. The Mission sought clarification from the authorities in the east about her case, to\nno avail."},{"id":"a-hrc-50-63-p0090","rec_id":"recaC5gtNvtAQyAXk","symbol":"A/HRC/50/63","n":"90","seq":90,"section":"I. Women and girls","text":"Finally, as Libya finds itself at a critical juncture with presidential and parliamentary\nelections still due to take place, the Mission considers that the continued impunity for the\nenforced disappearance of Sihem Sergiwa 40 serves as a cautionary tale to any woman seeking\nto be elected. These concerns are heightened by reports that women candidates for local,\nparliamentary and presidential elections were threatened, including online; a concern HNEC\nrepresentatives also shared with the Mission."},{"id":"a-hrc-50-63-p0091","rec_id":"recaC5gtNvtAQyAXk","symbol":"A/HRC/50/63","n":"91","seq":91,"section":"J. Children","text":"Throughout its mandate, the Mission has collected evidence demonstrating that\nchildren up to the age 18 have been subjected to similar human rights violations as adults,\nincluding abductions, summary executions, arbitrary detentions and torture in direct\ncontradiction with Libya’s obligations under international law, including to respect and\nprotect children's rights under the Convention on the Rights of the Child and the African\nCharter on the Rights and Welfare of the Child."},{"id":"a-hrc-50-63-p0092","rec_id":"recaC5gtNvtAQyAXk","symbol":"A/HRC/50/63","n":"92","seq":92,"section":"J. Children","text":"The Mission has collected substantial evidence, including testimonies from direct\nvictims and eyewitnesses, of children arbitrarily detained and being held in detention\nalongside adults. Such detention exposed them to further abuses, particularly of a sexual\nnature including in al-Kwaifiya, Qernada, Mitiga, al-Jawiyyah, Rajma and Sidi Frej prisons.\nIn an interview that included an examination by the Mission’s forensic doctor, a young man\nexplained that he was arrested when he was 15-years old in Benghazi in early 2016 for\npresumed links to a terrorist organization. He was made to confess under torture and then\ndetained in al-Kwaifiya prison. During the six years he spent in detention, he was deprived\nof an education, was held for long periods in solitary confinement or together with adults and\nwas subjected to torture."},{"id":"a-hrc-50-63-p0093","rec_id":"recaC5gtNvtAQyAXk","symbol":"A/HRC/50/63","n":"93","seq":93,"section":"J. Children","text":"The Mission also collected information relating to the prolonged detention of children\nunder the age of 15 solely because of their parents’ alleged association with Da’esh. As of\nMarch 2022, at least 64 children aged between 1 and 15 years old were held together with\ntheir mothers who remain detained without charges since 2016, in Mitiga, al-Jawiyyah and\nal-Kwaifiya prisons."},{"id":"a-hrc-50-63-p0094","rec_id":"recaC5gtNvtAQyAXk","symbol":"A/HRC/50/63","n":"94","seq":94,"section":"J. Children","text":"In the context of migration, the Mission found that, like adults, child migrants are\nvictimized by State and non-State actors. The Mission also received information about\nmigrant boys who were victims of forced labour and compelled to drive boats to Europe, a\nform of exploitation amounting to trafficking, after which they were detained in Italy on the\ngrounds of facilitating migrant smuggling. The Mission considers the recent establishment\nof a committee, which includes the Ministry of Social Affairs, specifically tasked to set up a\nshelter for migrant women and children41 as a promising development, as long as it meets the\nrequired minimum standards for childcare, and women and children are free to leave the\nshelter if they so wish."},{"id":"a-hrc-50-63-p0095","rec_id":"recaC5gtNvtAQyAXk","symbol":"A/HRC/50/63","n":"95","seq":95,"section":"J. Children","text":"The substantive evidence collected by the Mission throughout its mandate,\ndemonstrates that violations against children are rampant and deserve more extensive\ninvestigations."},{"id":"a-hrc-50-63-p0096","rec_id":"recaC5gtNvtAQyAXk","symbol":"A/HRC/50/63","n":"96","seq":96,"section":"K. Minorities","text":"Over the course of its mandate, the Mission investigated the situation of minorities in\nLibya who continue to be subjected to discriminatory practices and violations."},{"id":"a-hrc-50-63-p0097","rec_id":"recaC5gtNvtAQyAXk","symbol":"A/HRC/50/63","n":"97","seq":97,"section":"K. Minorities","text":"Activists from Amazigh, Tebu and Tuareg minorities have told the Mission of their\ndifficulties in exercising their cultural and linguistic rights, as well as in accessing health,\neducation and political representation, in particular for individuals with “Undetermined Legal\nStatus” (ULS). ULS individuals do not have access to birth certificates, national identity\nnumbers, or family book, and are denied Libyan nationality."},{"id":"a-hrc-50-63-p0098","rec_id":"recaC5gtNvtAQyAXk","symbol":"A/HRC/50/63","n":"98","seq":98,"section":"K. Minorities","text":"The Mission also found that the demolition of the Zawiyat Bin Issa Sufi shrine in Sirte\non the morning of 5 February 2020, on which it previously reported,42 formed part of a wider\npattern of discrimination and attacks against Sufism. Throughout Libya, armed groups\nmotivated by zealous religious ideology have attacked Sufi religious sites and cultural\nproperty, as well as abducted or otherwise illegally arrested and detained Sufi followers. On\nthe day of the attack, for instance, 23 to 25 Sufi people who had gone to the site of the\ndestruction, including elderly sheikhs, were arbitrarily arrested and detained for seven days.\nThe Mission also learned that some of them then decided to flee Sirte out of fear."},{"id":"a-hrc-50-63-p0099","rec_id":"recaC5gtNvtAQyAXk","symbol":"A/HRC/50/63","n":"99","seq":99,"section":"K. Minorities","text":"The Mission reiterates its conviction that protection, inclusivity and representation of\nall voices are essential if Libya is committed to achieving a truly meaningful reconciliation."},{"id":"a-hrc-50-63-p0100","rec_id":"recaC5gtNvtAQyAXk","symbol":"A/HRC/50/63","n":"100","seq":100,"section":"VI. Transition to accountability and reconciliation","text":"Libyans have made it clear to the Mission that they want peace, justice and\nreconciliation. To achieve these aims, such a transition must take the form of a sustainable\nprocess that results in ending impunity, guaranteeing the independence of the judiciary and\nensuring effective State oversight over the security sector.\nAccountability"},{"id":"a-hrc-50-63-p0101","rec_id":"recaC5gtNvtAQyAXk","symbol":"A/HRC/50/63","n":"101","seq":101,"section":"VI. Transition to accountability and reconciliation","text":"In its three reports, the Mission has reported on serious violations of international\nhuman rights law and international humanitarian law, some of which amount to crimes under\ninternational law. It has made repeated calls for relevant authorities to conduct prompt\ninvestigations, compliant with international standards, into alleged violations and to\nprosecute those responsible."},{"id":"a-hrc-50-63-p0102","rec_id":"recaC5gtNvtAQyAXk","symbol":"A/HRC/50/63","n":"102","seq":102,"section":"VI. Transition to accountability and reconciliation","text":"Challenges in ensuring accountability and achieving transitional justice in Libya are\nmultifaceted. In this respect, the adoption of a permanent Constitution and legislation\nconsistent with international human rights law are key to ensuring a future for Libya based\non justice, national reconciliation, respect for human rights and the rule of law, and\nguarantees of non-reoccurrence.\nAdministration of justice"},{"id":"a-hrc-50-63-p0103","rec_id":"recaC5gtNvtAQyAXk","symbol":"A/HRC/50/63","n":"103","seq":103,"section":"VI. Transition to accountability and reconciliation","text":"The Mission’s investigations reveal that many Libyan judges are willing and\ndetermined to facilitate the prevalence of the rule of law in Libya. However, many Libyan\njudges reported to the Mission a real sense of fear due to threats and intimidations from armed\ngroups. Judges and members of the legal profession should be protected, and strong\nguarantees should be in place to allow the judiciary to administer the law independently and\nfree from threats and violence."},{"id":"a-hrc-50-63-p0104","rec_id":"recaC5gtNvtAQyAXk","symbol":"A/HRC/50/63","n":"104","seq":104,"section":"VI. Transition to accountability and reconciliation","text":"In a context characterized by division and polarization, the fact that the Libyan\njudiciary remains largely unified, with judges and prosecutors operating under the authority\nof a single Supreme Judicial Council and applying the same Penal Code and Code of Criminal\nProcedure, is a positive aspect. Similarly, the unity of the Libyan Bar Association should be\nacknowledged."},{"id":"a-hrc-50-63-p0105","rec_id":"recaC5gtNvtAQyAXk","symbol":"A/HRC/50/63","n":"105","seq":105,"section":"VI. Transition to accountability and reconciliation","text":"The Libyan judiciary has showed on several occasions a sincere will to assert its\nindependence and many judges are keen to defend an effective and impartial unified judiciary.\nHowever, the Libyan justice system does not currently appear to have the means or capacity\nto conduct prompt, independent and impartial investigations, as evidenced by the many cases\ndocumented by the Mission characterized by an inability to prosecute those responsible in\naccordance with international human rights standards."},{"id":"a-hrc-50-63-p0106","rec_id":"recaC5gtNvtAQyAXk","symbol":"A/HRC/50/63","n":"106","seq":106,"section":"VI. Transition to accountability and reconciliation","text":"Courts in Libya are effectively non-functional in numerous places, with justice actors\nfacing continuing intimidation, death threats and other forms of violence, especially by non-\nstate actors. The Mission has documented instances where members of the judiciary were\nsubjected to attacks, including abduction and arbitrary detention. For instance, the Mission\nwishes to bring the attention of the Council to the recent arrest, on 22 May 2022, of the Head\nof Military Anti-Terrorism Prosecution, by DACOT on no apparent or stated legal grounds,\nwhich prompted his colleagues from the Military Prosecutor’s Office to issue a statement\nannouncing the suspension of their work. The ensuing environment of fear and intimidation\nhas severely undermined the criminal justice system, resulting in lack of investigation and\nprosecution of crimes.\nSecurity Sector Reform"},{"id":"a-hrc-50-63-p0107","rec_id":"recaC5gtNvtAQyAXk","symbol":"A/HRC/50/63","n":"107","seq":107,"section":"VI. Transition to accountability and reconciliation","text":"Important institutional changes in the form of Security Sector Reform are vital for\nguarantees of non-recurrence of atrocities. In a context characterized by the proliferation of\nweapons and significant power entrusted to armed groups and militias to perform law\nenforcement functions, it is essential to ensure that the Libyan State remains the sole\nlegitimate holder of power through effective Security Sector Reform.\nReconciliation"},{"id":"a-hrc-50-63-p0108","rec_id":"recaC5gtNvtAQyAXk","symbol":"A/HRC/50/63","n":"108","seq":108,"section":"VI. Transition to accountability and reconciliation","text":"The Mission followed up on several reconciliation initiatives in Libya and reiterates\nits strong support for the Libyan people in this regard. People in Libya have a right to live in\npeace, without divisions, in a society free from instability, violence, and insecurity.\nReconciliation can only be achieved through a holistic and inclusive transitional justice\nprocess. Such a process needs to be sustainable and rooted in accountability, truth-telling,\nreparation for the victims, a strong independent judiciary and a reformed security sector under\nthe control of the State. The Mission believes that the development of a National Human\nRights Plan of Action can aid this process."},{"id":"a-hrc-50-63-p0109","rec_id":"recaC5gtNvtAQyAXk","symbol":"A/HRC/50/63","n":"109","seq":109,"section":"VII. Conclusions and recommendations","text":"Urgent remedial action is required to allow for victims in Libya the possibility to\nrealize their rights to truth, justice, and reparations. Libya’s request for the Mission to\nassist national authorities in their efforts to investigate human rights violations during\nthe past six years in Libya reflects a welcomed willingness by the Libyan government.\nThe Mission supports Libyan efforts to maintain the unity of the judicial sector and\nremains ready to assist in ensuring its independence despite the challenges."},{"id":"a-hrc-50-63-p0110","rec_id":"recaC5gtNvtAQyAXk","symbol":"A/HRC/50/63","n":"110","seq":110,"section":"VII. Conclusions and recommendations","text":"All previous recommendations made by the Mission43 remain relevant and must\nbe implemented if there is to be any reasonable prospect of a future Libya based on\njustice, national reconciliation, respect for human rights and the rule of law."},{"id":"a-hrc-50-63-p0111","rec_id":"recaC5gtNvtAQyAXk","symbol":"A/HRC/50/63","n":"111","seq":111,"section":"VII. Conclusions and recommendations","text":"In addition, the Mission calls on Libya to:\n(a)    Adopt a holistic National Human Rights Plan of Action to address all\nfindings and recommendations from the Mission and other human rights bodies, ensure\na sustainable transition to peace, democracy and full respect for human rights and\ncommit to inclusive reconciliation pledging to ‘Leave No one Behind’;\n(b)   Take all necessary measures to fight impunity and develop a\ncomprehensive agenda on transitional justice and accountability including by ensuring\nprompt, thorough and effective investigations of allegations of violations by\nindependent and impartial judicial bodies;\n(c)    Adopt and implement a comprehensive vetting program and ensure that\nthose reasonably suspected of crimes under international law and serious human rights\nviolations do not remain, or are not placed, in positions where they could continue to\ncommit such crimes;\n(d)   Strengthen unified State-building activities, with a focus on building\ninclusive and integrated institutions, effective law enforcement agencies under the sole\npurview of the Libyan State, and an independent and impartial justice sector;\n(e)    Address urgently the proliferation and legitimization of armed groups\nthat are acting as separate islands of control in Libya, outside the State’s authority, and\nestablish strong programmes of disarmament, demobilization and reintegration;\n(f)    Create a safe, inclusive and enabling environment for all civil society\nstakeholders, including women, minorities and vulnerable groups, to be able to fully\nparticipate in political and public life, including elections;\n(g)   Accelerate efforts to remove landmines and other unexploded ordnances,\nincluding by allocating resources to mine action activities, and facilitating relevant\nnational and international efforts;\n(h)    Ensure that all prisons and detention facilities are brought under the\nsupervision of the judiciary and the effective control of the Ministry of Justice; ensure\nrespect for due process, immediately release those who are arbitrarily detained and\nensure respect of all rights of detainees, such as the right not to be subjected to torture\nand cruel treatment, including sexual violence;\n(i)    Take effective action to eliminate sexual and gender-based violence\nincluding by lifting legal and structural barriers preventing its reporting, providing\nrehabilitation services and access to justice for victims, publicly condemning all such\nforms of violence and holding perpetrators of sexual and gender-based violence to\naccount;\n(j)   Ensure the protection of journalists, members of the legal profession, civil\nsociety organizations and activists, including human rights defenders, from harassment,\nintimidation and acts of violence both online and offline, and hold the perpetrators of\nsuch acts accountable;\n(k)   Amend Law No. 19 of 2010 to end the automatic and arbitrary detention\nof migrants, asylum seekers and refugees, and decriminalise irregular migration;\nensure that all migrants detained are held in detention centres with government\noversight, are provided with adequate conditions and are protected from torture and\nother cruel treatment, sexual violence and exploitation, as well as forced labour; protect\nspecific groups, such as women and children, by ensuring that women are held in\nfacilities with adequately trained women guards, and children separately from\nunrelated adults;\n(l)    Ratify the African Union Convention for the Protection and Assistance of\nInternally Displaced Persons in Africa and establish a national plan for the safe return\nand reintegration of the internally displaced to their homes and land according to the\nGuiding Principles on Internal Displacement, the Pinheiro principles and international\nhuman rights standards; and\n(m) Comply as a matter of priority with its obligations to promote and protect\nthe rights of children, with particular regard to its obligations under the Convention on\nthe Rights of the Child and the African Charter on the Rights and Welfare of the Child."},{"id":"a-hrc-50-63-p0112","rec_id":"recaC5gtNvtAQyAXk","symbol":"A/HRC/50/63","n":"112","seq":112,"section":"VII. Conclusions and recommendations","text":"The Mission calls on the international community and the United Nations to:\n(a)    Provide technical support and capacity building to support Libya’s\ndevelopment and implementation of a holistic National Human Rights Plan of Action\naddressing all findings and recommendations from the Mission and other human rights\nbodies to ensure compliance with Libya’s international human rights obligations;\n(b)    Provide support to transitional justice mechanisms that are compliant\nwith international standards and assistance to strengthen the capacity of the justice and\nrelated sectors;\n(c)  Provide support to disarmament, demobilization and reintegration\nprogrammes compliant with international human rights standards; and\n(d)     Call on states to exercise universal jurisdiction to arrest and prosecute\nperpetrators who are found on their territories and accused of committing the\ninternational crimes documented in the Mission’s reports;"},{"id":"a-hrc-50-63-p0113","rec_id":"recaC5gtNvtAQyAXk","symbol":"A/HRC/50/63","n":"113","seq":113,"section":"VII. Conclusions and recommendations","text":"The Mission finally calls on all social media platforms active in Libya, including\nmessaging systems, to:\n(a)    Exercise greater due diligence in combating and prohibiting incitement to\nhatred and human rights violations, particularly against activists, human rights\ndefenders, women, minorities and vulnerable groups."},{"id":"a-hrc-50-crp-3-u0000","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":null,"seq":0,"section":null,"text":"Summary\nBetween 2015 and 2020, the al-Kaniyat militia ruled Tarhuna through a campaign of\nterror and intimidation against, and killing of, the inhabitants of this town. The militia\nterrorized the local population, primarily targeting those who they perceived as opposition\nor a threat. Based on extensive evidence, the Independent Fact-Finding Mission on Libya\nfound reasonable grounds to believe that members of the al-Kaniyat militia committed a\nnumber of crimes against humanity through underlying acts of murder, extermination,\nimprisonment, torture, persecution on political grounds, enforced disappearance and other\ninhumane acts, and war crimes. Significantly, the Mission was recently able to identify three\nlocations of possible undiscovered mass graves and wishes to extend its technical assistance\nto the Libyan authorities to utilize these findings in search for buried victims. Many of the\natrocities documented by the Mission in this conference room paper have a continuing impact\non the victims and the citizens of Tarhuna and Libya. The victims have addressed a clear\nmessage to the Mission demanding truth, justice, reparation, and peace. Those responsible\nfor these violations and crimes in Tarhuna must be held accountable.","unnumbered":true},{"id":"a-hrc-50-crp-3-p0001","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"1","seq":1,"section":"I. Introduction","text":"On 22 June 2020, at the request of the Government of Libya, the Human Rights\nCouncil adopted resolution 43/39 requesting the United Nations High Commissioner for\nHuman Rights to establish and dispatch a fact-finding mission to Libya.1 On 22 August 2020,\nthe High Commissioner announced the appointment of Mohamed Auajjar, of Morocco, Tracy\nRobinson, of Jamaica, and Chaloka Beyani, of Zambia and the United Kingdom of Great\nBritain and Northern Ireland, as the members of the Independent Fact-Finding Mission on\nLibya, hereinafter referred to as the Mission, with Mr. Auajjar as Chair."},{"id":"a-hrc-50-crp-3-p0002","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"2","seq":2,"section":"I. Introduction","text":"The Mission was mandated to establish, in an independent and impartial manner, the\nfacts and circumstances of the human rights situation throughout Libya, to document alleged\nviolations and abuses of international human rights law and international humanitarian law\nby all parties in Libya since the beginning of 2016, including any gendered dimensions, and\nto preserve evidence with a view to ensuring that perpetrators of violations and abuses are\nheld accountable. In October 2021, the Mission presented its first written report to the\nCouncil.2 By resolution 48/25 adopted on 13 October 2021, the Council then extended the\nMission’s mandate to 30 June 2022. It requested the Mission to present both a follow-up\nreport of its findings at the Council’s forty-ninth session, and at the fiftieth session, a\ncomprehensive report on the situation of human rights in Libya, including on efforts to\nprevent and ensure accountability for human rights violations and abuses and with\nrecommendations for follow-up.3 In March 2022, the Mission presented its follow-up report.4\nThe present Conference Room Paper is supplementary to the comprehensive report presented\nduring the Human Rights Council’s fiftieth session5 and presents the Mission’s detailed\nfindings on the situation in Tarhuna since 2016."},{"id":"a-hrc-50-crp-3-p0003","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"3","seq":3,"section":"I. Introduction","text":"The allegations of atrocity crimes in the town of Tarhuna warranted a particular focus\ndue to their gravity, the level of victimization and suffering inflicted on the victims, the\ndiscovery of mass graves, and the widespread and systematic nature of the crimes committed.\nThe crimes committed in Tarhuna have been addressed in the Mission’s first report,6 its\nfollow-up report7 and its comprehensive report.8 Yet the Mission considered that a thorough\nfocused investigation should be conducted in order to contribute to efforts towards\nuncovering the whole truth, including the fate and whereabouts of the missing persons,\nattributing responsibility, and ensuring guarantees of non-recurrence, in order to prevent such\natrocities from happening again in Libya."},{"id":"a-hrc-50-crp-3-p0004","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"4","seq":4,"section":"II. Methodology","text":"The Mission follows the best practices and methodologies for human rights fact-\nfinding,9 adhering at all times to the principles of “do no harm”, independence, impartiality,\nobjectivity, transparency, and integrity."},{"id":"a-hrc-50-crp-3-p0005","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"5","seq":5,"section":"II. Methodology","text":"In keeping with resolution 43/39, in which the Human Rights Council requested the\nMission to conduct its investigations in an independent and impartial manner, the Mission\nestablished its own investigative priorities. It did not seek approval or instructions from any\nexternal stakeholders at any stage of its work. The investigations also focused on all actors\ninvolved without distinction. The Mission considered the events of Tarhuna to be a priority\narea of investigation. It conducted two site visits in July 2021 and May 2022, interviewed\nwitnesses as well as representatives of governmental authorities and non-governmental\norganizations, gathered documentary evidence, including forensic reports and satellite\nimagery and conducted site visits of mass graves and places of detention in Tarhuna."},{"id":"a-hrc-50-crp-3-p0006","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"6","seq":6,"section":"II. Methodology","text":"The Mission considered information from a variety of sources, including interviews\nwith victims and other witnesses; summaries of accounts and analytical data included in\nreports of the United Nations and other reliable stakeholders, including NGOs and media;\ninvestigators’ direct observations during site visits; information provided by the Libyan\nauthorities, other States and reliable stakeholders working on Libya; authenticated satellite\nimagery and audio-visual material; and verified open-source material. Further to a call for\nsubmissions issued on 25 January 2021 and again on 14 December 2021, civil society\norganizations and lawyers representing victims filed with the Mission information relevant\nto the areas under investigation."},{"id":"a-hrc-50-crp-3-p0007","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"7","seq":7,"section":"II. Methodology","text":"Choosing Tarhuna as a focus of its investigations for this Conference Room Paper is\nin line with the Mission’s investigation scope as it fulfils two of its three criteria of selection.10\nIn this respect, the Mission wishes to bring the attention of the Council to: i) the grave,\nwidespread and systematic character of the violations that occurred in Tarhuna; and ii) the\nnature of violations, abuses and crimes committed against vulnerable groups who were\nsubjected to multiple forms of victimization in Tarhuna."},{"id":"a-hrc-50-crp-3-p0008","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"8","seq":8,"section":"II. Methodology","text":"Tarhuna was a major site of alleged violations that took place since 2016, which the\nMission investigated in line with its temporal mandate. Some incidents occurring prior to this\nperiod were investigated where, for instance, a longer-term perspective was necessary to\nunderstand a pattern of violations, and the policy and modus operandi of the perpetrators.\nFurthermore, many of the enforced disappearances documented commenced before 2016\nand, as continuing crimes, are thus falling within the Mission’s temporal mandate."},{"id":"a-hrc-50-crp-3-p0009","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"9","seq":9,"section":"II. Methodology","text":"Where the Mission established a link between specific acts and alleged perpetrators\nthat would be sufficient to warrant future criminal investigations or prosecutions, such\nevidence was collected and preserved on a strictly confidential basis."},{"id":"a-hrc-50-crp-3-p0010","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"10","seq":10,"section":"A. Standard of Proof","text":"Consistent with the practice of most United Nations fact-finding bodies, the Mission\nemploys the “reasonable grounds to believe” standard in making factual determinations on\nindividual cases, incidents and patterns of conduct. The standard is considered met when a\nsufficient and reliable body of primary information, consistent with other information, would\nallow an ordinarily prudent person to reasonably conclude that a case, incident or pattern of\nconduct occurred. This standard of proof is lower than that required in criminal proceedings."},{"id":"a-hrc-50-crp-3-p0011","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"11","seq":11,"section":"A. Standard of Proof","text":"Individual cases or incidents contained in this Conference Room Paper are based on\nat least one credible source of first-hand information, which was independently corroborated\nby at least another credible source of information. Where the report describes patterns of\nconduct, these are based on multiple credible sources of first-hand information, which are\nconsistent with and corroborated by the overall body of credible information collected. In the\nfew instances where this standard was not met – but the Mission still considered it appropriate\nto include the information – this is stated explicitly."},{"id":"a-hrc-50-crp-3-p0012","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"12","seq":12,"section":"A. Standard of Proof","text":"In cases of torture or sexual and gender-based violence, where a second independent\nsource of information was often unavailable, the Mission considered the case or incident\ncorroborated when it obtained one first-hand account which it assessed as credible and\nconsistent with what was known about the incident or the established patterns of similar\nincidents within the circumstances."},{"id":"a-hrc-50-crp-3-p0013","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"13","seq":13,"section":"A. Standard of Proof","text":"Assessment of the validity of the information was separate from the assessment of its\nreliability and credibility. The Mission did not assume that a credible and reliable source\nwould necessarily provide accurate and valid information. Where this report refers to the\naccount of a witness, the Mission has accepted the statement as assessed and described to be\ntruthful and relevant, unless stated otherwise."},{"id":"a-hrc-50-crp-3-p0014","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"14","seq":14,"section":"A. Standard of Proof","text":"The Mission made its own assessment of the credibility and reliability of sources, even\nwhen they were introduced by reliable intermediaries. All sources relied upon in the present\npaper were deemed to be credible and reliable."},{"id":"a-hrc-50-crp-3-p0015","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"15","seq":15,"section":"B. Challenges faced in collecting evidence","text":"The security situation did not provide for a safe space to hold in-person meetings with\nall victims and witnesses. The Mission therefore conducted some of the interviews using\nother means of communication through secure channels."},{"id":"a-hrc-50-crp-3-p0016","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"16","seq":16,"section":"B. Challenges faced in collecting evidence","text":"As discussed in its previous reports to the Human Rights Council, the Mission faced\nconsiderable challenges with respect to the collection of relevant evidence in and from Libya.\nThese included problems caused by evolving security concerns, access to pertinent locations\nor individuals, changing political dynamics, and layers of bureaucracy, among others."},{"id":"a-hrc-50-crp-3-p0017","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"17","seq":17,"section":"B. Challenges faced in collecting evidence","text":"With respect to state authorities seized of the Tarhuna file, the Mission has requested\nassistance and information from the Libyan authorities in Tripoli and Benghazi at various\ntimes in 2021 and 2022. In July 2021, the Mission requested and obtained assistance from\nthe Ministry of Foreign Affairs, the Ministry of Justice and the Ministry of Interior for a site\nvisit to Tarhuna. The Mission thanks these authorities for their cooperation, as well as the\nOffice of the Military Prosecutor in Benghazi who provided it with useful information. The\nMission requested similar assistance in April 2022 from the Ministries of Foreign Affairs and\nJustice for another site visit which took place during the Mission’s investigative mission to\nTripoli in May 2022."},{"id":"a-hrc-50-crp-3-p0018","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"18","seq":18,"section":"B. Challenges faced in collecting evidence","text":"The Mission has requested the sharing of information and evidentiary material in the\npossession of Libyan judicial institutions on Tarhuna-related crimes and human rights\nviolations, in particular information on mass graves and evidence collected from them. While\nsuch questions were the subject of official correspondence and in-person meetings that took\nplace in Tripoli, at the time of writing the Mission had not received the requested information\nand evidentiary material on these crimes and human rights violations."},{"id":"a-hrc-50-crp-3-p0019","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"19","seq":19,"section":"B. Challenges faced in collecting evidence","text":"During the Mission’s first visit to Tarhuna in July 2021, local security and political\nissues limited its access to sources of evidence, such as government authorities conducting\nexhumations of mass graves, as well as victims and witnesses who raised safety concerns in\ntheir refusal to meet with the Mission. Its second visit to Tarhuna in May 2022 saw a marked\nimprovement in the cooperation received from the relevant authorities which allowed the\nMission to conduct on-site visits to relevant locations in and around Tarhuna, to conduct in-\nperson interviews of the many victims and witnesses and to receive relevant evidence from\ngovernmental and non-governmental organizations."},{"id":"a-hrc-50-crp-3-p0020","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"20","seq":20,"section":"B. Challenges faced in collecting evidence","text":"The situation in Tarhuna has been under the scrutiny of a number of other actors\nlooking to assist in uncovering the truth and providing accountability for the alleged crimes\ncommitted there. Although this scrutiny over the facts associated with alleged crimes in\nTarhuna aided the Mission’s evidence collection in some respects, the interest of other actors\nalso comes with its complications, especially with respect to coordination among various\ngroups around evidentiary material. This is especially true in relation to the investigation of\nmass graves."},{"id":"a-hrc-50-crp-3-p0021","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"21","seq":21,"section":"B. Challenges faced in collecting evidence","text":"The Mission met with the General Authority for the Searching and Identification of\nMissing Persons (GASIMP), which is the leading institution in the current excavation work\nbeing conducted at the Tarhuna sites, in close collaboration with the Office of the Prosecutor\nGeneral and the Ministry of Health. GASIMP conducts DNA-related work for the purpose\nof identification in relation to the issue of missing persons by means of its laboratory\nfacilities. The Ministry of Justice and the Ministry of Interior also maintain DNA\nidentification capabilities and laboratories to conduct DNA identification work."},{"id":"a-hrc-50-crp-3-p0022","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"22","seq":22,"section":"B. Challenges faced in collecting evidence","text":"The Mission also contacted the Department of Forensic Medicine at the Centre for\nJudicial Expertise and Research (CJER), under the Ministry of Justice, which is in charge of\nproviding technical expertise to the courts, prosecution offices, and other judicial authorities\nin relation to criminal laboratory work; analyzing materials and samples; studying criminal\nacts and phenomena, determining their causes, following up on their development, and\nproposing ways to combat and reduce them; and conducting legal and judicial research and\nstudies related to crimes."},{"id":"a-hrc-50-crp-3-p0023","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"23","seq":23,"section":"B. Challenges faced in collecting evidence","text":"However, due to GASIMP and CJER’s reluctance to share the information on families\nin their possession, the Mission and its Forensic Doctor were unable to contact all the families\nvictimized. As a result, most of the information related to victims provided to the Mission\nwas obtained through the Tarhuna Victims Association (TVA) and/or directly from families."},{"id":"a-hrc-50-crp-3-p0024","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"24","seq":24,"section":"B. Challenges faced in collecting evidence","text":"The Mission met in December 2021 with the Forensic Medicine Committee (also\nknown as the “Mass Graves Committee”). According to Resolution No. 411, the Committee\nconsists of five representatives from the CJER, one representative from the Field Medicine\nSupport Centre of the Ministry of Health, as well as one representative from GASIMP and is\nin charge of excavating mass graves; recovering human remains and locating places where\nhuman remains might be buried; determining the circumstances of death; and identifying the\nvictims and preserving unidentified bodies temporarily, until they are identified in line with\nlegally recognized methods. The Mission’s requests for a second meeting in June 2022 and\nfor autopsy reports and a list of identified victims, were not fruitful."},{"id":"a-hrc-50-crp-3-p0025","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"25","seq":25,"section":"B. Challenges faced in collecting evidence","text":"All the challenges mentioned above are exacerbated by the scale and complexities of\nthe alleged crimes that took place in and around Tarhuna as well as the ongoing insecurity in\nthe country."},{"id":"a-hrc-50-crp-3-p0026","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"26","seq":26,"section":"C. Victim-centred approach","text":"During the whole investigative process, the interests and concerns of the victims were\ncentral to the Mission’s approach. Cooperation with the victims and their families remained\nstrong and consistent. The Mission paid the utmost attention to the safety and well-being of\nthe individuals with whom it interacted. In accordance with the well-established investigative\nprinciple of “do no harm”, the Mission ensured that their collaboration with the Mission did\nnot put them in danger or retraumatize them. Where appropriate, the Mission directed victims\nand witnesses to existing protection and assistance programmes."},{"id":"a-hrc-50-crp-3-p0027","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"27","seq":27,"section":"C. Victim-centred approach","text":"The Mission sought from each person or entity it met their informed consent to use\nthe information in this paper and/or share it with external stakeholders for accountability or\nassistance purposes. The report does not disclose the identity of the individuals interviewed\nby the Mission, except where consent was provided."},{"id":"a-hrc-50-crp-3-p0028","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"28","seq":28,"section":"C. Victim-centred approach","text":"In keeping with the Mission’s mandate to preserve evidence for accountability\npurposes, the Secretariat has kept a safe record of all the materials it gathered in its\nconfidential database and developed a record-management system to streamline future\ninvestigations."},{"id":"a-hrc-50-crp-3-p0029","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"29","seq":29,"section":"C. Victim-centred approach","text":"The Tarhuna Victims Association (TVA) has played a critical role in supporting\nvictims and their families. Given the aforementioned challenges, the role of the TVA and\nother civil society organisations became central to the Mission’s efforts to obtain information.\nFor example, the TVA has submitted case files on numerous victims for the Mission’s\nconsideration, which include summaries of the victim’s stories, police reports, medical\nrecords, identification documents, and other evidentiary material. The TVA has submitted\nregularly updated lists of victims of extrajudicial killings, enforced disappearances, and\nidentified bodies from local mass graves. The TVA has also referred witnesses and victims\nto the Mission for possible interviews and facilitated contacts with victims and relevant state\ninstitutions. Lastly, the TVA has been in regular communication with the Mission to provide\nrelevant information, when needed, allowing the Mission to corroborate much of the\nevidentiary material submitted. The Mission expresses its gratitude to the TVA and considers\nits cooperation an essential element and a model for a victim-centred approach to uncovering\nthe truth of what has happened in Tarhuna."},{"id":"a-hrc-50-crp-3-p0030","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"30","seq":30,"section":"A. Context","text":"Tarhuna is a town located about 90 km south-east of the Libyan capital Tripoli and a\ngateway to the country’s centre and the east. The population of the town itself is estimated at\n70,000 and the greater district has a population of around 250,000 inhabitants.11 In 2011, the\nmajority of Tarhuna’s population was considered loyal to the Qadhafi regime. In the first\nyear following the fall of the regime, the city was under the control of different and changing\nfactions, run by various local families."},{"id":"a-hrc-50-crp-3-p0031","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"31","seq":31,"section":"A. Context","text":"According to available information, before the fall of the Qadhafi regime, the Al-\nShaqaqi family, better known as the Al-Kani family or the al-Kaniyat, had no major influence\nin Tarhuna. Taking advantage of the anarchy in 2011 and 2012, the seven Al-Kani brothers\nwho had been among the few in Tarhuna to have supported the revolution, began engaging\nin extensive criminal activities and the elimination of (perceived) opponents."},{"id":"a-hrc-50-crp-3-p0032","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"32","seq":32,"section":"A. Context","text":"It is alleged that in 2012 the brothers and their associates, forming the al-Kaniyat\nmilitia, were behind the mysterious disappearance of Abu Ajila al-Hibshi, a senior figure\nwho was jailed during the Qadhafi regime for an attempted coup d’état. After the regime’s\nfall, al-Hibshi built an army in Benghazi and brought that army back to Tarhuna. Threatened\nby his growing power, it is reported that Tripoli militias requested the al-Kaniyat militia to\neliminate al-Hibshi."},{"id":"a-hrc-50-crp-3-p0033","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"33","seq":33,"section":"A. Context","text":"In the period that predates the Mission’s mandate, in order to assert themselves in\nTarhuna and exact revenge against those who had wronged them in any way, the brothers\nand their associates are reported to have killed entire families, expelled others, and\ndemolished their homes. By 2015, the al-Kaniyat consolidated their power and controlled\nevery aspect of life in Tarhuna."},{"id":"a-hrc-50-crp-3-p0034","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"34","seq":34,"section":"A. Context","text":"According to available information, the al-Kaniyat militia took control over the\ngovernment cement factory in Tarhuna, reportedly appropriated 90% of its production and\nsold it on the black market. They also took control of a water factory which was later used as\na prison (see infra paragraph 99). Using their increasing resources, they began purchasing\nand seizing weapons, including tanks, from other militias and criminals. The al-Kaniyat are\nalso reported to have imposed a monthly tax on various local businesses under the pretext of\nproviding them with security and protection."},{"id":"a-hrc-50-crp-3-p0035","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"35","seq":35,"section":"A. Context","text":"A witness interviewed by the Mission stated that soldiers who had been deployed from\nTripoli to Tarhuna were given large amounts of money to supplement their government\nsalaries as a reward for their loyalty to the al-Kaniyat, especially between 2013 and 2017."},{"id":"a-hrc-50-crp-3-p0036","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"36","seq":36,"section":"A. Context","text":"According to two witnesses, the militia also controlled banks in Tarhuna and Qasr ben\nGhasir. One of them explained that this was particularly relevant as there had been an ongoing\nfinancial crisis, the banks had no liquidity and ordinary citizens could not withdraw their\nmoney unless they did it with the assistance of the al-Kaniyat. Another witness asserted that\nthe government at the time was aware of this."},{"id":"a-hrc-50-crp-3-p0037","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"37","seq":37,"section":"A. Context","text":"Victims who had successful businesses also described to the Mission that they or their\nrelatives had been abducted, detained and, at times, tortured, so that they would give the al-\nKaniyat large sums of money."},{"id":"a-hrc-50-crp-3-p0038","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"38","seq":38,"section":"A. Context","text":"Several witnesses told the Mission that multiple Tripoli governments had supported\nthe al-Kaniyat militia. According to one of them, in 2015 the militia received support from\nthen Prime Minister Khalifa al Ghweil through intermediaries and were provided with money\nand weapons. According to another, prior to the militia’s alliance with the Libyan National\nArmy (LNA), the government of Prime Minister Sarraj (2016-2021), had been paying the al-\nKaniyat for their loyalty, through the Ministry of Defence. A witness with inside knowledge\nof the al-Kaniyat alleged that a government minister was financially supporting the militia\nwith “huge amounts of money” in 2017 and provided them with 50 armoured vehicles which\nhad arrived through Misrata. The insider as well as other witnesses also named several Libyan\nbusinessmen and politicians who had been reportedly financing the al-Kaniyat."},{"id":"a-hrc-50-crp-3-p0039","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"39","seq":39,"section":"A. Context","text":"The Harouda family (see infra paragraph 70) was also targeted for their land and\nassets. According to several witnesses, the Al-Kani brothers built a mall on the land they had\nseized from the family. The mall consisted of 150 shops which the al-Kaniyat rented to\ngenerate revenue."},{"id":"a-hrc-50-crp-3-p0040","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"40","seq":40,"section":"A. Context","text":"The al-Kaniyat also controlled Zaitouna University and allegedly built an amusement\npark in Tarhuna which became a considerable source of income. A witness also alleged that\nthe al-Kaniyat misappropriated social security funds, social solidarity funds for disabled\npersons and took over the Public Electricity Company for Tarhuna."},{"id":"a-hrc-50-crp-3-p0041","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"41","seq":41,"section":"A. Context","text":"As the most powerful family in Tarhuna from 2015-2020, the al-Kaniyat led an armed\nmilitia of hundreds of heavily armed and well-equipped men and controlled the town’s\ninfrastructure, services, businesses, taxes and security. They are reported to have also\ncollected significant income from taxes on human and fuel smuggling across territories under\ntheir control."},{"id":"a-hrc-50-crp-3-p0042","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"42","seq":42,"section":"A. Context","text":"From 2015-2018, the al-Kaniyat, also referred to as the 7th brigade, were aligned with\nthe Tripoli-based Government of National Accord (GNA)12 from which they allegedly\nreceived funding. However, that alliance became more strained as the al-Kaniyat sought\ncontrol and influence beyond Tarhuna, in Tripoli itself. The 7th brigade launched an assault\nagainst Tripoli in September 201813 and were allegedly involved in an attack against the\nNational Oil Corporation14 that same month."},{"id":"a-hrc-50-crp-3-p0043","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"43","seq":43,"section":"A. Context","text":"In April 2019, as the LNA, the GNA’s main rival based in the East, launched an\noffensive against Tripoli, the al-Kaniyat allied with the LNA and allowed Tarhuna to become\nLNA’s staging ground for the attack. Henceforth, they became the 9th Brigade."},{"id":"a-hrc-50-crp-3-p0044","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"44","seq":44,"section":"A. Context","text":"In June 2020, the GNA pushed the LNA and the al-Kaniyat out of Tarhuna and\nregained control of the city."},{"id":"a-hrc-50-crp-3-p0045","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"45","seq":45,"section":"B. Structure of the al-Kaniyat militia","text":"The Kaniyat family includes seven brothers:\n(a)    Abdel Khaleq Khalifa Abdel Rahim Al-Shaqaqi (half-brother)\n(b)    Mohammad Khalifa Abdel Rahim Al-Shaqaqi (Mohammed Al-Kani)\n(deceased)\n(c)    Ali Khalifa Abdel Rahim Al-Shaqaqi\n(d)    Abdel Rahim Khalifa Abdel Rahim Al-Shaqaqi\n(e)    Abdel Mohsen Khalifa Abdel Rahim Al-Shaqaqi (deceased)\n(f)    Moammar Khalifa Abdel Rahim Al-Shaqaqi\n(g)    Abdel Azim Khalifa Abdel Rahim Al-Shaqaqi (deceased)"},{"id":"a-hrc-50-crp-3-p0046","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"46","seq":46,"section":"B. Structure of the al-Kaniyat militia","text":"The Mission finds that Abdel Bari Al-Shaqiqi, their cousin, was close to the brothers."},{"id":"a-hrc-50-crp-3-p0047","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"47","seq":47,"section":"B. Structure of the al-Kaniyat militia","text":"Based on the evidence collected, the Mission finds that the al-Kaniyat was a militia\ngroup rather than an armed force, regardless of any military alliances that they may have\nformed. The Mission finds that there was no system of discipline nor any formal chain of\ncommand. However, the Al-Kani brothers had effective control over members of the militia."},{"id":"a-hrc-50-crp-3-p0048","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"48","seq":48,"section":"B. Structure of the al-Kaniyat militia","text":"Mohammed Al-Kani had a small group of men who were loyal to him and acted as\nhis informants. Mohsen and Abdel Azim had a number of commanders below them, who\nwere taking orders from them, and who themselves also had a number of subordinates. Abdel\nRahim and Abdel Bari also had leadership roles and were also giving orders to members of\nthe militia."},{"id":"a-hrc-50-crp-3-p0049","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"49","seq":49,"section":"B. Structure of the al-Kaniyat militia","text":"Their militia was formed from a number of tribes in Tarhuna and numbered in the\nthousands: they manned checkpoints, guarded prisons, conducted arrests, and carried out\norders for execution and other atrocities."},{"id":"a-hrc-50-crp-3-p0050","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"50","seq":50,"section":"B. Structure of the al-Kaniyat militia","text":"The Mission received a report that militia members working for the al-Kaniyat were\nnot allowed to execute or kill persons on their own volition, without receiving an order from\none of the brothers. The exception was if a victim tried to escape, resist or fight against al-\nKaniyat members; then they were allowed to kill them."},{"id":"a-hrc-50-crp-3-p0051","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"51","seq":51,"section":"B. Structure of the al-Kaniyat militia","text":"The Mission also received reports that while the commander of the 9th Brigade was\nappointed by the LNA, he was in fact taking orders from Mohammed Al-Kani, whom he\nfeared."},{"id":"a-hrc-50-crp-3-p0052","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"52","seq":52,"section":"B. Structure of the al-Kaniyat militia","text":"The Mission finds that Abdel Rahim, Abdel Bari, and Mohammed Al-Kani exercised\nauthority over the Judicial prison. The Mission has identified units of 7-8 militia members\nwho were in control of the Boxes Prison and the Water Factory prison respectively. The\nMission was unable to verify those individuals who were in charge of the Central Support\nPrison."},{"id":"a-hrc-50-crp-3-p0053","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"53","seq":53,"section":"B. Structure of the al-Kaniyat militia","text":"The Mission collected the names of over 100 alleged perpetrators from the 50\ntestimonies that it gathered in relation to Tarhuna but was only able to verify a fraction of\nthis figure in the available time. Those perpetrators in relation to which the Mission was able\nto gather a reliable body of evidence are listed in the confidential list referenced in paragraph\n189 of this paper."},{"id":"a-hrc-50-crp-3-p0054","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"54","seq":54,"section":"A. Introduction","text":"The al-Kaniyat militia ruled Tarhuna through force and terror. According to GASIMP,\napproximately 300 residents of Tarhuna are reported missing since 2015. According to the\nTVA, 215 are reported as still missing. Residents reported that the militia often abducted,\ndetained, tortured, killed, and disappeared people, mainly men, who opposed them or who\nwere suspected of doing so. An estimated 271 people were executed by the al-Kaniyat militia,\nincluding up to eight women and six children, however, two sources, including an insider,\ntold the Mission that the number of disappeared and killed is likely between 500-600. Some\nsaid the militia seized private property and stole their money."},{"id":"a-hrc-50-crp-3-p0055","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"55","seq":55,"section":"A. Introduction","text":"Based on available evidence, prior to 4 April 2019 when an agreement had been\nreached between the al-Kaniyat militia and the forces fighting in south Tripoli, the al-Kaniyat\nused to publicly execute their victims in order to intimidate the local population. For example,\nthey would bring people blind-folded and handcuffed to the roundabout known as Jazeerat\nAl-Dawaran in front of the police station in the centre of Tarhuna, where they would execute\nthem. As some families of the victims started to file complaints before the Public Prosecutor,\nthe negative public opinion towards the al-Kaniyat increased and they began hiding their\nvictims’ bodies or disposing of them in neighbouring municipalities. Libyans and foreigners\nwere hired to bury the bodies using bulldozers."},{"id":"a-hrc-50-crp-3-p0056","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"56","seq":56,"section":"A. Introduction","text":"From the beginning of the non-international armed conflict which opposed GNA to\nLNA forces in April 2019, the disappearances and executions of civilian women, men and\nchildren, including persons with disabilities, increased significantly. The majority of the 119\nbodies identified in mass graves in Tarhuna to date are victims of killings that occurred after\nApril 2019. The majority of the crimes recorded by the Mission occurred between April 2019\nand June 2020. Further investigations are required to investigate the correlation between the\nsignificant quantitative increase in criminality and the occurrence of the non-international\narmed conflict in Tarhuna."},{"id":"a-hrc-50-crp-3-p0057","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"57","seq":57,"section":"1. Targeted groups","text":"The victims interviewed by the Mission are representative of hundreds of Tarhunans\nwho have been subjected to great suffering and/or killed for being perceived to oppose the\nAl-Kani brothers and their militia. As indicated by the facts, victims were systematically\ntargeted for being perceived as associated with groups who opposed the al-Kaniyat."},{"id":"a-hrc-50-crp-3-p0058","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"58","seq":58,"section":"1. Targeted groups","text":"Illustrating the level of brutality, one resident of Tarhuna, three of whose relatives had\nbeen abducted by the al-Kaniyat militia, told the Mission: “When they capture and kill\nsomeone, they also make sure to kill the rest of the men in his family so that they don’t\nretaliate. After they kill people, they seize their money and property.”"},{"id":"a-hrc-50-crp-3-p0059","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"59","seq":59,"section":"1. Targeted groups","text":"According to witnesses, some of the victims of the al-Kaniyat had been civilians while\nothers had a military background. A witness with inside knowledge of the militia stated that\nthe al-Kaniyat were scared that people would inform the authorities in Tripoli about their acts\nand that they would immediately kill anyone they suspected to do so. The witness further\nexplained that some victims had been killed because the al-Kaniyat wanted to eliminate\npowerful men, particularly those who had been in the army."},{"id":"a-hrc-50-crp-3-p0060","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"60","seq":60,"section":"1. Targeted groups","text":"According to victims and witnesses, other reasons the al-Kaniyat militia used for\nselecting their victims depended on contemporary events, their alliances at the relevant time,\ntheir family links, or otherwise, grievances of the al-Kaniyat. Such justifications for arrest\nand later victimization included:\n(a)    Suspicion of having joined the ‘17 February’ revolution against Qadhafi in\n2011:"},{"id":"a-hrc-50-crp-3-p0061","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"61","seq":61,"section":"1. Targeted groups","text":"One victim whose family member was abducted and eventually killed stated “I believe\nthat our family was accused of supporting the 17 February Revolution and that we are\ntraitors.” After undergoing extensive torture for months in late 2019, another witness, whose\ninjuries the Mission’s Forensic Doctor examined and found consistent with torture, also told\nthe Mission that he was forced to produce a list of names “associated with the Revolution of\n17 February.”15\n(b)    Perceived to be opposed to LNA and LNA-affiliated groups:"},{"id":"a-hrc-50-crp-3-p0062","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"62","seq":62,"section":"1. Targeted groups","text":"According to one of the victims interviewed by the Mission, his siblings told him that\nthey had to delete their accounts on Facebook “because the al-Kaniyat were killing people\nwho were against the LNA by checking if they had posted anything against the LNA\nleadership on social media.” Another victim reported that he “was detained for four months\nwhere he was coerced to confess and to give names of those against LNA’s military forces\nand those affiliated to it, including the al-Kaniyat militia.” Another witness discussed the\nabduction, torture, and eventual killing of his 14-year-old son because the boy posted anti-\nKaniyat messages on his Facebook profile. One victim told the Mission that after being\ndetained and mistreated in an al-Kaniyat detention facility for months, he signed a pledge\nprior to his release that stated “I pledge before God and before the law that I will not work\nagainst the LNA”."},{"id":"a-hrc-50-crp-3-p0063","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"63","seq":63,"section":"1. Targeted groups","text":"Another victim detained and victimized by al-Kaniyat militia members told the\nMission, “they took my phone and went through the phone. They could not find anything\nthat could tie me to the other side, the West. Then they started accusing me of being a traitor\nfor not having joined them, they assumed that I was affiliated with the Misrata militia.”\n(c)     Actual or perceived wealth:"},{"id":"a-hrc-50-crp-3-p0064","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"64","seq":64,"section":"1. Targeted groups","text":"One victim was abducted and escorted to a bank by al-Kaniyat milita members who\nforced him to withdraw 800,000 dinars that were the proceeds of hiscompany. Another victim\nwho owned a food fertilizer factory was tortured and interrogated about the location of his\nmoney. One woman interviewed by the Mission in Tarhuna described how al-Kaniyat forces\nransacked the family home and took “everything” they had while also injuring, abducting,\nand eventually disappearing her son during this raid. His body was later identified in a\nTarhuna mass grave. In 2016, al-Kaniyat members abducted and beat a senior official at a\nTarhuna savings bank to force him to resign in favour of an al-Kaniyat associate, thus giving\nthe militia control of 65 million Libyan dinars.\n(d)     Perceived association with the GNA or Tripoli in general:"},{"id":"a-hrc-50-crp-3-p0065","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"65","seq":65,"section":"1. Targeted groups","text":"One witness explained to the Mission, for example, that his brother and cousin were\narrested (and remain missing) simply because they were born in Tripoli. Another victim told\nthe Mission that he was arrested by al-Kaniyat members and detained in the Central Support\nprison for “being an informant for Tripoli”. A religious figure who was abducted, detained,\nand tortured by al-Kaniyat members was confronted by one of the al-Kaniyat commanders\nwho accused him of informing the security apparatus in Tripoli about the militia.\n(e)     Refusal to join the al-Kaniyat:"},{"id":"a-hrc-50-crp-3-p0066","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"66","seq":66,"section":"1. Targeted groups","text":"In one revealing example of the al-Kaniyat’s overall policy to target people from\ncertain groups, an insider witness told the Mission about one victim who was first accused of\nbeing a spy and, when no incriminating material was found in his phone, was accused of\nbeing a traitor for not having joined them. Another witness explained that one of his family\nmembers was abducted at 1 a.m. after he had refused to join the militia. He remains missing,\nand when asked by a relative, an al-Kaniyat commander denied having any knowledge of his\nwhereabouts. In another case, when a victim was asked for the reasons of his abduction and\nsubsequent victimization in al-Kaniyat detention facilities, the victim told the Mission “the\nmain reason is that my cousins joined the al-Kaniyat militia. They tried to convince us to join\nthem but we refused. They insisted on us participating in their operations. My father did not\nallow us. He did not want us to go and work for criminals. When we refused several times,\nthey accused us of opposing them. I never worked with al-Kaniyat nor for them.”\n(f)     Failure to attend the funeral of Mohsen Al-Kani or being perceived to be happy\nthat he was killed:16"},{"id":"a-hrc-50-crp-3-p0067","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"67","seq":67,"section":"1. Targeted groups","text":"An insider told the Mission that the al-Kaniyat leadership had a “policy of killing. The\npeople who didn’t come to the funeral of Mohsen, they were killed. Also, those who didn’t\nbring their wife to the funeral, they were killed.” Another witness explained to the Mission\nwhen asked why people were killed by al-Kaniyat members: “some were accused of being\nhappy with Mohsen Al-Kani's death, and some were seen as dangerous.”\n(g)     Asking al-Kaniyat members about the whereabouts of loved ones:"},{"id":"a-hrc-50-crp-3-p0068","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"68","seq":68,"section":"1. Targeted groups","text":"As stated elsewhere, one victim was detained, tortured, and ill-treated for asking after\nthe status of his brother who he suspected was taken by al-Kaniyat members. Specifically,\nthe victim said “I, myself, got arrested by al-Kaniyat after the abduction of my brother in\nMay 2020. When they kill any member of any family, they kill the rest of the family. They\narrested me because I was asking about my brother.” In another example, a woman’s husband\nwas abducted in 2020 by al-Kaniyat militia members and was believed to be held at the\nJudicial Prison. When requesting information from al-Kaniyat officials about his\nwhereabouts, they first denied knowing anything before asking her to come in to talk, after\nwhich she disappeared. Her body was found in July 2020 after Tarhuna was liberated."},{"id":"a-hrc-50-crp-3-p0069","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"69","seq":69,"section":"2. Violations committed against women","text":"The Mission has received information that at least eight women were forcibly\ndisappeared and potentially six were confirmed killed. Given a discrepancy between sources,\nit is unclear if six or eight bodies of women have been identified.17 Also, according to\ntestimonies collected by the Mission, some witnesses heard the screams of women held in\nthe Judicial Prison that were consistent with being tortured."},{"id":"a-hrc-50-crp-3-p0070","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"70","seq":70,"section":"2. Violations committed against women","text":"The Mission documented the killing of four women, who were targeted because of\ntheir family links. They include three sisters from the Harouda family and a woman whose\nhusband had been abducted by the al-Kaniyat in April 2020 and December 2019,\nrespectively. According to the information received by the Mission, the Harouda family and\nthe al-Kaniyat had been feuding in relation to land and possessions confiscated by the Al-\nKani brothers. As mentioned above, the mall belonging to the Al-Kani brothers at the\nentrance of Tarhuna was reportedly built on land owned by the Harouda family. Also, the\nfarm where one of the largest mass graves is located, Al Rabt Project, belongs to the Harouda\nfamily. It is worth noting that two years prior to the abduction and killing of the three sisters,\ntheir two brothers, had been abducted and are still missing. A third brother had fled Tarhuna,\njoined the GNA forces in Tripoli and had been outspoken against the al-Kaniyat from there.\nDue to this, according to another sister, the al-Kaniyat had been threatening to “break his\nback” and targeting his sisters was a way to do so. The fourth woman had been asked by the\nal-Kaniyat to pick up her husband. When she did as instructed, she was abducted and\nsubsequently killed. The bodies of all four women were found in one of the Tarhuna mass\ngraves (see also infra paragraph 138)."},{"id":"a-hrc-50-crp-3-p0071","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"71","seq":71,"section":"2. Violations committed against women","text":"The period during which the Harouda sisters had been missing were particularly\nharrowing for the family because of the added fear of sexual violence. The surviving sister\nshared with the Mission her fear that the sisters had been abused sexually, that the abuses had\nbeen filmed and that it would be uploaded on social media or that images would circulate in\nTarhuna. She also told the Mission of her subsequent relief that her siblings had been killed\non the day of their abduction and that they died ‘clean’ and ‘honourable.’ She added that\nsexually abusing her sisters would have been the most hurtful way to get back at their brother."},{"id":"a-hrc-50-crp-3-p0072","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"72","seq":72,"section":"2. Violations committed against women","text":"Another four female victims documented by the Mission include a woman from the\nal-Na’ajy tribe, a Moroccan woman who lived in Tarhuna, and a policewoman, all of whom\nare still missing, as well as another policewoman from Tarhuna who had allegedly joined the\nal-Kaniyat and whose body was found in a Tarhuna mass grave."},{"id":"a-hrc-50-crp-3-p0073","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"73","seq":73,"section":"2. Violations committed against women","text":"When seeking to investigate allegations of sexual violence against women, the\nMission was told of reports that one of the brothers, Abdel Rahim Al-Kani, had a room in\ntheir mall and that he would threaten women into having sex with him or else he would target\ntheir father or brothers. The Mission also heard from the TVA that families would not report\nmissing women especially young women for fear of tarnishing their reputation and\nsuggesting they had gone to the al-Kaniyat voluntarily. The Mission was told that many\nfamilies with young women left Tarhuna or had their daughters married. These reports were\nraised in discussions several times, but the Mission was unable to independently confirm\nthem."},{"id":"a-hrc-50-crp-3-p0074","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"74","seq":74,"section":"2. Violations committed against women","text":"The targeting of women in Tarhuna was particularly shocking as it was against\ncultural, religious and local traditions that retribution would not target women. As\nexemplified by the killing of the Harouda sisters, in a patriarchal society with strong tribal\ndynamics such as Tarhuna, targeting women was seen as a way to hurt the men and attack\nthe honour of the whole family. Unlike other situations covered by the Mission where women\nhad been targeted to force their male relatives to surrender, in the case of Tarhuna, women\nappear to have been targeted to further attack their male relatives."},{"id":"a-hrc-50-crp-3-p0075","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"75","seq":75,"section":"2. Violations committed against women","text":"In the context of Libya and in particular in Tarhuna, a small town where patriarchal\nand tribal mentalities prevail, it is extremely difficult for survivors of sexual violence to come\nforward. Doing so puts them at risk of rejection and ostracism."},{"id":"a-hrc-50-crp-3-p0076","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"76","seq":76,"section":"3. Violations committed against children","text":"In the course of the Mission’s investigations in Tarhuna, it was found that children\nwere not spared but also subjected to kidnapping, torture and killing by al-Kaniyat members.\nWhile it could not be established whether children, particularly boys, were targeted as such,\nchildren under the age of 18 have been reportedly killed and abducted by al-Kaniyat\nmembers. In 2020, the UN in Libya verified the abduction of three children by al-Kaniyat\nforces.18 Amongst the bodies identified so far in Tarhuna’s mass graves and at the Tarhuna\nhospital there are five children."},{"id":"a-hrc-50-crp-3-p0077","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"77","seq":77,"section":"3. Violations committed against children","text":"Moreover, children in Tarhuna have witnessed the killing or abduction of their parents\nand relatives, the burning of houses, and have parents, siblings and family members forcibly\ndisappeared. This has had an enormous impact on the children. Witnesses interviewed by the\nMission’s Child Advisor consistently and emphatically raised the need for psychosocial\nsupport to children, arguing that children in Tarhuna are deeply affected by the traumatic\nexperiences they have gone through"},{"id":"a-hrc-50-crp-3-p0078","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"78","seq":78,"section":"3. Violations committed against children","text":"In 2015, a 14-year-old boy was abducted from the street in broad daylight as he was\nwalking to a nearby mosque for mid-day prayer. Witnesses recognized one of the kidnappers\nas a member of the al-Kaniyat militia. The victim was from the al-Na’ajy clan of Tarhuna. In\nits quest to seize control of the town, the al-Kaniyat militia waged a campaign targeting other\nclans. They reportedly abducted and killed a large number of al-Na’ajy clan members,19 and\namongst them three of the victim’s uncles who had been killed when al-Kaniyat militia\nattacked their home. The victim’s father told the Mission that the boy had reacted angrily\nwhen he heard about his uncles’ killing and wrote an angry post on his Facebook account\ncondemning the murderers."},{"id":"a-hrc-50-crp-3-p0079","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"79","seq":79,"section":"3. Violations committed against children","text":"A witness with inside knowledge of the al-Kaniyat reportedly informed the boy’s\nfather that, following abduction, his son was taken before an al-Kaniyat commander who was\ntold who the boy’s father and uncles were. The commander then allegedly asked the boy if\nhe had published these posts on Facebook. As the boy did not deny, he ordered his execution.\nThe same witness also admitted to the torture of the boy. Ten days later, the victim’s body\nwas found in Tarhuna with signs of torture. His death certificate indicates that the cause of\ndeath was a gunshot. The victim’s father stated that his brother had worked at the hospital\nand that he had examined the boy’s body at the time and concluded that the boy had been\nbrutally tortured. However, the father could not provide the Mission with the medical report\nas it had allegedly been destroyed."},{"id":"a-hrc-50-crp-3-p0080","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"80","seq":80,"section":"3. Violations committed against children","text":"The Mission received information from a number of witnesses about the killing of\nthree children from the Al-Fallous family. The al-Kaniyat reportedly stormed the home of\nAbdul-Akali Saleh al-Mabrouk Al-Fallous and abducted him together with three of his\nchildren, aged 16, 15 and 10 years-old. The remains of the four victims were found in a\nTarhuna mass grave. The family was reportedly targeted after a video produced by a group\nof men in Tripoli affiliated with the GNA (allegedly including a relative of Abdul-Akali Al-\nFallous) which contained messages threatening the al-Kaniyat, was published on social\nmedia. It was reported that an al-Kaniyat commander ordered the punishment of anyone in\nTarhuna related to those who appeared in the video, amongst whom were Abdul-Akali Al-\nFallous and his children. According to media reports, 15 members of the al-Kaniyat arrested\nAbdel and his four sons, after raiding their house in the Na’aja area of Tarhuna and took them\nto the commander’s farm, where the father and children were handcuffed. The al-Kaniyat\ncommander allegedly assassinated them one by one, after insulting them. The youngest son\nsurvived."},{"id":"a-hrc-50-crp-3-p0081","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"81","seq":81,"section":"3. Violations committed against children","text":"During its visit to Tarhuna, the Mission had intended to interview the child survivor.\nHowever, it did not do so for fear of re-traumatisation. The Mission had received reliable\ninformation that a few days prior to its scheduled visit, the victim had displayed signs of\ntrauma while speaking to a United Nations official."},{"id":"a-hrc-50-crp-3-p0082","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"82","seq":82,"section":"3. Violations committed against children","text":"In June 2020, more than 100 bodies, including women and children, were reportedly\nfound in a hospital in Tarhuna and some of the bodies had signs of torture and execution,\naccording to state officials. In addition, in June 2020, forces affiliated with the GNA stated\nthat a discovered mass grave included the handcuffed body of a 12-year-old girl."},{"id":"a-hrc-50-crp-3-p0083","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"83","seq":83,"section":"C. Abductions and arrests","text":"Evidence gathered by the Mission demonstrates that the pattern of criminal conduct\nof the al-Kaniyat almost always began with a violent abduction, at a checkpoint, in the street,\nor in homes."},{"id":"a-hrc-50-crp-3-p0084","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"84","seq":84,"section":"C. Abductions and arrests","text":"Following their alliance with the LNA, the al-Kaniyat placed checkpoints in and\naround Tarhuna but also as far afield as between Tripoli and Qasr ben Ghashir (over 60\nkilometres away). Many abductions occurred at these checkpoints. Victims would be stopped\nby individuals they identified as members of the al-Kaniyat and asked to hand over their\nmobile phones and their identification cards for inspection. The phones would be checked\nfor any anti-LNA social media posts. If such posts were found, the individuals would be taken\ninto custody or killed immediately. The same would happen if their identification cards\nindicated that they were residents of Tripoli or other areas which had been viewed with\nsuspicion by the militia. One witness whose relatives had been stopped at such a checkpoint\nsaid that when the militia saw that her brother and cousin were from Tripoli, they confiscated\ntheir phones, asked them to get out of the car, put them in a military car and drove them to\nthe Judicial Prison, located in Tarhuna."},{"id":"a-hrc-50-crp-3-p0085","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"85","seq":85,"section":"C. Abductions and arrests","text":"In addition to arrests at checkpoints, armed members of al-Kaniyat also conducted\ntargeted operations to apprehend and detain people in Tarhuna. Militia members in groups\nthat varied in size from two or three to as many as 60 or more conducted such operations in\nthe victims’ homes, at their workplace, at family gatherings or on the street. One victim said\nthat about 20 to 30 men and 14 vehicles surrounded their homes during one of these\noperations. Another victim described how more than 60 armed men attacked his extended\nfamily while they were attending a funeral and the noon prayer."},{"id":"a-hrc-50-crp-3-p0086","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"86","seq":86,"section":"C. Abductions and arrests","text":"Once found, the victim(s) would be abused and taken in vehicles bearing al-Kaniyat\ninsignia or similar identification. In one case, a witness reported that his brothers and friends\nhad been forcibly dragged out of their house and shoved into vehicles by al-Kaniyat militia\nmembers who were yelling at them: “you are traitors, you are against the army.” Another\nvictim described how a member of the militia rode in the back seat, pointing a weapon at his\nhead and threatening to blow it off if he made any movement."},{"id":"a-hrc-50-crp-3-p0087","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"87","seq":87,"section":"C. Abductions and arrests","text":"During arrest, victims were beaten with hard objects, such as the butt of a gun, and\nwere often handcuffed, blindfolded, and taken in various vehicles, some of which bore the\nlogos of al-Kaniyat, ‘9th Brigade’ or ‘Mohsen Al-Kani’. For example, a victim recounted\nthat a militia member forced him to get out of the house, tied his hands with a piece of cloth,\ncursed him and hit him with the butt of the gun. The victim further stated that the militia put\nhim in the back seat of a white Toyota 27 in between two militia members who said to him:\n‘You are traitors, you betray Tarhuna, you will sell it to Misrata and the Turks.’ The victim\nalso explained that after they had brought him to the ‘Water Factory’ in Tarhuna (see infra\nparagraph 99), they insulted his parents."},{"id":"a-hrc-50-crp-3-p0088","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"88","seq":88,"section":"C. Abductions and arrests","text":"According to witness testimonies, none of the victims were accused of, or charged\nwith, a criminal offence nor granted any form of due process."},{"id":"a-hrc-50-crp-3-p0089","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"89","seq":89,"section":"D. Places of Detention","text":"The al-Kaniyat and their militia imprisoned those they did not immediately kill,\nincluding in including abandoned houses and farms, and subjected them to physical and\nmental torture. The Mission documented four facilities in Tarhuna that the al-Kaniyat used\nas prisons: the Judicial Prison; the Boxes Prison; the Central Support Prison; and the Water\nFactory, considered a place of secret detention."},{"id":"a-hrc-50-crp-3-p0090","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"90","seq":90,"section":"D. Places of Detention","text":"Before being released or killed, detainees were held in arbitrary detention for various\nperiods of time, ranging from a few days to several months, according to those interviewed\nby the Mission."},{"id":"a-hrc-50-crp-3-p0091","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"91","seq":91,"section":"D. Places of Detention","text":"The majority of victims were taken to the Judicial Police which consisted of multiple\ncells, of different sizes, used for different purposes. Some victims referred to the cells as\nfollows:\n•    The Tahafuz cell, in which no one can visit the detainees, where they were waiting\nto die;\n•    The ‘camera cell’, which contained a surveillance camera;\n•    The ‘sauna cell’ which had no window, was covered with ceramic tiles and in which\nit was very hard to breathe;\n•    The ‘military cell’;\n•    The ‘convicted cell’;\n•    The ‘balanco or torture cell’, in which, a pulley device (see infra paragraph 104),\nelectricity shocks and electric cables were used for torture."},{"id":"a-hrc-50-crp-3-p0092","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"92","seq":92,"section":"D. Places of Detention","text":"Cells were overcrowded with, at times, 35 detainees in a 5x7m space. Some cells had\ntoilets and, at times, due to a lack of water, the prisoners would drink toilet water. Food was\nprovided, but it was of poor quality and quantity. The prisoners were sleeping on the floor."},{"id":"a-hrc-50-crp-3-p0093","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"93","seq":93,"section":"D. Places of Detention","text":"One of the prisoners, a doctor by profession, was ordered by the armed group to treat\npatients and provide them with some medication. However, no treatment was provided for\ninjuries sustained as a result of the torture. A victim reported that during detention, he\nsuffered from wounds from torture but did not receive any medical examination or treatment\ninside the prison. He also reported that many detainees suffered from scabies and skin ulcers\nas a result of torture."},{"id":"a-hrc-50-crp-3-p0094","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"94","seq":94,"section":"D. Places of Detention","text":"The Mission visited the Boxes Prison during its missions in July 2021 and May 2022.\nThis site was in an agricultural laboratory which had not been in use from 2011 until 2019\nwhen the al-Kaniyat began using it as a detention facility. According to victims, it was called\nthe Boxes Prison because it had nine small box-like iron enclosures in which the detainees\nwere kept. The Mission’s Forensic Doctor confirmed the existence of the boxes and measured\nthem at 0.8x0.8m.\nPhotos taken by the Mission during site visits to the Boxes Prison showing the 0.8x0.8m boxes-\nlike enclosures"},{"id":"a-hrc-50-crp-3-p0095","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"95","seq":95,"section":"D. Places of Detention","text":"Witnesses also stated that fires would be built on top of these enclosures. According\nto a witness, as many as three or four persons were placed in each oven that were used every\nfew days for interrogations. Given that these interrogations were mostly conducted at night,\nthe victims tried to sleep during the day. Another said that they would sometimes place two\npersons in each cell so that they could not breathe. One male victim, aged 28, said that he\n“had been locked in an oven” and told the Mission: “I saw hell in my own eyes. I thought I\nwas going to die. I could not stand. They were interrogating me every day.” Prisoners were\ngiven a small piece of bread per day, a bottle of water to drink from and another bottle in\nwhich to urinate. Some were not allowed to go to the toilet, while others were allowed every\nthree days and whipped if they took longer than the two minutes allowed."},{"id":"a-hrc-50-crp-3-p0096","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"96","seq":96,"section":"D. Places of Detention","text":"In addition to confirming the existence of the boxes during the site visit, the Mission’s\nForensic Doctor observed the presence of a massive amount of ash on the boxes and on the\nfloor. According to his analysis, it did not appear that the ash had been transferred from\nanother place, most notably because of the existence of soot on the walls and the ceiling as\nwell as partially burned wood pieces on the floor."},{"id":"a-hrc-50-crp-3-p0097","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"97","seq":97,"section":"D. Places of Detention","text":"The Mission also visited the Central Support Prison which was a government facility\nlocated next to the Judicial Prison, and close to the Boxes Prison, and had consisted of 12-16\ncells and rooms. The al-Kaniyat purportedly began using it as a detention facility as of 2015.\nThe detainees slept on the floor without mattresses. The cells were overcrowded, sometimes\nwith as many as 20-25 persons in one cell. Food was very scarce. For example, 20 people\nwould share one dish which would normally feed no more than three. The water was not\npotable."},{"id":"a-hrc-50-crp-3-p0098","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"98","seq":98,"section":"D. Places of Detention","text":"One of the witnesses stated that some detainees were from Tarhuna, while others were\nfrom Souk al Khamis, al Sayeh, Tajourah, al Erban, Massalata and Tripoli, towns and cities\nwhich were of strategic importance to the al-Kaniyat militia."},{"id":"a-hrc-50-crp-3-p0099","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"99","seq":99,"section":"D. Places of Detention","text":"According to witnesses, the al-Kaniyat killed Basset Bou Naamah and took over his\nWater Factory in Tarhuna to which they transferred one of their headquarters, and in which\nthey created another prison. The Water Factory is located 200 metres away from the\nUniversity of Tarhuna."},{"id":"a-hrc-50-crp-3-p0100","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"100","seq":100,"section":"D. Places of Detention","text":"This prison also had boxes but was different from the agriculture site Boxes Prison.\nSeveral witnesses described that at the Water Factory, prisoners were kept in two hangars or\nstorage areas, 20x5m, one of which contained five 1x1m boxes or cells in which it was\nimpossible to stand up. There were no toilets and the prisoners had to urinate into small water\nbottles. They were given expired dry food twice a day and despite some reporting stomach\npain, were not provided with any medical assistance or medication. They slept seated, on the\nfloor or in the cold, with rain leaking from the roof. A victim recounted that when he had\nasked an al-Kaniyat militia member for water, the man deliberately spilled the water on the\nfloor and told him to lick it off the floor, like an animal."},{"id":"a-hrc-50-crp-3-p0101","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"101","seq":101,"section":"E. Torture","text":"While in detention, victims were subjected to various methods of torture. A victim\nstated that the al-Kaniyat treated their prisoners like “insects”."},{"id":"a-hrc-50-crp-3-p0102","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"102","seq":102,"section":"E. Torture","text":"Based on interviews the Mission conducted with victims and witnesses, torture would\nlast from 15 minutes to three hours and the methods included: severe beatings by plastic\npipes, electric cables, iron sticks, butts of rifles and guns, and other blunt objects which\nresulted in broken noses and teeth."},{"id":"a-hrc-50-crp-3-p0103","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"103","seq":103,"section":"E. Torture","text":"For example, a victim described that he had been taken outside, beaten all over his\nbody and head with an iron stick and a plastic pipe, then left to lie handcuffed on the ground\nin the sun. Another victim described witnessing someone being beaten and threatened with\ndeath and then taken to a room where he was hung on a wall with metal chains while the\nperpetrators took turns beating him with a plastic hose. A witness described seeing someone\nwho had been tortured, with all his nails torn out. The man’s clothes were stained with blood\nand he was in a state of shock – he could not move or speak. According to the witness, he\nhad been hit on his hands, face, feet and had bruises all over the body. The perpetrators had\nused a Kalashnikov bayonet to torture him and his hands and feet had been pierced."},{"id":"a-hrc-50-crp-3-p0104","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"104","seq":104,"section":"E. Torture","text":"Several victims described the use of a ‘balanco’ at the Judicial Prison, Water Factory\nand Boxes Prison. The ‘balanco’ is described as a pulley system which would be used to\nsuspend detainees from the ceiling or a high wall whereby the victim would be tied by the\nwrists and suspended in stress positions (often with their arms pulled behind their backs) for\nextended periods of time during which they were also beaten. They would then be suddenly\nreleased, causing injury, pain and rupture in the wrist area. In at least one instance, a victim\nclaimed that his brother had died in a cell next to him as a consequence of ‘balanco’ torture\nafter he had been screaming in pain all night."},{"id":"a-hrc-50-crp-3-p0105","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"105","seq":105,"section":"E. Torture","text":"Several victims also described the ‘falaqa’ torture method to which they had been\nexposed. Foot whipping, or falaqa, is a method of inflicting pain and humiliation by\nadministering a beating on the soles of a person's bare feet. Unlike most types of flogging, it\nis used more to cause pain than actual injury to the victim."},{"id":"a-hrc-50-crp-3-p0106","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"106","seq":106,"section":"E. Torture","text":"In the Boxes Prison, the detainees were also tortured with extreme heat (see supra\nparagraph 95)."},{"id":"a-hrc-50-crp-3-p0107","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"107","seq":107,"section":"E. Torture","text":"According to the information gathered by the Mission, other methods of torture\nincluded being held incommunicado from several days to several weeks; being held in\nsolitary confinement, in one case for six months; being burned and tortured with electric\ncables; dripping a burning substance on the victim’s body; hooding; torturing with a drilling\nmachine; limiting access to water, food and toilets; death threats; witnessing the killing of\nother detainees; being wounded by gunfire; and sleep deprivation."},{"id":"a-hrc-50-crp-3-p0108","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"108","seq":108,"section":"E. Torture","text":"The Mission’s Forensic Doctor collected and evaluated information on these methods.\nHe specifically corroborated the allegations of torture by drilling in relation to two victims\nand the allegation of wounding by gunfire in relation to another."},{"id":"a-hrc-50-crp-3-p0109","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"109","seq":109,"section":"E. Torture","text":"Although underreported for a variety of reasons, available information suggests that\nrape and other forms of sexual violence occurred in al-Kaniyat prisons. Sexual violence in\ndetention included forced nudity, beating of, and applying electricity to, sexual organs,\ncutting off the genitals, sexual torture and rape. A victim, who was a religious figure, told the\nMission that he had been photographed naked and that this had been done with the threat of\ncirculating the images in Tarhuna. He also said that he was later raped during his interrogation\nwith an object which he believed to have been a wooden stick. He added that he had fallen\nunconscious several times and felt “from time-to-time sharp prickles on the anus. I don’t\nknow if it was sticks or other sharp objects”. A medical report provided to the Mission by the\nwitness also showed that he sustained injuries in the anal region consistent with being\ntortured."},{"id":"a-hrc-50-crp-3-p0110","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"110","seq":110,"section":"E. Torture","text":"The impact of sexual violence goes far beyond the physical act and the mere suspicion\nthat someone, whether male or female, has been subjected to sexual violence leads to\nstigmatization."},{"id":"a-hrc-50-crp-3-p0111","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"111","seq":111,"section":"F. Disappearances","text":"While in captivity, victims were provided with no reasons for their detention nor\naccess to any legal assistance and were held incommunicado. Families of those detained\nnever received any official notification or other information regarding the circumstances of\narrest or reasons for detention from the al-Kaniyat militia or any governmental authorities.\nIn some cases, when approached by the family members of a missing person, members of the\nmilitia verbally denied any knowledge of the person’s arrest, abduction, or detention. In other\ncases, al-Kaniyat leaders refused to answer the family members’ phone calls, threatened them\nif they continued to ask questions, ignored them and, in some cases, tortured or killed them.\nAccording to the TVA, around 215 people are still missing, some of them since 2016."},{"id":"a-hrc-50-crp-3-p0112","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"112","seq":112,"section":"F. Disappearances","text":"One victim recounted her family’s efforts to find her brother and cousin as follows:\nIn December 2019, we went to the Judicial Prison in Tarhuna, to the Central Support\nPrison and to the military police asking about my brother and cousin’s whereabouts.\nThe military police explained that as they were not military, they would not be held\nby them. They all said they did not know anything. We did not enter the prisons. We\nstayed outside. At the Judicial Prison, two armed men were standing at the gate. They\nwere very rude with us. At the Central Support Prison, there was a man standing\nbehind the gate. We did not even see his face. He said that they were not in that prison.\nOn that day, we went to see Mohammed Al-Kani who was with his guards. They were\nall armed. My mother wanted to speak with Mohammed Al-Kani. He told her to talk\nto his guard, who introduced himself and gave my mother his number. He told her\nthat he will check and will come back to her. My mother called him, he told her to call\nhim later. She called him three times and then at the last call, he told her rudely that\nshe was annoying him. My mother did not call him back."},{"id":"a-hrc-50-crp-3-p0113","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"113","seq":113,"section":"F. Disappearances","text":"Another victim described how the morning after their relative’s disappearance, family\nmembers went to the checkpoint to look for him and asked the military police about his\nwhereabouts. One of the officers confirmed that the relative had been arrested the previous\nday but stated that he did not know where the detainee was taken. They subsequently heard\nfrom others that the victim had been killed but, at the time of writing, the family has still not\nbeen able to find the body. Several women interviewed by the Mission also mentioned going\nto the mall belonging to the Al-Kani brothers to find out about their missing relatives. Many\nstill had hope that their missing sons were in jail in the East or in Tripoli. Some women even\ntravelled to Benghazi to find out about their loved ones who they believed to be held in the\nEast."},{"id":"a-hrc-50-crp-3-p0114","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"114","seq":114,"section":"F. Disappearances","text":"Another victim described multiple efforts over an extended period of time to find out\nwhat happened to his two brothers who had been abducted by the al-Kaniyat at a checkpoint.\nDespite death threats, the victim inquired at several checkpoints and with both State and non-\nState authorities. Together with his mother, he travelled to locations outside of Tarhuna in an\nattempt to find any information about his brothers. Following the end of the conflict in\nTarhuna, they learned, unofficially, that his brothers had been tortured and killed. One of the\nbrothers was found in a mass grave but, at the time of writing, the search for the other\ncontinues."},{"id":"a-hrc-50-crp-3-p0115","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"115","seq":115,"section":"F. Disappearances","text":"Another family told the Mission that they had been provided false information that\nled them to believe that their relatives might still be alive and that they paid a lot of money\nto receive information about the victims’ whereabouts. They had also been given assurances\nby senior officials in Benghazi that their relatives would be released. The victims were\nsubsequently found in mass graves. It has been established that they had been killed on the\nsame day of their abduction."},{"id":"a-hrc-50-crp-3-p0116","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"116","seq":116,"section":"F. Disappearances","text":"A witness with inside knowledge of the al-Kaniyat told the Mission that the militia\ndid not want to give the bodies to their relatives and families, as they wanted revenge. The\nwitness quoted an al-Kaniyat leader as saying: “I want families of the victims to search for\n50 years and to never find their sons and loved ones.”"},{"id":"a-hrc-50-crp-3-p0117","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"117","seq":117,"section":"F. Disappearances","text":"Most families did not request information about their abducted family members out\nof fear for their safety. One victim was arrested, detained for a month and tortured solely for\nasking about the whereabouts of his brother. Several witnesses told the Mission that the\nfamilies were too afraid to inquire about their missing relatives or file a complaint because\nal-Kaniyat controlled everything, including the police. Some even feared that they would\nhave been killed if they had tried to launch an investigation in Tripoli because the al-Kaniyat\nhad informants there as well."},{"id":"a-hrc-50-crp-3-p0118","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"118","seq":118,"section":"F. Disappearances","text":"A mother whose two younger sons had been abducted by one of the al-Kaniyat senior\nmembers from their beds at home in the middle of the night in April 2020 explained that her\nsons are still missing. She told the Mission that she had lodged a complaint but has not heard\nback, that she believes they are still in prison and that she continues to look for them."},{"id":"a-hrc-50-crp-3-p0119","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"119","seq":119,"section":"F. Disappearances","text":"Another victim, who was detained himself and whose five brothers are still missing\nafter the mass killings that followed Mohsen Al-Kani’s death in September 2019, told the\nMission that out of fear he did not dare ask about their whereabouts or whether they were\nstill alive. He only felt safe enough to file a complaint and take a DNA test until after Tarhuna\nwas liberated; he still has not received any information about his brothers’ whereabouts."},{"id":"a-hrc-50-crp-3-p0120","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"120","seq":120,"section":"F. Disappearances","text":"Victims held at the Judicial Prison and the Boxes Prison told the Mission that the\nprisoners were not allowed to receive visits or communicate with their families in any way,\nand that when the family asked about them, they did not receive an answer. Additionally, one\nof the prisoners had been told that he did not have any rights and that he was going to die in\ndetention."},{"id":"a-hrc-50-crp-3-p0121","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"121","seq":121,"section":"F. Disappearances","text":"Another victim explained that her husband had been arrested at a checkpoint. When\nhe did not return home the following day, she went to the checkpoint to look for him and\nasked about him at a nearby military police station. One of the officers confirmed that her\nhusband had been arrested the day before but said that he did not know where he was taken.\nShe also said that she did not know whether he was dead or alive for two months and that\nlater she was told in an anonymous phone call that he had actually been killed immediately\nand thrown into the desert."},{"id":"a-hrc-50-crp-3-p0122","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"122","seq":122,"section":"F. Disappearances","text":"Another witness told the Mission that the al-Kaniyat denied any knowledge of the\nwhereabouts of his nephew whose body was later discovered in the Gabina mass grave."},{"id":"a-hrc-50-crp-3-p0123","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"123","seq":123,"section":"G. Killings","text":"Since they began establishing their rule over the city, the al-Kaniyat regularly killed\npeople in Tarhuna. People were killed in the street, in their homes, during family gatherings\n(such as funerals), at checkpoints and in prisons."},{"id":"a-hrc-50-crp-3-p0124","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"124","seq":124,"section":"G. Killings","text":"In some cases, many members of the same family were eliminated as they opposed\nthe al-Kaniyat activities in Tarhuna, including one family that was killed because they refused\nto have one female family member in her early twenties marry one of the Al-Kani brothers.\nFor example, the Mission received information regarding the killings of at least 13 members\nof the Al-Awashir family, at least 13 members of the Abu-Klish family, and at least seven\nmembers of the Said Abdel Qader family. Killing practically entire families appears to have\nbeen a way for the al-Kaniyat to ensure no one would take revenge."},{"id":"a-hrc-50-crp-3-p0125","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"125","seq":125,"section":"G. Killings","text":"More than a dozen victims described how their relatives, cell mates or others were\nkilled while in detention. Some died as the consequence of torture. One victim stated that in\nthe Boxes Prison, some days four to six people would get killed and some days 16. In the\nJudicial Prison, one victim saw the execution of up to ten detainees and another witnessed\nthe killing of six."},{"id":"a-hrc-50-crp-3-p0126","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"126","seq":126,"section":"G. Killings","text":"Others recounted killings during the raids on their homes or abductions at checkpoints\nor in the street. For example, at a checkpoint, a victim witnessed the torture and murder of\nanother victim whose stomach, as well as hands and feet were pierced with a Kalashnikov\nbayonet. It is suspected that he was targeted because he was working for the government in\nTripoli. Similarly, after disappearing one family member in September 2019 and shooting\nanother in the streets of Tarhuna with 30 bullets in December 2019, al-Kaniyat members\nattacked the family at the latter’s funeral, abducting and killing more relatives. When asked\nwhy they were being targeted, one of the victims explained that it was because his uncle was\nan important merchant, who owned a gas station and real estate and had supported the 17\nFebruary revolution."},{"id":"a-hrc-50-crp-3-p0127","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"127","seq":127,"section":"G. Killings","text":"Numerous victims also recounted two mass killings – one in the aftermath of the\nkilling of Mohsen Al-Kani in September 2019 and the other in the aftermath of the injury of\nAbdel Rahim Al-Kani in December 2019, which both occurred during hostilities with the\nGNA."},{"id":"a-hrc-50-crp-3-p0128","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"128","seq":128,"section":"G. Killings","text":"According to several victims, members of the al-Kaniyat militia killed detainees in\nvarious prisons, as well as non-detainees, all out of revenge for the death of Mohsen Al-Kani\nwho died on or about 13 September 2019. The militia gathered people from the prisons and\nother locations and killed them en masse. One of the victims was later found in a mass grave.\nThe numbers of those killed are estimated by witnesses between 35-70."},{"id":"a-hrc-50-crp-3-p0129","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"129","seq":129,"section":"G. Killings","text":"According to several victims, the Judicial Prison and the Central Support Prison were\nthe site of what some refer to as the ‘21 December 2019 massacre’ when a large group of\npeople was killed in revenge for the injury of Abdel Rahim Al-Kani in an attack by the GNA\nforces the previous day. Estimates from witnesses place the number of people executed\nbetween 30 to above 40."},{"id":"a-hrc-50-crp-3-p0130","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"130","seq":130,"section":"G. Killings","text":"A victim recalled the mass killing as follows:\nAt the Judicial Prison, I remember the night of 21 December 2019. The night where\nthey killed tens and tens of detainees following the injury of Abdel Rahim Al-Kani\n(…) Before the evening prayers, an inmate noticed something unusual. He was\nlooking through the small window and saw a group of armed men spreading around\nthe prison. Few seconds later, we heard intensive shooting in the air and the prison\nbecame chaotic. The armed men were calling each other through their walkie-talkie\nand detainees were screaming. I also heard fire shooting in the Central support Prison\nwhich was located very close to the Judicial Prison. Few minutes later, three\nunmasked men came to our cell and picked seven detainees. They dragged them out\nof the cell. Then we heard fire shooting in the prison yard. We learned that the seven\ndetainees were executed. I was very scared, and I began to pray. On the next day,\nanother detainee was brought to our cell (...) He had been in a different cell on the\nnight of the massacre. He told us that he had seen a group of masked men dragging\ntens of detainees to the prison yard, handcuffing them and placing plastic bags on their\nheads before executing them. They shot them dead."},{"id":"a-hrc-50-crp-3-p0131","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"131","seq":131,"section":"G. Killings","text":"Other non-detainees were also killed in the aftermath of the attack against Abdel\nRahim Al-Kani. For example, a victim recounted that the al-Kaniyat had arrested many\npeople that day, and that his two brothers were taken from their home the same evening. One\nof the brothers was killed while the other managed to escape. The body of the victim was\nidentified in the Harouda farm mass grave site in September 2020."},{"id":"a-hrc-50-crp-3-p0132","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"132","seq":132,"section":"G. Killings","text":"Another man had been killed reportedly for no reason other than being in the street\nwhen al-Kaniyat members passed by them. At his funeral, the mourners were attacked by\naround 30 vehicles with many masked militia members who shot at the family, yelling: ‘you\nare a rat, you deserve it.’ Al-Kaniyat members also arrested and took away numerous family\nmembers, some of whom were later found and identified in Tarhuna mass graves."},{"id":"a-hrc-50-crp-3-p0133","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"133","seq":133,"section":"H. Mass graves","text":"There is no definition under international law of ‘mass graves.’ The Mission adopts\nthe definition as contained in the Bournemouth Protocol, which states: ‘[t]he term mass grave\nis used here to mean ‘a site or defined area containing a multitude (more than one) of buried,\nsubmerged or surface scattered human remains (including skeletonised, commingled and\nfragmented remains), where the circumstances surrounding the death and/or the body-\ndisposal method warrant an investigation as to their lawfulness’20 such as indications of\nextrajudicial, summary or arbitrary executions.21"},{"id":"a-hrc-50-crp-3-p0134","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"134","seq":134,"section":"H. Mass graves","text":"Since al-Kaniyat’s departure from the city in June 2020, the Libyan authorities, with\ninternational assistance, have located four mass grave sites and several individual graves.\nfrom which they recovered 247 bodies, 138 of which have thus far been positively identified,\nincluding three children and eight women.22"},{"id":"a-hrc-50-crp-3-p0135","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"135","seq":135,"section":"H. Mass graves","text":"The Mission’s Forensic Doctor conducted an analysis of the findings as well as a site\nvisit and concurred that the position of the bodies indicates that they had been dumped\nrandomly rather than laid to rest in a proper burial process. Furthermore, according to\nGASIMP, all recovered bodies had gunshot wounds to either the back of the head or chest,\nand over 90% of them were bound by the hands and blindfolded. Five cases of torture prior\nto death were documented by the Mission’s Forensic Doctor."},{"id":"a-hrc-50-crp-3-p0136","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"136","seq":136,"section":"H. Mass graves","text":"In May 2022, the Mission visited the four mass grave sites, which are referred to as,\nthe Landfill; Al Rabt Project; Gabina; and 5Km Agricultural site."},{"id":"a-hrc-50-crp-3-p0137","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"137","seq":137,"section":"H. Mass graves","text":"The Landfill is more than 100 hectares in size. Thus far, one hectare has been explored\nand five mass and two individual graves have been found, from which 34 bodies were\nrecovered. Resources are required to continue investigating this area.23"},{"id":"a-hrc-50-crp-3-p0138","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"138","seq":138,"section":"H. Mass graves","text":"At Al Rabt Project, an additional 20 other body parts were also recovered. In one mass\ngrave at this location, four bodies of women were found together. In another mass grave,\nthree women (the Harouda sisters) and a man were discovered. The largest mass grave found\nhere included 11 bodies with each body still handcuffed with gunshot wounds to the back of\nthe head or the chest.24"},{"id":"a-hrc-50-crp-3-p0139","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"139","seq":139,"section":"H. Mass graves","text":"At 5Km Agricultural site, 10 mass and nine individual graves were found from which\n54 bodies were recovered. The vast majority of the bodies were still handcuffed with gunshot\nwounds to the back of the head or the chest. Some were still blindfolded. It would also appear\nthat the perpetrators mixed the earth with barley seeds in an apparent attempt to conceal the\nlocation.25"},{"id":"a-hrc-50-crp-3-p0140","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"140","seq":140,"section":"H. Mass graves","text":"At the Gabina site, two mass graves and nine individual graves were uncovered from\nwhich 16 bodies were recovered. The majority of the bodies were still handcuffed with\ngunshot wounds to the back of the head or the chest. Some were still blindfolded. Four\nindividuals were found with their car license plates. The licence plate numbers facilitated the\nsearch for the victims’ families. The victims’ identity was then also confirmed through DNA\ntesting and the families confirmed that the victims had been kidnapped by members of the\nal-Kaniyat militia who had also confiscated the victims’ cars.26"},{"id":"a-hrc-50-crp-3-p0141","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"141","seq":141,"section":"H. Mass graves","text":"The bodies of nine members of the Jaballah family who had been abducted on 21\nDecember 2019 were found in a mass grave in Tarhuna on 31 January 2021. One of them\nstill had cigarettes and a lighter in his pocket and another had his oxygen inhaler; they were\nalso wearing the same socks and shoes as on the day of their abduction, indicating that they\nwere likely killed on the same day."},{"id":"a-hrc-50-crp-3-p0142","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"142","seq":142,"section":"H. Mass graves","text":"According to insider knowledge, there might still be up to 100 as of yet undiscovered\nmass graves.\nFindings of new Mass Graves in Tarhuna"},{"id":"a-hrc-50-crp-3-p0143","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"143","seq":143,"section":"H. Mass graves","text":"In this regard, the Mission identified three locations that may represent some of these\nundiscovered mass graves. While the Mission preserves evidence of its findings of new mass\ngraves in Tarhuna, further measures to take in this regard are at the disposal of the Libyan\nauthorities and the victims so that the truth of what is inside those probable mass graves is\nuncovered. To identify whether these places were mass graves, the Mission first used sources\nto locate the best possible GPS coordinates and compared those coordinates with relevant\nexisting evidence about known criminality nearby. Based on this information, the Mission\nthen requested assistance from UNOSAT to provide imagery and analysis of these locations\nover the relevant timeframe. The resulting imagery and analysis (see below) provided\nevidence that all three sites experienced soil disturbances consistent with mass graves, such\nas the digging of holes, movement of heavy machinery, and construction of buildings nearby.\nIn one of these sites, the imagery of a location which is within a short walking distance to the\nJudicial Prison shows the clear expansion of holes and mounds that are consistent with a mass\ngrave. The Mission is ready to share its technical knowledge and provide its findings to the\nLibyan authorities in order to excavate these new locations and to uncover the truth about\nany possible buried bodies."},{"id":"a-hrc-50-crp-3-p0144","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"144","seq":144,"section":"A. Introduction","text":"The Mission has approached the accountability aspect of its mandate in recognition\nof the fact that it is neither a judicial body nor a prosecutor. It cannot make final\ndeterminations of individual criminal responsibility. It can however determine whether its\nfindings establish reasonable grounds that crimes against humanity have been committed, so\nas to merit a criminal investigation by a competent national or international organ of justice,\nand preserve the relevant evidence. The Mission’s findings must be understood as being on\nthe basis of the ‘reasonable grounds’ standard of proof even when the full expression is not\nnecessarily expressed throughout the text."},{"id":"a-hrc-50-crp-3-p0145","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"145","seq":145,"section":"A. Introduction","text":"Applied to crimes against humanity, the ‘reasonable grounds’ standard of proof is\napplied to making factual determinations on individual cases, incidents and patterns of\nconduct which then provide the basis for their legal qualification as crimes against humanity.\nIn order to identify perpetrators, the Mission decided that there must be a reliable body of\nmaterial consistent with other verified information, which tends to show that a person may\nreasonably be suspected of being involved in the commission of a crime."},{"id":"a-hrc-50-crp-3-p0146","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"146","seq":146,"section":"A. Introduction","text":"In this paper, the Mission has focused its analysis of the crimes in Tarhuna in terms\nof crimes against humanity, although criminal conduct can be both a crime against humanity\nand a war crime. For conduct to be classified as a war crime it is not required by law that the\nconduct be part of a widespread or systematic attack against a civilian population but a nexus\nto an armed conflict is required. Since crimes against humanity encapsulate gross violations\nof international human rights law, and can be committed at all times, whether during armed\nconflict or in peacetime, the violations are not considered explicitly under the framework of\ninternational human right law. However, relevant human rights jurisprudence is applicable\nin the analysis of the underlying acts."},{"id":"a-hrc-50-crp-3-p0147","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"147","seq":147,"section":"B. Widespread and Systematic Attack on a Civilian Population","text":"Based on the body of testimony and information received, the Mission finds\nreasonable grounds to believe that members of the al-Kaniyat militia committed crimes\nagainst humanity against a civilian population in Tarhuna."},{"id":"a-hrc-50-crp-3-p0148","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"148","seq":148,"section":"B. Widespread and Systematic Attack on a Civilian Population","text":"The Mission finds that there was an attack, consisting of a course of conduct based on\nthe fulfilment of the actus reus requirements of the underlying acts of murder, extermination,\nrape, imprisonment, torture, persecution on political grounds, enforced disappearance and\nother inhumane acts by the al-Kaniyat militia against hundreds of civilians in Tarhuna that\nbegan in 2014 and continued until 2020. In line with the Mission’s temporal mandate, the\nreport and this analysis focuses on criminal conduct occurring from the beginning of 2016\nuntil June 2020 specifically."},{"id":"a-hrc-50-crp-3-p0149","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"149","seq":149,"section":"B. Widespread and Systematic Attack on a Civilian Population","text":"As detailed in this report, those targeted in Tarhuna, and victims of murder,\nextermination, torture, imprisonment, persecution and enforced disappearance, were\npredominantly civilians and included the elderly, persons with disabilities, women, and\nchildren. Although not documented by the Mission, among the hundreds of victims of the\ncrimes against humanity committed by the al-Kaniyat, there is a possibility that some may\nhave been GNA combatants from the 2019-2020 non-international armed conflict that took\nplace between the GNA and the LNA in and around southern Tripoli and down to Tarhuna,\nwho were no longer taking part in hostilities when the crimes were perpetrated because they\nhad been placed hors de combat, in particular, due to their wounds and/or having been\ndetained."},{"id":"a-hrc-50-crp-3-p0150","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"150","seq":150,"section":"B. Widespread and Systematic Attack on a Civilian Population","text":"There are reasonable grounds to believe that the attack was both widespread and\nsystematic. As outlined in this report, there is evidence of a policy by the Al-Kaniyat and\nassociated armed groups to regularly arrest and detain without any form of due process\nmembers of the population of Tarhuna, abduct them from their homes and from the street, to\nimprison them without due process, often secretly, to torture and murder them in detention,\nto execute them, including in public, and to exterminate dozens of people at once, including\nentire families and prison populations. The large number of victims, numbering in the\nhundreds, as detailed in this report, within a small geographical area, indicate that this attack\ncan be described as ‘widespread’."},{"id":"a-hrc-50-crp-3-p0151","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"151","seq":151,"section":"B. Widespread and Systematic Attack on a Civilian Population","text":"Although, it is not necessary to also conclude that the attack was systematic, there are\nreasonable grounds to believe that the ‘systematic’ requirement is satisfied. The Mission\nconsiders that the multitude of underlying acts committed by the al-Kaniyat militia\nconsidered in this report were committed pursuant to an organizational policy, such that they\ncould cumulatively be described as a deliberate campaign of terror, control, punishment and\noppression of the civilian population of Tarhuna. The evidence indicates a clear and\nconsistent pattern of similar, large-scale, and interlinked criminal conduct, based on the same\nmodus operandi, and consisting primarily of systematic abductions, arbitrary detention,\nenforced disappearance, torture, and executions at point blank range, often in broad daylight\nand in public. This criminal conduct is in line with an underlying political objective to\npersecute and punish opposition and silence critics, to consolidate power and wealth,\nincluding by eliminating actual or perceived political opponents, actual and perceived\nsupporters of the February 17 revolution, wealthy individuals (after which they appropriated\ntheir land and assets), and critics of the Al-Kani family."},{"id":"a-hrc-50-crp-3-p0152","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"152","seq":152,"section":"B. Widespread and Systematic Attack on a Civilian Population","text":"From April 2019 until June 2020, when they were integrated into LNA forces fighting\nagainst the GNA, they also systematically eliminated individuals as revenge for al-Kani\ndeaths caused by the GNA, critics of the war on Tripoli, critics of the LNA from towns or\ncities known to support the GNA, perceived supporters of the GNA, and those who refused\nto join the ranks of their militia. Acts of murder, imprisonment and torture committed in that\ntime period in relation to these victims may also amount to war crimes."},{"id":"a-hrc-50-crp-3-p0153","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"153","seq":153,"section":"B. Widespread and Systematic Attack on a Civilian Population","text":"Thus, the al-Kaniyat militia exerted absolute dominance over the town, through which\nit generated and perpetuated a climate of lawlessness, fear and terror. This fostered an\nenvironment for the commission of further crimes with total impunity, and with the imputed\nknowledge of State authorities. As described in this paper, organized efforts were made to\nconceal the crimes committed by burying corpses in mass graves, which were only\ndiscovered following the end of the conflict in June 2020, when the LNA, the al-Kaniyat\nmilitia and associated armed groups withdrew to the east of the country."},{"id":"a-hrc-50-crp-3-p0154","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"154","seq":154,"section":"1. Imprisonment or other severe deprivation of physical liberty27","text":"The Mission finds that detainees of all four prisons investigated in this report – the\nJudicial Prison (Al Qadaiyah), the Boxes Prison, the Water Factory, and the Central Support\nPrison - are victims of the crime of imprisonment. Suspects of what the al-Kaniyat would\nconsider ‘wrongs’ were violently abducted, from a checkpoint, a street, or their homes, and\nbrought to a detention facility. Often, victims could only guess the reason for their abduction\nfrom the line of interrogation."},{"id":"a-hrc-50-crp-3-p0155","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"155","seq":155,"section":"1. Imprisonment or other severe deprivation of physical liberty27","text":"As the al-Kaniyat operated with disregard for the law, and with total impunity,\ndetainees were never brought before a judge in accordance with article 9(3) and (4) of the\nInternational Covenant on Civil and Political Rights (ICCPR) nor were they ever charged,\nconvicted or sentenced to imprisonment, following a fair and public hearing, by a competent,\nindependent and impartial tribunal established by law as would be required by article 14(1)\nof the ICCPR."},{"id":"a-hrc-50-crp-3-p0156","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"156","seq":156,"section":"1. Imprisonment or other severe deprivation of physical liberty27","text":"Victims were not imprisoned for reasons that conform to international human rights\nlaw. As detailed in this paper, if the al-Kaniyat did not immediately execute a victim\nfollowing their abduction, they detained victims in the Judicial Prison and other prisons under\ntheir control without charge or any form of due process. As detailed above, victims were not\naccused of any criminal wrongdoing, but were imprisoned arbitrarily, based on perceived\naffiliations, family links, political opinions or allegiances, opposition to the al-Kaniyat, or\neven their wealth."},{"id":"a-hrc-50-crp-3-p0157","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"157","seq":157,"section":"1. Imprisonment or other severe deprivation of physical liberty27","text":"Victims told the Mission that they had been held incommunicado and subjected to\ncruel and inhuman treatment as a result of the conditions of detention. Many were severely\ntortured, in violation of Articles 1 and 2 of the United Nations Convention against Torture\nand Other Cruel, Inhuman or Degrading Treatment or Punishment (Convention Against\nTorture), during their confinement and languished for several months as disappeared persons\nbefore they were ultimately taken out and executed."},{"id":"a-hrc-50-crp-3-p0158","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"158","seq":158,"section":"1. Imprisonment or other severe deprivation of physical liberty27","text":"Given the violent nature of the abductions and the lack of due process, the conditions\nof detention, and the atrocities perpetrated in places of detention, the perpetrators involved\nin arbitrary arrest and detention must have known that those detained were civilians, that they\nwere arrested and detained without due process of law, that they were subjected to inhumane\nconditions of detention, and in most cases, subjected to torture and ultimately executed.\n2.        Torture28 and other inhumane acts29"},{"id":"a-hrc-50-crp-3-p0159","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"159","seq":159,"section":"1. Imprisonment or other severe deprivation of physical liberty27","text":"Torture, as defined under international criminal law and international human rights\nlaw, was an established feature of the prisons under the control of the al-Kaniyat. The\ninstances of torture recounted in this paper have taken place in detention facilities where the\nvictims have been in the custody, and under the control, of armed prison guards. The Mission\nfinds that the same forms of physical and psychological torture were used systematically in\nthe four prisons to punish, humiliate and intimidate victims held largely on discriminatory\npolitical grounds. The Mission has documented a wide range of methods of torture; in many\ncases, several of these methods were employed against a single victim."},{"id":"a-hrc-50-crp-3-p0160","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"160","seq":160,"section":"1. Imprisonment or other severe deprivation of physical liberty27","text":"As detailed in Section IV.E above, daily, constant beatings, stabbings, balanco\nsuspension for hours, which often resulted in broken bones, drilling into limbs, and other\natrocities, all amount to severe physical pain and suffering and mental anguish amounting to\ntorture. The Mission also documented one case of rape in detention, amounting to torture."},{"id":"a-hrc-50-crp-3-p0161","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"161","seq":161,"section":"1. Imprisonment or other severe deprivation of physical liberty27","text":"The Mission also considers that the cumulative effect of the circumstances and\nconditions in the places of detention also amounted to inhuman and degrading treatment and\ntorture. In the Boxes Prison in particular, the compounding effect of compelling vulnerable\npersons to live 24 hours a day, incommunicado, in claustrophobic cells similar to boxes - that\nsometimes were transformed into hot ovens - in darkness, with inadequate food and water,\nthe inability to exercise, and with the certainty, in most cases, of ultimate execution, in itself\namounts to torture."},{"id":"a-hrc-50-crp-3-p0162","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"162","seq":162,"section":"1. Imprisonment or other severe deprivation of physical liberty27","text":"The inhumanity of the overall situation in each of the prisons was particularly shaped\nby the cumulative effect of being held in unsanitary conditions, with scarce food and water,\nwhile hearing the screams and cries of torture and the executions of fellow detainees,\nwitnessing deaths in custody, and being threatened with execution, ultimately amounting to\ndeliberate and severe psychological torture."},{"id":"a-hrc-50-crp-3-p0163","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"163","seq":163,"section":"1. Imprisonment or other severe deprivation of physical liberty27","text":"Given that this treatment and these acts were inflicted upon these victims with the\nintent to punish, some of these acts also amount to war crimes, where the victims were\nopponents of the LNA, or GNA supporters (actual or perceived) during the April 2019-June\n2020 non-international armed conflict."},{"id":"a-hrc-50-crp-3-p0164","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"164","seq":164,"section":"1. Imprisonment or other severe deprivation of physical liberty27","text":"Furthermore, most of the victims inside the prisons were detained as forcibly\ndisappeared persons, isolated from their families for long periods. This is also a violation of\nthe right to humane conditions of detention and the prohibition of torture, with the victims of\nthe latter being both the disappeared person and their relatives. With respect to the latter, the\nuncertainty about the fate of their loved ones is a source of continued anguish and anxiety,\nwhich results from the refusal to acknowledge the deprivation of freedom or to give\ninformation about the whereabouts of these persons. Not knowing whether the disappeared\nis still alive, and if so in what state of health and under which conditions, causes a level of\nmental distress and suffering so severe which, in numerous cases documented by the Mission,\nalso rises to the level of torture as a crime against humanity."},{"id":"a-hrc-50-crp-3-p0165","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"165","seq":165,"section":"1. Imprisonment or other severe deprivation of physical liberty27","text":"As to the mental element, given the nature of the acts described in this paper, it is\nimplausible that the perpetrators did not intend to inflict pain or suffering. It is considered\nthat the infliction was intentional, and the mental element satisfied.\n3.        Extermination30 and Murder31"},{"id":"a-hrc-50-crp-3-p0166","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"166","seq":166,"section":"1. Imprisonment or other severe deprivation of physical liberty27","text":"The elements of murder and extermination as crimes against humanity are identical\nsave for the ‘mass killing’ requirement. Taken by themselves, the individual killings detailed\nin Section IV.G above do not meet the “large scale” requirement. However, cumulatively,\nthe individual or smaller-scale executions for which the al-Kaniyat militia was responsible,\noccurred on a large scale, even though they took place over several years, and amount to\nextermination. All of the killings documented by the Mission were perpetrated in the same\ntown, in similar circumstances, by the same perpetrators. As detailed, the victims were all\ncivilians, targeted for the same reasons, not in their individual capacity but as part of a policy\nto eliminate all opposition to the al-Kaniyat."},{"id":"a-hrc-50-crp-3-p0167","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"167","seq":167,"section":"1. Imprisonment or other severe deprivation of physical liberty27","text":"The massacres of families and prisoner populations that occurred in a single\ntransaction, as detailed above, clearly meet the ‘large scale’ requirement. Furthermore, the\nmurders carried out in revenge in relation to GNA attacks during the non-international armed\nconflict which occurred between April 2019 and June 2020 may also amount to war crimes."},{"id":"a-hrc-50-crp-3-p0168","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"168","seq":168,"section":"1. Imprisonment or other severe deprivation of physical liberty27","text":"Evidence gathered by the Mission, as detailed above in paragraph 54, indicates that\napproximately 271 individuals were exterminated by members of the al-Kaniyat between\n2016 and 2020. The number of people still listed as missing from Tarhuna provides further\nguidance as to the likely number of victims executed. A minimum of 215 persons from\nTarhuna are still listed as missing, based on the cross-referencing of lists and other sources."},{"id":"a-hrc-50-crp-3-p0169","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"169","seq":169,"section":"1. Imprisonment or other severe deprivation of physical liberty27","text":"As detailed above, the predominant method of killing was by gunshot, execution style,\nfollowing an abduction and/or period of detention. Many were killed whilst blindfolded and\nhandcuffed. Some of these victims reportedly died under torture (see supra paragraph 104)."},{"id":"a-hrc-50-crp-3-p0170","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"170","seq":170,"section":"1. Imprisonment or other severe deprivation of physical liberty27","text":"The bodies of many of these victims were consigned to mass graves, which were later\ndiscovered and exhumed. Although forensic experts have not yet been able to conclude with\ncertainty how many bodies linked to the crimes perpetrated by the al-Kaniyat are in mass\ngraves in and around Tarhuna, as they are still uncovering them, a conservative estimate is\nthat a minimum of 247 bodies have been exhumed from mass graves. It is expected that the\ntotal number of bodies found and linked with the atrocities in Tarhuna will increase as these\nsites continue to be exhumed."},{"id":"a-hrc-50-crp-3-p0171","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"171","seq":171,"section":"1. Imprisonment or other severe deprivation of physical liberty27","text":"There are reasonable grounds to believe that the perpetrators meant to cause these\ndeaths, based on the method of killing, the large scale and systematic nature of the killings;\nand the fact that the victims’ bodies were concealed in mass graves. Furthermore, there is\nevidence that many of the executioners were acting on explicit orders to kill.\n4.        Persecution32"},{"id":"a-hrc-50-crp-3-p0172","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"172","seq":172,"section":"1. Imprisonment or other severe deprivation of physical liberty27","text":"The Mission finds that the widespread and systematic attack against a defined\npopulation in Tarhuna was carried out by the al-Kaniyat on the basis of the political\naffiliations, actual or perceived, of the targeted population. Most of those targeted represented\nopposition, dissent, a threat to power, or otherwise a lack of support or obedience to the al-\nKaniyat. This is notably evidenced by the nature of the interrogations and accusations\nlevelled at victims (see the testimonies included in Section IV.B above)."},{"id":"a-hrc-50-crp-3-p0173","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"173","seq":173,"section":"1. Imprisonment or other severe deprivation of physical liberty27","text":"The deliberate and systematic disappearance and killing of civilians, as well as their\norganised abduction, detention, and torture, are blatant denials of fundamental rights and\nconstitute persecution as these acts qualify as other underlying acts of crimes against\nhumanity, namely extermination, enforced disappearance, imprisonment and torture. The\nMission therefore finds that the circumstances accompanying the terrorising, the cruel and\ninhumane treatment of the civilians, the enforced disappearances and exterminations\nevidence the existence of a discriminatory intent of the perpetrators on political grounds and\namounted to a persecutorial campaign against all opponents in Tarhuna.\n5.        Enforced disappearance33"},{"id":"a-hrc-50-crp-3-p0174","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"174","seq":174,"section":"1. Imprisonment or other severe deprivation of physical liberty27","text":"The Declaration on the Protection of All Persons from Enforced Disappearance\ncategorises enforced disappearance as a grave and flagrant violation of the human rights and\nfundamental freedoms proclaimed in the Universal Declaration of Human Rights, and an\naffront to human dignity.34"},{"id":"a-hrc-50-crp-3-p0175","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"175","seq":175,"section":"1. Imprisonment or other severe deprivation of physical liberty27","text":"According to testimony obtained by the Mission on the modus operandi of the practice\nof disappearances by the al-Kaniyat, the kidnappers followed a pattern. A person suspected\nof being opposed to the al-Kaniyat, or a critic, or a supporter of the GNA, was violently\nseized. He or she was put into a military vehicle and taken away. The perpetrators often\nappeared in plain clothes so that no personal names or affiliations were visible. In almost all\ncases, the victim was held incommunicado in prison, with no access to family or legal\ncounsel."},{"id":"a-hrc-50-crp-3-p0176","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"176","seq":176,"section":"1. Imprisonment or other severe deprivation of physical liberty27","text":"From the perspective of the victims’ relatives, targets of the al-Kaniyat were regularly\ndisappeared and not heard from again until their body was discovered in a mass grave, in\nsome cases, years later. Often, and unbeknownst to the family until later, the person was\nsecretly detained for a period of time before either being released or executed. When a\ndetainee was killed, whether following a period of detention or not, the family was not\nnotified, and the al-Kaniyat denied their families the opportunity to collect the body for\nburial, instead concealing the victims’ bodies in mass graves, thereby prolonging their\nenforced disappearance. Both situations amount to enforced disappearance in that the initial\narrest was followed by refusal to disclose the fate or whereabouts of the victim, who was\nintentionally placed outside the protection of the law."},{"id":"a-hrc-50-crp-3-p0177","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"177","seq":177,"section":"1. Imprisonment or other severe deprivation of physical liberty27","text":"Making opponents and other targets disappear was a deliberate feature of the system\nput in place by the al-Kaniyat that served to instil fear in the population of Tarhuna by\ndemonstrating that anyone who did not demonstrate allegiance or support could disappear at\nany time for reasons solely determined by, and known to, the al-Kaniyat. Refusing to deliver\nthe bodies to the families was also a form of revenge exacted on the population."},{"id":"a-hrc-50-crp-3-p0178","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"178","seq":178,"section":"1. Imprisonment or other severe deprivation of physical liberty27","text":"As detailed above, following a violent abduction, families of detainees were not\ninformed of the fate or whereabouts of their detained family member. At best, the al-Kaniyat\ncommonly refused to acknowledge the imprisonment outright, or evaded questions from\nfamily members. However, the Mission documented cases in which victims were tortured or\nkilled for simply wanting to know the whereabouts of their loved ones. As a consequence of\nthe climate of fear and terror instilled in the population of Tarhuna, several witnesses testified\nthat they were terrified of approaching the al-Kaniyat or other authorities in Tarhuna in\nrelation to disappeared relatives."},{"id":"a-hrc-50-crp-3-p0179","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"179","seq":179,"section":"1. Imprisonment or other severe deprivation of physical liberty27","text":"As to the mental element, the Mission collected evidence that abductions and\ndetentions were either carried out by, or with the authorization, support or acquiescence of,\nor on the direct orders of, al-Kaniyat leaders. In many instances, the al-Kaniyat was put on\nnotice that individuals were missing and actively promoted and participated in the forced\ndisappearance of their opponents and critics in Tarhuna. The Mission considers that the\ndisappearances were intentional, and the mental element is satisfied."},{"id":"a-hrc-50-crp-3-p0180","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"180","seq":180,"section":"1. Imprisonment or other severe deprivation of physical liberty27","text":"Despite the fact that the al-Kaniyat no longer exert any authority in Tarhuna, since\ntheir departure from the town in June 2020, many of the cases of enforced disappearance in\nrelation to the events in Tarhuna are continuous crimes, which will only come to an end when\nthe fate and whereabouts of all victims have been fully disclosed."},{"id":"a-hrc-50-crp-3-p0181","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"181","seq":181,"section":"D. The individual criminal responsibility of alleged perpetrators","text":"The importance of determining individual criminal responsibility for international\ncrimes whether committed under the authority of the State or outside such authority stands\nand is a critical aspect of the enforceability of rights and of protection against their violation."},{"id":"a-hrc-50-crp-3-p0182","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"182","seq":182,"section":"D. The individual criminal responsibility of alleged perpetrators","text":"International crimes, in particular crimes against humanity, genocide and war crimes,\nare not codified in Libyan law."},{"id":"a-hrc-50-crp-3-p0183","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"183","seq":183,"section":"D. The individual criminal responsibility of alleged perpetrators","text":"Libyan law fails to capture the particular gravity of crimes against humanity and the\nmens rea thereof that the underlying acts are committed “as part of a widespread or systematic\nattack directed against any civilian population, with knowledge of the attack.” Charging an\nindividual with “ordinary” crimes such as murder, torture, and enforced disappearance,\nwithout considering whether it rises to the level of a crime against humanity, does not ensure\nnational proceedings include the conduct and intent covered by the chapeau elements of\nArticle 7 of the Rome Statute of the International Criminal Court."},{"id":"a-hrc-50-crp-3-p0184","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"184","seq":184,"section":"D. The individual criminal responsibility of alleged perpetrators","text":"Furthermore, the underlying acts of crimes against humanity– in particular murder,\ntorture and inhumane treatment, enforced disappearance, and rape – are either not defined,\nor defined inconsistently with the definitions that apply under treaty or customary\ninternational law. For example, the definition of torture under article 2 of Law No. 10 of 2013\nexcludes some of the purposes included in the definition contained in article 1 of the\nConvention against Torture. The definition of ‘forced disappearance’ in Law No. 10 of 2013\nis inconsistent with the International Convention for the Protection of all Persons from\nEnforced Disappearance and customary international law, or acts which are constitutive of\nenforced disappearance and prohibited by the Convention against Torture and the ICCPR."},{"id":"a-hrc-50-crp-3-p0185","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"185","seq":185,"section":"D. The individual criminal responsibility of alleged perpetrators","text":"Although the primary responsibility for ensuring accountability for international\ncrimes in Libya rests with the Libyan justice system, Libya’s legal framework does not meet\ninternational law standards governing the obligation to penalise, investigate and prosecute\ncrimes under international law, and the rights to liberty and to a fair trial. Substantial reforms\nto the legal framework are required to ensure fair and effective justice in future cases,\nregardless of the modality adopted, whether the cases take place in the regular courts or in a\nspecially constituted chamber within the judicial system."},{"id":"a-hrc-50-crp-3-p0186","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"186","seq":186,"section":"D. The individual criminal responsibility of alleged perpetrators","text":"Failing domestic proceedings, individuals could also be held responsible on the basis\nof the Rome Statute of the International Criminal Court, as although Libya is not a State\nparty, the situation in Libya is the subject of a Security Council referral,35 or on the basis of\nuniversal jurisdiction."},{"id":"a-hrc-50-crp-3-p0187","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"187","seq":187,"section":"1. The identification of possible perpetrators","text":"Under international law as much as in national systems, the foundation of criminal\nresponsibility is the principle of personal culpability: nobody may be held criminally\nresponsible for acts or transactions in which he or she has not personally engaged or in some\nother way participated (nulla poena sine culpa). Furthermore, it is an established principle of\ninternational law that perpetrators of crimes against humanity are not relieved of criminal\nresponsibility on the basis that they have acted on superior orders, because orders to commit\ncrimes of such gravity are manifestly unlawful.36"},{"id":"a-hrc-50-crp-3-p0188","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"188","seq":188,"section":"1. The identification of possible perpetrators","text":"The Mission has collected reliable and consistent elements which indicate the\nresponsibility of some individuals for crimes against humanity or war crimes, in Libya and\nparticularly Tarhuna. In relation to Tarhuna, those identified as possibly responsible for\ncrimes against humanity consist of individual perpetrators, while others are identified for\ntheir possible involvement in ordering the commission of international crimes, or for aiding\nand abetting the perpetration of such crimes."},{"id":"a-hrc-50-crp-3-p0189","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"189","seq":189,"section":"1. The identification of possible perpetrators","text":"Where testimony or other information gathered by the Mission indicated the names of\nindividuals who committed, ordered, or aided and abetted crimes against humanity, these\nhave been duly recorded in a confidential list safeguarded as part of the Mission’s\nconfidential database. This list includes the names of suspects, information about the\npotential suspect’s position or role, and a summary of evidence compiled by the Mission\nrelating to the potential suspect."},{"id":"a-hrc-50-crp-3-p0190","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"190","seq":190,"section":"1. The identification of possible perpetrators","text":"The Mission has decided not to publish these names due to: (1) the importance of the\nprinciples of due process and respect for the rights of the suspects in light of article 14 of the\nInternational Covenant on Civil and Political Rights and article 7 of the African Charter on\nHuman and Peoples' Rights, given that the “reasonable grounds” standard of proof is much\nlower than that required in criminal trials, and the individuals have not been afforded the right\nto reply; and (2) its continued adherence to the “do no harm” principle, particularly, the need\nto ensure the protection of witnesses from being harassed, intimidated, or killed."},{"id":"a-hrc-50-crp-3-p0191","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"191","seq":191,"section":"2. Modes of criminal liability for international crimes","text":"Under international criminal law, all those who, individually or jointly, engage in\nconduct considered to be prohibited and criminalized bear individual criminal liability for\ntheir conduct if the requisite mens rea is present. It extends both to the individuals who carry\nout the underlying violent acts, and to the individuals who have planned, instigated, ordered,\nor otherwise aided and abetted in the planning, preparation, or execution of the attacks."},{"id":"a-hrc-50-crp-3-p0192","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"192","seq":192,"section":"2. Modes of criminal liability for international crimes","text":"Assigning criminal responsibility to specific individuals requires an extensive,\nfocused investigation into the actions and state of mind of specific perpetrators and will\nrequire additional fact-finding and investigation. While such an analysis is thus beyond the\nscope of this paper, this section sets out the most relevant analytical frameworks for\nunderstanding potential liability of the perpetrators implicated in the atrocities in Tarhuna."},{"id":"a-hrc-50-crp-3-p0193","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"193","seq":193,"section":"2. Modes of criminal liability for international crimes","text":"The available evidence implicates a number of individuals in the direct commission\nof the enumerated acts, as well as others responsible for ordering or aiding and abetting such\nacts. These individuals could be held criminally responsible if their acts were committed a\npart of the widespread or systematic attack and they acted with knowledge that their conduct\nwas part of such an attack.\nPerpetration"},{"id":"a-hrc-50-crp-3-p0194","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"194","seq":194,"section":"2. Modes of criminal liability for international crimes","text":"The Mission has identified four commanders who participated directly in the\ncommission of crimes against humanity in Tarhuna. In total, 12 individuals have been\nidentified as suspected to have directly committed some of the crimes against humanity and\nwar crimes detailed in this paper."},{"id":"a-hrc-50-crp-3-p0195","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"195","seq":195,"section":"2. Modes of criminal liability for international crimes","text":"Applying the mental element required for a crime against humanity, there are\nreasonable grounds to believe that these individuals are criminally liable for acts of\nextermination, torture, imprisonment, persecution and enforced disappearance which they are\naware were, and intended to be, committed in a widespread and systematic manner against a\ndefined civilian population in Tarhuna.\nOrdering"},{"id":"a-hrc-50-crp-3-p0196","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"196","seq":196,"section":"2. Modes of criminal liability for international crimes","text":"The Mission has gathered reliable material and information which tend to show that\nfour commanders directly ordered the men under their control to exterminate and murder\ncivilians, including those in detention, which are crimes against humanity."},{"id":"a-hrc-50-crp-3-p0197","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"197","seq":197,"section":"2. Modes of criminal liability for international crimes","text":"In addition to the direct commission of the crimes detailed in this report, based on\ncredible and reliable evidence gathered by the Mission, there are reasonable grounds to\nbelieve that these four individuals were directly ordering members of the militia to commit\nthe violations detailed in this paper. Specifically, the Mission received a report that over 150\nmen working for the al-Kaniyat were executing orders to kill, including the killing of\ndetainees from the Judicial Prison and from Tripoli prisons. Several lower-level commanders\nwere also issuing direct orders to subordinates. This evidence, together with evidence\nindicating that the militia only acted upon direct orders, gives rise to a reasonable inference\nthat these four commanders had ordered all of the killings that they did not personally\ncommit, particularly those which were carried out as revenge attacks/reprisals, and including\nviolations occurring in places of detention. Given their authority and control, they must have\nbeen aware of the substantial likelihood that the crimes that they ordered would be\ncommitted."},{"id":"a-hrc-50-crp-3-p0198","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"198","seq":198,"section":"2. Modes of criminal liability for international crimes","text":"For example, one witness told the Mission that the guards at the Boxes Prison would\nconsult with two of these individuals before executing prisoners and that they would come\nand give orders for people to die. Another said that he was detained and tortured by men\nunder the command of the four individuals, giving rise to an inference that those violations\nwere committed upon orders.\nAiding and Abetting"},{"id":"a-hrc-50-crp-3-p0199","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"199","seq":199,"section":"2. Modes of criminal liability for international crimes","text":"The Mission has identified a number of members of the al-Kaniyat militia who are\nsuspected of also having aided and abetted the commission of crimes against humanity and\nwar crimes in Tarhuna. The existing evidence indicates that they aided and abetted the crimes\nthrough: (1) their presence and actions during the course of the attacks, including during\nabductions, at checkpoints, and in prisons; (2) the provision of security at prisons in which\nattacks occurred; and/or (3) their failure to prevent or punish crimes."},{"id":"a-hrc-50-crp-3-p0200","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"200","seq":200,"section":"2. Modes of criminal liability for international crimes","text":"In combination with their authority, including over those in charge of and/or guarding\nthe prisons and checkpoints, their ability to stop the perpetration of the crimes, their presence\nat these places of detention, the fact of prior conduct of ordering and direct perpetration of\nviolations including killings, gives rise to a reasonable inference that those individuals\nintended to aid and abet the crimes detailed in this report that they either did not commit or\norder themselves, even if they were not aware of each single incident."},{"id":"a-hrc-50-crp-3-p0201","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"201","seq":201,"section":"2. Modes of criminal liability for international crimes","text":"For example, one individual gave orders to guards to detain victims at the Judicial\nPrison, where they were later held in inhumane conditions and subjected to torture.\nInterviewees testified as to the presence of one of the individuals at the Judicial Prison, in\nrelation to which the Mission has documented numerous atrocities. A witness told the\nMission that four commanders were in charge of the Boxes Prison where the Mission has\ndocumented torture, including by the same individuals (see Annex below, paragraphs 256-\n258)."},{"id":"a-hrc-50-crp-3-p0202","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"202","seq":202,"section":"2. Modes of criminal liability for international crimes","text":"The militia’s members who carried out arrests, as well as the directors and guards of\nthese places of detention, may also be considered aiders and abettors, as by arresting and\npreventing the escape of the detainees respectively, they substantially contributed to the\nviolations that were committed against these victims in detention, and their subsequent\nkilling. Furthermore, although the Mission was unable to gather evidence on those who\ntransported dead bodies, and those who dug the mass graves, these individuals may also be\nconsidered aiders and abettors of enforced disappearance and extermination."},{"id":"a-hrc-50-crp-3-p0203","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"203","seq":203,"section":"2. Modes of criminal liability for international crimes","text":"The Mission notes that a clear pattern of abductions, disappearances and killings by\nthe al-Kaniyat emerged between 2016 and 2020, and most notably between 2019 and 2020,\na fact which could not have been ignored by those identified by the Mission. By continuing\ntheir actions nonetheless, they may be suspected of having aided and abetted these crimes."},{"id":"a-hrc-50-crp-3-p0204","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"204","seq":204,"section":"E. State Responsibility for crimes against humanity","text":"The Mission was unable to obtain sufficient evidence that the al-Kaniyat was an organ\nof the State as per article 4 of the Articles on Responsibility of States for Internationally\nWrongful Acts. The Mission was also unable to obtain sufficient evidence that they had been\nempowered by the law to exercise elements of governmental authority and had been acting\nin that capacity such that their conduct would be considered an act of the State under\ninternational law in accordance with article 5 of the Articles on Responsibility of States for\nInternationally Wrongful Acts."},{"id":"a-hrc-50-crp-3-p0205","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"205","seq":205,"section":"E. State Responsibility for crimes against humanity","text":"On 14 June 2020, the Prosecutor-General’s office issued a statement concerning the\ninvestigation of crimes committed by armed groups that controlled Tarhuna prior to the GNA\ntaking over this territory. This statement indicated that warrants for arrest for 110 individuals\nhad been issued and that some of these warrants had been executed. The statement further\nelaborated on how forensic experts would be carrying out exhumations and autopsies, that\nDNA samples would be taken from bodies and possible family members for identification\npurposes, and that people should come forward to give evidence regarding the alleged\ninvolvement of al-Kaniyat members in these crimes."},{"id":"a-hrc-50-crp-3-p0206","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"206","seq":206,"section":"E. State Responsibility for crimes against humanity","text":"The Mission emphasizes that crimes against humanity, in their own right, are crimes\nof such gravity that they not only trigger the responsibility of the State concerned but demand\na firm response by the international community as a whole, in the form of universal\njurisdiction but also the provision of technical assistance to the State and capacity building\nto ensure that the perpetrators are held accountable."},{"id":"a-hrc-50-crp-3-p0207","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"207","seq":207,"section":"A. Listening to the victims’ voices","text":"Many of the atrocities documented by the Mission are international crimes that shock\nthe conscience of humanity and have a continuing impact on the victims and the citizens of\nTarhuna and Libya. Listening to the voice of the victims, the Mission noted their demand for\ntruth, justice, reparation and that these crimes never reoccur in Tarhuna and Libya. Those\nresponsible for the crimes of Tarhuna must be held accountable."},{"id":"a-hrc-50-crp-3-p0208","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"208","seq":208,"section":"A. Listening to the victims’ voices","text":"One victim told the Mission “I want dignity for my children, my life, and myself”.\nAnother shared their hope to see justice, telling the Mission “I hope from the bottom of my\nheart that one day justice will take its place and those who committed those atrocities will be\ntried.” Another explained: “I want those criminals to be tried and I want to see them behind\nbars. Justice should prevail.”"},{"id":"a-hrc-50-crp-3-p0209","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"209","seq":209,"section":"A. Listening to the victims’ voices","text":"Tarhuna inhabitants and Libyans in general have the right to know the truth of how,\nwhy and what happened to their relatives. They have a right to know why their town was\nsubject to a reign of terror and who supported the militia permitting them to commit these\ncrimes with complete impunity. The direct victims of crimes against humanity, as well as\nwar crimes, detailed in this paper have the right to reparations in the widest sense. The town\nof Tarhuna suffered destruction, terror and was left full of with mass graves and scenes of\ntorture, killing, abduction and general sense of fear."},{"id":"a-hrc-50-crp-3-p0210","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"210","seq":210,"section":"A. Listening to the victims’ voices","text":"The victims of Tarhuna and their families have continuously expressed to the Mission\nan acute need to see an end to such heinous crimes. For this to happen, Libyan authorities\nhave to take concrete measures so that no weapon remains in the hand of militias, no security\nforces can work outside the ambit of the law, and no political authority support a militia in\ncommitting crimes with impunity in return for political loyalty. There is a legal and ethical\nresponsibility on Libyan officials and duty bearers to admit to the mistake of supporting the\nal-Kaniyat and allowing the perpetrators to terrorize Tarhuna. The failure of senior authorities\nin Tripoli prior to 2019 and in Benghazi after 2019 to prevent such crimes or to prosecute the\nperpetrators is a failure in their duty to protect the human rights of their citizens. Reforming\nsecurity sectors, strengthening Libyan judicial institutions, and ensuring that the rule of law\nand democracy prevail in Libya, are sustainable guarantees for preventing these atrocious\ncrimes from happening again."},{"id":"a-hrc-50-crp-3-p0211","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"211","seq":211,"section":"B. Transitional justice in the context of Tarhuna","text":"The Mission’s core mandate is the documentation of violations of international human\nrights law and international humanitarian law with a view to ensuring that perpetrators of\nthese violations are held accountable. Therefore, through its fact-finding, the Mission seeks\nto contribute to the fight against impunity by contributing to effective prosecutions, which\nare not only indispensable to the realisation of the right to justice, but are also a guarantee of\nnon-recurrence, and thus a central aspect of transitional justice."},{"id":"a-hrc-50-crp-3-p0212","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"212","seq":212,"section":"B. Transitional justice in the context of Tarhuna","text":"As such, the Mission is also an aspect of the operationalisation of the right to truth. In\nthis sense, the Mission’s purpose should be seen as part of a public reckoning of the\nmagnitude of the crimes committed in Tarhuna since 2016, their patterns and causes, and the\nunderlying motives, means and structures used in committing them. By gathering and\nverifying information on violations and perpetrators, the Mission is contributing to the\ncreation of a historical record of events and providing the basis for future investigations,\nthrough which the right to truth may be further realised."},{"id":"a-hrc-50-crp-3-p0213","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"213","seq":213,"section":"B. Transitional justice in the context of Tarhuna","text":"The Mission’s contribution in discovering more mass graves in the recent period and\nthe expectations of finding additional ones pose specific additional challenges. First and\nforemost, a mass grave signifies the commission of a multiplicity of crimes – not only gross\nhuman rights violations, such as the violation of the right to life, the right to recognition as a\nperson before the law, the right to liberty and security of the person, and the right not to be\nsubjected to torture and other cruel, inhuman or degrading treatment or punishment, and\nunlawful handling of human remains but also the intention to obstruct justice.37"},{"id":"a-hrc-50-crp-3-p0214","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"214","seq":214,"section":"B. Transitional justice in the context of Tarhuna","text":"The United Nations Special Rapporteur on extrajudicial, summary or arbitrary\nexecutions also recognizes that , “[l]awful and respectful handling of mass graves are major\nelements of States’ obligations to non-repetition and to the rights of victims to reparation.”38\nIn this respect, decisions must be made about the management of these sites with a view to\nachieving different and sometimes conflicting, objectives emerge such as identification,\ncrime scene investigation and collection of evidence, memorialization and (re)burial.39"},{"id":"a-hrc-50-crp-3-p0215","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"215","seq":215,"section":"B. Transitional justice in the context of Tarhuna","text":"Finally, without positive identification of the dead and the legal recognition of death,\nfamilies of the missing face not only the anguish of not knowing the fate of their loved ones\nbut also “encounter often debilitating impediments to their exercise of inheritance rights.”40"},{"id":"a-hrc-50-crp-3-p0216","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"216","seq":216,"section":"VII. Conclusions and recommendations","text":"The Mission finds reasonable grounds to believe that the crimes against humanity of\nextermination, imprisonment, torture, persecution and enforced disappearance were\ncommitted by members of the al-Kaniyat militia against a defined population in Tarhuna\nsince they asserted control over the town until June 2020. These crimes were committed in a\nwidespread manner, whereby the al-Kaniyat systematically targeted and eliminated all actual\nand perceived opposition with total impunity."},{"id":"a-hrc-50-crp-3-p0217","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"217","seq":217,"section":"VII. Conclusions and recommendations","text":"Given the vast scale of the acts committed against a defined population in Tarhuna,\nover many years, there may be many additional individuals who could also be criminally\nliable, including lower-ranking members of the al-Kaniyat and associated militia."},{"id":"a-hrc-50-crp-3-p0218","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"218","seq":218,"section":"VII. Conclusions and recommendations","text":"The Mission encourages the Libyan authorities to utilize its findings of probable\nadditional mass graves to exhume new locations in search for buried victims."},{"id":"a-hrc-50-crp-3-p0219","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"219","seq":219,"section":"VII. Conclusions and recommendations","text":"The crimes in Tarhuna have victimised entire families, through the killings of male\nfamily members, who were the primary source of economic support for the family, and the\nconsequent traumatisation, fear and impoverishment of remaining family members, including\nchildren."},{"id":"a-hrc-50-crp-3-p0220","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"220","seq":220,"section":"VII. Conclusions and recommendations","text":"In relation to the crimes committed in Tarhuna, the Mission calls on Libya to:\n(a)    End impunity by developing a comprehensive transitional justice agenda\nwhich should include both judicial and non-judicial processes and mechanisms, such as\nprosecution initiatives, facilitating initiatives in respect of the right to truth, delivering\nreparations as well as institutional reform in full conformity with international legal\nstandards and obligations."},{"id":"a-hrc-50-crp-3-p0221","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"221","seq":221,"section":"VII. Conclusions and recommendations","text":"Specifically, the Mission calls on Libyan authorities to:\n(a)    Establish a Special Tribunal for Tarhuna to prosecute international\ncrimes with international technical support and expertise; and ensure that\nstatutes of limitations and amnesties do not to apply for such international crimes\nunder the jurisdiction of this Tribunal. The Tribunal should enjoy an\nindependent judicial law enforcement force at its disposal to implement its\ndecisions, and ensure its protection from interference;\n(b)   Continue searching for the missing and for remaining mass graves, using\nthe Mission’s findings in that regard;\n(c)   Continue exhumations of bodies as well as their identification, in\nconsultation with and full respect for the families of the victims;\n(d)    Analyse and address the deficiencies in Libyan State institutions that have\nenabled – if not promoted – impunity and the attendant cycles of violence that\nhave led to the atrocities; and implement a comprehensive vetting program and\nsecurity sector reform.\n(e)    Develop, adopt and implement a comprehensive program of recognition,\ncompensation and rehabilitation for victims and their families, with a particular\nfocus on providing psychosocial help for the children of Tarhuna; establish a\ntrust fund for developing the town of Tarhuna; and\n(f)    In consultation with the victims’ families, implement measures to preserve\nthe victims’ memory. These measures could include establishing at least one\nschool and naming it in reference to the victims of Tarhuna; allocate a day for\nremembrance for the victims of Tarhuna; and name one street in Tripoli and in\nBenghazi in reference to Tarhuna victims."},{"id":"a-hrc-50-crp-3-p0222","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"222","seq":222,"section":"VII. Conclusions and recommendations","text":"The Mission calls on the international community and States to:\n(a)   Cooperate in criminal matters to prosecute the perpetrators of\ninternational crimes in Tarhuna including via extradition of the accused and\ncooperation;\n(b)    Apply universal jurisdiction over the accused when found on their\nterritory; and\n(c)   Support Libya in all its efforts to implement recommendations above\nthrough technical and other assistance."},{"id":"a-hrc-50-crp-3-p0223","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"223","seq":223,"section":"Annex","text":"The Mission recognises that it is neither a judicial body nor a prosecutor. It cannot\nmake final determinations of individual criminal responsibility. It can however determine\nwhether its findings establish reasonable grounds that crimes against humanity have been\ncommitted so as to merit a criminal investigation by a competent national or international\norgan of justice. The Mission’s findings on crimes against humanity are to be understood as\nbeing on the basis of the ‘reasonable grounds’ standard of proof."},{"id":"a-hrc-50-crp-3-p0224","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"224","seq":224,"section":"Annex","text":"Broadly, the definition of crimes against humanity in Article 7 of the Rome Statute\nreflects that accepted in general international law. It is unknown which variant of this offence\nmay ultimately be utilised in relation to crimes committed in Libya. For its part, the Mission\nhas based its investigations on the definition of crimes against humanity under the Rome\nStatute, however it has not adopted the ICC’s state or organisational policy requirement (of\nthe “attack” component of the chapeau) as formulated in Article 7(2)(a) as a distinct\ncontextual element for two reasons. The first is that there are some indications in ICC\njurisprudence of a nascent shift away from such a requirement41 and secondly, considering\nthe drafting history of the ICC Statute, the rationale underlying the inclusion of a policy\nelement in the definition was to “help distinguish between what is of concern to the\ninternational community on the one hand and, on the other, the sort of crimes that should\nremain the exclusive concern of domestic jurisdictions”.42 This normative limitation,\neffectively limiting the ICC’s jurisdiction, does not apply to the Mission. Furthermore, the\nMission has also departed from the ICC in that it has not applied the ‘prolonged’ requirement\nwith respect to enforced disappearance as a crime against humanity.\nCrimes Against Humanity"},{"id":"a-hrc-50-crp-3-p0225","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"225","seq":225,"section":"Annex","text":"The prohibition of crimes against humanity is recognized as a principle of jus cogens\nand is universally applicable.43 Crimes against humanity entail gross human rights violations\nof a scale and level of organisation that shock the conscience of humanity."},{"id":"a-hrc-50-crp-3-p0226","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"226","seq":226,"section":"Annex","text":"Article 7(1) of the ICC Statute, which largely reflects customary international law,\ndefines crimes against humanity as any of the following acts when committed as part of a\nwidespread or systematic attack directed against any civilian population, with knowledge of\nthe attack:\n(a)    Murder;\n(b)    Extermination;\n(c)    Enslavement;\n(d)    Deportation or forcible transfer of population;\n(e)    Imprisonment;\n(f)    Torture;\n(g)    Rape and forms of sexual violence;\n(h)    Persecution on political, racial, national, ethnic, cultural, religious, gender as\ndefined in paragraph 3, or other grounds;\n(i)    Enforced disappearance of persons;\n(j)    The crime of apartheid;\n(k)     Other inhumane acts of a similar character intentionally causing great\nsuffering, or serious injury to body or to mental or physical health."},{"id":"a-hrc-50-crp-3-p0227","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"227","seq":227,"section":"Annex","text":"Pursuant to Article 7(2)(a) of the Statute, an ‘[a]ttack directed against any civilian\npopulation’ means a course of conduct involving the multiple commission of acts referred to\nin paragraph 1 against any civilian population, pursuant to or in furtherance of a State or\norganizational policy to commit such attack.44\nArticle 7 chapeau requirements\nAttack"},{"id":"a-hrc-50-crp-3-p0228","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"228","seq":228,"section":"Annex","text":"An ‘attack’ for the purposes of crimes against humanity has been described as “a\ncourse of conduct involving the commission of acts of violence”.45 A ‘course of conduct’\nsignifies a “systemic aspect” to the attack, describing “a series or overall flow of events as\nopposed to a mere aggregate of random acts. The ‘multiple commission of acts’ sets a\nquantitative threshold involving a certain number of acts falling within the course of\nconduct”.46"},{"id":"a-hrc-50-crp-3-p0229","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"229","seq":229,"section":"Annex","text":"The notion of ‘attack’ encompasses any form of mistreatment of a civilian\npopulation47 that includes multiple commission of acts referred to in Article 7(1).48 The attack\nneed not necessarily be military in nature, and it may involve any form of violence against a\ncivilian population.49 An attack may precede, outlast, or continue during an armed conflict,\nwithout necessarily being part thereof.50 It is an event in which the enumerated crimes must\nform part.51\nDirected against a civilian population"},{"id":"a-hrc-50-crp-3-p0230","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"230","seq":230,"section":"Annex","text":"The ICTY held that ‘the emphasis is not on the individual victim but rather on the\ncollective, the individual being victimised not because of [their] individual attributes but\nrather because of [their] membership of a targeted civilian population.’52 Article 7 of the ICC\nStatute does not require a separate finding that the civilian population was the primary object\nof the attack.”53"},{"id":"a-hrc-50-crp-3-p0231","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"231","seq":231,"section":"Annex","text":"The term ‘civilian’ refers to persons who are not members of any armed forces or\nother legitimate combatants.54 The term ‘civilian population’ means that the population must\nsimply be predominantly civilian in nature.55 Members of armed forces placed hors de\ncombat by sickness, wounds, detention, or any other cause, may also be victims of acts\namounting to crimes against humanity.56"},{"id":"a-hrc-50-crp-3-p0232","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"232","seq":232,"section":"Annex","text":"Relevant factors include the means and methods used in the course of the attack; the\nnumber and status of the victims; the discriminatory nature, if any, of the attack, in terms of\na pattern related to the national, ethnic, racial or religious identity of victims; and the nature\nof the crimes committed in its course57 and evidence of the scale of the crimes committed in\nthe course of the attack.58\nWidespread or systematic character of the attack"},{"id":"a-hrc-50-crp-3-p0233","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"233","seq":233,"section":"Annex","text":"Under both the Rome Statute (Article 7(1)) and customary international law, the attack\nagainst the civilian population as a whole – as opposed to the individual underlying crimes -\nmust be either widespread or systematic in nature.59 Although the two criteria are disjunctive\nrather than cumulative, they are often difficult to separate since a widespread attack targeting\na large number of victims is generally predicated on some degree of coordination, planning\nor organisation.\nWidespread"},{"id":"a-hrc-50-crp-3-p0234","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"234","seq":234,"section":"Annex","text":"The term ‘widespread’ refers to the large-scale nature of the attack, its geographic\nscope, and the number and multiplicity of civilians against whom the attack is directed.60 It\nmay be established by the cumulative effect of a multiplicity of smaller, discrete acts, or the\nsingular effect of an inhumane act of extraordinary magnitude.61"},{"id":"a-hrc-50-crp-3-p0235","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"235","seq":235,"section":"Annex","text":"The ICC Trial Chamber III in Bemba held the term ‘widespread’ to denote an attack\nthat is massive, frequent, carried out collectively with considerable seriousness and directed\nagainst a multiplicity of victims,62 or “an attack carried out over a large geographical area or\nan attack in a small geographical area directed against a large number of civilians”.63 Hence,\na key feature of the ‘widespread’ standard is that it is intended to exclude isolated acts of\nviolence,64 such as “murder directed against individual victims by persons acting of their own\nvolition rather than as part of a broader initiative”.65 The assessment as to whether an attack\nis widespread is “neither exclusively quantitative nor geographical, [and] must be carried out\non the basis of the individual facts”.66\nSystematic"},{"id":"a-hrc-50-crp-3-p0236","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"236","seq":236,"section":"Annex","text":"‘Systematic’ refers to the “organised nature of the acts of violence and the\nimprobability of their random occurrence”67 in furtherance of a common policy, which\nfollows a regular pattern and results in a continuous commission of acts or as ‘patterns of\ncrimes’ such that the crimes constitute a non-accidental repetition of similar criminal conduct\non a regular basis.68 It requires “organized action, following a regular pattern, on the basis of\na common policy and involves substantial public or private resources”.69"},{"id":"a-hrc-50-crp-3-p0237","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"237","seq":237,"section":"Annex","text":"In determining whether an attack is systematic and to identify patterns of crimes, the\nfollowing are taken into account: (i) identical acts took place or similarities in criminal\npractices can be identified; (ii) the same modus operandi (and/or means or methods) was\nemployed or (iii) victims were treated in a similar manner across a wide geographic area.70\nFurther indicators of the systematic nature of an attack include that: (i) the violations are in\nline with an underlying political objective; (ii) there is an ideology to destroy, persecute or\nweaken a community, including on the basis of national/ethnic/racial or religious grounds;\n(iii) high-level political and/or military authorities are implicated in the definition and\nestablishment of a methodical plan to commit violations; (iv) propaganda, indoctrination or\npsychological oppression are used to create an environment in which crimes will occur; (v)\ncriminal acts are being perpetrated on a very large scale and follow a regular pattern making\nit improbable that the acts could occur randomly; (vi) there is a repeated and continuous\ncommission of inhumane acts linked to one another; and (vii) organized efforts are made to\nconceal the crimes committed.71"},{"id":"a-hrc-50-crp-3-p0238","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"238","seq":238,"section":"Annex","text":"Neither the underlying attack nor the acts of the accused need be supported by any\nform of state or organisational plan or policy. Nor is a plan or policy a necessary element of\nproof that the underlying attack was systematic in character;72 nonetheless may serve as\nevidence of the systematic character of the attack. This policy may be made by an organ of\nthe State but can also be formulated “by groups of persons who govern a specific territory or\nby any organisation with the capability to commit a widespread or systematic attack against\na civilian population”.73 A policy can therefore be “inferred by discernment of, inter alia,\nrepeated actions occurring according to a same sequence, or the existence of preparations or\ncollective mobilisation orchestrated and coordinated by that State or organisation”74 or from\na variety of factors which taken together, establish that a policy existed.\nApplicable Underlying Acts\nImprisonment"},{"id":"a-hrc-50-crp-3-p0239","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"239","seq":239,"section":"Annex","text":"Imprisonment as a crime against humanity requires that an individual is arbitrarily\ndeprived of his or her liberty, and that this deprivation is done intentionally or in the\nreasonable knowledge that arbitrary deprivation of liberty is likely to occur.75 Not every\ninfringement of liberty forms the material element of the underlying offence; the deprivation\nof liberty must be of similar gravity and seriousness as the other crimes enumerated as crimes\nagainst humanity.76 A deprivation of liberty amounts to imprisonment if it is arbitrary and\ntherefore illegal, with the term ‘arbitrary’ establishing the requirement that the deprivation\nbe without due process of law.77"},{"id":"a-hrc-50-crp-3-p0240","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"240","seq":240,"section":"Annex","text":"In assessing whether imprisonment constitutes a crime against humanity, relevant\nfactors are whether the initial arrest was unlawful by considering, for example, whether it\nwas based on a valid arrest warrant, whether the detainees were informed of the reasons for\ntheir detention, whether the detainees were ever formally charged, whether they were\ninformed of any procedural rights, and whether any period of detention was lawful. 78"},{"id":"a-hrc-50-crp-3-p0241","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"241","seq":241,"section":"Annex","text":"The Working Group on Arbitrary Detention has classified secret detention as being\nper se arbitrary as it is clearly impossible to invoke any legal basis justifying the deprivation\nof liberty, and its very nature may result in indefinite periods of detention.79 The practice of\nsecret detention ipso facto violates the guarantees enshrined in Articles 9 (right to liberty)\nand 14 (right to a fair trial) of the ICCPR, or in most cases, automatically or inherently entails\nsuch consequences that amount to a violation. Under IHRL, every instance of secret detention\nby a state or de facto state authority also amounts to a case of enforced disappearance80 and\nalso violates the prohibition against torture and other forms of ill-treatment81 including\nbecause every instance of secret detention is by definition incommunicado detention.82\nIndefinite or prolonged solitary confinement83 - in excess of 15 consecutive days84 - as a\nrestriction or disciplinary sanction may amount to torture or other cruel, inhuman or\ndegrading treatment or punishment.85 Confinement under inhumane conditions can be\nincluded in the underlying acts of “imprisonment” and \"other inhumane acts\" and also meets\nthe definition of a persecutory act.86\nTorture"},{"id":"a-hrc-50-crp-3-p0242","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"242","seq":242,"section":"Annex","text":"Under the Rome Statute, torture as a crime against humanity means the intentional\ninfliction of severe pain and suffering, whether physical or mental, upon a person in the\ncustody or under the control of the accused.87 Under the Rome Statute, the crime against\nhumanity of torture does not require the act to be committed with a specific purpose, or by a\npublic official.88"},{"id":"a-hrc-50-crp-3-p0243","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"243","seq":243,"section":"Annex","text":"The material elements of this crime are (1) the infliction of severe pain and suffering,\nwhether physical or mental; and (2) that the infliction is on a person in the custody or under\nthe control of the accused. Although there is no definition of the threshold of “severe”, “an\nimportant degree of pain and suffering has to be reached”.89 The objective severity of the\nharm inflicted must be first assessed, before considering subjective criteria such as the\nphysical or mental effect on the victim.90 When assessing the seriousness of acts charged as\ntorture, one must “take into account all the circumstances of the case, including the nature\nand context of the infliction of pain, the premeditation and institutionalisation of the ill-\ntreatment, the physical condition of the victim, the manner and method used, and the position\nof inferiority of the victim. The extent that an individual has been mistreated over a prolonged\nperiod of time will also be relevant.”91 Intentionally subjecting persons to extremely\ninhumane conditions of detention can also constitute ‘other inhumane acts’ as a crime against\nhumanity.92"},{"id":"a-hrc-50-crp-3-p0244","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"244","seq":244,"section":"Annex","text":"Acts considered to amount to “severe pain or suffering” for the purpose of torture\ninclude: severe beatings, punches and kicks; rape, attempted rape and other forms of sexual\nviolence; electric shocks; and deprivation of sleep, food or water.93 Examples of treatment\ncausing mental suffering include: mock executions, prolonged solitary confinement and\nthreats of death or violence and being forced to watch others being killed, tortured or raped.94"},{"id":"a-hrc-50-crp-3-p0245","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"245","seq":245,"section":"Annex","text":"The very fact of being detained as a disappeared person, isolated from one’s family\nfor a long period is certainly a violation of the right to humane conditions of detention and\nthe prohibition of torture.95 According to the Special Rapporteur on Torture, “to make\nsomeone disappear is a form of prohibited torture or ill-treatment, clearly as regards the\nrelatives of the disappeared person and arguably in respect of the disappeared person or\nhim/herself”.96 Under the Convention against Torture, \"torture\" means any act by which\nsevere pain or suffering, whether physical or mental, is intentionally inflicted on a person for\nsuch purposes as obtaining from him or a third person information or a confession, punishing\nhim for an act he or a third person has committed or is suspected of having committed, or\nintimidating or coercing him or a third person, or for any reason based on discrimination of\nany kind, when such pain or suffering is inflicted by or at the instigation of or with the consent\nor acquiescence of a public official or other person acting in an official capacity."},{"id":"a-hrc-50-crp-3-p0246","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"246","seq":246,"section":"Annex","text":"As to the mental element, Article 7(2)(e) of the ICC requires that the infliction of pain\nand suffering must be intentional. This means that Article 30 of the Rome Statute, which sets\nup a general requirement for the double elements of intent and knowledge, is not applicable\nhere.97 It is therefore sufficient that the perpetrator intended to inflict pain or suffering, and\nthat the victim endured severe pain or suffering.98\nEnforced disappearance"},{"id":"a-hrc-50-crp-3-p0247","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"247","seq":247,"section":"Annex","text":"Enforced disappearance as a crime against humanity entails the arrest, detention or\nabduction of a person, accompanied by a refusal to acknowledge it or to give information on\nthe whereabouts of the person.99 The detention and refusal to give information must have\nbeen by or with the authorisation, support or acquiescence of a State or political organisation,\nand the perpetrator must have “intended to remove [the victim] from the protection of the\nlaw for a prolonged period of time”.100 However, the wording ‘prolonged’ is a normative\nlimitation acting as a jurisdictional threshold101 for the ICC that does not bind the FFM, thus\nenforced disappearances of any duration have been included in this report.102"},{"id":"a-hrc-50-crp-3-p0248","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"248","seq":248,"section":"Annex","text":"Secret detention, the refusal to provide information/provision of false\ninformation/intimidation of those requesting information, and the concealment of victims’\ncorpses in mass graves, prolonging their enforced disappearance, evidences an intention to\nremove the persons from the protection of the law.\nExtermination"},{"id":"a-hrc-50-crp-3-p0249","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"249","seq":249,"section":"Annex","text":"The actus reus of extermination is the act of killing on a large scale,103 distinguishes\nthe crime against humanity of extermination from that of murder.104 “Large scale” does not\nsuggest a strict numerical approach with a minimum number of victims.105 The assessment\nof “large scale” is made on a case-by-case basis, taking into account the circumstances in\nwhich the killings occurred.106 Relevant factors include, inter alia, the time and place of the\nkillings, the selection of the victims and the manner in which they were targeted, and whether\nthe killings were aimed at the collective group rather than victims in their individual\ncapacity.107 For example, the ICTR Trial Chamber considered that the killing of between 15\nand 60 Tutsis at the Nyabikenke commune office occurred on a “large scale”.108 Similarly, in\nGatete, recalling that no numerical minimum is required, it was satisfied that the killings of\nat least 25 to 30 people were conducted on a sufficiently large scale for the purposes of\namounting to extermination.109 Separate incidents may be considered cumulatively in\nassessing whether killings meet the required scale.110 The actus reus of extermination may\nbe established on the basis of “an accumulation of separate and unrelated incidents”.111\nPersecution"},{"id":"a-hrc-50-crp-3-p0250","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"250","seq":250,"section":"Annex","text":"The actus reus of persecution as a crime against humanity is the gross or blatant\ndenial, on discriminatory grounds, of a fundamental right, laid down in international\ncustomary or treaty law, reaching the same level of gravity as and committed in connection\nwith one or more underlying acts. The requisite mens rea is the specific intent to discriminate\nagainst the victims on account of their racial or religious characteristics or political affiliation\nas well as knowledge of the widespread or systematic nature of the attack on civilians.112\nThe mens rea for persecutions “is the specific intent to cause injury to a human being because\nhe belongs to a particular community or group”. There is no requirement in law that the\nperpetrator possesses a ‘persecutory intent’ over and above a discriminatory intent.113"},{"id":"a-hrc-50-crp-3-p0251","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"251","seq":251,"section":"Annex","text":"The targeted group does not only comprise persons who personally carry the\n(religious, racial or political) criteria of the group. The targeted group must be interpreted\nbroadly and may include such persons who are defined by the perpetrator as belonging to the\nvictim group due to their close affiliations or sympathies for the victim group such that the\nvictims are discriminated in fact for who or what they are on the basis of the perception of\nthe perpetrator.114 Discrimination on the basis of a person’s political ideology satisfies the\nrequirement of ‘political’ grounds.115 The targeting of inhabitants of areas perceived as\nsupporting an opposing group has been held to be persecutory.116\nThe mental element for crimes against humanity"},{"id":"a-hrc-50-crp-3-p0252","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"252","seq":252,"section":"Annex","text":"As the Elements of Crimes under the Rome Statute state, it is required that, “the\nperpetrator knew that the conduct was part of or intended the conduct to be part of a\nwidespread or systematic attack against a civilian population”. Therefore, the required nexus\nbetween the acts of an accused and the attack consists of two elements: (a) the commission\nof an act which, by its nature or consequences, is objectively part of the attack; and (b)\nknowledge on the part of the accused that there is an attack on the civilian population and\nthat their acts are part thereof117 or are intended to be a part thereof."},{"id":"a-hrc-50-crp-3-p0253","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"253","seq":253,"section":"Annex","text":"In relation to (a), the acts need not be committed in the midst of the attack to be\nsufficiently connected to it.118 An act therefore committed before or after the main attack\ncould still be considered to be part of it, provided that the act was not isolated from it.119 Acts\nare considered part of the attack if the acts share common features, such as nature,\nconsequences, characteristics, and targets120 and are consistent with the general motives and\na modus operandi.121 The requirements in (b) are not such that proof is required that the\nperpetrator had knowledge of all the attack’s details or characteristics;122 it is sufficient that\nthe perpetrator knew of the overall context within which his or her acts took place,123 which\ncould be evidenced by, for example, the perpetrator’s participation in the attack124 or in the\npreparation of the attack.125\nApplicable Modes of Criminal Liability\nDirect Commission/Perpetration"},{"id":"a-hrc-50-crp-3-p0254","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"254","seq":254,"section":"Annex","text":"The available evidence implicates a number of individuals in the direct commission\nof the enumerated acts. These individuals can be held criminally responsible if their acts were\na part of the widespread or systematic attack and they acted with knowledge that their conduct\nwas part of such an attack.\nOrdering"},{"id":"a-hrc-50-crp-3-p0255","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"255","seq":255,"section":"Annex","text":"Some individuals are implicated in orders, particularly to kill. To be held criminally\nresponsible for ordering the commission of a crime, an individual must have instructed\nanother person to engage in an act or an omission, and such instruction must have resulted in\nthe commission of a crime or an attempt thereof. The accused must have held a position of\nde jure or de facto authority over the other person; there must be proof of some position of\nauthority on the part of the individual that would compel another to commit a crime in\nfollowing the accused’s order.126 However, a mere position of authority cannot suffice to\ninfer that a perpetrator must have ordered the crime.127 The order need not be in written or\nany particular form, nor must it be transmitted directly to the physical perpetrator. It is not\nnecessary that the crime would not have been perpetrated but for the accused’s order, but the\norder must have had a direct and substantial effect on its commission. The fact that an order\nwas given can be proved from inferences through circumstantial evidence.128 For example,\nan act of ordering can be proven by considering direct or circumstantial evidence of\nomissions or failures to act, but an omission cannot of itself constitute an act of ordering129\nsince giving an order requires a positive act.130 The suspect must intend to order a crime or\nmust be aware of the substantial likelihood that a crime would be committed in the execution\nof the act or omission ordered.131 The knowledge of any level of risk, however low, does not\nsuffice for the imposition of criminal responsibility.132\nAiding and Abetting"},{"id":"a-hrc-50-crp-3-p0256","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"256","seq":256,"section":"Annex","text":"Although there may be insufficient evidence to establish that some individuals\npersonally carried out or ordered the underlying criminal acts, some individuals have been\nidentified by the Mission as responsible for aiding and abetting crimes against humanity.\nAiding and abetting is a form of liability in which the accused contributes to the perpetration\nof a crime that is committed by another person. While the contribution need not be\nindispensable to the crime, it must have a substantial effect on the commission of the crime.133"},{"id":"a-hrc-50-crp-3-p0257","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"257","seq":257,"section":"Annex","text":"The actus reus of aiding and abetting may be satisfied by a commander permitting the\nuse of resources under his or her control, including personnel, to facilitate the perpetration of\na crime. The provision of engineering machinery and personnel for burial operations can have\na substantial effect on the commission of mass executions.134 An individual can be found\nliable for aiding and abetting a crime when it is established that his conduct amounted to tacit\napproval and encouragement of the crime and that such conduct substantially contributed to\nthe crime. When this form of aiding and abetting has been a basis for a conviction, \"it has\nbeen the authority of the accused combined with his presence on (or very near to) the crime\nscene, especially if considered with his prior conduct, which all together allow the conclusion\nthat the accused’s conduct amounts to official sanction of the crime and thus substantially\ncontributes to it.135"},{"id":"a-hrc-50-crp-3-p0258","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"258","seq":258,"section":"Annex","text":"The aider and abettor need not share the mens rea of the principal perpetrator but must\nbe aware of the essential elements of the crime ultimately committed by the principal,\nincluding his state of mind.136 It is not necessary that the aider and abettor know the precise\ncrime that was intended or actually committed137 but only knowledge that his acts or\nomissions assist the commission of such crime.138\nWar Crimes"},{"id":"a-hrc-50-crp-3-p0259","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"259","seq":259,"section":"Annex","text":"This class of international crimes embraces any serious violation of international\nhumanitarian law committed in the course of an international or non-international armed\nconflict, which entails the individual criminal responsibility of the person breaching that\nlaw.139"},{"id":"a-hrc-50-crp-3-p0260","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"260","seq":260,"section":"Annex","text":"Article 8(2)(c) of the ICC Statute defines war crimes in the case of an armed conflict\nnot of an international character as serious violations of Article 3 common to the four Geneva\nConventions of 12 August 1949, including murder, cruel treatment and torture committed\nrisk, shows the degree of intention necessary (recklessness) so as to incur responsibility for having\nordered, planned or incited the commitment of the crimes\". For an application to the facts, see para.\n345 et seq.\nagainst persons taking no active part in the hostilities, including members of armed forces\nwho have laid down their arms and those placed hors de combat.140"},{"id":"a-hrc-50-crp-3-p0261","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"261","seq":261,"section":"Annex","text":"To establish whether a crime qualifies as a ‘war crime’, certain pre-conditions must\nbe met:\n(a)    The existence of an armed conflict (international or non-international); and\n(b)    A nexus between the alleged violation and the armed conflict."},{"id":"a-hrc-50-crp-3-p0262","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"262","seq":262,"section":"Annex","text":"The classification of a situation of armed violence under international law is an\nobjective legal test. A non-international armed conflict exists “whenever there is protracted\narmed violence between governmental authorities and organized armed groups or between\nsuch groups within a State”.141 This definition encompasses two core, cumulative criteria,\nwhich distinguish a non-international armed conflict from internal tensions or disturbances:\n(i) the intensity of the armed violence and (ii) the level of organization of the armed group(s)\ninvolved. ICTY jurisprudence reflects a number of indicative factors142 to assess whether\nthese criteria have been met.143"},{"id":"a-hrc-50-crp-3-p0263","rec_id":"rec29IKNRtUDecvC8","symbol":"A/HRC/50/CRP.3","n":"263","seq":263,"section":"Annex","text":"The armed conflict need not have been causal to the commission of the crime charged\nbut must have played a substantial part in the perpetrator’s ability to commit that crime. It is\nnot required that the alleged crimes occur at a time and in a place where fighting is actually\ntaking place. Relevant factors include whether the perpetrator was a combatant, whether the\nvictim was a non-combatant, whether the victim was a member of the opposing party, and\nwhether the act may be said to have served the ultimate goal of a military campaign.144"},{"id":"a-hrc-49-4-u0000","rec_id":"recVilmxHdPgkesVQ","symbol":"A/HRC/49/4","n":null,"seq":0,"section":null,"text":"United Nations                                                                                    A/HRC/49/4\nGeneral Assembly                                                            Distr.: General\n18 August 2022","unnumbered":true},{"id":"a-hrc-49-4-p0001","rec_id":"recVilmxHdPgkesVQ","symbol":"A/HRC/49/4","n":"1","seq":1,"section":"I. Introduction","text":"On 22 June 2020, at the request of the Government of Libya, the Human Rights\nCouncil adopted resolution 43/39 requesting the United Nations High Commissioner for\nHuman Rights to establish and dispatch a fact-finding mission to Libya. On 22 August 2020,\nthe High Commissioner announced the appointment of Mohamed Auajjar, Tracy Robinson\nand Chaloka Beyani as the members of the Independent Fact-Finding Mission on Libya, with\nMr. Auajjar as Chair.1"},{"id":"a-hrc-49-4-p0002","rec_id":"recVilmxHdPgkesVQ","symbol":"A/HRC/49/4","n":"2","seq":2,"section":"I. Introduction","text":"In accordance with resolution 43/39,2 the Mission was mandated to establish, in an\nindependent and impartial manner, the facts and circumstances of the human rights situation\nthroughout Libya, to collect and review relevant information, to document alleged violations\nand abuses of international human rights law and international humanitarian law by all parties\nin Libya since the beginning of 2016, including any gendered dimensions of such violations\nand abuses, and to preserve evidence with a view to ensuring that perpetrators of violations\nor abuses of international human rights law and international humanitarian law were held\naccountable.3"},{"id":"a-hrc-49-4-p0003","rec_id":"recVilmxHdPgkesVQ","symbol":"A/HRC/49/4","n":"3","seq":3,"section":"I. Introduction","text":"In October 2021, the Mission presented a first written report to the Human Rights\nCouncil on the situation of human rights in Libya. 4 By resolution 48/25 adopted on 13\nOctober 2021, the Human Rights Council then extended the Mission’s mandate to 30 June\n2022. The Human Rights Council requested the Mission to present both a follow-up report\nof its findings at the Council’s forty-ninth session and, at the fiftieth session, a comprehensive\nreport on the situation of human rights in Libya, including on efforts to prevent and ensure\naccountability for human rights violations and abuses, with recommendations for follow-up."},{"id":"a-hrc-49-4-p0004","rec_id":"recVilmxHdPgkesVQ","symbol":"A/HRC/49/4","n":"4","seq":4,"section":"I. Introduction","text":"The present report accordingly is of a supplementary and interim nature. It contains\nfurther findings reached since October 2021, within the constraints of the challenges faced in\nthis period, and should be read in conjunction with the Mission’s first report. It records\nimportant factual developments during the reporting period and violations that, from the point\nof view of technical capacity, can have an impact on Libyans’ efforts towards a transition to\nthe rule of law, democracy and greater respect for human rights. These include violations\nagainst the integrity of the electoral process and the independence and safety of the judiciary.\nThe report also continues the Mission’s documentation of other violations and abuses of\ninternational human rights law and of violations of international humanitarian law in Libya.\nIt retains the same areas of focus as the previous report; in particular, violations against\nwomen, persons deprived of their liberty, migrants, enforced disappearances, extrajudicial\nkillings, shrinking civic space and violations against civil society organizations and activists."},{"id":"a-hrc-49-4-p0005","rec_id":"recVilmxHdPgkesVQ","symbol":"A/HRC/49/4","n":"5","seq":5,"section":"I. Introduction","text":"As noted in paragraph 5 of the Mission’s first report, a comprehensive human rights\ninvestigation is an effective tool to foster accountability, deter further violations and promote\nlong-term peace and security. To that end, the Mission recommended that Libya ensure that\naccountability formed part of the reconciliation process. 5 The present report includes areas\nof fact-finding and recommendations to help the Libyan people to adopt a sustainable victim-\ncentred path towards this legitimate goal. However, achieving this goal requires technical\nassistance to Libya. As reflected in the recommendations, areas requiring technical assistance\ninclude the strengthening of an independent, impartial and competent judiciary to address the\nviolations against the administration of justice, which are contrary to article 14 of the\nInternational Covenant on Civil and Political Rights; Libyans’ right to participate in public\nlife pursuant to article 25 of that Covenant; the rights of minorities under article 27 of that\nCovenant; and the rights of women, children and persons with disabilities specified in the\nConvention on the Elimination of All Forms of Discrimination against Women, the\nConvention on the Rights of the Child and the Convention on the Rights of Persons with\nDisabilities, respectively.\n1 See further A/HRC/48/83, para. 2.\n2 Para. 43.\n3 The Mission’s mandate is further explained in A/HRC/48/83, annex I.\n4 A/HRC/48/83.\n5 Ibid., para. 80 (o)."},{"id":"a-hrc-49-4-p0006","rec_id":"recVilmxHdPgkesVQ","symbol":"A/HRC/49/4","n":"6","seq":6,"section":"II. Political and security situation","text":"Between October 2021 and March 2022, political turmoil and insecurity in Libya\ncontinued. On 8 September and 4 October 2021, the House of Representatives issued Laws\n1/2021 and 2/2021 setting out the legal frameworks for presidential and parliamentary\nelections, respectively. On 25 October 2021, the President of the High Council of State,\nsupported by mayors, representatives of civil society and some armed groups, submitted a\nchallenge against Law 1/2021 before the Supreme Court of Libya in Tripoli, arguing that the\nCouncil had not been consulted in the law’s drafting, in violation of the Libyan Political\nAgreement of 2015."},{"id":"a-hrc-49-4-p0007","rec_id":"recVilmxHdPgkesVQ","symbol":"A/HRC/49/4","n":"7","seq":7,"section":"II. Political and security situation","text":"The legal and political dispute led to the postponement of the elections that were\nscheduled for 24 December 2021,6 undermining Libyans’ rights to self-determination and\npublic participation. 7 On 22 December 2021, the High National Elections Commission\ndeclared its inability to organize elections according to the road map of the Libyan Political\nDialogue Forum and asked the House of Representatives to set a new date for the elections.\nInconsistencies in the legal framework were cited, in addition to irregularities in the judicial\nappeal process for the selection of candidates in the presidential elections."},{"id":"a-hrc-49-4-p0008","rec_id":"recVilmxHdPgkesVQ","symbol":"A/HRC/49/4","n":"8","seq":8,"section":"II. Political and security situation","text":"The House of Representatives subsequently declared that the mandate of the\nGovernment of National Unity had expired. In February 2022, in consultation with the High\nCouncil of State, the House of Representatives adopted a constitutional amendment, which\ncharts a path for the revision of the draft constitution (proposed in 2017 but not put to a\nnational referendum) and for the electoral process, and voted to designate a new Prime\nMinister.8 However, the Prime Minister of the Government of National Unity, Abdul Hamid\nDbeibah, vowed to only hand over power to an elected government."},{"id":"a-hrc-49-4-p0009","rec_id":"recVilmxHdPgkesVQ","symbol":"A/HRC/49/4","n":"9","seq":9,"section":"II. Political and security situation","text":"On 1 March 2022, the House of Representatives held a vote of confidence in the\nappointment of a new government led by former interior minister Fathi Bashagha, known as\nthe Government of National Stability.9 This power struggle has triggered further tension and\npolarization, creating new political divisions and new political rifts since October 2021."},{"id":"a-hrc-49-4-p0010","rec_id":"recVilmxHdPgkesVQ","symbol":"A/HRC/49/4","n":"10","seq":10,"section":"II. Political and security situation","text":"Armed forces affiliated with various actors continued to mobilize in the shadow of\nthese rifts. Retaliation among militias, abductions, carjacking and armed robberies were\nrecorded throughout Libya. The threat of terrorism remains a major challenge with reported\nmovements of violent extremist organizations in the southern part of the country."},{"id":"a-hrc-49-4-p0011","rec_id":"recVilmxHdPgkesVQ","symbol":"A/HRC/49/4","n":"11","seq":11,"section":"III. Cooperation of the Libyan authorities","text":"The Mission expresses its appreciation to the Permanent Mission of Libya to the\nUnited Nations and to the Libyan authorities in Tripoli and Benghazi for their cooperation,\nby facilitating visa issuance and access to the western and eastern parts of Libya. This\ncooperation has been vital for the Mission to discharge its mandate to conduct impartial fact-\nfinding investigations into violations and abuses of international human rights law and\ninternational humanitarian law by all parties throughout Libya."},{"id":"a-hrc-49-4-p0012","rec_id":"recVilmxHdPgkesVQ","symbol":"A/HRC/49/4","n":"12","seq":12,"section":"III. Cooperation of the Libyan authorities","text":"In March 2022, the Mission conducted its first ever visit to eastern Libya – to\nBenghazi in particular. This was the Mission’s third visit to Libya. It met several key\ninterlocutors representing different stakeholders in Benghazi. The Mission reiterates its\nappreciation for the cooperation of the local authorities in Benghazi – in particular, the\n6 The parliamentary election, formerly scheduled to occur on the same day as the presidential election,\nwas postponed until 50 days after it.\n7 International Covenant on Civil and Political Rights, arts. 1 and 25; and International Covenant on\nEconomic, Social and Cultural Rights, art. 1.\n8 United Nations Support Mission in Libya, “Statement attributable to the Spokesperson for the\nSecretary-General on Libya”, 11 February 2022.\n9 Sami Zapita, “Bashagha Government of National Stability (GNS) releases new crest”, Libya Herald,\nmilitary prosecutor and the prosecutor of Benghazi – and previously in Tripoli in its\nfulfilment of its mandate."},{"id":"a-hrc-49-4-p0013","rec_id":"recVilmxHdPgkesVQ","symbol":"A/HRC/49/4","n":"13","seq":13,"section":"III. Cooperation of the Libyan authorities","text":"As noted in paragraph 10 of the Mission’s first report, restrictions imposed on civil\nsociety organizations and fear of retaliation pose grave obstacles to interactions between the\nMission and civil society organizations based in Libya. The Mission reiterates its call to the\nLibyan authorities to ensure that any person in Libya is free to approach it."},{"id":"a-hrc-49-4-p0014","rec_id":"recVilmxHdPgkesVQ","symbol":"A/HRC/49/4","n":"14","seq":14,"section":"IV. Challenges","text":"After a delayed start as detailed in its previous report, since October 2021 the Mission\nhas continued to face multiple, significant challenges. Delays in recruitment and severe\nunderstaffing have, in particular, impeded its ability to operate effectively during this period.\nWhile the Mission should have had 18 staff members, it functioned from November 2021 to\nmid-February 2022 with only 6, with key roles vacant, including those of the Coordinator,\nInvestigation Team Leader and Reporting Officer.10"},{"id":"a-hrc-49-4-p0015","rec_id":"recVilmxHdPgkesVQ","symbol":"A/HRC/49/4","n":"15","seq":15,"section":"IV. Challenges","text":"To enhance its ability to conduct investigations, the Mission had hoped to deploy its\ninvestigative team to Libya for the duration of its mandate. Unfortunately, limited United\nNations accommodation in Libya and security challenges prevented this. Delays in\nrecruitment were partly due to this thwarted attempt to base staff in Libya. The Mission’s\nability to conduct visits to Libya was further limited by the General Assembly’s decision to\ncut the position of security coordinator, for budgetary reasons, and the limited availability of\naccommodation in the United Nations compound even for short-term visits."},{"id":"a-hrc-49-4-p0016","rec_id":"recVilmxHdPgkesVQ","symbol":"A/HRC/49/4","n":"16","seq":16,"section":"IV. Challenges","text":"Despite the above challenges, the Mission has carried out considerable investigative\nactivities. These included visits to Egypt from 25 to 29 November 2021 and, after the\nCoordinator and additional staff were appointed in February and March 2022, to Malta from\n6 to 9 March and Libya from 10 to 13 March. The partially restored capacity of the Mission\nhas ensured that significant progress in fulfilling its mandate has been achieved. More could\nhave been achieved if the Mission had operated at full capacity. But the gravity and\nwidespread nature of violations in the past six years in Libya still requires more than the\nremaining three months of the mandate to holistically achieve conclusive findings that can\nhelp Libyans to achieve their right to truth, take stock and make the appropriate plans for\npeaceful transition."},{"id":"a-hrc-49-4-p0017","rec_id":"recVilmxHdPgkesVQ","symbol":"A/HRC/49/4","n":"17","seq":17,"section":"A. Applicable law","text":"The legal framework applicable to the Mission’s fact-finding activities is detailed in\nannex II to its first report.11"},{"id":"a-hrc-49-4-p0018","rec_id":"recVilmxHdPgkesVQ","symbol":"A/HRC/49/4","n":"18","seq":18,"section":"B. Objective criteria for determining the scope of the Mission’s","text":"The Mission’s investigations since October 202112 have adopted objective criteria that\ninformed its selection of themes and topics for investigation. The Mission focused on three\nareas. The first was the apparent violations of international human rights law and\ninternational humanitarian law that appeared the most serious and, among these, in particular,\nthose of an apparently widespread and/or systematic nature. This built on the Mission’s\nprevious documentation of trends and patterns and preliminary findings on the commission\nof international crimes, and reflected its aim to further substantiate the impact of violations\non the rights of victims – Libyan victims, as well as migrants, refugees and asylum seekers."},{"id":"a-hrc-49-4-p0019","rec_id":"recVilmxHdPgkesVQ","symbol":"A/HRC/49/4","n":"19","seq":19,"section":"B. Objective criteria for determining the scope of the Mission’s","text":"The second was the potential violations, abuses and crimes against vulnerable groups\nthat are subjected to multiple forms of victimization. These included persons deprived of\ntheir liberty, women, migrants, refugees, asylum seekers, and religious, racial and ethnic\nminorities."},{"id":"a-hrc-49-4-p0020","rec_id":"recVilmxHdPgkesVQ","symbol":"A/HRC/49/4","n":"20","seq":20,"section":"B. Objective criteria for determining the scope of the Mission’s","text":"The third was the violations and abuses of international human rights law and\ninternational humanitarian law that especially hamper the transition of Libya towards the rule\nof law and democratic elections. Elections are part and parcel of the right of everyone to\nparticipate in public affairs under article 25 of the International Covenant on Civil and\nPolitical Rights and are critical to democratic transition and institutional reform. In the\ncontext of the pending elections, the Mission has focused on investigating allegations of\nattacks on women politicians, as impunity for such acts has suppressed women’s participation\nin political and public affairs in Libya. Acknowledging that an environment of fear and\nintimidation undermines the democratic process, cripples the justice system and threatens the\nindependence of the judiciary, the Mission has also focused on attacks committed by armed\ngroups on offices and personnel of the High National Elections Commission, judges\nconducting judicial reviews of candidates’ eligibility and other election-related violations,\nincluding attacks on civil society."},{"id":"a-hrc-49-4-p0021","rec_id":"recVilmxHdPgkesVQ","symbol":"A/HRC/49/4","n":"21","seq":21,"section":"B. Objective criteria for determining the scope of the Mission’s","text":"To the extent that it was both practically feasible and consistent with these three areas\nof focus, the Mission endeavoured to investigate impartially all geographical regions within\nLibya."},{"id":"a-hrc-49-4-p0022","rec_id":"recVilmxHdPgkesVQ","symbol":"A/HRC/49/4","n":"22","seq":22,"section":"B. Objective criteria for determining the scope of the Mission’s","text":"Given the interim nature and limitations on length of the present report, not all of the\ninvestigations carried out during this period, nor the findings thereof, are described below.\nUnless otherwise stated below, specific incidents are highlighted since they are representative\nof those that the Mission has identified."},{"id":"a-hrc-49-4-p0023","rec_id":"recVilmxHdPgkesVQ","symbol":"A/HRC/49/4","n":"23","seq":23,"section":"C. Methods of work","text":"Consistent with the practice of most United Nations fact-finding bodies, the Mission\nemploys the “reasonable grounds to believe” standard in making factual determinations. The\nMission found the standard met when it obtained a reliable body of primary information,\ncorroborated by at least one other independent source, that could lead a reasonable and\nordinarily prudent person to believe that an incident or pattern of conduct had occurred. 13"},{"id":"a-hrc-49-4-p0024","rec_id":"recVilmxHdPgkesVQ","symbol":"A/HRC/49/4","n":"24","seq":24,"section":"C. Methods of work","text":"During the period of reporting, the Mission continued to consider and collect\ninformation from a variety of sources, including summaries of accounts and analytical data\nincluded in reports of the United Nations, civil society organizations and media;\ninvestigators’ direct observations during visits to Libya and third States; domestic Libyan\nlaw; information provided by Libyan authorities, other States and reliable stakeholders\nworking on and in Libya; authenticated satellite imagery and audiovisual material; verified\nopen source material; interviews; and medical examinations by the Mission’s forensic\nphysician. Following the decision of the Human Rights Council to extend the Mission’s\nmandate until 30 June 2022, the Mission renewed its call for submissions from individuals,\ngroups and organizations with new or complementary documentation and information\nrelevant to its mandate. By the submission deadline of 31 January 2022, the Mission had\nreceived a number of submissions from civil society organizations, international non-\ngovernmental organizations, and victims or their representatives, which it is now reviewing."},{"id":"a-hrc-49-4-p0025","rec_id":"recVilmxHdPgkesVQ","symbol":"A/HRC/49/4","n":"25","seq":25,"section":"C. Methods of work","text":"The Mission conducted more than 120 interviews during this period, both in person\nand remotely. The Mission also conducted three in-person investigative visits: to Egypt in\nNovember 2021 and to Malta and Libya (Benghazi) in March 2022. In Benghazi, the Mission\nmet key public officials and various representatives of the judiciary and the legal profession.\nAmong other interlocutors, in Egypt, members of the Mission met with representatives of the\nLeague of Arab States and with civil society organizations working on the human rights\nsituation in Libya; and, in Malta, secretariat members, including the Mission’s forensic\nphysician, met with migrants, refugees and asylum seekers and discussed their experiences\nin Libya. They also met with representatives of international organizations. The Mission met\nonline with the Armed Forces and the Rescue Coordination Centre of Malta due to time\nconstraints. The Mission expresses its appreciation to the Governments of Egypt and Malta,\nthe Agency for the Welfare of Asylum Seekers of Malta and the Office of the United Nations\nHigh Commissioner for Refugees for their full cooperation on these visits."},{"id":"a-hrc-49-4-p0026","rec_id":"recVilmxHdPgkesVQ","symbol":"A/HRC/49/4","n":"26","seq":26,"section":"VI. Violations and abuses in the context of deprivation of liberty","text":"Up to October 2021, the Mission’s investigations concerning the deprivation of liberty\nprimarily concentrated on seven facilities, believed to hold thousands of inmates, in three\nareas of Libya. The Mission selected these seven for a combination of reasons, including the\nvulnerability of the persons deprived of liberty and the variety of regions and actors\nconcerned. The Mission concluded that acts of murder, torture, imprisonment, rape and\nenforced disappearance committed in these facilities may amount to crimes against\nhumanity.14"},{"id":"a-hrc-49-4-p0027","rec_id":"recVilmxHdPgkesVQ","symbol":"A/HRC/49/4","n":"27","seq":27,"section":"VI. Violations and abuses in the context of deprivation of liberty","text":"In the current period of reporting, the Mission interviewed 36 additional persons\nregarding those 7 facilities and 13 further places of detention, both official and unofficial.\nInvestigations during this period provided further evidence of the widespread and/or\nsystematic nature of human rights violations and abuses in places of detention and the\nrepetitive and continuous nature of attacks against detainees. This includes the sites the\nMission had previously identified, and additional official facilities and extralegal detention\nfacilities run by militias acting under the umbrella of the State. The Mission found the same\npatterns of acts occurring in and regarding the newly investigated facilities as those it had\nidentified in its first report. Its investigations reinforced the Mission’s belief that those\nimprisoned in Libya are commonly detained arbitrarily for prolonged periods; systematically\ntortured, raped or threatened with rape, including of female family members, 15 and\nsometimes killed; routinely subjected to enforced disappearance; and subjected to extortion\nand inhumane conditions of detention, among other violations and abuses."},{"id":"a-hrc-49-4-p0028","rec_id":"recVilmxHdPgkesVQ","symbol":"A/HRC/49/4","n":"28","seq":28,"section":"VI. Violations and abuses in the context of deprivation of liberty","text":"The Mission has received information about the impact of detention on women family\nmembers of detainees who may face harassment during visits and who find themselves heads\nof household and in a precarious financial situation. The Mission also identified further\nevidence of a pattern regarding the profile of victims, namely, perceived opponents of the\ndetaining authorities. One matter these investigations highlighted, besides those previously\nreported, was that orders of release and acquittal issued by judicial authorities were very\nfrequently not implemented. For example, the Mission found indications that there were\nhundreds of instances of this in the Mitiga/Radaa, Al-Koweifya and Gernada prisons."},{"id":"a-hrc-49-4-p0029","rec_id":"recVilmxHdPgkesVQ","symbol":"A/HRC/49/4","n":"29","seq":29,"section":"VI. Violations and abuses in the context of deprivation of liberty","text":"The Mission also continued to identify instances of serious human rights violations\nand war crimes committed against conflict-related detainees. In one example, during the non-\ninternational armed conflict that occurred between April 2019 and June 2020 between the\nGovernment of National Accord and the Libyan National Army, the Mission documented a\ncase of abduction and repeated torture of a combatant for approximately one year. The\nMission found reasonable grounds to believe that the victim had been subjected to regular\nbeatings for hours and kept in solitary confinement in inhumane conditions. The Mission\nconcluded that there were reasonable grounds to believe that the detainee was the victim of\nthe war crimes of torture and cruel treatment."},{"id":"a-hrc-49-4-p0030","rec_id":"recVilmxHdPgkesVQ","symbol":"A/HRC/49/4","n":"30","seq":30,"section":"VI. Violations and abuses in the context of deprivation of liberty","text":"The Mission investigated the detention, torture, enforced disappearance and killing of\ntwo men in Tarhuna during the same conflict. It found that there were reasonable grounds to\nbelieve that, due to their perceived support for one of the factions involved in the conflict,\nthe men had been detained at a checkpoint, tortured and eventually killed. One man had died\nimmediately from his torture, while the second had been detained, incommunicado, for eight\nmonths before being executed. His body was later discovered in a mass grave with three\nbullets in the head. Family members were given false information about their loved ones’\nwhereabouts and at times harassed by the authorities in Tarhuna. The Mission considers that\nthere are reasonable grounds to believe that both men may have been victims of the war\ncrimes of murder, torture and cruel treatment and that the second may also have been\narbitrarily detained and forcibly disappeared."},{"id":"a-hrc-49-4-p0031","rec_id":"recVilmxHdPgkesVQ","symbol":"A/HRC/49/4","n":"31","seq":31,"section":"VI. Violations and abuses in the context of deprivation of liberty","text":"The Mission’s investigations on the plethora of secret detention facilities in Libya are\nalso ongoing. Secret detention is a particularly gross human rights violation as it subsumes\nipso facto numerous serious violations against the detained victims. The Mission has reports\nof and is investigating a number of secret prison networks controlled by different armed\nmilitias, including a number of prisons that were declared closed but are still secretly\noperative. Based on the testimonies of ex-detainees, which have been corroborated by\ninternational organizations and human rights activists, the Mission has reasonable grounds to\nbelieve that violations of international humanitarian law and international human rights law\nare being committed in a number of secret prisons that currently exist in Libya."},{"id":"a-hrc-49-4-p0032","rec_id":"recVilmxHdPgkesVQ","symbol":"A/HRC/49/4","n":"32","seq":32,"section":"VI. Violations and abuses in the context of deprivation of liberty","text":"For example, the Mission documented, during the current reporting period, the\nabduction of a civilian by one security apparatus. He was detained in a secret location,\nincommunicado, where he was interrogated, beaten three times a day for about eight days,\nthen moved to a secret prison for six weeks. According to the victim, several other detainees\nhad been held in that prison for up to five years, many of whom had been tortured. The victim\ntold the Mission that during his disappearance, the victim’s family had asked about his fate\nand whereabouts but had been falsely informed by authorities that he was not in their custody.\nThe family only discovered the truth when the victim was released."},{"id":"a-hrc-49-4-p0033","rec_id":"recVilmxHdPgkesVQ","symbol":"A/HRC/49/4","n":"33","seq":33,"section":"VI. Violations and abuses in the context of deprivation of liberty","text":"The Mission also found that, in some cases, different security entities across Libya\ncooperated with one another in operating places of detention and transferring detainees\nbetween them. In investigating these prisoner exchanges, the Mission also identified and\ncontinues to document the practice of hostage-taking, whereby the militias controlling secret\nprisons arbitrarily detain adults and children based on their tribal or family links to a wanted\nperson, in order to force that person to surrender. The Mission has received a report of a case\nin which a woman in her seventies was held to force her son to surrender."},{"id":"a-hrc-49-4-p0034","rec_id":"recVilmxHdPgkesVQ","symbol":"A/HRC/49/4","n":"34","seq":34,"section":"VI. Violations and abuses in the context of deprivation of liberty","text":"The Mission finally noted from its review of published material during the current\nperiod that there was no comprehensive official statistical data on prisons in Libya."},{"id":"a-hrc-49-4-p0035","rec_id":"recVilmxHdPgkesVQ","symbol":"A/HRC/49/4","n":"35","seq":35,"section":"VII. Ongoing investigations of extrajudicial killings and enforced","text":"As has previously been reported by the Mission, unlawful killings of civilians not\ndirectly participating in hostilities and other protected persons are a common feature of the\nconduct of hostilities by various parties to the conflicts in Libya. In both an en masse and a\nmore targeted fashion, alleged agents of State and non-State actors have used lethal force\nagainst such victims, often employing firearms to execute their victims brutally. The Mission\nhas received further compelling evidence that these deaths were indeed arbitrary and\nunlawful. This evidence points to the fact that women and children were among the victims,\nthat the victims were all presumably associated with an opposing group to the alleged\nperpetrators or otherwise perceived to be enemies in some way and that items typically\nassociated with such unlawful killings, including blindfolds and ligatures, were apparently\nused. In its first report, the Mission disclosed initial persuasive evidence that mass murder\nhad occurred in Tarhuna. Such evidence remains a strong indication of large-scale violations\nof international human rights law and international humanitarian law. The Mission has\ncontinued to investigate these matters during the current reporting period."},{"id":"a-hrc-49-4-p0036","rec_id":"recVilmxHdPgkesVQ","symbol":"A/HRC/49/4","n":"36","seq":36,"section":"VII. Ongoing investigations of extrajudicial killings and enforced","text":"The Mission has obtained further prima facie evidence that arbitrary arrest and\ndetention have regularly occurred in Libya since 2016 and, in many cases, have amounted to\nenforced disappearances as an international crime. Often used as an apparent tool of\noppression and/or retribution by various actors, this practice typically targets civilians who\nare associated with another side in a conflict and/or who are exercising their fundamental\nrights in a manner that is unpopular with certain groups thought to be behind such abductions.\nThe further evidence collected by the Mission demonstrates that these civilians are forcibly\narrested without legal authority to do so and detained incommunicado for significant periods\nof time (in some cases, presumably, are still being held to this day), and their whereabouts\nand/or status are unknown to their families or close associates, who are denied this\ninformation. The evidence obtained also shows that it is common for other violations and\nabuses to accompany arbitrary detention and enforced disappearance, such as arbitrary and/or\ninhumane conditions of detention, violations of the rights to due process and a fair trial, cruel\nand inhuman treatment, and torture. As these abductions have ostensibly occurred in both\npeacetime and times of conflict and are widespread, they may amount to crimes against\nhumanity, violations of international humanitarian law and/or serious violations of\ninternational human rights law."},{"id":"a-hrc-49-4-p0037","rec_id":"recVilmxHdPgkesVQ","symbol":"A/HRC/49/4","n":"37","seq":37,"section":"VIII. Sexual and gender-based violence","text":"As defined in the Mission’s first report, 16 gender-based violence is any form of\nviolence directed towards, or disproportionately affecting, persons because of their gender or\nsex. The focus in the present section is on sexual violence. Other forms of gender-based\nviolence are addressed elsewhere in this and the Mission’s first report."},{"id":"a-hrc-49-4-p0038","rec_id":"recVilmxHdPgkesVQ","symbol":"A/HRC/49/4","n":"38","seq":38,"section":"VIII. Sexual and gender-based violence","text":"During the period of reporting, the Mission was able to conduct 12 detailed interviews\nwith survivors of sexual violence and received information from families of detainees,\nincluding migrants. It has also received information from witnesses of sexual violence, as\nwell as organizations and health professionals who provide assistance to survivors be it\nwithin or outside Libya."},{"id":"a-hrc-49-4-p0039","rec_id":"recVilmxHdPgkesVQ","symbol":"A/HRC/49/4","n":"39","seq":39,"section":"VIII. Sexual and gender-based violence","text":"The Mission has continued, during the current reporting period, to receive reports of\ndetainees in Libya being threatened with sexual violence against them or their relatives,\nstripped naked for prolonged periods of time or subjected to intrusive body searches\namounting to rape. It had previously also received reports of sexual violence during\ninterrogation, including electricity being applied in the genital area and rape."},{"id":"a-hrc-49-4-p0040","rec_id":"recVilmxHdPgkesVQ","symbol":"A/HRC/49/4","n":"40","seq":40,"section":"VIII. Sexual and gender-based violence","text":"The Mission also continued to receive reports of sexual violence in detention centres\nrun by the Department for Combating Illegal Migration.17 It notes that, when reports of sexual\nviolence in a given detention centre become widespread, the centre in question tends to be\nclosed and detainees, guards and the Department’s officers moved around. No one appears\nto be held legally accountable. Before submitting its first report to the Human Rights Council,\nthe Mission had received consistent reports of sexual violence against women and girls held\nat the Shari’ al-Zawiya centre run by the Department. During the current reporting period,\nthe authorities have closed that centre, but not taken any further action against the\nperpetrators of the violence, to the best of the Mission’s knowledge. That was also the case\nfor the Surman detention centre (in western Libya). Sexual violence affecting migrants is\nfurther addressed in section IX below."},{"id":"a-hrc-49-4-p0041","rec_id":"recVilmxHdPgkesVQ","symbol":"A/HRC/49/4","n":"41","seq":41,"section":"VIII. Sexual and gender-based violence","text":"Sexual violence is also common outside the context of detention. Reports and rumours\nof abuse by members of armed groups and militias of women and girls stopped in the street,\nat checkpoints or in their neighbourhoods feed a climate of fear. This in turn leads families\nand communities to prevent women from taking part in public life with the ostensible aim of\nprotecting them. Threats of sexual violence online against critics and activists, particularly\nwomen activists but also their female relatives, are routine. Victims and witnesses\ninterviewed by the Mission shared their concerns that such threats seemed to be part of the\ntactics used to terrify and silence activists."},{"id":"a-hrc-49-4-p0042","rec_id":"recVilmxHdPgkesVQ","symbol":"A/HRC/49/4","n":"42","seq":42,"section":"VIII. Sexual and gender-based violence","text":"The Mission heard first-hand accounts of persons being targeted for arrest and abuse,\nincluding sexual violence, solely on the basis of their sexual orientation or gender identity.\nSome armed groups with ostensible Salafist-leaning views, including those affiliated with\nthe State, seek to enforce their own interpretation of religious or societal norms and act with\nthe stated objective of cleansing Libya of “deviant” behaviour. In one such example,\naccording to information the Mission received in interviews during the reporting period, two\nmen in a car were accosted by an armed group and their mobile phones checked. After the\nmembers of the armed group had found content on a phone suggesting that the men were gay,\nthey arrested them. One man was reportedly held in Mitiga prison and sexually abused while\nthere."},{"id":"a-hrc-49-4-p0043","rec_id":"recVilmxHdPgkesVQ","symbol":"A/HRC/49/4","n":"43","seq":43,"section":"VIII. Sexual and gender-based violence","text":"The Mission received reports of sexual violence being filmed by perpetrators, while\nvictims were being held in detention or by armed groups or criminal gangs, with a view to\nfurther subjugating and terrorizing them and ensuring that they did not report sexual violence\nor seek redress."},{"id":"a-hrc-49-4-p0044","rec_id":"recVilmxHdPgkesVQ","symbol":"A/HRC/49/4","n":"44","seq":44,"section":"VIII. Sexual and gender-based violence","text":"The Mission considers that not only do the law enforcement authorities and justice\nsystem of Libya appear to be failing to provide protection from sexual violence and remedy\nto survivors, but several laws facilitate or allow impunity for sexual violence and should be\noverhauled."},{"id":"a-hrc-49-4-p0045","rec_id":"recVilmxHdPgkesVQ","symbol":"A/HRC/49/4","n":"45","seq":45,"section":"IX. Migrants","text":"Unless otherwise indicated, the expression “migrants” used in the present report\ncovers the categories of migrant, refugee or asylum seeker.18"},{"id":"a-hrc-49-4-p0046","rec_id":"recVilmxHdPgkesVQ","symbol":"A/HRC/49/4","n":"46","seq":46,"section":"IX. Migrants","text":"In its first report to the Human Rights Council, the Mission found that numerous\nviolations against migrants in Libya may amount to crimes against humanity, while noting\nthe need for further investigations to establish the role of all involved. 19 Sexual violence\nagainst migrants was an integral part of that finding. The Mission also highlighted that those\nincidents were neither isolated nor could they be attributed to rogue elements, particularly in\nthe case of violent interceptions at sea and subsequent detention. In spite of the Mission’s\nfindings, the Libyan authorities have continued to detain migrants, including those\nintercepted at sea. European States continued to cooperate with the Libyan authorities,\nincluding the Libyan Coastguard.20 The Mission reiterates that such cooperation should be\ncarried out in accordance with the obligations of international human rights law and each\nState’s responsibility to protect migrants in its territorial waters and search and rescue zone."},{"id":"a-hrc-49-4-p0047","rec_id":"recVilmxHdPgkesVQ","symbol":"A/HRC/49/4","n":"47","seq":47,"section":"IX. Migrants","text":"Since October 2021, the Mission has continued to document further cases of murder,\ntorture, inhumane acts, rape, persecution and enslavement of migrants by some State\nauthorities, militias, armed groups and traffickers, employing a consistent pattern of conduct.\nThese abuses occur against the backdrop of a domestic legal framework that – inconsistent\nwith the human rights obligations of Libya – prescribes automatic and indefinite detention\nfor people entering the country irregularly. During the current reporting period, thousands of\npeople were intercepted by the Coastguard and brought back to Libya where they faced\narbitrary detention in inhumane conditions, torture and other ill-treatment.21"},{"id":"a-hrc-49-4-p0048","rec_id":"recVilmxHdPgkesVQ","symbol":"A/HRC/49/4","n":"48","seq":48,"section":"IX. Migrants","text":"The Mission’s latest investigations have centred on a number of incidents, including\nthe raid on the Gargaresh area of Tripoli, that occurred at the beginning of October 2021 and\nensuing incidents of excessive use of force in detention centres under the control of the\nDepartment for Combating Illegal Migration, as well as inhumane conditions of detention.\nThe Mission also investigated continuing abuses against migrants at the hands of traffickers.\nOne incident documented by the Mission related to the death of a young migrant whom\ntraffickers had reportedly set alight. The Mission additionally documented the case of\nabduction and torture of a migrant boat mechanic by an armed group involved in trafficking.\nIt received reports of sexual and gender-based violence in migrant detention centres. During\nthe reporting period, Shari’ al-Zawiya, a detention centre in which the Mission is\ninvestigating incidents of sexual violence by guards, was closed down."},{"id":"a-hrc-49-4-p0049","rec_id":"recVilmxHdPgkesVQ","symbol":"A/HRC/49/4","n":"49","seq":49,"section":"IX. Migrants","text":"The Gargaresh raid by Libyan security forces was reported to have targeted foreigners\nand migrants, killing 1 person and injuring at least 15 others.22 The raid took place in the\ncontext of xenophobic statements associating migrants with criminality and drug trafficking.\nThe Mission’s further investigations indicated that, on 1 October 2021, Libyan security forces\nhad launched a campaign in the area, arresting thousands of foreigners, before transporting\nthem to several detention centres, including Mabani, Abusliem and Abu Rashada in Gharyan.\nThe Mission was able to interview 2 migrants from the arrested group, both of whom\ninformed it that, on that date, at least 4,000 migrant men, women and children had been\narrested and transferred to a detention centre already housing a large of number of other\nmigrant detainees in very poor material conditions."},{"id":"a-hrc-49-4-p0050","rec_id":"recVilmxHdPgkesVQ","symbol":"A/HRC/49/4","n":"50","seq":50,"section":"IX. Migrants","text":"The Mission has received information about the forcible dispersal of a sit-in by\nmigrants in front of the registration centre of the Office of the United Nations High\nCommissioner for Refugees in Tripoli in January 2022 and reports of excessive use of force."},{"id":"a-hrc-49-4-p0051","rec_id":"recVilmxHdPgkesVQ","symbol":"A/HRC/49/4","n":"51","seq":51,"section":"IX. Migrants","text":"Migrants interviewed by the Mission continued to share alarming information about\nthe situation in Bani Walid, a trafficking hub approximately 130 kilometres south-east of\nMisrata. Victims recounted that “If migrants who were kept there heard the word Bani Walid,\nshe or he would start crying. They set fire to and burn women’s breasts and vaginas there”\nand “[After I was abducted by traffickers in Libya] I was tortured in different ways. I was\nburned with cigarettes. They poured petrol on me and attempted to set me on fire. They tied\neach of my arms to a car and threatened to drive and pull them away. I was penetrated with\na knife and a baseball bat, as well as with a broomstick. I was filmed by my abductors, who\nthreatened to release the video.” Among other violations, the Mission found that there were\nreasonable grounds to believe that migrants had been held captive, murdered, tortured and\nraped. Of eight migrants interviewed shortly before the writing of the present report, several\ntold of the existence of mass graves in Bani Walid, one of them recounting that he had buried\nthree bodies himself in such a grave. The Mission is still seeking to verify this information."},{"id":"a-hrc-49-4-p0052","rec_id":"recVilmxHdPgkesVQ","symbol":"A/HRC/49/4","n":"52","seq":52,"section":"IX. Migrants","text":"The Mission continued to receive, from interviewees, reports of sexual violence\naffecting migrant women in Bani Walid. Five migrant women recently interviewed, all from\nEast Africa, told the Mission that they had been raped and sexually abused in Bani Walid.\nGuards threatened one woman that her husband, also detained in Bani Walid, would be killed\nif she did not submit to them. Three of the other women told of drunk guards coming into the\nplace in which women were sleeping during the night and picking women for rape,\nconfirming a pattern documented by the Mission."},{"id":"a-hrc-49-4-p0053","rec_id":"recVilmxHdPgkesVQ","symbol":"A/HRC/49/4","n":"53","seq":53,"section":"IX. Migrants","text":"The Mission also draws the attention of the Human Rights Council to the death, in\nMarch 2022, of an 18-year-old Sudanese migrant, whom the Mission had recently\ninterviewed, from injuries apparently inflicted on him by human traffickers. Before his death,\nthe victim had informed the Mission that traffickers had tortured him, demanded a ransom\nfor his release from his family and set him on fire when the money had not been paid. The\nincident reportedly occurred in Sabha, in the south-west of Libya."},{"id":"a-hrc-49-4-p0054","rec_id":"recVilmxHdPgkesVQ","symbol":"A/HRC/49/4","n":"54","seq":54,"section":"IX. Migrants","text":"The Libyan authorities have been either unable or unwilling to protect migrants\nagainst abuse by traffickers and to hold perpetrators to account. Some traffickers have been\nheld to account in European States for trafficking and human rights abuses against migrants\nin Libya, as recently exemplified by the decision in February 2022 of a preliminary hearing\njudge in Palermo to sentence two nationals of Bangladesh to 20 years in prison for detaining\nand torturing migrants in Zuwarah (located to the west of Tripoli)."},{"id":"a-hrc-49-4-p0055","rec_id":"recVilmxHdPgkesVQ","symbol":"A/HRC/49/4","n":"55","seq":55,"section":"X. Violations of the right of Libyans to participate in public life","text":"Participation in public affairs, including through freely chosen representatives, is a\nhuman right protected by treaties to which Libya is party, as are the rights to vote and be\nelected.23 With the period of reporting dominated by the prospect of elections and related\npolitical and legal action, violations affecting these rights have been a focus of the Mission’s\ninvestigations. The run-up to the anticipated, but now postponed, elections on 24 December\n2021 was characterized by several concerning incidents, casting doubt on the ability of the\nGovernment of Libya and de facto authorities to guarantee the right of Libyans to participate\nin public life and choose their own representatives, and protect those involved in elections\nfrom violence and threats.24"},{"id":"a-hrc-49-4-p0056","rec_id":"recVilmxHdPgkesVQ","symbol":"A/HRC/49/4","n":"56","seq":56,"section":"X. Violations of the right of Libyans to participate in public life","text":"The Mission collected many testimonies, videos and photographs on elections-related\nincidents that provided evidence of violations of the right to participate in public affairs.\nWhile the information gathered by the Mission indicates that the Libyan people are eager for\nthe elections to take place, it also reveals that some candidates, election officials and\ncandidates’ supporters appear to have received threats that can affect the fairness of the\nprocess and the chances of different candidates in favour of those who have de facto power\nand influence on the ground."},{"id":"a-hrc-49-4-p0057","rec_id":"recVilmxHdPgkesVQ","symbol":"A/HRC/49/4","n":"57","seq":57,"section":"X. Violations of the right of Libyans to participate in public life","text":"In November 2021, armed groups reportedly arrested and detained a number of\nindividuals from Sirte, for expressing their views about the elections or their support for\nspecific candidates on social media and during demonstrations. According to several\ntestimonies received by the Mission, there are indications that the victims were arrested\narbitrarily and may have been subjected to ill-treatment and, possibly, torture in detention.\nSimilar incidents were also documented in other parts of the country."},{"id":"a-hrc-49-4-p0058","rec_id":"recVilmxHdPgkesVQ","symbol":"A/HRC/49/4","n":"58","seq":58,"section":"X. Violations of the right of Libyans to participate in public life","text":"The Mission also investigated one incident during which armed men had attempted to\nprevent the judicial review of a candidate’s eligibility. In Sabha, from late November to 2\nDecember 2021, a group of armed men surrounded the Court of Appeal, which was due to\nhear an appeal by Saif al-Islam al-Gadafi against his exclusion from the presidential\nelection.25 According to eyewitnesses, the armed men prevented the judges from entering the\npremises, and resorted to threats and intimidation of both judicial and other legal personnel\nand protesters who had gathered in front of the courthouse. The appeal hearing eventually\ntook place on 2 December 2021, following the group’s departure from the grounds."},{"id":"a-hrc-49-4-p0059","rec_id":"recVilmxHdPgkesVQ","symbol":"A/HRC/49/4","n":"59","seq":59,"section":"X. Violations of the right of Libyans to participate in public life","text":"Reliable reports have also described incidents of violence and intimidation against\nofficials and infrastructure of the High National Elections Commission, including a number\nof voters’ registration offices, polling stations, looting of election equipment and incidents of\nharassment and intimidation of officials responsible for securing elections. 26"},{"id":"a-hrc-49-4-p0060","rec_id":"recVilmxHdPgkesVQ","symbol":"A/HRC/49/4","n":"60","seq":60,"section":"X. Violations of the right of Libyans to participate in public life","text":"Violations affecting the participation of women and ethnic minorities, specifically, in\npublic life, are described in sections XIII and XIV below."},{"id":"a-hrc-49-4-p0061","rec_id":"recVilmxHdPgkesVQ","symbol":"A/HRC/49/4","n":"61","seq":61,"section":"XI. Violations against civil society organizations, activists and","text":"The Mission has received alarming reports of attacks on civil society organizations\nand activists in Libya, contrary to the rights to peaceful assembly and freedom of association\nunder articles 21 and 22 of the International Covenant on Civil and Political Rights. One\nLibyan civil society activist interviewed in March 2022 stated that: “I left [Libya] because I\nam scared to be arrested and forced to say things [on camera] that would hurt people around\nme. Me not being around would help protect my family. My priority is to keep everyone\nsafe.” The silencing of civil society organizations, activists, journalists and human rights\ndefenders relies on restrictive laws and regulations, extensive oversight powers given to the\nCivil Society Commission, a government-established body, and the fear of suspension or\nclosure of organizations, while funding is tightly controlled. In effect, organizations, activists\nand defenders are expected to seek prior authorization before carrying out activities or\nmeeting with international bodies such as the Mission."},{"id":"a-hrc-49-4-p0062","rec_id":"recVilmxHdPgkesVQ","symbol":"A/HRC/49/4","n":"62","seq":62,"section":"XI. Violations against civil society organizations, activists and","text":"Against the backdrop of a public campaign denigrating the work of civil society and\na shrinking civic space, activists are routinely threatened online, mainly on the platforms\nFacebook and Club House, and live under the constant fear of abduction, arrest and arbitrary\ndetention. As the Mission and others have documented elsewhere, arbitrary detention is often\naccompanied by torture and other ill-treatment, sexual and gender-based violence and other\nviolations, and in some cases may amount to enforced disappearance."},{"id":"a-hrc-49-4-p0063","rec_id":"recVilmxHdPgkesVQ","symbol":"A/HRC/49/4","n":"63","seq":63,"section":"XI. Violations against civil society organizations, activists and","text":"On 26 October 2021, the House of Representatives ratified a law against cybercrime.\nThe law’s overly broad terms give the Libyan judicial authorities excessive discretion to\nrestrict online freedom of expression and impose penalties, contrary to article 19 of the\nInternational Covenant on Civil and Political Rights."},{"id":"a-hrc-49-4-p0064","rec_id":"recVilmxHdPgkesVQ","symbol":"A/HRC/49/4","n":"64","seq":64,"section":"XI. Violations against civil society organizations, activists and","text":"A draft civil society regulation was proposed by the Government of National Unity in\nJuly 2021 that further restricts civil society groups, increases control over them and subjects\norganizations to a code of conduct. The Mission has received information indicating that civil\nsociety organizations have been asked by the Civil Society Commission to reregister.\nAccording to the information received by the Mission, the High National Elections\nCommission will not allow organizations that have not reregistered with the Civil Society\nCommission to monitor elections."},{"id":"a-hrc-49-4-p0065","rec_id":"recVilmxHdPgkesVQ","symbol":"A/HRC/49/4","n":"65","seq":65,"section":"XI. Violations against civil society organizations, activists and","text":"During the current reporting period, further chilling video recordings of activists’\n“confessions” were posted on the Facebook page of the Internal Security Agency and\ninternational organizations were portrayed as imposing a foreign agenda and perverting\nLibyan youth. The Mission fears that such “confessions” may have been obtained under\nduress and are intended to terrorize activists."},{"id":"a-hrc-49-4-p0066","rec_id":"recVilmxHdPgkesVQ","symbol":"A/HRC/49/4","n":"66","seq":66,"section":"XII. Other violations affecting the transition to the rule of law and","text":"Reliable reports have identified, throughout the period covered by the Mission’s\nmandate, a pattern of attacks against members of the legal community, public prosecution\noffices and courthouses, 27 together with a steady weakening in the judiciary’s ability to\nconduct transparent and effective trials. The Mission has also collected information regarding\nsuch attacks and threats of violence against courthouses, the judiciary and other members of\nthe legal community."},{"id":"a-hrc-49-4-p0067","rec_id":"recVilmxHdPgkesVQ","symbol":"A/HRC/49/4","n":"67","seq":67,"section":"XII. Other violations affecting the transition to the rule of law and","text":"In particular, the Mission investigated the abduction in 2017 of a local prosecutor in\nTarhuna who had reportedly been trying to build a case against associates of the Al-Kaniyat\nfamily.28 The victim remains missing at the time of submission of the present report. Local\nauthorities only opened an investigation into this incident in 2019, following the departure of\nthat family from Tarhuna, with little progress to date."},{"id":"a-hrc-49-4-p0068","rec_id":"recVilmxHdPgkesVQ","symbol":"A/HRC/49/4","n":"68","seq":68,"section":"XII. Other violations affecting the transition to the rule of law and","text":"As described earlier in the present report, violence against the judiciary was observed\nin the build-up to the elections in December 2021, when a number of judicial processes took\nplace to confirm candidates’ standing in the elections – notably during the four-day assault\non the Sabha courthouse, which was due to hear an appeal from a lawyer of Saif al-Islam al-\nGadafi, one of the candidates.29"},{"id":"a-hrc-49-4-p0069","rec_id":"recVilmxHdPgkesVQ","symbol":"A/HRC/49/4","n":"69","seq":69,"section":"XII. Other violations affecting the transition to the rule of law and","text":"The Mission expresses its concern that these attacks and acts of intimidation foster an\nincreasingly insecure environment, which is highly detrimental to one of the cornerstones of\nthe rule of law: the ability of the judiciary to administer and adjudicate the law in a manner\nthat is fair, independent, accessible and efficient. Hampering this ability, through intimidation\nand violence, is a serious obstacle to Libyan victims’ transition to a democratic system ruled\nby (human rights) law and justice.30"},{"id":"a-hrc-49-4-p0070","rec_id":"recVilmxHdPgkesVQ","symbol":"A/HRC/49/4","n":"70","seq":70,"section":"XII. Other violations affecting the transition to the rule of law and","text":"Furthermore, the Mission has gathered – during the present reporting period – enough\ninformation regarding more attacks and crimes against the judiciary and lawyers in different\nregions of Libya. The Mission will continue its work to verify the information that it has\ngathered to reach further conclusive findings for the purpose of its report due to be submitted\nto the Human Rights Council at its fiftieth session."},{"id":"a-hrc-49-4-p0071","rec_id":"recVilmxHdPgkesVQ","symbol":"A/HRC/49/4","n":"71","seq":71,"section":"XIII. Violations against women","text":"Women and girls in Libya face a myriad of challenges and obstacles that prevent them\nfrom fully enjoying their human rights and meaningfully participating in the public life of\ntheir country. Violence, including sexual violence,31 takes place offline and online and is\nfuelled by patriarchy and religious and cultural conservativism, as well as sexism and\nmisogyny. State authorities fail to protect women and girls from violence and perpetuate\ngender stereotypes and the marginalization of women. In this context, Libyan women are\nunderrepresented in all elected and appointed State institutions and marginalized in peace\nprocesses. In its resolution 43/39 establishing the mandate of the Mission, the Human Rights\nCouncil called upon the Libyan authorities to facilitate women’s full, equal and effective\nparticipation in activities relating to the prevention and resolution of the armed conflict, the\nmaintenance of peace and security and post-conflict peacebuilding. It further called upon all\nLibyans to oppose polarization and hate speech in official and public discourse, which\nthreatened democratic values, social stability and peace, weakened the social fabric and\nundermined stability, peace and security.32"},{"id":"a-hrc-49-4-p0072","rec_id":"recVilmxHdPgkesVQ","symbol":"A/HRC/49/4","n":"72","seq":72,"section":"XIII. Violations against women","text":"Since October 2021, the Mission has conducted detailed interviews of 10 women and\nhas spoken to a range of organizations and activists. It has reviewed legal documents, video\nfootage and posts on social media platforms. Virtually all those who spoke to the Mission did\nso on condition of anonymity."},{"id":"a-hrc-49-4-p0073","rec_id":"recVilmxHdPgkesVQ","symbol":"A/HRC/49/4","n":"73","seq":73,"section":"XIII. Violations against women","text":"Women’s role in civic space and public life carries significant risks for them: those\nwho overcome systemic obstacles and manage to take part in public life may be threatened,\ntheir political affiliations or morality questioned with the aim of damaging their reputation\nor that of their family members. A number of women activists face hate speech and\nincitement to violence, sometimes by senior religious establishment members, such as the\nGrand Mufti of Libya, Sheikh Sadiq al-Ghariani."},{"id":"a-hrc-49-4-p0074","rec_id":"recVilmxHdPgkesVQ","symbol":"A/HRC/49/4","n":"74","seq":74,"section":"XIII. Violations against women","text":"Women played an important role in the Libyan Political Dialogue Forum and the\nensuing road map included a 30 per cent quota for women in leadership positions in the\nGovernment.33 However, this pledge was soon revoked, and it was announced that only a few\nwomen had been nominated to participate in the Government. 34 Eventually, under intense\npressure, including from all women members of the Libyan Political Dialogue Forum\nregardless of their political affiliations, five women ministers were appointed. The\nGovernment of National Unity comprised only 15 per cent of women, rather than the 30 per\ncent pledged. In March 2022, the competing Government that was sworn in by the House of\nRepresentatives comprised only 2 women among its 38 members."},{"id":"a-hrc-49-4-p0075","rec_id":"recVilmxHdPgkesVQ","symbol":"A/HRC/49/4","n":"75","seq":75,"section":"XIII. Violations against women","text":"Women’s participation and their ability to engage in the public life of the country free\nof intimidation, threats and fears for their lives is essential. Women registered massively to\nvote and the High National Elections Commission sought to address the challenges faced by\nwomen to register, due, among other things, to the issue of male family members holding the\n“family book”."},{"id":"a-hrc-49-4-p0076","rec_id":"recVilmxHdPgkesVQ","symbol":"A/HRC/49/4","n":"76","seq":76,"section":"XIII. Violations against women","text":"The enforced disappearance of a member of the House of Representatives, Sihem\nSergiwa, which the Mission previously reported,35 cast a shadow on elections in Libya and\nwomen’s participation. Since her abduction from her home in Benghazi, although the judicial\nauthorities opened a formal investigation into her enforced disappearance, little regarding her\nwhereabouts or the identity of the perpetrators has been established at this time. The Mission\nreminds the local authorities that the duty to protect Ms. Sergiwa falls on the Libyan\nauthorities themselves. During its visit to Benghazi, the Mission held meetings with the\nrepresentatives of the Office of Public Prosecution and other officials in Benghazi and\ndiscussed the abduction and enforced disappearance of Ms. Sergiwa. The Office of Public\nProsecution shared documents with the Mission about the investigation. While the opening\nof the investigation is a welcome step, two and a half years after the abduction of Ms.\nSergiwa, law enforcement agencies and the judiciary have yet to unveil the truth about what\nhappened to her, to end her enforced disappearance and to hold accountable the perpetrators\nof such a crime."},{"id":"a-hrc-49-4-p0077","rec_id":"recVilmxHdPgkesVQ","symbol":"A/HRC/49/4","n":"77","seq":77,"section":"XIII. Violations against women","text":"No one has yet been held accountable for the killing of a vocal critic active on social\nmedia, Hanan al-Barassi, who was gunned down in the street in Benghazi.36 During its visit\nto Benghazi, the Mission met with the relevant authorities and sought clarification of the\ncircumstances of the killing of Ms. Al-Barassi and whether anyone had been held responsible\nfor it. The Office of Public Prosecution informed the Mission that the investigation was\nongoing. Such an investigation must lead to the truth being uncovered and hold the\nperpetrators accountable. In fact, the only persons jailed in relation to the killing of Ms. Al-\nBarassi were her children."},{"id":"a-hrc-49-4-p0078","rec_id":"recVilmxHdPgkesVQ","symbol":"A/HRC/49/4","n":"78","seq":78,"section":"XIII. Violations against women","text":"The impunity for the enforced disappearance of Ms. Sergiwa and the killing of Ms.\nAl-Barassi is part of a broader pattern of impunity for the killing of women activists and\npoliticians. While some of these killings took place during a period outside the Mission’s\nmandate, the continued impunity for such killings is of concern to the Mission. Some eight\nyears after her death, no one has been held accountable for the killing, in her house in\nBenghazi, of prominent lawyer Salwa Bugaighis. Her husband, Essam al-Ghariani, was\nabducted on the same day and his whereabouts are still unknown. Another woman politician,\nFariha al-Berkawi, was killed in Derna in 2014. Activist Intissar al-Hasairi, co-founder of\nTanweer, was found dead in Tripoli in the same year. While these women held different\nviews and were involved in public life in different ways, they were all targeted for their\nactivism and killed, and no perpetrator has been held responsible for their deaths or enforced\ndisappearance."},{"id":"a-hrc-49-4-p0079","rec_id":"recVilmxHdPgkesVQ","symbol":"A/HRC/49/4","n":"79","seq":79,"section":"XIII. Violations against women","text":"The killing or enforced disappearance of prominent women politicians and activists\nand ensuing impunity has sent out shockwaves among activists and aspiring candidates and\nforced several activists to flee Libya or to stop their activism. It has had a chilling effect on\nwomen wanting to engage in public life."},{"id":"a-hrc-49-4-p0080","rec_id":"recVilmxHdPgkesVQ","symbol":"A/HRC/49/4","n":"80","seq":80,"section":"XIII. Violations against women","text":"The concerns of the Mission regarding women’s political participation in the\nupcoming elections in Libya are heightened by reports that women candidates in local,\nparliamentary and presidential elections have been threatened, including online, and deterred\nfrom running for office."},{"id":"a-hrc-49-4-p0081","rec_id":"recVilmxHdPgkesVQ","symbol":"A/HRC/49/4","n":"81","seq":81,"section":"XIII. Violations against women","text":"Women ministers in the Government of National Unity have faced a sustained public\ncampaign driven by misogyny to undermine them and cast doubt on their credibility."},{"id":"a-hrc-49-4-p0082","rec_id":"recVilmxHdPgkesVQ","symbol":"A/HRC/49/4","n":"82","seq":82,"section":"XIII. Violations against women","text":"Women’s rights suffered a further setback during the current reporting period with the\nsuspension of a memorandum of understanding between the United Nations Entity for\nGender Equality and the Empowerment of Women (UN-Women) and the ministry in charge\nof women’s affairs. The memorandum of understanding, signed in October 2021, was part of\nthe steps taken for UN-Women to support Libyan stakeholders to devise a national action\nplan in the framework of Security Council resolution 1325 (2000) on women, peace and\nsecurity. In the ensuing months, conservative figures attacked the memorandum of\nunderstanding and declared the Convention on the Elimination of All Forms of\nDiscrimination against Women – to which Libya has been a party since 1989 – contrary to\nIslam. In spite of the Prime Minister mandating the minister in charge of women’s affairs to\nsign a memorandum of understanding, she was subjected to an investigation at the request of\nthe Prime Minister and the memorandum itself has now been suspended, initially by a\ndecision of an administrative tribunal and later by the Prime Minister, although the case is\nstill pending before the tribunal. Divisions over the memorandum of understanding unleashed\nhate speech on social media platforms, along with questions regarding the security and life\nof the minister, and marks a setback for women’s rights in Libya. The Mission reviewed\nsome of the pamphlets distributed against the memorandum of understanding and Security\nCouncil resolution 1325 (2000). The backlash concerning the signing of the memorandum of\nunderstanding and the highly critical views of gender equality that were expressed are not\nisolated incidents and seem to be part of an orchestrated campaign."},{"id":"a-hrc-49-4-p0083","rec_id":"recVilmxHdPgkesVQ","symbol":"A/HRC/49/4","n":"83","seq":83,"section":"XIV. Violations against minorities","text":"During the current reporting period, the Mission considered the broader context of\ndiscrimination and exclusion experienced by some minority groups in Libya. The continued\npolitical instability and insecurity in Libya has also had an impact on the country’s ability to\nend the legacies of marginalization and discrimination against minority groups. The\nMission’s focus on discrimination against minorities is of paramount importance in\ndocumenting the violations against those vulnerable groups and ensuring their protection. It\nis the Mission’s conviction that any possible national reconciliation in Libya will not be\nmeaningful without an inclusive process in which all Libyans from all groups participate\nwithout discrimination or fear."},{"id":"a-hrc-49-4-p0084","rec_id":"recVilmxHdPgkesVQ","symbol":"A/HRC/49/4","n":"84","seq":84,"section":"XIV. Violations against minorities","text":"In its previous report, the Mission highlighted the situation of the Tawerghan\ncommunity, whose members have been greatly affected by forced displacement and continue\nto face dire living conditions in the camps in which they have sought refuge."},{"id":"a-hrc-49-4-p0085","rec_id":"recVilmxHdPgkesVQ","symbol":"A/HRC/49/4","n":"85","seq":85,"section":"XIV. Violations against minorities","text":"During the current reporting period, the Mission continued its investigation of\ndiscriminatory practices and violations against some minority groups in Libya. The Mission\nconducted a number of interviews with members of the Tuareg and Tebu minorities, as well\nas a member of the “Arab returnees” community in Libya. 37 In the aftermath of the 2011\nrevolution, approximately 40,000 individuals were forcibly expelled from their homes in\nTawergha by Misratan armed groups. Today, there are more than 35,000 internally displaced\nTawerghans who have not been able to safely return to their homes, despite the reconciliation\nagreement between the two communities in 2017."},{"id":"a-hrc-49-4-p0086","rec_id":"recVilmxHdPgkesVQ","symbol":"A/HRC/49/4","n":"86","seq":86,"section":"XIV. Violations against minorities","text":"During his time in office, Muammar Gaddafi recruited Tuareg soldiers by promising\nthem Libyan documentation. Not only did this have the effect of stigmatizing this group as\n“pro-Gaddafi”, these promises never materialized and approximately 14,000 Tuareg still do\nnot hold official documentation, such as the “family booklet”, which is essential proof of\ncitizenship. In October 2021, Prime Minister Dbeibah lamented the absence of legal status\nof the Tuareg, which has prevented them, for example, from benefiting from vaccination\ncampaigns. It is evident that the Tuareg are unable to avail themselves of the full array of\neconomic, social and cultural rights afforded to Libyan citizens. In 1973, pro-Gaddafi forces\ninvaded the Aouzou Strip and granted Libyan nationality to a number of Tebus to entice them\nto join the army. However, after the International Court of Justice ruled that the Aouzou Strip\nshould be returned to Chad, Muammar Gaddafi issued a decree stating that any\ndocumentation issued in the Strip should be revoked and, as a result, many Tebus have been\nunable to obtain documentation ever since. These and other ethnic minorities, such as the\nAmazigh, risk being overlooked in the electoral process. The percentage of undocumented\npersons remains high. Many are unable to acquire citizenship or other forms of\ndocumentation that would allow them to vote in elections and on a possible constitution."},{"id":"a-hrc-49-4-p0087","rec_id":"recVilmxHdPgkesVQ","symbol":"A/HRC/49/4","n":"87","seq":87,"section":"XIV. Violations against minorities","text":"The Mission is continuing to examine the situation of all minorities in Libya, including\nin relation to the electoral and constitution-drafting process and intersectional discrimination\nfaced by women from minority groups."},{"id":"a-hrc-49-4-p0088","rec_id":"recVilmxHdPgkesVQ","symbol":"A/HRC/49/4","n":"88","seq":88,"section":"XV. Violations of international humanitarian law","text":"A number of protracted periods of non-international armed conflict between\norganized State armed forces and non-State armed groups has been well-documented\nthroughout the mandate of the Mission. The Mission has ongoing investigations into a range\nof incidents that may amount to violations of international humanitarian law and war crimes,\nsuch as indiscriminate shelling, airstrikes on civilian areas and the intentional destruction of\nprotected objects, such as hospitals, schools and places of worship. To provide insight into\nthe status of these ongoing investigations, the following section addresses two matters:\nalleged drone strikes targeting civilians in Murzuq and attacks on a protected site in Sirte\ncalled Zawiyat Bin Issa.38"},{"id":"a-hrc-49-4-p0089","rec_id":"recVilmxHdPgkesVQ","symbol":"A/HRC/49/4","n":"89","seq":89,"section":"XV. Violations of international humanitarian law","text":"Murzuq: the Mission received reports that, on or around 4 August 2019, several drone\nstrikes had struck a location in a densely populated Tebu neighbourhood in Murzuq, in which\napproximately 200 unarmed dignitaries and similar officials were gathered. The attack killed\nat least 43 civilians and wounded around 51, including an unknown number of women and\nchildren. It is reported that, after the first strike, civilians and first responders came to aid\nthose who might have been affected when a second strike occurred, killing additional\ncivilians. It is presumed that the additional drone strikes occurred thereafter, likely adding to\nthe ultimate count of fatalities and casualties."},{"id":"a-hrc-49-4-p0090","rec_id":"recVilmxHdPgkesVQ","symbol":"A/HRC/49/4","n":"90","seq":90,"section":"XV. Violations of international humanitarian law","text":"The drone attack occurred in association with the non-international armed conflict\ntaking place in Libya at that time. Two days prior, an armed Tebu group had stormed the Al-\nMagarif neighbourhood in Murzuq, which had been reportedly occupied by armed members\nof the Al-Ahali group, with armoured personnel carriers and heavy artillery. Additionally, in\nTripoli, a siege of the city was under way. While there are some reports that armed fighters\nwere in the location at the time, the Mission has yet to uncover evidence to corroborate this\nallegation or to suggest that this location had military or strategic value. More investigative\nwork is necessary to determine additional details of these attacks and make definitive\nfindings."},{"id":"a-hrc-49-4-p0091","rec_id":"recVilmxHdPgkesVQ","symbol":"A/HRC/49/4","n":"91","seq":91,"section":"XV. Violations of international humanitarian law","text":"Zawiyat Bin Issa: the Mission received reports that, in early 2020, during the non-\ninternational armed conflict taking place in Libya between the Government of National\nAccord and the Libyan National Army, members of an armed Salafist group affiliated with\nthe Army had bulldozed a Sufi sanctuary in Sirte, named Zawiyat Bin Issa, that formed part\nof the “Old Mosque” or the “Ben Shafi Mosque” completed in 1885. Just prior to the alleged\nattack, which likely occurred on 5 February 2020, this protected site became part of the\nterritory controlled by the Libyan National Army when the above-mentioned armed Salafist\ngroup switched allegiances in January 2020 from the Government of National Unity to the\nLibyan National Army. The building had a cultural and religious purpose and historical\nsignificance for the local and regional population, and it did not appear to be a military\nobjective. In this regard, the Mission obtained evidence suggesting that the site had been in\nuse for religious and other non-military purposes up until its alleged partial destruction. The\nsite was located in a civilian area that was not subject to or close to active hostilities at the\ntime and was not proximate to any military objectives. There are therefore indications that\nthis building was a protected object under international humanitarian law."},{"id":"a-hrc-49-4-p0092","rec_id":"recVilmxHdPgkesVQ","symbol":"A/HRC/49/4","n":"92","seq":92,"section":"XV. Violations of international humanitarian law","text":"There are also indications that the attack was intentional, in light of the use of heavy\nearth-moving equipment. Furthermore, there are indications that the attack took place in the\ncontext of and in association with the non-international armed conflict that was ongoing in\nLibya at the time, as Zawiyat Bin Issa was under the control of this armed Salafist group\nbefore January 2020, but was not attacked."},{"id":"a-hrc-49-4-p0093","rec_id":"recVilmxHdPgkesVQ","symbol":"A/HRC/49/4","n":"93","seq":93,"section":"XVI. Conclusions","text":"The political situation in Libya remains tense and the security situation is fragile. The\nMission continued in this period to investigate and fulfil its mandate regarding violations of\ninternational human rights law and international humanitarian law, in the context of secret\nprisons, other places of detention, extrajudicial killings and enforced disappearances,\nviolations against vulnerable populations and the conduct of armed hostilities. At the same\ntime, the Mission focused on investigating violations and practices that impede the Libyan\npeople’s aspiration for peace, democracy and greater respect for human rights. With its\nincreased capacity in the weeks immediately before the submission of the present report, the\nMission made notable advances in these investigations."},{"id":"a-hrc-49-4-p0094","rec_id":"recVilmxHdPgkesVQ","symbol":"A/HRC/49/4","n":"94","seq":94,"section":"XVI. Conclusions","text":"The Mission appreciates the continued cooperation of the Libyan authorities, notably\nin facilitating recent visits and sharing information about their own efforts to investigate and\nprosecute. Nonetheless profound challenges in ensuring accountability for human rights\nviolations and abuses in Libya remain. Attempts to achieve transitional justice remain\nincomplete and further efforts and technical capacity are needed, including to increase the\nability of the Libyan authorities to prosecute violations and international crimes. Holding\nperpetrators to account for such violations, against Libyan victims and others living on\nLibyan territory alike, is essential for their prevention and non-recurrence. The Mission will\naddress the efforts made to ensure accountability in more detail in its report to the Human\nRights Council at its fiftieth session. The Mission underlines once again, however, that a truly\ncomprehensive investigation into the situation of human rights in Libya as a whole, by the\nMission, is urgently needed and will require more than the remaining three months of its\nmandate to achieve that."},{"id":"a-hrc-49-4-p0095","rec_id":"recVilmxHdPgkesVQ","symbol":"A/HRC/49/4","n":"95","seq":95,"section":"XVII. Recommendations","text":"The Mission calls on Libya to:\n(a)    Strengthen the judiciary to bring to justice the perpetrators of violations\nor abuses of international human rights law and violations of international\nhumanitarian law;\n(b)    Eliminate all forms of discrimination against women and ensure that\nwomen are protected from violence, including by conducting effective investigations\ninto incidents of sexual and gender-based violence and holding perpetrators\naccountable;\n(c)    Enhance protection of, and eliminate discriminatory laws and practices\nagainst, vulnerable groups, in particular migrants, refugees, members of religious and\nethnic minorities, persons deprived of liberty and children. Religious and ethnic\nminorities should be protected from any attack or persecution;\n(d)    End the arbitrary detention of migrants and enact a comprehensive legal\nframework to combat trafficking;\n(e)    Uphold the rights to freedom of expression, association and peaceful\nassembly and enable civic space; ensure that civil society organizations, activists and\ndefenders are able to conduct their work free from undue limitations and fears for their\nsafety or their lives; rescind Presidential Council Decree No. 286 of 2019 on civil society\norganizations; and take measures to halt hate speech and incitement to violence;\n(f)    Ensure that: (i) the management of all prisons falls under the\nresponsibility of the State and that secret prisons are eradicated; (ii) prisoners can have\ntheir detention reviewed in accordance with the law; and (iii) prisoners are held in\nhumane and dignified conditions and protected from violence;\n(g)     Establish an independent national prevention mechanism to conduct\nregular visits to detention centres and prisons in Libya to ensure that human rights\nabuses are eradicated and prevented;\n(h)    Ensure that no one is held outside the protection of the law and that all\nreported cases of enforced disappearance are investigated effectively, with a view to\nclarifying the victims’ whereabouts and fate, and take steps to ratify the International\nConvention for the Protection of All Persons from Enforced Disappearance;\n(i)     Strengthen efforts to achieve a permanent ceasefire as a first step in the\nsearch for a lasting peace;\n(j)    Ensure that parliamentary and presidential elections take place in a\ntimely manner and in a free and secure environment without intimidation or attacks\nagainst candidates and activists, and guarantee women’s full and meaningful\nparticipation, as well as the participation of minorities, including by enforcing quotas;\n(k)    Ensure that women fully participate in the public life of Libya, free from\nintimidation, threats and attacks;\n(l)    Set out a plan for security sector reform so that the State remains the sole\nlegitimate holder of power in Libya."},{"id":"a-hrc-49-4-p0096","rec_id":"recVilmxHdPgkesVQ","symbol":"A/HRC/49/4","n":"96","seq":96,"section":"XVII. Recommendations","text":"The Mission additionally calls upon the members of the international community\nto:\n(a)   Support the Libyan people in strengthening unified and reformed law\nenforcement institutions under the supervision of an independent judiciary;\n(b)    Support independent national judicial and international accountability\nmechanisms for international crimes and human rights violations in Libya;\n(c)    Call upon receiving States to protect the rights of migrants, refugees and\nasylum seekers coming from Libya according to international human rights and refugee\nlaw obligations without discrimination;\n(d)    Exercise universal jurisdiction as a measure to bring to account\nperpetrators of international crimes in Libya;\n(e)   Support international monitoring of the preparations for parliamentary\nand presidential elections to ensure that such elections are conducted in a free and fair\nmanner and are free from human rights violations;\n(f)     Support the Mission’s fact-finding efforts regarding election-related\nviolations to ensure that free elections take place in Libya without intimidation or fear;\n(g)   Support the extension of the Mission’s mandate to effectively cover the\nviolations and abuses from 2016 and ongoing violations that may impair a future for\nLibya based on justice, national reconciliation, respect for human rights and the rule of\nlaw."},{"id":"a-hrc-49-4-p0097","rec_id":"recVilmxHdPgkesVQ","symbol":"A/HRC/49/4","n":"97","seq":97,"section":"XVII. Recommendations","text":"The Mission finally calls on the United Nations system to:\n(a)    Provide technical support and capacity-building to Libya to strengthen\nLibyan institutions, in particular the judiciary and, following their reform, law\nenforcement agencies;\n(b)    Support the strengthening of a Libyan national human rights institution\nto protect and promote human rights in compliance with the principles relating to the\nstatus of national institutions for the promotion and protection of human rights (the\nParis Principles) and independent from any political loyalty or interference;\n(c)    Support a victim-centred reconciliation process through a transitional\njustice approach that ensures accountability, reconciliation, reparation for victims,\ninstitutional and security sector reform, and guarantees of non-recurrence for\nviolations in Libya."},{"id":"a-hrc-52-83-u0000","rec_id":"recsvi26SYPBMJd3q","symbol":"A/HRC/52/83","n":null,"seq":0,"section":null,"text":"Summary\nThe present report is the final report by the Independent Fact-Finding Mission on\nLibya, which was requested by the Human Rights Council in its resolution 50/23. The\nMission was established to document, in an independent and impartial manner, alleged\nviolations and abuses of international human rights law and international humanitarian law\nby all parties in Libya since the beginning of 2016.\nThe Mission has found reasonable grounds to believe that crimes against humanity\nwere committed against Libyans and migrants throughout Libya in the context of deprivation\nof liberty. Notably, the Mission documented and made findings on numerous cases of, inter\nalia, arbitrary detention, murder, torture, rape, enslavement, sexual slavery, extrajudicial\nkilling and enforced disappearance, confirming their widespread practice in Libya.","unnumbered":true},{"id":"a-hrc-52-83-p0001","rec_id":"recsvi26SYPBMJd3q","symbol":"A/HRC/52/83","n":"1","seq":1,"section":"I. Introduction","text":"The present report is the final report by the Independent Fact-Finding Mission on\nLibya, which was requested by the Human Rights Council in its resolution 50/23. The\nMission was established pursuant to Council resolution 43/39, in which the United Nations\nHigh Commissioner for Human Rights was requested to designate experts to document, in\nan independent and impartial manner, alleged violations and abuses of international human\nrights law and international humanitarian law by all parties in Libya since the beginning of\n2016. Mohammad Auajjar, Tracy Robinson and Chaloka Beyani were appointed as experts.\nThe Mission previously presented three reports1 and a conference room paper on the situation\nin Tarhuna2 to the Council."},{"id":"a-hrc-52-83-p0002","rec_id":"recsvi26SYPBMJd3q","symbol":"A/HRC/52/83","n":"2","seq":2,"section":"I. Introduction","text":"Allegations of violations and abuses have rightly warranted the attention of the Human\nRights Council. Indeed, the Mission has found reasonable grounds to believe that since 2016\ncrimes against humanity have been committed against Libyans and migrants throughout\nLibya in the context of deprivation of liberty. Notably, the Mission documented and made\nfindings on numerous cases of, inter alia, arbitrary detention, murder, torture, rape,\nenslavement and enforced disappearance, confirming their widespread practice in Libya. In\nits assessment of evidence on the treatment of migrants, the Mission concluded that there\nwere reasonable grounds to believe that sexual slavery, as an additional underlying act of\ncrime against humanity, was committed against migrants. The State remains under an\nobligation to investigate allegations of human rights violations and crimes in areas under its\ncontrol in accordance with international standards."},{"id":"a-hrc-52-83-p0003","rec_id":"recsvi26SYPBMJd3q","symbol":"A/HRC/52/83","n":"3","seq":3,"section":"I. Introduction","text":"The rapid, deep and ongoing absorption of armed groups and their leadership into\nState-affiliated structures and institutions, including the Libyan Arab Armed Forces, and the\nspread of Salafist-leaning conservative ideologies are of significant concern to the Mission.3\nThe Mission found that State authorities and affiliated entities, such as the Deterrence\nApparatus for Combating Organized Crime and Terrorism, the Libyan Arab Armed Forces,\nthe Internal Security Agency, and the Stability Support Apparatus, and their leadership, were\nrepeatedly involved in violations and abuses arising in the context of detention. Persons were\ndetained for their actual or perceived sexual orientation and gender identity, criticism of the\nState and affiliated actors, and expression of divergent political, religious and social views\nand norms, including their opposition to patriarchy and sexism. Moreover, in the view of the\nMission, the practice of conservative Salafist-leaning ideologies compounded the shrinking\nof civic space."},{"id":"a-hrc-52-83-p0004","rec_id":"recsvi26SYPBMJd3q","symbol":"A/HRC/52/83","n":"4","seq":4,"section":"I. Introduction","text":"During its last mandate period, the Mission strengthened the factual evidence and\nlegal analysis of the involvement of States, groups and individuals in the violations and\nabuses that it documented. In this regard, the Mission found that crimes against humanity\nwere committed against migrants in places of detention under the actual or nominal control\nof Libya’s Directorate for Combating Illegal Migration, the Libyan Coast Guard and the\nStability Support Apparatus. These entities received technical, logistical and monetary\nsupport from the European Union and its member States for, inter alia, the interception and\nreturn of migrants."},{"id":"a-hrc-52-83-p0005","rec_id":"recsvi26SYPBMJd3q","symbol":"A/HRC/52/83","n":"5","seq":5,"section":"I. Introduction","text":"The violations and abuses investigated by the Mission were connected primarily to\nthe consolidation of power and wealth by militias and other State-affiliated groups through,\nfor instance, the misappropriation of public funds. It is beyond question that significant\nrevenue arising from the widescale exploitation of vulnerable irregular migrants incentivized\nthe continuation of the violations documented."},{"id":"a-hrc-52-83-p0006","rec_id":"recsvi26SYPBMJd3q","symbol":"A/HRC/52/83","n":"6","seq":6,"section":"I. Introduction","text":"The Mission’s mandate is ending when the human rights situation in Libya is\ndeteriorating, parallel State authorities are emerging and the legislative, executive and\nsecurity sector reforms needed to uphold the rule of law and unify the country are far from\nbeing realized. In this polarizing context, armed groups that have been implicated in\nallegations of torture, arbitrary detention, trafficking and sexual violence remain\nunaccountable."},{"id":"a-hrc-52-83-p0007","rec_id":"recsvi26SYPBMJd3q","symbol":"A/HRC/52/83","n":"7","seq":7,"section":"I. Introduction","text":"The practices and patterns of gross violations continue unabated, and there is little\nevidence that meaningful steps are being taken to reverse this troubling trajectory and bring\nrecourse to victims. The Mission calls on the Human Rights Council to establish a sufficiently\nresourced, independent international investigation mechanism. The Mission also calls on the\nOffice of the United Nations High Commissioner for Human Rights to establish a distinct\nand autonomous mechanism with an ongoing mandate to monitor and report on gross human\nrights violations in Libya, with a view to supporting Libyan reconciliation efforts and\nassisting the Libyan authorities in achieving transitional justice and accountability."},{"id":"a-hrc-52-83-p0008","rec_id":"recsvi26SYPBMJd3q","symbol":"A/HRC/52/83","n":"8","seq":8,"section":"A. Mandate and scope of the investigations","text":"The mandate of the Mission, as outlined in Human Rights Council resolution 43/39,\nis broad and general, encompassing all of the geographical area of Libya and violations and\nabuses of all types and degrees of gravity committed by any actors. The Mission has\ninterpreted its mandate to encompass violations and abuses of a continuing nature that\ncommenced before the beginning of 2016, such as enforced disappearance. It has also\ninterpreted its mandate to cover violations and abuses committed on the Libyan territory,\nincluding its territorial waters, and acts that were initiated outside the Libyan borders but\ncontinued within its territory.4"},{"id":"a-hrc-52-83-p0009","rec_id":"recsvi26SYPBMJd3q","symbol":"A/HRC/52/83","n":"9","seq":9,"section":"A. Mandate and scope of the investigations","text":"The Mission’s investigations were informed by three objective criteria: (a) the gravity\nand widespread or systematic nature of violations; (b) violations, abuses and crimes against\nvulnerable groups that are subjected to multiple forms of victimization; and (c) violations,\nabuses and crimes that especially hamper the transition of Libya to the rule of law and\ndemocratic elections. In keeping with Human Rights Council resolution 43/39, the Mission\nalso investigated sexual and gender-based violence and violations and abuses against women.\nParticular attention was given to the gendered dimensions of the violations and abuses\nidentified."},{"id":"a-hrc-52-83-p0010","rec_id":"recsvi26SYPBMJd3q","symbol":"A/HRC/52/83","n":"10","seq":10,"section":"A. Mandate and scope of the investigations","text":"The Human Rights Council recognized the need for accountability in Libya when it\nestablished the Mission.5 The Mission adopted a broad view of accountability and\nacknowledged victims’ rights to truth and effective remedy and guarantees of non-recurrence\nas essential components of human rights and transitional justice. The Mission also drew on\ninternational criminal law and compiled a list of individuals allegedly responsible for\ndocumented violations and abuses. The list will be deposited, as part of the Mission’s\nevidentiary holdings, with the United Nations High Commissioner for Human Rights."},{"id":"a-hrc-52-83-p0011","rec_id":"recsvi26SYPBMJd3q","symbol":"A/HRC/52/83","n":"11","seq":11,"section":"B. Methods of work and investigation activities","text":"Since its establishment, the Mission has carried out more than 400 interviews,\nprimarily with witnesses and victims, and collected more than 2,800 discrete items of\ninformation. A large proportion of the items was in the form of reports, meeting notes,\nlegislation, maps and photographic and audiovisual materials."},{"id":"a-hrc-52-83-p0012","rec_id":"recsvi26SYPBMJd3q","symbol":"A/HRC/52/83","n":"12","seq":12,"section":"B. Methods of work and investigation activities","text":"Investigation and reporting activities were guided by the Mission’s commitment to\nsafeguarding the well-being and safety of the individuals and groups with which it interacted,\nand Mission staff adhered scrupulously to the “do no harm” principle in all their activities.\nInvestigators arranged interviews and the transmission of information in safe places and over\nsecure platforms and referred victims to protection and assistance programmes as appropriate\nand when feasible."},{"id":"a-hrc-52-83-p0013","rec_id":"recsvi26SYPBMJd3q","symbol":"A/HRC/52/83","n":"13","seq":13,"section":"B. Methods of work and investigation activities","text":"The Mission did not interview persons unless they agreed to be interviewed, and it\nsought informed consent from sources to use and share their information in its reports and\nwith external stakeholders. The identities of victims and witnesses in the present report have\nbeen disclosed with their knowledge and after secondary consent was obtained."},{"id":"a-hrc-52-83-p0014","rec_id":"recsvi26SYPBMJd3q","symbol":"A/HRC/52/83","n":"14","seq":14,"section":"B. Methods of work and investigation activities","text":"The Mission undertook 13 missions, three of which were conducted during the last\nmandate extension period. The Mission went to Tripoli on six separate occasions 6 and to\nBenghazi on one occasion.7 One of the last missions was a lengthy investigative mission to\nTripoli, from 21 October to 21 November 2022. Investigators also travelled to Italy, Rwanda,\nMalta and the Netherlands,8 as well as to other countries."},{"id":"a-hrc-52-83-p0015","rec_id":"recsvi26SYPBMJd3q","symbol":"A/HRC/52/83","n":"15","seq":15,"section":"C. Standard of proof","text":"Consistent with most other United Nations fact-finding missions and commissions of\ninquiry, the Mission applied the “reasonable grounds to believe” evidentiary standard when\nmaking factual and legal determinations on patterns, incidents and cases. The standard was\ndeemed met when a reliable body of primary information was obtained that was corroborated\nby at least one other independent source, which could lead a reasonable and ordinarily\nprudent person to believe that the patterns, incidents and cases had occurred. At least one\ncredible first-hand source of information and one other independent and credible source of\ninformation were relied upon to verify individual incidents and cases contained in the present\nreport."},{"id":"a-hrc-52-83-p0016","rec_id":"recsvi26SYPBMJd3q","symbol":"A/HRC/52/83","n":"16","seq":16,"section":"C. Standard of proof","text":"The Mission found that the evidentiary standard was met with respect to violations\ninvolving torture, cruel, inhuman or degrading treatment, enforced disappearance, and sexual\nand gender-based violence, and the conditions in which those violations occurred, where\ndetailed, reliable and credible first-hand sources of information were corroborated by\nevidence establishing patterns of similar incidents in the area of investigation."},{"id":"a-hrc-52-83-p0017","rec_id":"recsvi26SYPBMJd3q","symbol":"A/HRC/52/83","n":"17","seq":17,"section":"C. Standard of proof","text":"The Mission identified patterns based on several pieces of first-hand evidence that\nwere consistent with and corroborated by the overall body of evidence collected. The Mission\ndiscerned patterns from suspected perpetrators, time-periods, localities, victim profiles, modi\noperandi and motives."},{"id":"a-hrc-52-83-p0018","rec_id":"recsvi26SYPBMJd3q","symbol":"A/HRC/52/83","n":"18","seq":18,"section":"C. Standard of proof","text":"Unlike the criminal standard of proof, the reasonable grounds basis does not require\nthe Mission to make findings to the exclusion of all other reasonable inferences. Considering\nthe stigma attached to the violations and abuses documented, the public nature of its work\nand the presumption of innocence, the Mission resorted to the higher evidentiary standard of\nbalance of probabilities when compiling its list of allegedly responsible individuals."},{"id":"a-hrc-52-83-p0019","rec_id":"recsvi26SYPBMJd3q","symbol":"A/HRC/52/83","n":"19","seq":19,"section":"D. Challenges and cooperation with authorities in Libya","text":"The Mission did its utmost to discharge its mandate fully, but was confronted with a\nmyriad of resource-, access- and security-related challenges that inadvertently impeded the\nscope and continuity of the its work. These challenges arose from the time of the decision to\nestablish and dispatch the Mission and continued until the end of its mandate."},{"id":"a-hrc-52-83-p0020","rec_id":"recsvi26SYPBMJd3q","symbol":"A/HRC/52/83","n":"20","seq":20,"section":"D. Challenges and cooperation with authorities in Libya","text":"In its resolution 43/39 of 22 June 2020, the Human Rights Council requested the\nUnited Nations High Commissioner for Human Rights to establish and dispatch a fact-\nfinding mission on Libya, but the coronavirus disease (COVID-19) pandemic, the United\nNations budgetary liquidity crisis and a suspension of recruitment delayed the formation of\nthe Mission secretariat and the commencement of investigations. The secretariat became fully\noperational in June 2021. While the intention was to recruit 18 staff members for the\nsecretariat, it was composed of less than 10 staff members for lengthy periods of time and\nsuffered a chronic shortage of investigators during critical stages of the investigation."},{"id":"a-hrc-52-83-p0021","rec_id":"recsvi26SYPBMJd3q","symbol":"A/HRC/52/83","n":"21","seq":21,"section":"D. Challenges and cooperation with authorities in Libya","text":"The Mission’s endeavours to base its investigation team in Libya proved unfeasible\nowing to limited United Nations accommodation in Libya and security challenges,9 and\naccess to Libyan territory depended upon the cooperation of numerous authorities in Libya.\nWhile cooperation with authorities in Libya improved, the Mission struggled to obtain the\npermissions necessary to gain unhindered access to all parts of the Libyan territory, without\ndelay.10"},{"id":"a-hrc-52-83-p0022","rec_id":"recsvi26SYPBMJd3q","symbol":"A/HRC/52/83","n":"22","seq":22,"section":"D. Challenges and cooperation with authorities in Libya","text":"The Libyan Arab Armed Forces did not grant the Mission’s requests to visit areas of\nsouthern Libya (Fazzan) under its control. In May 2022, the Government of National Unity\ndenied the Mission permission to depart from Tripoli to enter the areas of southern Libya\nunder the control of the Libyan Arab Armed Forces, and the Libyan Arab Armed Forces\ndenied it authorization to access Sabha. Both authorities cited security concerns. In October\n2022, the Libyan Arab Armed Forces withdrew the authorization to access Sabha that the\nMission had received after significant delay. The Mission sent an official letter to the Libyan\nArab Armed Forces protesting the withdrawal of authorization, but never received a reply."},{"id":"a-hrc-52-83-p0023","rec_id":"recsvi26SYPBMJd3q","symbol":"A/HRC/52/83","n":"23","seq":23,"section":"D. Challenges and cooperation with authorities in Libya","text":"The Mission submitted several requests to the Presidential Council of the Government\nof National Unity, the Ministry of the Interior, the Ministry of Justice, the Ministry of Social\nAffairs and the Ministry of Public Health, to visit prisons and places where persons were\ndeprived of their liberties. The Mission did not receive official responses to its requests."},{"id":"a-hrc-52-83-p0024","rec_id":"recsvi26SYPBMJd3q","symbol":"A/HRC/52/83","n":"24","seq":24,"section":"D. Challenges and cooperation with authorities in Libya","text":"Despite the calls by the Human Rights Council for the Libyan authorities to allow the\nmembers of the Mission to meet and speak freely and privately, when they so request, with\nwhomever they wish to meet or speak with, the climate of fear surrounding witnesses and\ncivil society frequently hampered the Mission’s engagements. There were instances when\ngroups and individuals declined to meet with the Mission in particular locations, or at all,\nbecause of the fear of reprisal."},{"id":"a-hrc-52-83-p0025","rec_id":"recsvi26SYPBMJd3q","symbol":"A/HRC/52/83","n":"25","seq":25,"section":"A. Conduct of hostilities and armed clashes","text":"The Mission investigated violations allegedly committed in and around Murzuq in the\nmonths of February, March and August 2019 against the backdrop of a Libyan Arab Armed\nForces military operation supported by affiliated armed groups and resisted by local armed\nforces that allegedly received support from the Government of National Accord. The declared\nobjective of the operation was to restore stability and cleanse southern Libya of purported\nterrorists and criminals. The Tebu were in control of the Murzuq city administration at the\ntime of the launch of the operation, and the situation between the al-Ahali and Tebu\ncommunities in southern Libya had been tense since 2011."},{"id":"a-hrc-52-83-p0026","rec_id":"recsvi26SYPBMJd3q","symbol":"A/HRC/52/83","n":"26","seq":26,"section":"A. Conduct of hostilities and armed clashes","text":"The Mission found reasonable grounds to believe that during the military operation\nand ensuing violence, acts were committed that amount to human rights violations and may\npotentially constitute war crimes as violations of international humanitarian law. These\ninclude incidents of killing, corpse desecration, enforced disappearance, pillaging and\ndestruction of civilian objects."},{"id":"a-hrc-52-83-p0027","rec_id":"recsvi26SYPBMJd3q","symbol":"A/HRC/52/83","n":"27","seq":27,"section":"A. Conduct of hostilities and armed clashes","text":"On 1 February 2019, Libyan Arab Armed Forces and affiliated armed groups,\nincluding the Tariq Bin Ziyad Brigade and the 128th battalion with members of the Awlad\nSulayman and Zway communities, advanced from Sabha towards Murzuq. For over 20 days,\nthe Tebu-led South Protection Force, formed in February 2019, fought the advance of the\nLibyan Arab Armed Forces and its affiliated groups on the city of Ghudwa. After a first and\nfailed attempt to enter Murzuq City on 21 February, the Libyan Arab Armed Forces\nestablished control over Murzuq on 23 February 2019, and the situation reportedly stabilized\ntemporarily."},{"id":"a-hrc-52-83-p0028","rec_id":"recsvi26SYPBMJd3q","symbol":"A/HRC/52/83","n":"28","seq":28,"section":"A. Conduct of hostilities and armed clashes","text":"Evidence obtained by the Mission established that there were reasonable grounds to\nbelieve that the Libyan Arab Armed Forces and its affiliated groups killed members of the\nTebu community in February 2019 and that fighting triggered displacements. The Mission\nwas, however, not in a position to verify the exact number of casualties and the circumstances\nof the deaths. Video footage dated 18 March 2019 shows eight dead bodies, two of them\nhandcuffed, of alleged Tebu members off a main road approximately six kilometres north of\nMurzuq City. The Mission also found that a member of the local police, the Security Director\nof Murzuq, was a victim of extrajudicial killing."},{"id":"a-hrc-52-83-p0029","rec_id":"recsvi26SYPBMJd3q","symbol":"A/HRC/52/83","n":"29","seq":29,"section":"A. Conduct of hostilities and armed clashes","text":"The Mission found that Tebu homes and properties, including hundreds of cars, were\ndestroyed and looted in the first days of the entry of the Libyan Arab Armed Forces and its\naffiliated groups into Murzuq. Furthermore, the Mission established that a minimum of 10\nmembers of the Tebu community had disappeared in or around the month of February."},{"id":"a-hrc-52-83-p0030","rec_id":"recsvi26SYPBMJd3q","symbol":"A/HRC/52/83","n":"30","seq":30,"section":"A. Conduct of hostilities and armed clashes","text":"The Libyan Arab Armed Forces moved towards Tripoli in March 2019, where they\njoined the military campaign to seize the capital of the country, which was controlled by the\nGovernment of National Accord. Following withdrawal by the Libyan Arab Armed Forces,\nmembers of the Tebu community gradually returned to Murzuq."},{"id":"a-hrc-52-83-p0031","rec_id":"recsvi26SYPBMJd3q","symbol":"A/HRC/52/83","n":"31","seq":31,"section":"A. Conduct of hostilities and armed clashes","text":"The Mission found reasonable grounds to believe that, on 8 March 2019, two children,\naged 5 and 14, from the al-Ahali community were killed by gunshots to the head in the\npresence of their relatives in a family home in Murzuq. According to the evidence, Tebu men\nkilled the children because their father was fighting for the Libyan Arab Armed Forces."},{"id":"a-hrc-52-83-p0032","rec_id":"recsvi26SYPBMJd3q","symbol":"A/HRC/52/83","n":"32","seq":32,"section":"A. Conduct of hostilities and armed clashes","text":"Fighting between al-Ahali and Tebu communities intensified in August 2019. Reports\nindicate that more than 90 civilians were killed and 200 were injured in Murzuq. There was\nlarge-scale destruction, with approximately 60 apartments reportedly burned down and\nlooted in the al-Daman neighbourhood. Witnesses described how Murzuq became a ghost\ntown. By 20 August, a total of 1,890 families from Murzuq had been displaced."},{"id":"a-hrc-52-83-p0033","rec_id":"recsvi26SYPBMJd3q","symbol":"A/HRC/52/83","n":"33","seq":33,"section":"A. Conduct of hostilities and armed clashes","text":"The Mission found reasonable grounds to believe that, on 1 August 2019, a Tebu taxi\ndriver was found dead in a burned car. He was tied and significant parts of his body were\ncharred. The burning of the body was described as “the highest insult to the deceased and his\nfamily in Tebu traditions”. The Mission also collected evidence on a separate but similar\nincident of a Tebu man found burned to death in a car, with his hands tied, in early August\n2019."},{"id":"a-hrc-52-83-p0034","rec_id":"recsvi26SYPBMJd3q","symbol":"A/HRC/52/83","n":"34","seq":34,"section":"A. Conduct of hostilities and armed clashes","text":"There were also killings, disappearances and abductions of al-Ahali members during\nthis period. The Mission received reports of 21 cases of alleged disappearances and\nabductions, mostly in August. These included the cases of at least two al-Ahali men in their\nseventies who were allegedly abducted by the South Protection Force and disappeared. The\nMission also found reasonable grounds to believe that on 7 August, a civilian from the al-\nAhali community was shot in his car in front of his wife and children at a checkpoint.\nAccording to witnesses, the 13-year-old son jumped on his father’s dead body, took over the\nsteering wheel and drove family members to safety. The Mission found reasonable grounds\nto believe that the father’s right to life was violated and that he may be a victim of murder as\na war crime.\nArmed clashes in Tripoli"},{"id":"a-hrc-52-83-p0035","rec_id":"recsvi26SYPBMJd3q","symbol":"A/HRC/52/83","n":"35","seq":35,"section":"A. Conduct of hostilities and armed clashes","text":"On or around 27 August 2022, armed clashes erupted in Tripoli, including in civilian\npopulated areas. Fathi Ali Bashagha reiterated his intention to enter the Tripoli and his call\nfor Abdul Hamid Dbeibha to peacefully hand over power. The Government of National Unity\ndeclared a state of emergency in Tripoli and mobilized armed forces."},{"id":"a-hrc-52-83-p0036","rec_id":"recsvi26SYPBMJd3q","symbol":"A/HRC/52/83","n":"36","seq":36,"section":"A. Conduct of hostilities and armed clashes","text":"Armed groups employed medium to heavy weaponry during the fighting, some of\nwhich took place near civilian hospitals. Medical facilities were reportedly damaged during\nthe clashes, and one witness informed the Mission that medical personnel were not able to\nreach civilians in need of medical attention safely. The Mission also received reports of\ndamage to at least one cultural site. Such acts, which entail a risk to the lives of civilians and\nthe medical personnel and facilities that are indispensable for the survival of the civilian\npopulation, may amount to violations of the right to life.\nMercenaries and landmines"},{"id":"a-hrc-52-83-p0037","rec_id":"recsvi26SYPBMJd3q","symbol":"A/HRC/52/83","n":"37","seq":37,"section":"A. Conduct of hostilities and armed clashes","text":"The Mission investigated violations allegedly committed by mercenaries and foreign\nfighters from Chad, the Russian Federation, the Sudan, the Syrian Arab Republic and other\ncountries. The evidence collected by the Mission allowed it to make findings in relation to\nallegations of international law violations by Wagner Group agents in southern Tripoli during\nthe armed conflict in 2019 and 2020. The evidence demonstrated a heavier than initially\ncalculated contamination of unexploded Russian-made ordnance and commonly used\nWagner landmines and other military explosives in manifestly civilian areas of southern\nTripoli between May and July 2020. The Mission also confirmed the placement of military\nexplosives in homes, inside sofas and bathroom fixtures, for example, and other civilian\nareas, which led to death and injury of civilians. Investigations reinforced the Mission’s\nprevious finding that Wagner personnel may have violated the international law principle of\nproportionality and the obligation to minimize the indiscriminate effects of mines and other\nexplosives. By not clearing the ordnance, Wagner personnel and the Libyan Arab Armed\nForces may also have violated the right to life. In addition, the use of mercenaries by Wagner\nGroup agents in Libya may constitute the crime of mercenarism under the 1977 Organization\nof African Unity Convention for the elimination of mercenarism in Africa, to which Libya is\na State party."},{"id":"a-hrc-52-83-p0038","rec_id":"recsvi26SYPBMJd3q","symbol":"A/HRC/52/83","n":"38","seq":38,"section":"A. Conduct of hostilities and armed clashes","text":"The Mission interviewed a victim whose family members were unlawfully arrested\nand detained after Wagner forces entered their home in southern Tripoli. After being held for\napproximately 24 hours at various nearby locations, where they were subjected to various\nforms of physical and psychological abuse, Wagner fighters summarily executed by gunfire\nthree members of the victim’s family and maimed a brother. The victim pretended to have\nbeen shot and killed. The Mission found reasonable grounds to believe that the Wagner\nfighters involved in this case committed the war crimes of murder, torture and cruel\ntreatment.\nAirstrike on the Tripoli military academy"},{"id":"a-hrc-52-83-p0039","rec_id":"recsvi26SYPBMJd3q","symbol":"A/HRC/52/83","n":"39","seq":39,"section":"A. Conduct of hostilities and armed clashes","text":"The Mission continued to investigate the airstrike on the military academy in\nHadabah, Tripoli.11 It found reasonable grounds to believe that academy students were not\ntaking a direct part in the hostilities, that they were protected from attack and that the attack\non the Academy amounted to a serious violation of international humanitarian law and a war\ncrime. Further investigation is necessary to identify those responsible for the attack.\nB.        Migrants12"},{"id":"a-hrc-52-83-p0040","rec_id":"recsvi26SYPBMJd3q","symbol":"A/HRC/52/83","n":"40","seq":40,"section":"A. Conduct of hostilities and armed clashes","text":"More than 670,000 migrants from over 41 countries were present in Libya during the\nlast mandate extension period, and the number of migrants in Libya has been increasing since\n2021.13 Libya serves as a point of departure and transit country for many of those bound for\nEurope. All the migrants interviewed shared similar accounts of an abhorrent cycle of\nviolence. The cycle started with the migrants’ entry into Libya, often with the involvement\nof smugglers, and led to their capture, recapture and repeated transfers to official or unofficial\nplaces of detention without recourse to judicial review. Racial discrimination against\nmigrants was a persistent undercurrent throughout the cases documented by the Mission."},{"id":"a-hrc-52-83-p0041","rec_id":"recsvi26SYPBMJd3q","symbol":"A/HRC/52/83","n":"41","seq":41,"section":"A. Conduct of hostilities and armed clashes","text":"The Mission interviewed more than 100 migrants over the course of its investigations,\nincluding in cases of alleged trafficking and deprivation of liberty for ransom in connection\nwith smuggling and trafficking. The Mission established, on the basis of this evidence, that\nthere are reasonable grounds to believe that migrants across Libya are victims of crimes\nagainst humanity and that acts of murder, enforced disappearance, torture, enslavement,\nsexual violence, rape and other inhumane acts are committed in connection with their\narbitrary detention.14 The Mission also concluded a holistic assessment of all the evidence\ncollected and found reasonable grounds to believe that the crime against humanity of sexual\nslavery, previously unreported by the Mission, had been committed in the trafficking hubs of\nBani Walid and Sabratah during the Mission’s mandate."},{"id":"a-hrc-52-83-p0042","rec_id":"recsvi26SYPBMJd3q","symbol":"A/HRC/52/83","n":"42","seq":42,"section":"A. Conduct of hostilities and armed clashes","text":"The cases investigated by the Mission during the reporting period confirmed that there\nwere reasonable grounds to believe that the underlying acts of crimes against humanity were\ncommitted in detention centres of the Directorate for Combating Illegal Migration in Tariq\nal-Matar, Abu Salim, Ayn Zarah, Abu Isa, Gharyan, Tariq al-Sikka, Mabani, Salah al-Din\nand Zawiyah, as well as non-official places of detention in al-Shwarif, Bani Walid, Sabratah,\nZuwarah and Sabha. The Mission identified a particularly significant role played by the\nStability Support Apparatus in crimes against humanity through their cooperation with the\nLibyan Coast Guard in Zawiyah and their control of the detention centres of Abu Salim and\nAyn Zarah."},{"id":"a-hrc-52-83-p0043","rec_id":"recsvi26SYPBMJd3q","symbol":"A/HRC/52/83","n":"43","seq":43,"section":"A. Conduct of hostilities and armed clashes","text":"The Directorate for Combating Illegal Migration is the official entity of the Libyan\nMinistry of the Interior responsible for migrant detention centres across Libya. The Council\nof Ministers of the Government of National Unity appointed Mohamed al-Khoja, the head of\nthe al-Khoja militia and Tariq al-Sikka detention centre, as head of the Directorate for\nCombatting Illegal Migration in January 2022. The Stability Support Apparatus was\nestablished in January 2021 by the Presidential Council. It is made up of an alliance of armed\ngroups and is led by militia leader Abdel Ghani al-Kikli, also known as “Ghneiwa”."},{"id":"a-hrc-52-83-p0044","rec_id":"recsvi26SYPBMJd3q","symbol":"A/HRC/52/83","n":"44","seq":44,"section":"A. Conduct of hostilities and armed clashes","text":"The ongoing, systematic and widespread character of the crimes documented by the\nMission strongly suggests that personnel and officials of the Directorate for Combating\nIllegal Migration, at all levels, are implicated. In addition, the Mission found reasonable\ngrounds to believe that high-ranking staff of the Libyan Coast Guard, the Stability Support\nApparatus and the Directorate for Combating Illegal Migration colluded with traffickers and\nsmugglers, which are reportedly connected to militia groups,15 in the context of the\ninterception and deprivation of liberty of migrants. The Mission also found reasonable\ngrounds to believe that guards demanded and received payment for the release of migrants.\nTrafficking, enslavement, forced labour, imprisonment, extortion and smuggling generated\nsignificant revenue for individuals, groups and State institutions."},{"id":"a-hrc-52-83-p0045","rec_id":"recsvi26SYPBMJd3q","symbol":"A/HRC/52/83","n":"45","seq":45,"section":"A. Conduct of hostilities and armed clashes","text":"The Mission also collected evidence of collusion between the Libyan Coast Guard\nand those in charge of al-Nasr detention centre in Zawiyah. Abd al-Rahman al-Milad, also\nknown as “Bija”, the head of the regional unit of the Libyan Coast Guard in Zawiyah, is on\nthe Security Council sanctions list for involvement in trafficking and smuggling. 16"},{"id":"a-hrc-52-83-p0046","rec_id":"recsvi26SYPBMJd3q","symbol":"A/HRC/52/83","n":"46","seq":46,"section":"A. Conduct of hostilities and armed clashes","text":"Libyan authorities, including the Directorate for Combating Illegal Migration, the\nLibyan Coast Guard and the Stability Support Apparatus, and third States have been on notice\nfor years regarding the ongoing widespread and systematic attacks on migrants, including\nviolations occurring at sea, in detention centres, along trafficking and smuggling routes and\nin trafficking hubs.17 Nonetheless, in accordance with memorandums of understanding\nbetween Libya and third States, the Libyan authorities have continued their policy of\nintercepting and returning migrants to Libya, where their mistreatment resumes. Based on\nthe substantial evidence and reports before it, the Mission has grounds to believe that the\nEuropean Union and its member States, directly or indirectly, provided monetary and\ntechnical support and equipment, such as boats, to the Libyan Coast Guard and the\nDirectorate for Combating Illegal Migration that was used in the context of interception and\ndetention of migrants."},{"id":"a-hrc-52-83-p0047","rec_id":"recsvi26SYPBMJd3q","symbol":"A/HRC/52/83","n":"47","seq":47,"section":"A. Conduct of hostilities and armed clashes","text":"Interviewees that escaped captivity and attempted to reach Europe eventually tried to\ncross the Mediterranean Sea. In the words of one migrant that was held in Maya, Ayn Zarah\nand Gharyan detention centres, “our concern is not dying in the water, but our concern is to\ngo back to the prison where we will be oppressed and tortured by guards”. Immigration\ncontrol by Libya and European States must be exercised consistent with their international\nlaw obligations, especially the principle of non-refoulement, and in accordance with the\nGlobal Compact for Safe, Orderly and Regular Migration.\nTorture"},{"id":"a-hrc-52-83-p0048","rec_id":"recsvi26SYPBMJd3q","symbol":"A/HRC/52/83","n":"48","seq":48,"section":"A. Conduct of hostilities and armed clashes","text":"There is overwhelming evidence that migrants were systematically tortured in\ndetention centres under the nominal or actual control of the Directorate for Combating Illegal\nMigration, including Tariq al-Matar, Tariq al-Sikka, Abu Isa and Gharyan. The Mission also\nfound evidence of torture in trafficking hubs in Bani Walid and Sabratha. The appalling\nmistreatment of migrants resulted in long-term physical and emotional harm."},{"id":"a-hrc-52-83-p0049","rec_id":"recsvi26SYPBMJd3q","symbol":"A/HRC/52/83","n":"49","seq":49,"section":"A. Conduct of hostilities and armed clashes","text":"Suicides among migrants, which can be an indication of torture, were reported to the\nMission. In one incident documented, a boy, allegedly tortured and suffering from severe\nheadaches, hung himself in Ayn Zarah. His lifeless body was left hanging in front of other\nmigrants for at least one and a half days before it was taken down. A witness said that guards\nordered them not to take photos.\nRape"},{"id":"a-hrc-52-83-p0050","rec_id":"recsvi26SYPBMJd3q","symbol":"A/HRC/52/83","n":"50","seq":50,"section":"A. Conduct of hostilities and armed clashes","text":"The Mission spoke to numerous survivors and witnesses of rape. It found, on this\nbasis, reasonable grounds to believe that rape as a crime against humanity was committed in\nplaces of detention in Mabani, al-Shwarif, Zuwarah, Sabratha, Sabha and Bani Walid.\nMigrants were routinely raped, with one male witness describing how, “during the nights,\nthe guards [of Bani Walid] come in the dark with the torch and approach the ladies, pick any\nand rape her. They order us to sleep and cover ourselves with the mattress as they take the\nlady away”. Pregnancies are a commonplace outcome of rape, and migrants reported having\nseen women give birth in detention without professional medical support."},{"id":"a-hrc-52-83-p0051","rec_id":"recsvi26SYPBMJd3q","symbol":"A/HRC/52/83","n":"51","seq":51,"section":"A. Conduct of hostilities and armed clashes","text":"Migrant survivors faced insurmountable challenges in accessing safe and adequate\nsexual and reproductive health services and assistance programmes that could offer them\nprotection and address the harm inflicted and consequential pregnancies and births. Since the\nirregular entry and stay of migrants is criminalized in Libya, migrant survivors risk\nprosecution and punishment if they approach Libyan authorities and medical facilities.\nEnslavement, including sexual slavery"},{"id":"a-hrc-52-83-p0052","rec_id":"recsvi26SYPBMJd3q","symbol":"A/HRC/52/83","n":"52","seq":52,"section":"A. Conduct of hostilities and armed clashes","text":"There are reasonable grounds to believe that migrants were enslaved in detention\ncentres of the Directorate for Combatting Illegal Migration in Abu Salim, Zawiyah and\nMabani, as well as in places of detention in al-Shwarif, Bani Walid, Sabratah, Zuwarah and\nSabha. The Mission considered that enslavement, including sexual slavery, had occurred\nwhen, for example, there was an element of ownership or there were actions imposing a\nsimilar deprivation of liberty. The Mission found that sexual slavery was committed in\nSabratah and Bani Walid.\nOther inhumane acts, including starvation"},{"id":"a-hrc-52-83-p0053","rec_id":"recsvi26SYPBMJd3q","symbol":"A/HRC/52/83","n":"53","seq":53,"section":"A. Conduct of hostilities and armed clashes","text":"Migrants were held in inhumane conditions and severely mistreated in centres of the\nDirectorate for Combatting Illegal Migration and by traffickers. An overwhelming number\nof migrants testified to the lack of mattresses and sleeping accommodations, overcrowding,\na severe shortage of lavatories, the continued presence of crawling insects such as lice,\ninadequate quantities and quality of food and water, and the lack of medical care. Migrants\nthat spoke with the Mission described how migrants were often starved in places of detention."},{"id":"a-hrc-52-83-p0054","rec_id":"recsvi26SYPBMJd3q","symbol":"A/HRC/52/83","n":"54","seq":54,"section":"C. Enforced disappearance","text":"Enforced disappearance is a particularly egregious violation of international human\nrights law, which may constitute a crime against humanity. Enforced disappearance places\nthe direct victim outside the protection of the law and victimizes family members of the\nvictim. Cases investigated by the Mission confirmed that enforced disappearances frequently\noccur in the Libyan context alongside arbitrary detention."},{"id":"a-hrc-52-83-p0055","rec_id":"recsvi26SYPBMJd3q","symbol":"A/HRC/52/83","n":"55","seq":55,"section":"C. Enforced disappearance","text":"The Mission found that, during the temporal scope of its mandate, persons were\nsubjected to enforced disappearance in Libya by, or through affiliated armed groups of, the\nGovernment of National Unity led by Abdul Hamid Dbeibah and the Libyan Arab Armed\nForces led by Khalifa Haftar. Notably, the Mission documented during the last mandate\nperiod the abduction, enforced disappearance and arbitrary detention of three men in the\nLibyan Arab Armed Forces-controlled Gernada prison. The Mission found reasonable\ngrounds to believe that they were victims of imprisonment, enforced disappearance and other\ninhuman acts, as crimes against humanity in connection with the exercise of their freedom of\nexpression. These cases reinforced the Mission’s previous finding that crimes against\nhumanity have been committed in Gernada prison “to repress freedom of expression, thought\nand association with the aim to silence ideological opponents, journalists, activists and actual\nor perceived critics of the [Libyan National Army]”.18"},{"id":"a-hrc-52-83-p0056","rec_id":"recsvi26SYPBMJd3q","symbol":"A/HRC/52/83","n":"56","seq":56,"section":"C. Enforced disappearance","text":"Two of the cases concerned Ahmed Mustafa and Ali Omar, known as Ali Alaspli,\nwho are both online critics of leaders of the Libyan Arab Armed Forces in eastern Libya. The\nmen were taken by armed members of the Libyan Arab Armed Forces under coercive\ncircumstances on related occasions in March 2016. They were held captive in the home of\nthen-Libyan National Army commander Ahmad al-Ghourour for three nights before they\nwere taken to Gernada prison and placed in solitary confinement in a secret wing that was\nreportedly guarded by men that subscribed to the Madkhali-Salafist ideology. The victims\nwere beaten and were not provided with sufficient food or basic amenities. Family members\nwere informed of the detainees’ whereabouts after approximately three months. The men\nwere released after four months in detention."},{"id":"a-hrc-52-83-p0057","rec_id":"recsvi26SYPBMJd3q","symbol":"A/HRC/52/83","n":"57","seq":57,"section":"C. Enforced disappearance","text":"The Mission also documented the enforced disappearance of persons because of their\nplace of origin and family links. In an incident investigated by the Mission, armed men\nsearching for individuals from eastern Libya at a café in Tripoli abducted approximately six\nmen. The Mission found that at least one of the victims from eastern Libya was taken to\nMitiga airport, where he was interrogated about other persons from eastern Libya living in\nTripoli and tortured over a two-day period. The victim was shackled and hung upside down,\nin the so-called balanco position, his hair was burnt with a lighter and his reproductive organs\nwere hit and squeezed with pliers. The victim was subsequently transferred to a prison within\nthe Mitiga airport complex, where the cruel and inhuman treatment continued. The victim\nwas held incommunicado until 2017. He was only permitted to call his family one year and\n10 months after his abduction from the café. His father, who had inquired about the victim\nand filed complaints about his disappearance, died before his son could contact the family.\nThere are reasonable grounds to believe that the victim was subjected to enforced\ndisappearance for close to two years and arbitrary detention for seven years, as crimes against\nhumanity. The victim was released from Mitiga prison in 2022."},{"id":"a-hrc-52-83-p0058","rec_id":"recsvi26SYPBMJd3q","symbol":"A/HRC/52/83","n":"58","seq":58,"section":"C. Enforced disappearance","text":"The Mitiga airport complex, including places of detention located therein, remains\nunder Radaa’s control. Radaa is an armed group that was formally integrated into the\nDeterrence Apparatus for Combating Organized Crime and Terrorism by decision of the\nPresidential Council of the Government of National Accord in 2018.19 The Deterrence\nApparatus for Combating Organized Crime and Terrorism was reorganized by decision of\nthe Government of National Accord in 2020.20"},{"id":"a-hrc-52-83-p0059","rec_id":"recsvi26SYPBMJd3q","symbol":"A/HRC/52/83","n":"59","seq":59,"section":"C. Enforced disappearance","text":"The Mission reported in 2022 on several incidents of the crime against humanity of\nenforced disappearance in Tarhuna.21 The Mission made a new legal finding on crimes\nagainst humanity in Tarhuna in the case of Zahra Maatouq. Ms. Maatouq was summoned in\nDecember 2019 to the Tarhuna police station to provide proof of her husband’s identity. He\nhad been taken from their home days earlier. According to witnesses, Ms. Maatouq met her\nhusband at the police station but appeared shaken in her last communication with her family.\nMs. Maatouq’s body was exhumed from a mass grave in 2020. It is established that she died\nfrom gunshot wounds to the head, torso and pelvis. The Mission found reasonable grounds\nto believe that Ms. Maatouq was a victim of enforced disappearance as a crime against\nhumanity and murder as a crime against humanity and a war crime."},{"id":"a-hrc-52-83-p0060","rec_id":"recsvi26SYPBMJd3q","symbol":"A/HRC/52/83","n":"60","seq":60,"section":"D. Violations in the context of deprivation of liberty","text":"The pervasive and widespread deprivation of liberty inflicted on Libyans and other\nnon-migrants in detention centres across the country has been a fixture of all the Mission’s\nreports. Since its establishment, the Mission has conducted over 134 interviews with current\nand former detainees, their relatives, insider witnesses and other individuals with respect to\nover 41 detention sites throughout Libya. The Mission also obtained large amounts of\ncorroborating and other pieces of evidence regarding violations of international law occurring\nat those detention centres, including “secret prisons”. The Government placed the total\nnumber of detainees at 18,523, but evidence collected by the Mission indicated that the true\nnumber of individuals arbitrarily detained is likely much higher."},{"id":"a-hrc-52-83-p0061","rec_id":"recsvi26SYPBMJd3q","symbol":"A/HRC/52/83","n":"61","seq":61,"section":"D. Violations in the context of deprivation of liberty","text":"In its final mandate period, the Mission substantiated its prior finding that there are\nreasonable grounds to believe that the crimes against humanity of murder, torture,\nimprisonment, rape, enforced disappearance and other inhumane acts have been committed\nin several places of detention in western, eastern and southern Libya since 2016. The Mission\ndocumented a prevalence of the underlying acts of crimes against humanity in Mitiga\ndetention complex in Tripoli, which is controlled by Radaa, in al-Kwaifiya and Gernada\nprisons, which are run by the Libyan Arab Armed Forces, and in detention centres under\nStability Support Apparatus control."},{"id":"a-hrc-52-83-p0062","rec_id":"recsvi26SYPBMJd3q","symbol":"A/HRC/52/83","n":"62","seq":62,"section":"D. Violations in the context of deprivation of liberty","text":"The victims of detention-related violations and abuse came from every segment of\nLibyan society and included children, adult men and women, human rights defenders,\npolitical participants, civil society representatives, members of military or security forces,\nlegal professionals and persons of perceived or actual diverse sexual orientations and gender\nidentities. Nearly all of the victims and witnesses the Mission interviewed were never\nconfronted with the evidence against them and were held without charge. As detailed in prior\nMission reports, the conditions of detention throughout Libyan detention centres were\npersistently deplorable, with detainees subjected regularly to torture and solitary confinement\nand held incommunicado. Detainees were also denied adequate access to water, food, toilets,\nsanitation, light, exercise, medical care, legal counsel and communication with family\nmembers."},{"id":"a-hrc-52-83-p0063","rec_id":"recsvi26SYPBMJd3q","symbol":"A/HRC/52/83","n":"63","seq":63,"section":"D. Violations in the context of deprivation of liberty","text":"Detainees have been subjected to systematic torture, in particular in detention centres\nwithin the Mitiga airport complex. According to one detainee held there for more than three\nyears, detainees were “onboarded” in a “room resembling a hospital for the insane, where\nbeating is mandatory […] and blood flows”. The victim was never charged of a crime and no\ninvestigation was opened into his arbitrary detention."},{"id":"a-hrc-52-83-p0064","rec_id":"recsvi26SYPBMJd3q","symbol":"A/HRC/52/83","n":"64","seq":64,"section":"D. Violations in the context of deprivation of liberty","text":"The Mission investigated the arbitrary detention of Abdul Hakim al-Mashri in a\nMitiga detention centre since his illegal abduction on 16 October 2016 under vague\nallegations of being affiliated with Da’esh. Such accusations were common against people\nfrom Sirte, and the victim has never been confronted with evidence supporting this allegation.\nA witness explained that his family waited in line for upwards of 14 hours to speak with the\nvictim."},{"id":"a-hrc-52-83-p0065","rec_id":"recsvi26SYPBMJd3q","symbol":"A/HRC/52/83","n":"65","seq":65,"section":"D. Violations in the context of deprivation of liberty","text":"In another similar case, a colonel in the Libyan army, Osama Muhammad Salih al-\nGhafir, was arrested and detained on 7 December 2016 near Sidrah by Libyan Arab Armed\nForces. He appeared as a prisoner on the Libya Alhadath television channel at the time of his\narrest. A family member met with an eyewitness who told him that he saw Colonel al-Ghafir\nin a prison operated by Tariq Bin Ziyad Brigade in early 2017 in the Sidi Faraj area near\nBenghazi. He was stripped of his clothes and tortured outside in the rain and thereafter\ndragged by a car. Colonel al-Ghafir’s whereabouts remain unconfirmed."},{"id":"a-hrc-52-83-p0066","rec_id":"recsvi26SYPBMJd3q","symbol":"A/HRC/52/83","n":"66","seq":66,"section":"D. Violations in the context of deprivation of liberty","text":"The Mission collected compelling evidence of families of detainees held in Mitiga\nand Judaydah prisons being forced to purchase all items for their detained relatives from a\nprivate shop at Judaydah prison that is allegedly owned by Colonel Osama Njeim. Colonel\nNjeim is the director of an official section of the Mitiga detention centre complex and a\nmember of Radaa. He has also been the head of the Operations and Security Department of\nthe Judicial Police since the issuance of a directive to that effect by the then Minister of\nJustice, Mohammed Lamlum. There are reasonable grounds to believe that government\npublic funds were misappropriated in detention centres within the Mitiga airport complex\nand that the illicit financial gain incentivized arbitrary detention as a tool of oppression and\nrepression."},{"id":"a-hrc-52-83-p0067","rec_id":"recsvi26SYPBMJd3q","symbol":"A/HRC/52/83","n":"67","seq":67,"section":"E. Violations of the rights to assembly, association, expression and belief","text":"The Mission continued to investigate violations of the rights to expression, assembly,\nassociation and belief in Libya. The Mission’s investigations underscored that Libyan\nauthorities, notably the Internal Security Agency, are curtailing the rights to assembly,\nassociation, expression and belief to ensure obedience, entrench self-serving values and\nnorms, and punish criticism against authorities and their leadership. The Internal Security\nAgency is a civil institution of the Libyan State with country-wide jurisdiction headquartered\nin Tariq al-Sikka in Tripoli. The Mission understood that Internal Security Agency branches\noperate under the influence of authorities in eastern and western Libya, depending on their\nlocation."},{"id":"a-hrc-52-83-p0068","rec_id":"recsvi26SYPBMJd3q","symbol":"A/HRC/52/83","n":"68","seq":68,"section":"E. Violations of the rights to assembly, association, expression and belief","text":"The Mission found that persons were tortured, raped, arbitrarily detained and\nsubjected to enforced disappearance after expressing their views on women’s rights and\ngender equality, sexual and gender diversity, the rights of indigenous groups and religion.\nAttacks against, inter alia, human rights defenders, women’s rights activists, journalists and\ncivil society associations have created an atmosphere of fear that has sent persons into self-\ncensorship, hiding or exile at a time when it is necessary to create an atmosphere that is\nconducive to free and fair elections."},{"id":"a-hrc-52-83-p0069","rec_id":"recsvi26SYPBMJd3q","symbol":"A/HRC/52/83","n":"69","seq":69,"section":"E. Violations of the rights to assembly, association, expression and belief","text":"The case of Jaber Zain is emblematic of the use of physical measures and laws to\noppress. He is a Sudanese male who immigrated to Libya at the age of six and amassed a\nsignificant online following because of his posts and public talks on racism, freedom of\nreligion and women’s rights. Mr. Zain was subjected to enforced disappearance for 20\nmonths and arbitrarily detained for longer than two years after his abduction in Tripoli on 25\nSeptember 2016 by armed members of the Second Special Support Forces of the Ministry of\nthe Interior from Tripoli. During his time in detention, Mr. Zain was interrogated about his\nwritings, views on religion, relationship with international organizations and embassies, and\nposition on women. He was also accused of not being a Muslim and corrupting Libyan\nsociety. Mr. Zain was sexually assaulted, beaten with sticks, gas pipes, fists and knees, and\ninterrogators threatened to rape his sisters. In one incident, interrogators attempted to rape\nhim with a 12-centimetres-long bullet. In May 2018, Mr. Zain was brought before a judge\nand charged with “offending the State’s religion”, “trying to destroy the conservative Libyan\nsociety” and “immoral practice”. Mr. Zain denied the charges and was deported in November\n2018. The Mission found reasonable grounds to believe that Mr. Zain’s rights to freedom of\nassociation, assembly, expression and belief have been violated and that he is a victim of\narbitrary detention, enforced disappearance, torture and arbitrary expulsion.\nSuppression of Tanweer Movement and its members"},{"id":"a-hrc-52-83-p0070","rec_id":"recsvi26SYPBMJd3q","symbol":"A/HRC/52/83","n":"70","seq":70,"section":"E. Violations of the rights to assembly, association, expression and belief","text":"In 2022, the Internal Security Agency published on its Facebook page and website\n“confession” videos of men, seemingly under duress, pronouncing that they and others were\nmembers of Tanweer Movement, atheists, agnostics, feminists and infidels.22 In December\n2022, four of the men were sentenced to three-year imprisonment “with hard labour” and\nfined by a domestic court in Tripoli. The Mission is concerned that the evidence relied upon\nwas extracted under coercive circumstances without lawyers present. The Mission is also\nconcerned that the legal provisions relied upon are inconsistent with the principle of legality\nand international human rights law.\nLegislation incompatible with fundamental freedoms"},{"id":"a-hrc-52-83-p0071","rec_id":"recsvi26SYPBMJd3q","symbol":"A/HRC/52/83","n":"71","seq":71,"section":"E. Violations of the rights to assembly, association, expression and belief","text":"The rights to manifest one’s belief and freedom of expression, association and\nassembly may be restricted, subject to necessity, justification and proportionality. Some of\nthe vague terminology used in Libyan legislation is incompatible with the right to freedom\nof expression, which requires that laws must be sufficiently precise to enable an individual\nto regulate his or her behaviour.23 The Libyan Penal Code, for example, stipulates the death\npenalty for any views or principles that aim to overthrow the political, social or economic\norder of the State24 and proscribes blasphemy.25 Similarly, the Law on Telecommunications\nholds that the publishing of information and data that “harms the political, economic, social\nor cultural heritage of Libyan Arab society” is punishable.26"},{"id":"a-hrc-52-83-p0072","rec_id":"recsvi26SYPBMJd3q","symbol":"A/HRC/52/83","n":"72","seq":72,"section":"E. Violations of the rights to assembly, association, expression and belief","text":"The Mission is alarmed by the Anti-Cybercrime Law that came into effect in October\n2022, which could exacerbate an already constricted and heavily monitored civic space\nonline. The law affords the Libyan authorities extensive discretionary powers to restrict and\ncriminalize online freedom of expression, opinion and belief on the basis of “public order\nand morality”.27"},{"id":"a-hrc-52-83-p0073","rec_id":"recsvi26SYPBMJd3q","symbol":"A/HRC/52/83","n":"73","seq":73,"section":"E. Violations of the rights to assembly, association, expression and belief","text":"Civil society organizations were also impacted directly by Presidential Council\ndecision No. 286 of 2019, in which the Council imposed stringent reporting procedures on\ncivil society organizations and limited activities of association in Libya.28"},{"id":"a-hrc-52-83-p0074","rec_id":"recsvi26SYPBMJd3q","symbol":"A/HRC/52/83","n":"74","seq":74,"section":"F. Women","text":"Women are systematically discriminated against in Libya, and the situation of women\nhas markedly deteriorated since the establishment of the Mission. This situation has been\ncompounded by the militarization of Libya, the proliferation of armed groups whose powers\ncontinuously increase and the weaking of State institutions."},{"id":"a-hrc-52-83-p0075","rec_id":"recsvi26SYPBMJd3q","symbol":"A/HRC/52/83","n":"75","seq":75,"section":"F. Women","text":"Alarmingly, the Mission received information of an increase in domestic violence in\nthe context of the availability of weapons, trauma suffered by abusers, the COVID-19\npandemic and security-imposed movement restrictions. In July 2022, a spate of “honour-\nrelated” femicides shook the country in what has been referred to as “the bloody week”.\nAround the Eid al-Adha week alone, at least six women were killed by their husbands,\nfathers, brothers or fiancées. The public outcry surrounding these killings led to arrests;\nhowever, perpetrators of violence against women are rarely prosecuted or handed sentences\nthat are commensurate with the gravity of the offence."},{"id":"a-hrc-52-83-p0076","rec_id":"recsvi26SYPBMJd3q","symbol":"A/HRC/52/83","n":"76","seq":76,"section":"F. Women","text":"There is no comprehensive law on combating violence against women in Libya. Nor\ndoes Libya have a national action plan for the implementation of Security Council resolution\n1325 (2000). Cooperation between the United Nations and Libya on issues concerning\nwomen has suffered a setback. The October 2021 memorandum of understanding between\nthe United Nations Entity for Gender Equality and the Empowerment of Women (UN-\nWomen) and the Minister of State for Women’s Affairs, which contained a standard reference\nto the 1979 Convention on the Elimination of All Forms of Discrimination against Women,\ncaused an uproar, and an investigation was opened against the Minister of the State on\nWomen’s Affairs. The decision to sign the memorandum of understanding was cancelled in\nSeptember 2022."},{"id":"a-hrc-52-83-p0077","rec_id":"recsvi26SYPBMJd3q","symbol":"A/HRC/52/83","n":"77","seq":77,"section":"F. Women","text":"The vilification of the Minister of the State for Women’s Affairs, one of the few\nwomen holding senior public office, was reprehensible and discouraged women’s political\nparticipation. The attack against the Minister of the State for Women’s Affairs is not isolated.\nThe Mission observed similar online vitriol against the Minister for Foreign Affairs and the\nMinister of Justice, both of whom are women."},{"id":"a-hrc-52-83-p0078","rec_id":"recsvi26SYPBMJd3q","symbol":"A/HRC/52/83","n":"78","seq":78,"section":"F. Women","text":"Another matter of concern to the Mission is the discriminatory treatment of Libyan\nwomen married to non-Libyans. Libyan women should possess the right to transfer their\nnationality to their children on an equal basis with men. They should also be permitted to\nmaintain their national identity number and their right to run for political office if they marry\nnon-Libyan men. The unequal treatment of Libyan women amounts to a violation under\ninternational human rights law."},{"id":"a-hrc-52-83-p0079","rec_id":"recsvi26SYPBMJd3q","symbol":"A/HRC/52/83","n":"79","seq":79,"section":"F. Women","text":"The Mission followed up on the local authorities’ responses to the enforced\ndisappearance of Siham Sergiwa nearly four years ago and the extrajudicial killing of Hanan\nBarassi in 2020. The Mission has reasonable grounds to believe that the Libyan Arab Armed\nForces leadership failed to take reasonable measures to submit those cases to competent\nauthorities for effective, genuine and independent investigation and prosecution."},{"id":"a-hrc-52-83-p0080","rec_id":"recsvi26SYPBMJd3q","symbol":"A/HRC/52/83","n":"80","seq":80,"section":"F. Women","text":"Ms. Sergiwa was abducted from her home in the heavily secured Bu Hadimah district\nof Benghazi during the afternoon by 25 to 30 armed men wearing masks and uniforms. She\nhad given an interview the day before her abduction in which she opposed the Libyan Arab\nArmed Forces attack on Tripoli. Benghazi is effectively and tightly controlled by the Libyan\nArab Armed Forces and its commander, Khalifa Haftar. The scale and sophistication of the\noperation suggest that the top Libyan Arab Armed Forces leadership knew or should have\nknown of the abduction and fate of Ms. Sergiwa."},{"id":"a-hrc-52-83-p0081","rec_id":"recsvi26SYPBMJd3q","symbol":"A/HRC/52/83","n":"81","seq":81,"section":"F. Women","text":"Ms. Barassi was gunned down in broad daylight by two armed and masked men in the\ncentre of Benghazi. She announced to her 70,000 followers on the day before her killing that\nshe would release information about Saddam Haftar, the son of Khalifa Haftar. While Omar\nMraja al-Megerhi is formally the head of the Tariq Bin Ziyad Brigade, evidence shows that\nthe group is controlled by Saddam Haftar."},{"id":"a-hrc-52-83-p0082","rec_id":"recsvi26SYPBMJd3q","symbol":"A/HRC/52/83","n":"82","seq":82,"section":"G. Sexual and gender-based violence","text":"There is no protection or accountability for victims of sexual and gender-based\nviolence in Libya. Women, detainees, migrants and persons of diverse sexual orientations\nand gender identities are particularly vulnerable to sexual and gender-based violence in Libya\nbecause of a combination of pervasive patriarchal norms and gender inequality, a lack of\ninstitutional arrangements that guarantee safe reporting on sexual violence and assistance to\nvictims, and ineffective or non-existent legal recourse."},{"id":"a-hrc-52-83-p0083","rec_id":"recsvi26SYPBMJd3q","symbol":"A/HRC/52/83","n":"83","seq":83,"section":"G. Sexual and gender-based violence","text":"The Mission’s recent investigations underscored that sexual and gender-based\nviolence continues to be widely employed by Libyan State actors and the Libyan Arab Armed\nForces to force confessions, punish, subjugate, terrify and silence journalists, activists,\ndetainees, migrants and women, including on the basis of persons’ actual or perceived sexual\norientation and gender identity.29 The Internal Security Agency and the Deterrence Apparatus\nfor Combating Organized Crime and Terrorism, which are formally part of the State, have\nbeen implicated in such violence.30 Conservative Salafist-leaning ideologies have been used\nto justify and motivate sexual and gender-based violence."},{"id":"a-hrc-52-83-p0084","rec_id":"recsvi26SYPBMJd3q","symbol":"A/HRC/52/83","n":"84","seq":84,"section":"G. Sexual and gender-based violence","text":"In an emblematic case documented by the Mission, two young Libyan men, perceived\nto be gay, were held up and coerced by heavily armed men to unlock and provide access to\ntheir phones. The two young men were taken to the Mitiga airport complex and handed over\nto Radaa. There, a bearded man in traditional clothing – described as a sheikh – severely\ntortured both victims and hurled foul language at them, denigrating their sexual orientation.\nOne of the victims was released the same day, while the other was kept for four days. The\nman that was kept in detention informed the Mission that he was later ordered, at gunpoint,\nto undress the lower part of his body and was raped by the guards. The victim was asked in\ndetention for information about other gay men. Both survivors subsequently fled Libya."},{"id":"a-hrc-52-83-p0085","rec_id":"recsvi26SYPBMJd3q","symbol":"A/HRC/52/83","n":"85","seq":85,"section":"G. Sexual and gender-based violence","text":"Libyan legislation excuses sexual and gender-based violence in Libya and gives rise\nto double victimization. For example, rape and other forms of sexual assault are not\ncriminalized in Libya in accordance with international law and standards.31 Libya’s Penal\nCode provision on “sexual intercourse with another by force, threat or deceit” has been\ninterpreted as the vaginal or anal penetration by the male reproductive organ and does not\ntake into account coercive circumstances or cover marital rape.32 Sexual relations between\nconsenting adults, whether they are same-sex or sexual relations outside marriage, are\npunishable. Moreover, the law provides for the exoneration of the perpetrator should he\nmarry the victim and remain married to the victim for three years.33"},{"id":"a-hrc-52-83-p0086","rec_id":"recsvi26SYPBMJd3q","symbol":"A/HRC/52/83","n":"86","seq":86,"section":"G. Sexual and gender-based violence","text":"Nearly all survivors interviewed refrained from lodging complaints out of fear of\nreprisal, arrest or extortion. A case concerning a Libyan female journalist who reported being\nrepeatedly raped and tortured during her detention highlighted the difficulties encountered\nby survivors of sexual violence. The victim was threatened that Radaa would arrest her for\nprostitution and deem her “spoiled” if she complained that she had been raped. When the\nvictim suspected that she was pregnant, she pretended to need blood tests to confirm the\npregnancy and self-administered medication to terminate it. Abortion is a criminal offense in\nLibya, unless necessary to preserve the mother’s life. In another case, a Sudanese asylum-\nseeker was arrested after giving birth at a public hospital. Despite her claim that the child was\nconceived through rape, the victim was accused of engaging in sexual relations outside of\nmarriage, an act criminalized in Libya."},{"id":"a-hrc-52-83-p0087","rec_id":"recsvi26SYPBMJd3q","symbol":"A/HRC/52/83","n":"87","seq":87,"section":"H. Children","text":"The Mission has previously reported on violations committed against children in\nLibya. For example, the Mission established in its first report to the Human Rights Council\nthat there were reasonable grounds to believe that Syrian children aged 15 to 18 years were\nrecruited into armed groups from late 2019. It also reported in this regard that Libya may\nhave failed to comply with its obligations under the African Charter on the Rights and\nWelfare of the Child and the Optional Protocol to the Convention on the Rights of the Child\non the involvement of children in armed conflict.34"},{"id":"a-hrc-52-83-p0088","rec_id":"recsvi26SYPBMJd3q","symbol":"A/HRC/52/83","n":"88","seq":88,"section":"H. Children","text":"The Mission has since received information that Syrian children are still being\nrecruited into armed groups and that children of minority groups of Libya that lack citizenship\nand are of undetermined legal status are at risk of becoming involved in fighting. It also\ncontinued to receive reports about children held in arbitrary detention with their parents or\nnon-familial detainees, as well as harm suffered to children during armed clashes and\nhostilities because of unexploded ordnance, among other things. While the Mission could not\nindependently corroborate and investigate such reports, the Mission underscores the need for\nfurther investigation of violations against children and their rights."},{"id":"a-hrc-52-83-p0089","rec_id":"recsvi26SYPBMJd3q","symbol":"A/HRC/52/83","n":"89","seq":89,"section":"I. Internally displaced persons","text":"The Mission welcomed the development of a national Durable Solutions Strategy and\nthe approval of funds to support reconstruction of several areas damaged during the conflicts\nand provide compensation for loss of property to the concerned persons. The Mission\nobserved that, despite these encouraging steps, no funding was disbursed for the purpose of\nreconstruction and that, in general, limited efforts were made to create the conditions needed\nfor people to return in a voluntary and dignified manner. Damage to houses and\nadministrative buildings, as well as limited access to basic services, remained key obstacles\nto their return. Many of the inhabitants from Murzuq who fled between February and August\n2019 remain displaced and will only be able to return if significant investments are made to\nrestore administrative buildings and housing and provide services for their livelihoods. In the\nsame vein, Tawurgha, which saw the mass displacement of some 40,000 people in 2011,\nremains largely unhabitable, and very few displaced persons have returned despite an\nagreement to that end signed in 2018. The presence of unexploded ordnance has been\nreported in many areas, posing a risk to the safety of those who would like to return."},{"id":"a-hrc-52-83-p0090","rec_id":"recsvi26SYPBMJd3q","symbol":"A/HRC/52/83","n":"90","seq":90,"section":"I. Internally displaced persons","text":"The largest group of internally displaced persons came from Benghazi, with hundreds\nof thousands of people displaced between 2014 and 2017 during the violence between the\nLibyan Arab Armed Forces and various non-State armed groups such as Da’esh. While many\nhave returned, the Mission learned that some internally displaced persons remain unable to\nreturn to their areas of origin in Benghazi and Darnah, owing to a risk of persecution or\nretaliation from militias."},{"id":"a-hrc-52-83-p0091","rec_id":"recsvi26SYPBMJd3q","symbol":"A/HRC/52/83","n":"91","seq":91,"section":"I. Internally displaced persons","text":"The majority of internally displaced persons found safety in the main urban centres,\nsuch as Benghazi, Misrata and Tripoli. There is increasing evidence that many in these\nlocations have integrated locally and may be unwilling to return. Internally displaced persons\nshould have the same access to services and livelihood opportunities as host communities.\nAlthough there has been some progress in that regard, the Mission received accounts of\ninternally displaced persons being discriminated against and left unable to avail themselves\nof their rights. Moreover, very few gender-specific services were available for women and\ngirls. The Mission also received reports of cases of eviction in places such as Sidi al-Sayeh,\nDawa Eslameya and Bani Walid."},{"id":"a-hrc-52-83-p0092","rec_id":"recsvi26SYPBMJd3q","symbol":"A/HRC/52/83","n":"92","seq":92,"section":"I. Internally displaced persons","text":"National reconciliation, including transitional justice, is a condition for the resolution\nof internal displacement in Libya. The Mission did not receive any information that the\nauthorities had provided internally displaced persons with effective remedies for\ndisplacement-related violations, including access to justice and reparations for harm suffered,\nor that they had taken the necessary steps to ensure that perpetrators of violations would be\nheld accountable."},{"id":"a-hrc-52-83-p0093","rec_id":"recsvi26SYPBMJd3q","symbol":"A/HRC/52/83","n":"93","seq":93,"section":"I. Internally displaced persons","text":"It is imperative that Libya ratify the African Union Convention for the Protection and\nAssistance of Internally Displaced Persons of 2019, which it has signed, with a view to\nproviding effective measures for the protection and resolution of the situation of internally\ndisplaced persons, based on a normative framework."},{"id":"a-hrc-52-83-p0094","rec_id":"recsvi26SYPBMJd3q","symbol":"A/HRC/52/83","n":"94","seq":94,"section":"J. Attacks against legal professionals and challenges to the rule of law","text":"The Mission investigated attacks against legal professionals and identified challenges\nto the rule of law in Libya. Although the Libyan judiciary is relatively cohesive, the Mission\nfound reasonable grounds to believe that acts had been committed that undermined the\nindependence of the judiciary and curtailed the rule of law. An independent, impartial,\ncompetent and effective judicial system is essential if victims are to be able to seek and\nreceive remedies and accountability at the domestic level."},{"id":"a-hrc-52-83-p0095","rec_id":"recsvi26SYPBMJd3q","symbol":"A/HRC/52/83","n":"95","seq":95,"section":"J. Attacks against legal professionals and challenges to the rule of law","text":"The Mission documented the alleged arbitrary detention, enforced disappearance and\n(attempted) killing of several judges and prosecutors. The Mission also documented cases of\ndetainees being denied access to lawyers and received reports of judges being replaced to fix\nan outcome, sentences that were adapted to serve certain interests and cases that were not\nbrought to trial owing to tribal affiliations. Attacks against members of the legal profession\nwere reported in Benghazi, Tripoli, Sirte and Sabha."},{"id":"a-hrc-52-83-p0096","rec_id":"recsvi26SYPBMJd3q","symbol":"A/HRC/52/83","n":"96","seq":96,"section":"J. Attacks against legal professionals and challenges to the rule of law","text":"For example, the Mission documented the case of a lawyer in Tripoli who was\nlitigating civil cases, the majority of which were lawsuits against the Government for\ncompensation for victims of crimes committed by militias who were on the government\npayroll. He was also speaking out against child recruitment by militias. The victim was\nabducted from the streets in Tripoli in April 2019, detained and interrogated. The perpetrators\nagreed to release him on the condition that he did not proceed with the lawsuits and refrained\nfrom speaking publicly about child recruitment. The victim was released after one day. He\nsoon afterward left Libya and has never returned."},{"id":"a-hrc-52-83-p0097","rec_id":"recsvi26SYPBMJd3q","symbol":"A/HRC/52/83","n":"97","seq":97,"section":"J. Attacks against legal professionals and challenges to the rule of law","text":"In another emblematic case from 2021, a female lawyer in Benghazi was kidnapped\nfrom the street near Ajdabiya Court, arbitrarily detained in inhumane conditions and\nsubjected to enforced disappearance for two days by the Internal Security Agency before\nbeing thrown on the street, handcuffed and blindfolded. In August 2022, another lawyer was\nharshly beaten by Radaa elements inside a Tripoli courtroom, in front of judges, kidnapped\nand then held by Radaa in Mitiga prison for about eight hours, before being released\nfollowing pressure from external entities."},{"id":"a-hrc-52-83-p0098","rec_id":"recsvi26SYPBMJd3q","symbol":"A/HRC/52/83","n":"98","seq":98,"section":"J. Attacks against legal professionals and challenges to the rule of law","text":"The Mission found that there was no domestic legislation establishing protection\nmeasures for witnesses and victims. Nor was there a Libyan security or military force capable\nof providing security protection to the courts, prosecutors' offices and the judiciary in\naccordance with international practice. In fact, the Judicial Police operations room, which is\npart of the Judicial Police and is tasked with providing judicial security, was implicated in\nattacks on judicial personnel."},{"id":"a-hrc-52-83-p0099","rec_id":"recsvi26SYPBMJd3q","symbol":"A/HRC/52/83","n":"99","seq":99,"section":"J. Attacks against legal professionals and challenges to the rule of law","text":"Victims seeking justice through domestic avenues encountered considerable\nobstacles. For example, those who sought to lodge complaints with the public prosecution in\nTripoli, after having fled to territory outside the control of the Libyan Arab Armed Forces,\nreported that prosecutors told them they lacked jurisdiction to investigate alleged Tariq Bin\nZiyad Brigade crimes. It was further reported that no criminal cases were heard in Fazzan\nbetween 2011 and 2019 and that police stations closed by 2 p.m.\nMilitary trials of civilians"},{"id":"a-hrc-52-83-p0100","rec_id":"recsvi26SYPBMJd3q","symbol":"A/HRC/52/83","n":"100","seq":100,"section":"J. Attacks against legal professionals and challenges to the rule of law","text":"The Libyan Arab Armed Forces have been operating a parallel military justice system\nin areas under their control. The House of Representatives, allied with the Libyan Arab\nArmed Forces since 2014, enacted a law in 2016 extending the personal and subject-matter\njurisdiction of the military judiciary over civilians who are members of militias and those\nwho commit “terrorist acts”. Trials of civilians before military courts violate international\nhuman rights law, including the African Charter on Human and Peoples’ Rights, as they often\ndo not satisfy the requirements of judicial independence, impartiality and competence under\nthe right to a fair trial."},{"id":"a-hrc-52-83-p0101","rec_id":"recsvi26SYPBMJd3q","symbol":"A/HRC/52/83","n":"101","seq":101,"section":"IV. Recommendations","text":"All of the Mission’s previous recommendations remain relevant and must be\nimplemented."},{"id":"a-hrc-52-83-p0102","rec_id":"recsvi26SYPBMJd3q","symbol":"A/HRC/52/83","n":"102","seq":102,"section":"IV. Recommendations","text":"The Mission calls on the authorities of Libya:\n(a)     To investigate and prosecute individuals allegedly responsible for\nviolations and abuses of international humanitarian and human rights law and\ndomestic criminal law, in accordance with due process guarantees and the principle of\nlegality. To this end, they should exclude amnesty for gross human rights violations and\ninternational crimes and provide a safe working environment for judges, lawyers and\nprosecutors;\n(b)   To abide by the pledge made to the Human Rights Council in 2022 to use\nthe findings and recommendations of the Mission as a baseline for Libya’s future\nreports to the Council under the universal periodic review and human rights treaty\nbodies;\n(c)    To undertake effective disarmament, demobilization, reintegration and\nrehabilitation measures to establish integrated armed and security forces in keeping\nwith international standards and practices;\n(d)   To restructure the State security sector and subject it to an independent\ncivilian oversight mechanism that operates in accordance with international law\nstandards;\n(e)     To cease all military trials of civilians and halt the implementation of\njudgments issued by military courts against civilians;\n(f)  To end the criminalization of irregular entry and stay of migrants in Libya\nand immediately release arbitrarily detained migrants, including by amending Law No.\n19 on Combating Irregular Migration of 2010. Where migrant detention is justified,\nensure that women and men are separated and are kept in humane and dignified\nconditions;\n(g)    To dismantle secret prisons and immediately release all persons\narbitrarily detained;\n(h)    To cooperate fully with the United Nations human rights system and\nimplement recommendations made by all United Nations special procedures mandate\nholders and facilitate their unhindered and safe access to all parts of Libya and places\nof detention, as requested;\n(i)    To cooperate fully with and facilitate unhindered and safe access to the\nInternational Criminal Court;\n(j)   To ensure the enjoyment of fundamental rights, including the free and\nsafe exchange of diverse opinions and information;\n(k)    To protect and promote the rights of women, minorities, persons of\ndiverse sexual orientations and gender identities, civil society activists, journalists and\nhuman rights defenders and encourage their participation in political and public life.\n(l)\nI     To amend provisions of the Libyan Penal Code and the Publications Law\nto the extent necessary to align them with international human rights law;\n(m) To amend the Anti-Cybercrime Law, the Law on Civic Associations,\nmedia regulations, including decision No. 811 (2022), and the Publications Law to the\nextent necessary to align them with international human rights law;\n(n)     To remedy and abolish undue restrictions imposed on national and\ninternational civil society organizations in Libya;\n(o)     To strengthen efforts to organize free, fair and transparent elections;\n(p)    To take remedial action to realize victims’ rights to truth, justice and\nreparations, and to that end:\n(i)    To develop and adopt a holistic national human rights plan of action that\nreflects international human rights law and standards and addresses all findings\nand recommendations made by the Mission and international human rights\nbodies;\n(ii)  To enact legislation and develop a system to protect victims and witnesses\nfrom reprisal;\n(iii) To develop a comprehensive, inclusive, victim-centred and detailed road\nmap on transitional justice and accountability for Libya;\n(iv) To amend article 417 of the Code of Criminal Procedure to allow for civil\nproceedings even in the absence of a criminal conviction;\n(q)   To eliminate all forms of discrimination against women, including by\ntaking appropriate measures to modify practices that marginalize women in public and\nprivate spheres;\n(r)   To ensure that comprehensive legislation protects, prevents, and punishes\nviolence against women, bring the legal definition of rape in line with international law\nand standards and repeal provisions, such as article 424 of the Libyan Penal Code, that\nmitigate or absolve the perpetrator of responsibility for rape;\n(s)   To ensure that internally displaced persons can make voluntary and\ninformed decisions about the type of durable solutions they pursue, including return to\ntheir places of origin, and guarantee that internally displaced persons have access to\ntheir rights and entitlements in their areas of displacement without any discrimination;\n(t)    To ensure that all unexploded ordnance is removed;\n(u)    To continue searching for the missing and remaining mass graves,\nincluding by using the Mission’s findings in that regard on Tarhuna, and, to that end,\ntake steps to ratify the International Convention for the Protection of All Persons from\nEnforced Disappearance;\n(v)    To take steps to implement the national Durable Solutions Strategy and\nother relevant frameworks for the resolution of internal displacement, including by\nallocating the necessary funding and investing in the reconstruction of areas of origin\nof internally displaced persons."},{"id":"a-hrc-52-83-p0103","rec_id":"recsvi26SYPBMJd3q","symbol":"A/HRC/52/83","n":"103","seq":103,"section":"IV. Recommendations","text":"The Mission calls on the United Nations, the international community and third\nStates:\n(a)     To urge the Human Rights Council to establish an independent,\ninternational investigation mechanism and to call on the Office of the United Nations\nHigh Commissioner for Human Rights to establish a distinct and autonomous\nmechanism with an ongoing mandate to monitor and report on gross human rights\nviolations in Libya, with a view to supporting Libyan reconciliation efforts and assisting\nthe Libyan authorities in achieving transitional justice and accountability. In this\nregard, the Mission calls on the United Nations, the international community and third\nStates to extend to the mechanisms the resources necessary for them to undertake their\ntasks in an efficient and effective manner;\n(b)     To apply a strict human rights due diligence policy to their support to\nauthorities in Libya, especially with respect to the Libyan State security sector;\n(c)   To increase resources and other support to the United Nations Support\nMission in Libya to promote and protect human rights pursuant to Security Council\nresolution 2542 (2020);\n(d)   To assist Libya in developing and implementing a national human rights\naction plan by, inter alia, providing it with technical and capacity-building support;\n(e)    To exercise universal jurisdiction over international crimes committed in\nLibya, including over mercenaries and foreign fighters;\n(f)    To cooperate with the Office of the Prosecutor of the International\nCriminal Court investigation of the situation in Libya, including by surrendering\nindividuals for whom an arrest warrant has been issued;\n(g)    To abide by the customary international law principle of non-refoulement\nand cease all direct and indirect support to Libyan actors involved in crimes against\nhumanity and gross human rights violations against migrants, such as the Directorate\nfor Combating Illegal Migration, the Stability Support Apparatus and the Libyan Coast\nGuard;\n(h)  To regulate migration in accordance with international law and the\nGlobal Compact for Safe, Orderly and Regular Migration."},{"id":"a-hrc-52-crp-8-u0000","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":null,"seq":0,"section":null,"text":"Summary\nThe present paper contains the detailed findings of the Independent Fact-Finding\nMission on Libya, and it is presented at the 52nd session of the Human Rights Council. It is\nfocused on the exploitation of migrants and repression of dissent in Libya since 2016.\nThe Mission found reasonable grounds to believe that the exploitation of migrants\nentailed violations of international human rights law and international humanitarian law and\nthe commission of crimes against humanity. Furthermore, the smuggling, trafficking,\nenslavement, forced labour, imprisonment, and extortion of migrants generated significant\nrevenue for individuals, armed groups, and State institutions. State affiliated entities in Libya\nreceived technical, logistical, and monetary support from the European Union and its\nmember States for inter alia the interception and return of migrants to Libya.\nThe repression of dissent was manifest in cases involving violations of the rights to the\nfundamental freedoms of expression, association, assembly, and belief. Persons were inter\nalia arbitrarily detained, killed, tortured, and subjected to sexual and gender-based violence\nfor their expression of divergent political, religious, and social views and norms, including\ntheir opposition to patriarchy and sexism, their criticism of the State and affiliated actors,\nand their actual or perceived sexual orientations and gender identities. In this regard, the\nrapid, deep, and ongoing absorption of armed groups and their leadership into State structures\nand institutions, including the LAAF, and the spread of Salafist-leaning conservative\nideologies were observed with concern.\nConduct and patterns of gross violations of international human rights law and\ninternational humanitarian law described in the present report continue unabated. Structural,\nfundamental reforms of the Libyan constitutional and legislative framework, executive\nbranch, and security sectors are necessary to uphold the rule of law and bring an end to the\nrepression of fundamental human rights and freedoms of Libyans and the exploitation of\nmigrants.","unnumbered":true},{"id":"a-hrc-52-crp-8-u0001","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":null,"seq":1,"section":null,"text":"* The information contained in the present document should be read in conjunction with the official\nreport of the Independent Fact-Finding Mission on Libya (A/HRC/52/83), submitted to the Human\nRights Council at its fifty-second session, pursuant to Council resolution 50/23.","unnumbered":true},{"id":"a-hrc-52-crp-8-p0001","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"1","seq":2,"section":"I. Introduction","text":"The present report contains the detailed findings of the Independent Fact-Finding\nMission on Libya, and it is presented at the 52nd session of the Human Rights Council,\nalongside the Mission’s final report mandated in resolution 50/23.1 The Human Rights\nCouncil established the Mission to document, in an independent and impartial manner,\nalleged violations and abuses of international human rights and humanitarian law by all\nparties in Libya since the beginning of 2016.2 The Human Rights Council extended the\nMission’s mandate for a final, non-extendable period of nine months in July 2022 to allow it\nto submit its final report and concluding recommendations.3"},{"id":"a-hrc-52-crp-8-p0002","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"2","seq":3,"section":"I. Introduction","text":"The present report is focused on the exploitation of migrants 4 and repression of\ndissent, two themes which constitute a considerable part of the large body of evidence\ncollected by the Mission. The exploitation of migrants and repression of dissent are linked in\nthat they facilitated consolidations of power and wealth by authorities that exercise effective\ncontrol of different parts of Libya and State affiliated armed groups. This occurred at a time\nwhen the legislative, executive and security sector reforms needed to uphold the rule of law\nand unify the country are far from being realised."},{"id":"a-hrc-52-crp-8-p0003","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"3","seq":4,"section":"I. Introduction","text":"Notably, the Mission found reasonable grounds to believe that the exploitation of\nmigrants entailed violations of international human rights law and international humanitarian\nlaw and the commission of crimes against humanity. Furthermore, the exploitation of\nmigrants, in the forms of smuggling, trafficking, enslavement, forced labour, imprisonment,\nand extortion of migrants generated significant revenue for individuals, armed groups, and\nState institutions. State affiliated entities in Libya also received technical, logistical, and\nmonetary support from the European Union and its member States for inter alia the\ninterception and return of migrants to Libya."},{"id":"a-hrc-52-crp-8-p0004","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"4","seq":5,"section":"I. Introduction","text":"The repression of dissent was manifest in cases involving violations of the rights to\nthe fundamental freedoms of expression, association, assembly, and belief. Based on the\nevidence collected, persons were inter alia arbitrarily detained, killed, tortured, and subjected\nto sexual and gender-based violence for their expression of divergent political, religious, and\nsocial views and norms, including their opposition to patriarchy and sexism, their criticism\nof the State and affiliated actors, and their actual or perceived sexual orientations and gender\nidentities."},{"id":"a-hrc-52-crp-8-p0005","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"5","seq":6,"section":"I. Introduction","text":"In this regard, the rapid, deep, and ongoing absorption of armed groups and their\nleadership into State structures and institutions, including the LAAF, and the spread of\nSalafist-leaning conservative ideologies are of significant concern to the Mission. 5 The\nMission found that State authorities and affiliated entities, such as Libya’s Deterrence\nApparatus for Combating Terrorism and Organized Crime (DACOT, also known as Radaa),\nthe Libyan Arab Armed Forces (LAAF), the Internal Security Agency (ISA), and the Stability\nSupport Apparatus (SSA), and their leadership, were repeatedly involved in violations and\nabuses of human rights arising in the context of arbitrary detention."},{"id":"a-hrc-52-crp-8-p0006","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"6","seq":7,"section":"I. Introduction","text":"Allegations of violations and abuses of international human rights law and\ninternational humanitarian law have rightly warranted the Council’s attention. The Mission\nhas found reasonable grounds to believe that crimes against humanity were committed\nagainst Libyans and migrants in connection with their arbitrary deprivation of liberty across\nthe Libyan territory since 2016. Notably, the Mission documented and made findings on\nnumerous cases of inter alia arbitrary detention, murder, torture, rape, enslavement, and\nenforced disappearance, confirming their widespread violations in Libya. The Mission also\nconcluded a holistic assessment of evidence on the treatment of migrants and established\nreasonable grounds to believe that sexual slavery, as an additional underlying act of crimes\nagainst humanity, was committed against migrants. The State remains under an obligation to\ninvestigate allegations of human rights violations and crimes committed in areas under its\neffective control in accordance with international standards."},{"id":"a-hrc-52-crp-8-p0007","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"7","seq":8,"section":"I. Introduction","text":"The present report of the detailed findings of the Mission builds cumulatively on\nviolations and abuses previously reported on in the Mission’s four reports to the Human\nRights Council6 and a conference room paper on Tarhuna.7 These reports detail a wider range\nof violations and abuses committed in Libya since 2016 and contain thematic sections on the\nhuman rights situation of groups of society that are particularly vulnerable to violations, such\nas internally displaced persons, children, and women."},{"id":"a-hrc-52-crp-8-p0008","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"8","seq":9,"section":"II. Establishment and mandate of the Mission","text":"On 22 June 2020, the Human Rights Council requested, through resolution 43/39, the\nUnited Nations High Commissioner for Human Rights to immediately establish and dispatch\na fact-finding mission to Libya. The Mission was called upon to establish, in an independent\nand impartial manner, the:\nfacts and circumstances of the situation of human rights throughout Libya, and to\ncollect and review relevant information, to document alleged violations and abuses of\ninternational human rights law and international humanitarian law by all parties in\nLibya since the beginning of 2016, including any gendered dimensions of such\nviolations and abuses, and to preserve evidence with a view to ensuring that\nperpetrators of violations or abuses of international human rights law and international\nhumanitarian law are held accountable.8"},{"id":"a-hrc-52-crp-8-p0009","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"9","seq":10,"section":"II. Establishment and mandate of the Mission","text":"Accordingly, the High Commissioner announced on 22 August 2020 the appointment\nof Mohammad Auajjar (Chair), Tracy Robinson, and Chaloka Beyani as experts of the\nMission."},{"id":"a-hrc-52-crp-8-p0010","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"10","seq":11,"section":"II. Establishment and mandate of the Mission","text":"The Mission, which was asked to carry out its work in cooperation with the Libyan\nauthorities, the League of Arab States, the African Union, and the United Nations Support\nMission in Libya,9 was instituted initially for a period of one year and requested to report on\nits findings to the Human Rights Council at its 45th session.10 Noting, however, that certain\nactivities mandated could not be carried out in 2020 due to a liquidity crisis and the outbreak\nof the COVID-19 pandemic, the Human Rights Council decided to extend the Mission’s\nmandate until its 48th session.11 The Human Rights Council has since adopted two more\nresolutions extending the mandate of the Mission until March 2023.12"},{"id":"a-hrc-52-crp-8-p0011","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"11","seq":12,"section":"II. Establishment and mandate of the Mission","text":"The last resolution extending the Missions mandate, dated 4 July 2022, requested the\nMissions to:\n• present to [the Human Rights Council], its final report on the situation of human rights\nin Libya with a particular focus on its concrete and concluding recommendations for\nthe Libyan authorities in the priority areas of:\n(a)     Achieving transitional justice and national reconciliation;\n(b)    Strengthening national human rights institutions and the national action\nplan for human rights to follow-up on the investigation of the fact-finding\nmission and recommendations made by the treaty bodies and in the context of\nthe universal periodic review;\n(c)    Strengthening the rule of law, including supporting judicial processes\nand law enforcement.13"},{"id":"a-hrc-52-crp-8-p0012","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"12","seq":13,"section":"II. Establishment and mandate of the Mission","text":"The mandate of the Mission as outlined in Human Rights Council resolution 43/39 is\nbroad and general, encompassing all of the geographical area of Libya and violations and\nabuses of international human rights law and international humanitarian law committed by\nany actors. The Mission interpreted its mandate to encompass violations and abuses of a\ncontinuing nature that commenced before the beginning of 2016, such as enforced\ndisappearance. It has also interpreted its mandate to cover violations and abuses committed\non the Libyan territory, including its territorial waters, and acts that were initiated outside the\nLibyan borders but continued within its territory. 14"},{"id":"a-hrc-52-crp-8-p0013","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"13","seq":14,"section":"II. Establishment and mandate of the Mission","text":"When the Human Rights Council established the Mission, it recognized the need for\naccountability in Libya.15 Notably, resolution 43/39 stated that the objective of the Mission’s\nmandate to preserve evidence is to have those responsible held accountable.16 The Human\nRights Council requested the Mission to also provide an oral update on “efforts to prevent\nand ensure accountability for violations and abuses of human rights and recommendations\nfor follow-up.” 17 The Mission interpreted its mandate to involve international criminal law\nwhere the gravity of the abuses and violations reached the threshold of international criminal\nresponsibility. It included in its investigation the identification of those most responsible for\nviolations and abuses under investigation.18"},{"id":"a-hrc-52-crp-8-p0014","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"14","seq":15,"section":"II. Establishment and mandate of the Mission","text":"The beginning of the Mission’s mandate period followed chronologically other UN-\nmandated investigations into violations of international law committed in the context of\nLibya since 2011. The Human Rights Council formed in 2011 an independent commission\nof inquiry to investigate all alleged violations of international human rights law in Libya, to\nidentify those most responsible, and to make recommendations on accountability measures.19\nThat commission concluded its work in 2014 and found, in accordance with its standard of\nproof, that Qadhafi forces and anti-Qadhafi forces had committed serious violations of\ninternational law, including international crimes.20 In 2015, the High Commissioner was\nrequested to dispatch another mission, this time to investigate violations and abuses of\ninternational human rights law committed in Libya since the beginning of 2014, in\ncoordination with the United Nations Support Mission in Libya.21 The United Nations High\nCommissioner’s mission found that “there are reasonable grounds to conclude that there were\nwidespread violations of international human rights law and international humanitarian law,\nand abuses of human rights in Libya throughout 2014 and 2015”.22"},{"id":"a-hrc-52-crp-8-p0015","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"15","seq":16,"section":"A. Scope of the investigation and criteria for selection","text":"The Mission’s investigations were informed by three objective criteria: (a) the gravity\nand widespread or systematic nature of violations, (b) violations, abuses, and crimes against\nvulnerable groups that are subjected to multiple forms of victimization, and (c) violations,\nabuses, and crimes that especially hamper Libya’s transition to the rule of law and democratic\nelections."},{"id":"a-hrc-52-crp-8-p0016","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"16","seq":17,"section":"A. Scope of the investigation and criteria for selection","text":"In keeping with resolution 43/39, the Mission focused its investigations on sexual and\ngender-based violence and violations and abuses against women throughout its mandate.\nParticular attention was given to gendered dimensions of the violations and abuses\nidentified.23"},{"id":"a-hrc-52-crp-8-p0017","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"17","seq":18,"section":"A. Scope of the investigation and criteria for selection","text":"The Mission adopted a broad view of accountability and acknowledged victims’ rights\nto truth and effective remedy and guarantees of non-reoccurrence as essential components of\nhuman rights and transitional justice. 24 The Mission also drew on international criminal law\nand compiled a preserved list of individuals allegedly responsible for certain documented\nviolations and abuses. The list will be deposited, as part of the Mission’s evidentiary\nholdings, with the United Nations High Commissioner for Human Rights."},{"id":"a-hrc-52-crp-8-p0018","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"18","seq":19,"section":"B. Methods of work and investigation activities","text":"Since its establishment, the Mission has carried out more than 400 interviews,\nprimarily with witnesses and victims, and collected more than 2,800 discrete items of\ninformation. A large proportion of the items was in the form of reports, meeting notes,\nlegislation, maps, and photographic and audiovisual imagery."},{"id":"a-hrc-52-crp-8-p0019","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"19","seq":20,"section":"B. Methods of work and investigation activities","text":"Investigation and reporting activities were guided by the Mission’s commitment to\nsafeguard the well-being and safety of the individuals and groups with which it interacted,\nand Mission staff adhered scrupulously to the “do no harm” principle in all their activities.\nInvestigators arranged interviews and the transmission of information in safe places and over\nsecure platforms and referred victims to protection and assistance programs as appropriate\nand when feasible."},{"id":"a-hrc-52-crp-8-p0020","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"20","seq":21,"section":"B. Methods of work and investigation activities","text":"The Mission did not interview persons unless they agreed to be interviewed and it\nsought informed consent from sources to use and share their information in its reports and\nwith external stakeholders. The identities of victims and witnesses in the present report have\nbeen disclosed with their knowledge and after secondary consent was obtained."},{"id":"a-hrc-52-crp-8-p0021","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"21","seq":22,"section":"B. Methods of work and investigation activities","text":"The Mission undertook 13 missions, three of which were conducted during the last\nmandate extension period. The Mission went to Tripoli on six separate occasions 25 and to\nBenghazi on one occasion.26 One of the last missions was a lengthy investigative mission to\nTripoli, from 21 October to 21 November 2022. Investigators also travelled to Italy27,\nRwanda28, Malta29, the Netherlands30, as well as to other countries."},{"id":"a-hrc-52-crp-8-p0022","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"22","seq":23,"section":"B. Methods of work and investigation activities","text":"In addition to its regular interactions with relevant groups, the Mission made three\nopen calls for submissions to the public to solicit information. 31 The Mission invited on its\ndedicated page of the Human Rights Council website, individuals, groups, and organizations\nto provide it with information relevant to its mandate.32 Furthermore, the Mission organized\nat least eight roundtable meetings with civil society, including two in October 2022 and two\nin January 2023."},{"id":"a-hrc-52-crp-8-p0023","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"23","seq":24,"section":"C. Standard of proof","text":"Consistent with most other United Nations fact-finding missions and commissions of\ninquiry, the Mission applied the “reasonable grounds to believe” evidentiary standard when\nmaking factual and legal determinations on patterns, incidents, and cases. The standard was\ndeemed met when a reliable body of primary information was obtained that was corroborated\nby at least one other independent source, which could lead a reasonable and ordinarily\nprudent person to believe that the patterns, incidents, and cases had occurred."},{"id":"a-hrc-52-crp-8-p0024","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"24","seq":25,"section":"C. Standard of proof","text":"In assessing the reliability of primary and secondary sources, the Mission considered\nthe position of the witness in relation to the subject of the information, when and how the\nwitness obtained the information, the witness’ capacity to recall events, and potential biases\nand/or motives on the part of the source. In assessing the credibility of information, the\nMission took account of the level of detail and specificity in the information collected and its\nplausibility. It also examined consistency and coherence within one source’s assertions\n(internal consistency) and compared information received by one source with information\nderived from other sources (external consistency), while having regard to memory\nimpairment by trauma."},{"id":"a-hrc-52-crp-8-p0025","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"25","seq":26,"section":"C. Standard of proof","text":"Information collected was either categorized as first-hand or second-hand\ninformation. Interviews by the Mission with victims and witnesses, satellite imagery,\nobservations by investigators, laws and regulations, and policies were regarded as first-hand\ninformation. In general, interviews conducted by reliable and credible organizations, reports\nand documents by non-governmental organizations and the United Nations, academic\nresearch papers, and media reports were considered second-hand information."},{"id":"a-hrc-52-crp-8-p0026","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"26","seq":27,"section":"C. Standard of proof","text":"The Mission found that the evidentiary standard was met with respect to violations\ninvolving torture, cruel, inhuman or degrading treatment, enforced disappearance, and sexual\nand gender-based violence, and the conditions in which those violations occurred where\ndetailed, reliable, and credible first-hand sources of information were corroborated by\nevidence establishing patterns of similar incidents in the area of investigation."},{"id":"a-hrc-52-crp-8-p0027","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"27","seq":28,"section":"C. Standard of proof","text":"The Mission identified patterns based on several pieces of first-hand evidence that\nwere consistent with and corroborated by the overall body of evidence collected. The Mission\ndiscerned patterns from inter alia, time-periods, localities, victim profiles (based on gender,\nage, and ethnic, religious, racial and political grounds), modus operandi, and motives."},{"id":"a-hrc-52-crp-8-p0028","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"28","seq":29,"section":"C. Standard of proof","text":"Unlike the criminal standard of proof, the “reasonable grounds” basis does not require\nthe Mission to make findings to the exclusion of all other reasonable inferences. Considering\nthe stigma attached to the violations and abuses documented, the public nature of its work,\nand the presumption of innocence, the Mission resorted to the higher evidentiary standard of\nbalance of probabilities when compiling its list of individuals allegedly responsible for the\nviolations and abuses that the Mission documented."},{"id":"a-hrc-52-crp-8-p0029","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"29","seq":30,"section":"D. Challenges and cooperation","text":"The Mission did its utmost to discharge its mandate fully but was confronted with a\nmyriad of resource-, access-, and security-related challenges that inadvertently impeded the\nscope and continuity of its work. These challenges arose from the time of the decision to\nestablish and dispatch the Mission and continued until the end of its mandate."},{"id":"a-hrc-52-crp-8-p0030","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"30","seq":31,"section":"D. Challenges and cooperation","text":"In its resolution 43/39 of 22 June 2020, the Human Rights Council requested the\nUnited Nations High Commissioner for Human Rights to establish and dispatch a fact-\nfinding mission on Libya, but the coronavirus disease (COVID-19) pandemic, the United\nNations budgetary liquidity crisis and a suspension of recruitment delayed the formation of\nthe Mission secretariat and the commencement of investigations. The secretariat became fully\noperational in June 2021. While the intention was to recruit 18 staff members for the\nsecretariat, it was composed of less than 10 staff members for lengthy periods of time and\nsuffered a chronic shortage of investigators during critical stages of the investigation.33"},{"id":"a-hrc-52-crp-8-p0031","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"31","seq":32,"section":"A. Access-related challenges","text":"The Mission’s endeavours to base its investigation team in Libya proved unfeasible\nowing to limited United Nations accommodation in Libya and security challenges.34 Access\nto Libyan territory and other countries depended upon the cooperation of authorities primarily\nin Libya, the Republic of Tunisia, and the Swiss Confederation, with the assistance of the\nUnited Nations."},{"id":"a-hrc-52-crp-8-p0032","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"32","seq":33,"section":"A. Access-related challenges","text":"The Mission extends its appreciation to the Libyan Permanent Mission in Geneva and\nthe Libyan Ministry for Foreign Affairs for facilitating the Mission’s travels to Libya. The\nMission is also grateful to the United Nations Resident Coordinator to Libya, and the United\nNations Support Mission in Libya, including its Human Rights Section, for their continued\nsupport to it. Furthermore, the Mission extends its gratitude to the Republic of Tunisia for\nhosting the Secretariat."},{"id":"a-hrc-52-crp-8-p0033","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"33","seq":34,"section":"A. Access-related challenges","text":"Cooperation with authorities in Libya was not, however, without complication. While\ncooperation with authorities in Libya improved, the Mission struggled to obtain the\npermissions necessary to gain unhindered access to all parts of the Libyan territory, without\ndelay.35"},{"id":"a-hrc-52-crp-8-p0034","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"34","seq":35,"section":"A. Access-related challenges","text":"The LAAF did not grant the Mission’s several requests to visit southern Libya\n(Fazzan), under its control. In May 2022, the Government of National Unity (GNU) denied\nthe Mission permission to depart from Tripoli to enter the areas of southern Libya under the\ncontrol by the LAAF, and the LAAF contemporaneously denied it authorization to access\nSabha. Both authorities cited security concerns. In October 2022, the LAAF withdrew the\nauthorization to Sabha that the Mission had received after significant delays. The Mission\nsent an official letter to the LAAF protesting the withdrawal of authorization, but never\nreceived any reply."},{"id":"a-hrc-52-crp-8-p0035","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"35","seq":36,"section":"A. Access-related challenges","text":"The Mission submitted several requests to the Presidential Council of the GNU, the\nMinistry of the Interior, the Ministry of Justice, the Ministry of Social Affairs, and the\nMinistry of Public Health, to visit several prisons and places where persons were deprived of\ntheir liberty. The Mission did not receive official responses to its requests."},{"id":"a-hrc-52-crp-8-p0036","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"36","seq":37,"section":"A. Access-related challenges","text":"Despite the calls by the Human Rights Council for the Libyan authorities to allow the\nmembers of the Mission to meet and speak freely and privately, when they so request, with\nwhomever they wish to meet or speak, the climate of fear surrounding witnesses and civil\nsociety frequently hampered the Mission’s engagements. There were instances when groups\nand individuals declined to meet with the Mission in particular locations, or at all, because\nof the fear of reprisals."},{"id":"a-hrc-52-crp-8-p0037","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"37","seq":38,"section":"A. Access-related challenges","text":"In this regard, the Mission is grateful to civil society groups, affected communities,\nvictims, and witnesses that engaged with it and shared high-quality and pointed information\nand feedback over the years. It was of great importance for the Mission to maintain open\nlines of communication with all concerned by its work."},{"id":"a-hrc-52-crp-8-p0038","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"38","seq":39,"section":"IV. Applicable law","text":"Pursuant to its mandate, the Mission centered its work around international human\nrights law and international humanitarian law. The applicable international human rights law\nand international humanitarian standards were drawn from the treaties that Libya had ratified\nand customary international law. International human rights obligations were further\ndelineated by reference to non-binding, soft law instruments. The Mission considered Libyan\nlaw where it was found relevant to its assessment."},{"id":"a-hrc-52-crp-8-p0039","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"39","seq":40,"section":"IV. Applicable law","text":"Although the Mission’s subject-matter mandate, as expressed in resolution 43/39, did\nnot explicitly include international criminal law or questions of individual responsibility, the\nMission did give regard to it for reasons specified below."},{"id":"a-hrc-52-crp-8-p0040","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"40","seq":41,"section":"A. International human rights law","text":"International human rights law obliges States to continually respect, protect, and fulfil\nhuman rights where they exercise effective control. States are the primary duty bearers of\ninternational human rights obligations, and they can be held responsible for human rights\nviolations committed by their organs (for example, the legislative or executive branch) or by\ntheir agents (for example, civil servants, the police, the armed forces). The State is also\nresponsible for the actions of non-state actors that may be attributed to it, such as militia\ngroups that operate with its endorsement or acquiescence, even where those actions are\ncommitted outside the scope of the official’s apparent authority."},{"id":"a-hrc-52-crp-8-p0041","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"41","seq":42,"section":"A. International human rights law","text":"The Mission did not, however, view international human rights law solely within the\nconstruct of State responsibility. Rather, the Mission concurred with the position that both\nState and non-State actors have human rights obligations under customary international law\nover territory over which they exercise effective control and carry out government-like\nfunctions. Similarly, it accepted that all parties to non-international armed conflicts,\nincluding non-State actors, are bound by customary international law under those\ncircumstances."},{"id":"a-hrc-52-crp-8-p0042","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"42","seq":43,"section":"A. International human rights law","text":"Libya is bound by the United Nations Charter and has committed itself to advance\n“universal respect for, and observance of, human rights and fundamental freedoms for all\nwithout distinction as to race, sex, language, or religion.”36 Libya is also a State Party to many\nof the principal international human rights treaties, chiefly the International Covenant on\nCivil and Political Rights and its first Optional Protocol; the International Covenant on\nEconomic, Social and Cultural Rights; the Convention against Torture and Other Cruel\nInhuman or Degrading Treatment or Punishment; the International Convention on the\nElimination of all Forms of Racial Discrimination; the Convention on the Elimination of All\nForms of Discrimination against Women and its Optional Protocol; the International\nConvention on the Protection of the Rights of All Migrant Workers and Their Families; the\nConvention on the Rights of the Child and its Optional Protocols on the Involvement of\nChildren in Armed Conflict; and the Convention on the Rights of Persons with Disabilities.\nIn ratifying these treaties, Libya expressed its consent to be bound by the obligations\narticulated therein and accepted that its domestic laws cannot be invoked to justify a failure\nto comply.37"},{"id":"a-hrc-52-crp-8-p0043","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"43","seq":44,"section":"A. International human rights law","text":"Libya has not signed or ratified the Convention for the Protection of All Persons from\nEnforced Disappearance, but several provisions of the International Covenant on Civil and\nPolitical Rights are infringed by enforced disappearance. 38 In any case, enforced\ndisappearance was considered to have attained the status of jus cogens."},{"id":"a-hrc-52-crp-8-p0044","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"44","seq":45,"section":"A. International human rights law","text":"Libya also committed itself to abide by provisions of regional human rights treaties,\nincluding the African Charter on Human and Peoples’ Rights, the African Charter on the\nRights and Welfare of the Child, and the Arab Charter on Human Rights. It also accepted the\njurisdiction of the African Court on Human and Peoples’ Rights."},{"id":"a-hrc-52-crp-8-p0045","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"45","seq":46,"section":"A. International human rights law","text":"When making its findings, the Mission took account of the content of the international\nand regional treaties ratified, as well as General Comments and jurisprudence issued by the\ncorresponding treaty bodies such as courts and committees, Special Rapporteurs and working\ngroups, as applicable."},{"id":"a-hrc-52-crp-8-p0046","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"46","seq":47,"section":"A. International human rights law","text":"Additionally, the Mission relied on soft law instruments in its analysis of the\napplicable human rights law, including the Declaration on the Protection of Persons from\nEnforced Disappearances; the Guiding Principles on Internal Displacement; the Basic\nPrinciples on the Use of Force and Firearms by Law Enforcement Officials; the Updated Set\nof Principles for the Protection and Promotion of Human Rights through Action to Combat\nImpunity; the Basic Principles and Guidelines on the Right to a Remedy and Reparation for\nVictims of Gross Violations of International Human Rights Law and Serious Violations of\nInternational Humanitarian Law; the Standard Minimum Rules for the Treatment of\nPrisoners39; the Body of Principles for the Protection of All Persons under Any Form of\nDetention or Imprisonment; the United Nations Declaration on the Rights of Persons\nBelonging to National or Ethnic, Religious and Linguistic Minorities; the International\nConvention on the Protection of the Rights of All Migrant Workers and Members of Their\nFamilies; the Protocol to Prevent, Suppress and Punish Trafficking in Persons Especially\nWomen and Children, and the Protocol against the Smuggling of Migrants by Land, Sea and\nAir, both supplementing the United Nations Convention against Transnational Organized\nCrime; and the Declaration on the Protection of Women and Children in Emergency and\nArmed Conflict."},{"id":"a-hrc-52-crp-8-p0047","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"47","seq":48,"section":"B. International humanitarian law","text":"International humanitarian law regulates the conduct of parties engaged in an armed\nconflict. Given that the alleged violations of international humanitarian law in Libya took\nplace in the context of either an armed conflict opposing the Libyan State’s armed forces\nagainst a non-State armed group, or an armed conflict involving two or more non-State armed\ngroups, the Mission applied international customary law and treaty rules relevant to non-\ninternational armed conflicts since 2016."},{"id":"a-hrc-52-crp-8-p0048","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"48","seq":49,"section":"B. International humanitarian law","text":"Parties to non-international armed conflicts are obliged to, at a minimum, treat persons\ntaking no active part in hostilities and those hors de combat humanely, without any adverse\ndistinction. Violence to life and person is prohibited, in particular murder of all kinds,\nmutilation, cruel treatment and torture, taking of hostages, outrages upon personal dignity as\nwell as the passing of sentences and the carrying out of executions without previous judgment\npronounced by a regularly constituted court, respecting the generally recognized principles\nof fair trial and due process."},{"id":"a-hrc-52-crp-8-p0049","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"49","seq":50,"section":"B. International humanitarian law","text":"Furthermore, parties to armed conflicts must always abide by the principles of\ndistinction, proportionality and precautions in attack. Attacks are prohibited where they are\nexpected to cause incidental loss of life, injury to civilians, damage to civilian objects or a\ncombination thereof, which would be excessive in relation to the concrete and direct military\nadvantage anticipated. Parties must also take all feasible precautionary measures to avoid,\nand in any event to minimize, incidental loss of civilian life, injury to civilians and damage\nto civilian objects."},{"id":"a-hrc-52-crp-8-p0050","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"50","seq":51,"section":"B. International humanitarian law","text":"Libya, the de facto authorities, and foreign States are responsible for all violations of\ninternational humanitarian law committed by their armed forces or those acting under their\ninstruction, direction, or control."},{"id":"a-hrc-52-crp-8-p0051","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"51","seq":52,"section":"B. International humanitarian law","text":"Violations of international humanitarian law may constitute war crimes. In the context\nof non-international armed conflicts, they are serious violations of common article 3 of the\nGeneva Conventions of 1949. The Mission qualified violations as war crimes where a nexus\nto an armed conflict was established."},{"id":"a-hrc-52-crp-8-p0052","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"52","seq":53,"section":"C. International criminal law","text":"To appropriately characterize the human rights and international humanitarian law\nviolations occurring in Libya, the Mission considered and applied where appropriate\ninternational criminal law. Notably, crimes against humanity have generally been referred to\nas “systematic or mass violations of human rights” and underlying acts of crimes against\nhumanity (for example, torture, enforced disappearance, imprisonment, and slavery) are\nviolations incorporated into international human rights treaties, most of which are binding on\nLibya."},{"id":"a-hrc-52-crp-8-p0053","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"53","seq":54,"section":"C. International criminal law","text":"The Mission adopted a broad view of accountability that extended beyond individual\ncriminal responsibility and recognized victims’ rights to truth and effective remedy/\nreparation, including guarantees of non-reoccurrence as essential components of transitional\njustice. The Mission thus approached the accountability aspect of its mandate in recognition\nof the fact that it was neither a judicial nor a prosecutorial body. It could not make final\ndeterminations of individual criminal responsibility. That said, it could determine whether its\nevidence establish reasonable grounds to believe that violations of international human rights\nlaw and international humanitarian law had occurred."},{"id":"a-hrc-52-crp-8-p0054","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"54","seq":55,"section":"C. International criminal law","text":"The Mission accordingly made legal findings on crimes against humanity and war\ncrimes consistent with its evidentiary standard."},{"id":"a-hrc-52-crp-8-p0055","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"55","seq":56,"section":"V. Political context","text":"The current situation in Libya can be traced back to the Muammar Qadhafi regime\nand its fall during a civil war that erupted after peaceful demonstrations. The peaceful\ndemonstrations aimed at “achieving reforms in governance and more particularly seeking to\nsee the regime evolve into a democratic form of government subject to the rule of law and\nupholding human rights”.40 The first Libyan parliamentary elections were subsequently held\non 7 July 2012.41 Afterwards, the National Transitional Council handed over power to the\nnewly elected General National Congress tasked with forming an interim government and\ndrafting a permanent constitution to be approved by referendum.42"},{"id":"a-hrc-52-crp-8-p0056","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"56","seq":57,"section":"V. Political context","text":"In February 2014, the Constitution Drafting Assembly was elected by popular vote. 43\nIt adopted in 2017 a draft constitutional declaration with the intention to put it to a popular\nvote.44 A referendum on the draft constitutional declaration had not been held by the end of\nthe Mission’s mandate."},{"id":"a-hrc-52-crp-8-p0057","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"57","seq":58,"section":"A. Transition from General National Congress to the Libyan Political","text":"The General National Congress established a roadmap committee to address the\ntransitional period after 7 February 2014.45 On 3 February 2014, the General National\nCongress stipulated that it would continue to exist until its authority could be transferred to\na constitutionally elected legislative body, subject to the completion of the constitution\nprocess.46 The General National Congress’ decision was opposed by Khalifa Haftar in\nparticular, a former military commander of and chief of staff to Qadhafi. Haftar voiced his\nopposition in a speech on 14 February in which he also, in absence of a formal appointment\nat the time, announced the roadmap of the Libyan National Army (LNA). 47"},{"id":"a-hrc-52-crp-8-p0058","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"58","seq":59,"section":"A. Transition from General National Congress to the Libyan Political","text":"These developments set the stage for numerous violent clashes and armed conflicts in\nand around 2014 and 2015, that were divided along geographical areas of Libya and\ncharacterized by shifting alliances. One of the major armed conflicts erupted in May 2014\nwhen Khalifa Haftar launched Operation Dignity in eastern Libya to eradicate so-called\n“radical terrorist” groups from eastern Libya.48 Haftar’s forces were joined by other\nbrigades.49 Around the same time, armed groups in West Libya aligned with the General\nNational Congress in Tripoli formed the Libya Dawn coalition to counter Operation Dignity\nand evict Zintan-based brigades from Tripoli.50 Operation Dignity and Libya Dawn engaged\nin hostilities, that spread into Tripoli, Benghazi, and southern Libya.51"},{"id":"a-hrc-52-crp-8-p0059","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"59","seq":60,"section":"A. Transition from General National Congress to the Libyan Political","text":"The House of Representatives (HOR) was formed following a June election provided\nfor by the General National Congress.52 The HOR convened for the first time on 4 August\n2014 in the east of Libya, in Tobruk,53 and later declared its support for Operation Dignity.54"},{"id":"a-hrc-52-crp-8-p0060","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"60","seq":61,"section":"A. Transition from General National Congress to the Libyan Political","text":"Libya Dawn called upon the former General National Congress to reconvene,\nclaiming that the transitional caretaker government and the newly elected HOR had violated\nthe Constitutional Declaration and consequently lost legitimacy. 55 Sections of the\nGovernment of National Congress reconstituted itself, then created a parallel government\n(Government of National Salvation) that took control of Tripoli-based ministries and other\nState institutions. It supported the Libya Dawn campaign.56"},{"id":"a-hrc-52-crp-8-p0061","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"61","seq":62,"section":"A. Transition from General National Congress to the Libyan Political","text":"On 17 December 2015, the Libyan Political Agreement, also known as the “Skhirat\nAgreement”, was signed. The Libyan Political Agreement rests on four main principles,\nnamely ”ensuring the democratic rights of the Libyan people, the need for a consensus\ngovernment based on the principle of the separation of powers, oversight and balance\nbetween them, and the need to empower State institutions like the Government of National\nAccord (GNA) so that they can address the serious challenges ahead, respect for the Libyan\njudiciary and its independence”.57 The agreement provided for the formation of the GNA\nwith a Presidency Council, the High Council of State, and a roadmap for a transition to a\nunified government structure.58 It also affirmed the HOR as the legislative body during\ntransitional period.59 Although the HOR endorsed the Libyan Political Agreement on 25\nJanuary 2016, it did not accept the GNA.60"},{"id":"a-hrc-52-crp-8-p0062","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"62","seq":63,"section":"B. The Libyan Political Agreement and 2020 ceasefire","text":"Despite the signing of the Libyan Political Agreement, the GNA struggled to gain the\nsupport of all parties. This lack of stability influenced the resurgence of fighting of varying\nintensity, in the east, west and south of the country, including a non-international armed\nconflict from April 2019 to June 2020 between the LAAF and the GNA.61"},{"id":"a-hrc-52-crp-8-p0063","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"63","seq":64,"section":"B. The Libyan Political Agreement and 2020 ceasefire","text":"In April 2019, the LAAF initiated a military campaign to seize control of the Tripoli,\nwhich was effectively under the control of the GNA. 62 After 14 months of intense fighting\nthe offensive against Tripoli came to an end in June 2020.63"},{"id":"a-hrc-52-crp-8-p0064","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"64","seq":65,"section":"B. The Libyan Political Agreement and 2020 ceasefire","text":"Notwithstanding the United Nations imposed arms embargo, parties to the conflict\nreceived military support from foreign actors.64 These included Turkey and Qatar on the GNA\nside, and Egypt, Jordan, Saudi Arabia, and the United Arab Emirates on the LAAF side.\nDifferent Chadian and Sudanese armed groups supported both sides65, and there is a reliable\nbody of information indicating that individuals associated with ChVK Wagner, a company\nregistered in Russia, were present in Libya in support of the LAAF.66"},{"id":"a-hrc-52-crp-8-p0065","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"65","seq":66,"section":"B. The Libyan Political Agreement and 2020 ceasefire","text":"Between January and October 2020, the high-level Berlin conference and 5+5 Joint\nMilitary meetings were held on the resolution of the conflict in Libya with parties and\nconcerned international actors.67 These events eventually paved the way for the conclusion\nof the Agreement for a Complete and Permanent Ceasefire by forces affiliated with the GNA\nand the LAAF on 3 October 2020 and the creation of the Libyan-led ceasefire monitoring\nmechanism68."},{"id":"a-hrc-52-crp-8-p0066","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"66","seq":67,"section":"C. From 2020 ceasefire until present-day","text":"Based on Security Council resolution 2510 of 2020, the first round of the Libyan\nPolitical Dialogue Forum took place in Tunis from 7 to 15 November 2020.69 This forum\nadopted on 15 November 2020 the Roadmap for the \"Preparatory Phase for a Comprehensive\nSolution” based on Article 64 of the Libyan Political Agreement providing for the\nestablishment of the Government of National Unity (GNU) and the convening of presidential\nand parliamentary elections in December 2021.70 Following a vote in the HOR in March\n2021, the GNU was installed71 and mandated to prepare for elections at the end of 2021.72"},{"id":"a-hrc-52-crp-8-p0067","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"67","seq":68,"section":"C. From 2020 ceasefire until present-day","text":"Two days prior to the planned elections in December 2021, the High National\nElections Commission declared that it could not organise the elections due to inadequacies\nin the electoral legislation and irregularities in the judicial process relating to the eligibility\nof candidates.73"},{"id":"a-hrc-52-crp-8-p0068","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"68","seq":69,"section":"C. From 2020 ceasefire until present-day","text":"In February 2022, the HOR appointed, through a contested vote, the former Minister\nof Interior Fathi Bashaga to form a new Government of National Stability. It argued that the\nmandate of the GNU had expired because of its failure to organize timely elections.74"},{"id":"a-hrc-52-crp-8-p0069","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"69","seq":70,"section":"C. From 2020 ceasefire until present-day","text":"The deadlocked political situation in Libya was exacerbated by the appointment of\nthe Government of National Stability and the still-existent internationally recognised GNU\nled by Abdul Hamid Dbeibah.75 This division, also led to armed clashes between forces loyal\nto the two rival governments, as in Tripoli in May and August 2022, with the latter being the\nworst outbreak of violence in two years.76"},{"id":"a-hrc-52-crp-8-p0070","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"70","seq":71,"section":"VI. Financial and economic situation in Libya","text":"Libya has one of the largest known oil and gas reserves in Africa and the potential for\nwealth is significant. However, the volatile political situation in Libya since 2011, coupled\nwith the outbreak of the COVID-19 pandemic and recurrent armed conflicts both in Libya\nand abroad, including in Ukraine, dramatically impacted the Libyan economic-financial\nfabric, economic growth, and affordability of essential goods. 77 Economic-financial\ninequality led to an increase in malnourishment and low-quality diets,78 particularly affecting\nvulnerable households.79 In 2021, the GDP per capita estimates were about half of their value\nin 2010.80"},{"id":"a-hrc-52-crp-8-p0071","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"71","seq":72,"section":"VI. Financial and economic situation in Libya","text":"In 2021, Libya was ranked 172 out of 180 countries in Transparency International’s\nCorruption Perception Index indicating a very high level of corruption. 81 The acutely\nundiversified economy of Libya is predominantly dependent on oil and gas exports, over\nwhich access and ownership is highly contentious.82 In 2020 the export of fuels made up 73\nper cent of the exports from Libya.83 While the majority of the population is located in the\nNorth-West of the country, natural resources, including oil and water, are largely\nconcentrated in the East and South.84"},{"id":"a-hrc-52-crp-8-p0072","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"72","seq":73,"section":"VI. Financial and economic situation in Libya","text":"The Central Bank of Libya (CBL) receives financing from the National Oil\nCompany.85 The Libyan treasury generates income by sovereign revenues primarily from oil,\ngas and derivates trade. It also generates revenues from inter alia taxes and other fees on\neconomic activities, customs, telecom charges, CBL profit distribution, fuel sale in the local\nmarket, and public services fees.86 The Libyan State has also received funding from the EU 87\nand its member States, including Italy.88"},{"id":"a-hrc-52-crp-8-p0073","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"73","seq":74,"section":"VII. Repression of fundamental freedoms","text":"A considerably high proportion of all the cases investigated by the Mission since it\nwas dispatched concern the repression of dissent. The Mission observed from the evidence\nthat it collected that violations of the rights to freedom of expression, assembly, association,\nand belief were committed at a large scale by the State and affiliated actors as part of their\nconsolidation of control over a particular geographical area, group, alliance, revenue stream,\nor natural resource."},{"id":"a-hrc-52-crp-8-p0074","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"74","seq":75,"section":"VII. Repression of fundamental freedoms","text":"The repression of dissent occurred through the arbitrary killing, torture, rape, arbitrary\ndetention, and enforced disappearance of persons because of their actual or perceived sexual\norientation or gender identity, their criticism of the State and its affiliated armed groups, and\ntheir expression of divergent political, religious, and social views and norms, including their\nopposition to patriarchy and sexism. It was also evident from the plethora of restrictions\nplaced upon civil society. By example, the Civil Society Commission (CSC), supported by\nlegally the Supreme Judicial Council, further tightened in early 2023 the criteria for obtaining\nand gaining recognition of registration, potentially rendering existing registrations invalid.\nThe CSC has also been demanding that civil society organisations receive permission to\nengage with foreign missions."},{"id":"a-hrc-52-crp-8-p0075","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"75","seq":76,"section":"VII. Repression of fundamental freedoms","text":"Relatedly, the Mission witnessed a hardening of the public discourse around\nauthorities’ position on women’s rights and gender equality. Activism around gender equality\nhas been quelled and both women and men were subjected to sexual and gender-based\nviolence if they were perceived to behave in socially, culturally, and religiously unacceptable\nways."},{"id":"a-hrc-52-crp-8-p0076","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"76","seq":77,"section":"VII. Repression of fundamental freedoms","text":"A significant number of the cases documented by the Mission were connected to an\nincreased adherence to conservative Salafist-leaning ideologies. Witnesses recalled to the\nMission the presence of so-called “Madkhali-Salafist” followers during interrogation and\ndetention and the invocation of religious values during the infliction of torture and sexual and\ngender-based violence. Armed actors, in particular those that ascribe to Salafist-leaning\nideologies, have gained ground in Libya. The Mission noted in this regard the deep,\nextensive, and ongoing absorption of militias and other armed groups into the State apparatus\nthat violate international law for the purpose of entrenching or establishing total control and\npower over Libyans and Libyan territory."},{"id":"a-hrc-52-crp-8-p0077","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"77","seq":78,"section":"VII. Repression of fundamental freedoms","text":"Notably, the Mission found that State affiliated entities such as Libya’s Deterrence\nApparatus for Combating Organized Crime and Terrorism (DACOT, also known as Radaa),\nthe Libyan Arab Armed Forces (LAAF), the Internal Security Agency (ISA), and the Stability\nSupport Apparatus (SSA) were repeatedly involved in violations and abuses that affected the\nenjoyment of fundamental freedoms. As provided in detail in section XI, all these bodies are\nlinked to the Libyan State."},{"id":"a-hrc-52-crp-8-p0078","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"78","seq":79,"section":"VII. Repression of fundamental freedoms","text":"The arrest, detention, and punishment of individuals for their alleged membership of\nthe Tanweer movement is emblematic of Libya’s gradually shrinking civic space. According\nto its now defunct website, the Tanweer is an organisation working to spread the principles\nof human rights, equality, and non-discrimination. Between November 2021 and March\n2022, seven young activists, including a migrants’ rights defender, had “confessions”\nrecorded on video in which they declared that they are members of Tanweer, atheists,\nagnostics, feminists, and seculars. The recordings also implicated persons that were not\narrested and detained. These video recordings, which appear to have been recorded under\nduress, were posted on ISA’s Facebook page and website."},{"id":"a-hrc-52-crp-8-p0079","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"79","seq":80,"section":"VII. Repression of fundamental freedoms","text":"In December 2022, four of the men that appeared on the ISA recordings were\nsentenced to three-year imprisonment “with hard labour” and fined by a domestic court in\nTripoli. The Mission is concerned that the evidence relied upon was extracted under coercive\ncircumstances, and without lawyers present. The Mission is also concerned that the legal\nprovisions used to convict the men are inconsistent with the principle of legality and\ninternational human rights law."},{"id":"a-hrc-52-crp-8-p0080","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"80","seq":81,"section":"VII. Repression of fundamental freedoms","text":"The right to hold a belief or not is absolute and cannot be derogated or abrogated\nduring a state of emergency or armed conflict. However, manifestation of one’s belief,\nfreedom of expression, association, and assembly may be restricted exceptionally, subject to\nnecessity, justification, and proportionality. In the case of the right to hold a belief, the\nrestriction is contingent upon its absolute and non-derogable nature. Considering this, some\nof the vague terminology used in Libyan legislation, including the Publications Law, is\nincompatible with the principle of legality and the right to freedom of expression which\nrequire that laws are sufficiently precise to enable an individual to regulate his or her\nbehaviour.89 The Libyan Penal Code, for example, stipulates the death penalty for “any views\nor principles” that aim to overthrow the political, social, or economic order of the State 90 and\nproscribes blasphemy.91 Similarly, the Law on Telecommunications holds that the publishing\nof information and data that “harms the political, economic, social, or cultural heritage of\nLibyan Arab society” is punishable.92"},{"id":"a-hrc-52-crp-8-p0081","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"81","seq":82,"section":"VII. Repression of fundamental freedoms","text":"The Mission is particularly alarmed by the Anti-Cybercrime law that came into effect\nin October 2022. It affords the Libyan authorities’ extensive discretionary powers to restrict\nand criminalize online freedom of expression, opinion, and belief because of “public order\nand morality”.93 The Mission received reports that the law was relied upon on for the arrest\nand detention of Ahlam al-Yamani and Haneen al-Abdali in February 2022. A statement by\nthe Ministry of the Interior held that the women were arrested for “violating public morals\nand insulting the status of chaste and dignified Libyan women in our conservative society”.\nThe law could exacerbate an already constricted and heavily monitored online space and\nprovide another legal avenue through which to punish persons that do not conform to the\nnorms and views of the authorities."},{"id":"a-hrc-52-crp-8-p0082","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"82","seq":83,"section":"VII. Repression of fundamental freedoms","text":"The above referenced legislation and attacks against inter alia human rights defenders,\nwomen rights activists, journalists, and civil society associations have already created an\natmosphere of fear that has led to self-censorship and sent persons into hiding or exile."},{"id":"a-hrc-52-crp-8-p0083","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"83","seq":84,"section":"A. Arbitrary arrest and unlawful detention","text":"The pervasive and widespread deprivation of liberty inflicted on Libyans and other\nnon-migrants in detention centres across the country has been a feature of all the Mission’s\nreports. Since its establishment, the Mission conducted over 134 interviews with current and\nformer detainees, their relatives, insider witnesses, and/or other individuals with respect to\nover 41 sites of detention throughout Libya. The Mission also obtained large amounts of\ncorroborating and other pieces of evidence regarding violations of international law occurring\nat these detention centres, including “secret prisons”. In total, Government numbers place the\nofficial number of detainees at 18,523, but evidence collected by the Mission indicated that\nthe true number of individuals detained is likely much higher."},{"id":"a-hrc-52-crp-8-p0084","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"84","seq":85,"section":"A. Arbitrary arrest and unlawful detention","text":"The vast number of cases of deprivation of liberty documented by the Mission were\narbitrary. A common method of arrest entailed the interception of victims by groups of\nmasked and armed men at home or in public spaces, including on the streets or at airports.\nThe identity of the group arresting the victim could occasionally be deduced from markings\non the vehicle used to transfer the victim to a place of detention. The Mission also\ndocumented cases where the group identified itself to the victim. The arbitrary arrest occurred\nunder coercion, physical violence, intimidation, with victims typically blindfolded and/or\nhandcuffed. Victims were not presented arrest or search warrants, nor were they informed of\ntheir rights."},{"id":"a-hrc-52-crp-8-p0085","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"85","seq":86,"section":"A. Arbitrary arrest and unlawful detention","text":"Almost all the victims and witnesses the Mission interviewed were never confronted\nwith evidence against them and held without charge. Detainees interviewed were held\narbitrarily for periods of hours to years. In some cases, victims were subsequently brought\nup on baseless “terrorism” charges, and tried in proceedings that fall short of due process\nguarantees."},{"id":"a-hrc-52-crp-8-p0086","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"86","seq":87,"section":"A. Arbitrary arrest and unlawful detention","text":"The arbitrary arrest of a retired businessman is emblematic. The victim, who had\nbegun to write frequently online on the poor living conditions and lack of salaries of people\nin Libya, was arbitrarily arrested in 2022 under violent circumstances. The victim was exiting\na mosque after Friday prayers, when confronted by eleven people, some wearing civilian\nclothes and others wearing military uniforms. As the men attempted to seize the victim, other\nworshippers began to defend the victim and a melee ensued. The perpetrators shot into the\nground and air to disperse the worshippers. The commotion ended with the victim\nincapacitated on the ground whereupon he was dragged by his feet into the back of a pickup\ntruck that eventually departed with him. The victim was held at different locations, including\nal-Kwaifiya prison. Family members of the victim were unaware of the victim’s whereabouts\nfor an extended period of time. The victim was released in 2023."},{"id":"a-hrc-52-crp-8-p0087","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"87","seq":88,"section":"A. Arbitrary arrest and unlawful detention","text":"Likewise, the case of Issa Buhedma illustrates the practice of arbitrary detention\nagainst persons because of their political activity and views. Mr. Buhedma, who is from\nBenghazi, has been detained in Mitiga detention centre complex since 2017. He was detained\nincommunicado for 45 days and tortured. He remains held in inhumane conditions. Mr.\nBuhedma’s family has repeatedly urged the relevant authorities, including the Attorney\nGeneral and the Chair of the Presidential Council, to either charge and try or release the\nvictim, to no avail."},{"id":"a-hrc-52-crp-8-p0088","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"88","seq":89,"section":"A. Arbitrary arrest and unlawful detention","text":"Arbitrary arrest and detention were used on a large scale across Libya, with the\nknowledge of the authorities in control of detention centres. For example, senior officials at\nMitiga detention centre complex in Tripoli, which is under the control of Radaa, organized\nin 2017 and 2018 so-called “sorting lines” made up of thousands of individuals in which\nsenior officials interviewed detainees about the details of their cases. The detainees were\nasked why they were detained in the first place. Only the 2018 sorting line resulted in the\nrelease of detainees. While the precise reasons for the “sorting lines” remained unclear, they\ndemonstrated that prison officials either did not know why detainees were being held or were\nindifferent to their unjust detention."},{"id":"a-hrc-52-crp-8-p0089","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"89","seq":90,"section":"A. Arbitrary arrest and unlawful detention","text":"Libyan judicial authorities have also been aware of the illegal practices of arbitrary\narrest and unlawful detention. Mission investigators received many accounts of release orders\nissued by the appropriate Libyan authorities that were either not honoured or only carried out\nat a much later date, typically after enough political pressure was applied on prison officials.\nIt was common practice among prison administrations to ignore Libyan judicial and\nprosecutorial orders for release."},{"id":"a-hrc-52-crp-8-p0090","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"90","seq":91,"section":"A. Arbitrary arrest and unlawful detention","text":"An advocate for detainees’ rights explained that detainees held at Mitiga detention\ncentre complex were (a) either not presented to the Public Prosecution at all, (b) were\npresented to the Public Prosecution, and received a decision declaring their innocence and\nordering their release that was not implemented, or (c) were presented to civilian courts and\nthen transferred to military courts."},{"id":"a-hrc-52-crp-8-p0091","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"91","seq":92,"section":"B. Enforced disappearance","text":"Cases investigated by the Mission confirmed that enforced disappearances frequently\noccurred in the Libyan context alongside arbitrary detention. The Mission found that persons\nwere subjected to enforced disappearance in Libya within the temporal scope of its mandate\nby, or through affiliated armed groups of, the GNU led by Abdul Hamid Dbeibah, and the\nLAAF, led by Khalifa Haftar. Enforced disappearances documented by the Mission occurred\nin response to perceived criticism against groups and leadership in control over a particular\narea, on the basis of the victim’s origin (perceived alliance to or agreement with a group in\ncontrol of an area solely based on birthplace), or the victim’s perceived family ties to groups\nor their leadership."},{"id":"a-hrc-52-crp-8-p0092","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"92","seq":93,"section":"B. Enforced disappearance","text":"In this regard, the Mission continued to investigate the enforced disappearance of\nSiham Sergiwa throughout its mandate extensions. Ms. Sergiwa was an elected independent\nmember of the Libyan HOR when she was abducted from her home in the heavily secured\nBu Hadimah district of Benghazi during the afternoon of 17 July 2019 by around 25-30 armed\nmen wearing masks and uniforms. Violent confrontations erupted between the intruders and\nfamily during the search for and abduction of Ms. Sergiwa. Ms. Sergiwa had given an\ninterview the day before her abduction in which she inter alia opposed the LAAF attack on\nTripoli."},{"id":"a-hrc-52-crp-8-p0093","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"93","seq":94,"section":"B. Enforced disappearance","text":"Benghazi was effectively and tightly controlled by the LAAF and its commander\nKhalifa Haftar at the time of the abduction of Ms. Sergiwa. The scale and sophistication of\nthe operation suggest that the top LAAF leadership knew or should have known of the\nabduction and fate of the victim. The Mission found reasonable grounds to believe that LAAF\nleadership failed to take reasonable measures to submit these cases to competent authorities\nfor effective, genuine, and independent investigation and prosecution."},{"id":"a-hrc-52-crp-8-p0094","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"94","seq":95,"section":"B. Enforced disappearance","text":"The Mission also investigated the enforced disappearance of Mansour Mahmoud Atti,\na human rights activist, head of the Red Crescent Committee and Civil Society Commission\nof Adjabiyah, and producer of a popular television series. On 3 June 2021, Mr. Atti was\nabducted and detained by LAAF affiliated Brigade 302. His family’s request for information\nfrom the brigade was not met. Only in August 2021, did the General Command of the LAAF\ninformed Mr. Atti’s family that they were detaining him, that he was alive, and that he would\nnot be released until after the election set to occur in December 2021. Mr. Atti was released\non 2 April 2022."},{"id":"a-hrc-52-crp-8-p0095","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"95","seq":96,"section":"B. Enforced disappearance","text":"The Mission established that Mr. Atti was blindfolded and handcuffed, kept in solitary\nconfinement and in inhumane conditions. He was detained, without due process, in a Brigade\n302 prison in Ganfouda before being transferred to a prison operated by the Tariq bin Ziyad\nbrigade (TBZ). He was arbitrarily detained by the TBZ for approximately six months, during\nwhich he was held in solitary confinement. The Mission found reasonable grounds to believe\nthat Mr. Atti was a victim of arbitrary detention, torture and enforced disappearance. His\nfamily was also deprived of the right to know about his fate and whereabouts until two\nmonths after his abduction."},{"id":"a-hrc-52-crp-8-p0096","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"96","seq":97,"section":"B. Enforced disappearance","text":"The Mission also made a finding on enforced disappearance and arbitrary detention\nof a TV personality in 2022 by TBZ for airing comments critical of a politician. Family\nmembers did not know of the victim’s whereabout for the first three months. They were too\nintimidated to make a formal complaint but did search local security agencies. The victim,\nwho was held in several locations, including Gernada prison, was subjected to various forms\nof torture and inhumane conditions. The victim was released after 100 days."},{"id":"a-hrc-52-crp-8-p0097","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"97","seq":98,"section":"B. Enforced disappearance","text":"Another two cases of enforced disappearance in the LAAF-controlled Gernada prison\nconcerned Ahmed Mustafa and Ali Omar, known as Ali Alaspli. Both men, who were online\ncritics of LAAF leaders, were abducted by armed LAAF members under coercive\ncircumstances in two distinct but interrelated incidents in March 2016. They were held\ncaptive at the home of then-LNA commander Ahmad al-Ghourour for three nights before\nthey were taken to Gernada prison and placed in solitary confinement in a secret wing,\nreportedly guarded by men that subscribed to the “Madkhali-Salafist” ideology. The victims\nwere beaten and deprived of sufficient food and basic amenities. Family members were\ninformed of the detainees’ whereabouts after around three months. The victims were\neventually released after four months in detention. The Mission collected significant\nevidence on the detention of individuals similarly held incommunicado, in secret sections of\nlarger prisons, such as in Gernada prison, or in seemingly stand-alone secret prisons."},{"id":"a-hrc-52-crp-8-p0098","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"98","seq":99,"section":"B. Enforced disappearance","text":"The Mission also documented the enforced disappearance of persons because of their\nplace of origin and family links. In an incident investigated by the Mission, armed men\nsearching for individuals from eastern Libya at a café in Tripoli abducted around six men.\nThe Mission found that at least one of the victims from eastern Libya was taken to Mitiga\nairport where he was interrogated about other persons from the east living in Tripoli and\ntortured over a two-day period. The victim was shackled and hung upside down, in the so-\ncalled balanco position, his hair was burnt with a lighter, and his reproductive organs were\nhit and squeezed with pliers. The victim was subsequently transferred to a prison within the\nMitiga airport complex where there was a continuation of the cruel and inhuman treatment.\nThe victim was held incommunicado until 2017. He was only permitted to call his family\nafter one year and ten months of his abduction from the café. His father, who had inquired\nabout the victim and filed complaints on his disappearance, died before his son could contact\nthe family. There are reasonable grounds to believe that victim was subjected to enforced\ndisappearance, for close to two years and arbitrary detention for seven years, as crimes\nagainst humanity. The victim was released from Mitiga prison in 2022."},{"id":"a-hrc-52-crp-8-p0099","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"99","seq":100,"section":"B. Enforced disappearance","text":"The Mission reported on several incidents of the crime against humanity of enforced\ndisappearance in Tarhuna in 2022.94 From the evidence uncovered, the Mission found that\nvictims were disappeared or killed around 2019-2020 by members of the al-Kaniyat militia\nfor a range of reasons including, inter alia, family ties to persons with perceived or actual\naffiliation with the 2011 Libyan revolution against the Qadhafi regime and opposition to the\nLAAF. Between 2015 and 2018, the al-Kaniyat militia carried out similar crimes, including\nenforced disappearances and killings, at the behest of successive governments in Tripoli\nagainst perceived or actual opponents to those governments. Regardless of their allegiances,\nthe al-Kaniyat leadership instilled fear and maintained unchallenged control over the\npopulation in and around Tarhuna using widespread criminality, most acutely enforced\ndisappearances and extrajudicial killings. Over 200 persons remain missing in Tarhuna."},{"id":"a-hrc-52-crp-8-p0100","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"100","seq":101,"section":"B. Enforced disappearance","text":"The Mission made a finding on enforced disappearance of Zahra Maatouq because of\nher perceived family ties during its last mandate extension. Ms. Maatouq was summoned in\nDecember 2019 to the Tarhuna police station to provide proof of her husband’s identity who\nwas taken from their home days earlier. According to witnesses, Ms. Maatouq met her\nhusband at the police station but appeared shaken in her last communication with her family.\nMs. Maatouq’s body was exhumed from a mass-grave in 2020. It is established that she died\nfrom gunshot wounds to the head, torso, and pelvis. The Mission found reasonable grounds\nto believe that Ms. Maatouq was a victim of enforced disappearance as a crime against\nhumanity and murder as a crime against humanity and war crime."},{"id":"a-hrc-52-crp-8-p0101","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"101","seq":102,"section":"C. Torture and other cruel, inhuman or degrading treatment","text":"Nearly all former Libyan detainees and family members of detainees that were\ninterviewed by the Mission reported treatment that may amount to torture, cruel, inhuman or\ndegrading treatment. The widescale infliction of torture, cruel, inhuman or degrading\ntreatment was recorded in all prisons investigated by the Mission, irrespective of prison\nlocation and entity in control of the detainees. There are reasonable grounds to believe that\nthe SSA, Radaa, ISA, LAAF and affiliated groups systematically subjected detainees to\ntorture, cruel, inhuman, or degrading treatment since 2016."},{"id":"a-hrc-52-crp-8-p0102","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"102","seq":103,"section":"C. Torture and other cruel, inhuman or degrading treatment","text":"Combinations of similar harmful techniques were applied during interrogations across\nprisons in Libya. These included flogging with sharp or hard instruments such as PPR pipes,\nelectrocution, punching, kicking, placing detainees’ bodies in forced positions for lengthy\nperiods of time, primarily by hanging them upside down in the balanco position, and extended\nsolitary confinement. The Mission also documented the use and threat of sexual assault\nduring interrogation, elaborated on in section VII.D."},{"id":"a-hrc-52-crp-8-p0103","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"103","seq":104,"section":"C. Torture and other cruel, inhuman or degrading treatment","text":"Several detainees reported to the Mission that they had their head shaved during\ninterrogation, or were threatened to have it shaved, as a measure of causing humiliation and\nharm. Denigrating language was routinely hurled at detainees, who were accused of being\nspies, non-believers, acting in contravention with religious and social norms and values, and\nharmful to society."},{"id":"a-hrc-52-crp-8-p0104","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"104","seq":105,"section":"C. Torture and other cruel, inhuman or degrading treatment","text":"Conditions in detention were consistently inhumane. Detainees described\novercrowded cells, confinement to exceptionally small spaces, shortages in basic amenities\nincluding lavatories, substandard and insufficient quantities of food, water deficiency, and\nthe spread of infectious diseases such as scabies. Detainees also complained of a lack of\nsunlight, small windows, if any, an overall inadequate circulation of fresh air, revolting\nodour, and limited opportunities to physical exercise."},{"id":"a-hrc-52-crp-8-p0105","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"105","seq":106,"section":"C. Torture and other cruel, inhuman or degrading treatment","text":"The case of a victim of torture in detention for his involvement in and opinions on the\nneed for COVID-19 health restrictions illustrated the range of techniques that cause physical\nand emotional suffering, also against persons exercising their fundamental freedoms. The\nvictim was stopped on his way from work in October 2021, close to al-Marj in East Libya,\nby two Toyota Hilux cars with tinted windows, blindfolded and taken by force to al-Marj\nprison. Al-Marj prison is under de facto control of the LAAF. After spending two days in a\n1 by 2 metres cell, three bearded men, two of them in military attire and one wearing a\njalabiyya, took the victim out of the cell and flogged his feet about forty times. The victim\nwas told that the reason for the flogging was incitement to close mosques under the pretext\nof COVID-19. The victim crawled from the pain back into his cell where he stayed until the\nmen in military attire returned later in the day and took him to another place within the prison.\nAt the other location, the men hit the victim for around ten minutes with a PPR pipe while\nchanting “you are a secular, you are a stray dog, you are a spy”. They then shaved the victim’s\nhead. The victim was released after four months. He reported posttraumatic symptoms and\nphysical pain caused by the torture."},{"id":"a-hrc-52-crp-8-p0106","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"106","seq":107,"section":"C. Torture and other cruel, inhuman or degrading treatment","text":"In another case similarly motivated by a perceived divergence from religious and\nsocial norms and values, a young artist was tortured by a GNA loyal brigade in Sert for\norganizing a cultural activity during a sacred religious period. The victim was hit, kicked,\nsuspended in the balanco and falaka positions, and had his hair razored off. He also informed\nthe Mission that members of the brigade brought a coffin and buried him alive in it.\nInterrogators repeatedly questioned the victim about his sexual orientation and accused him\nof intending to destroy the Islamic values. The victim was released after a few days, after\nfalsely confessing under duress to supporting persons of diverse sexual orientation and\ngender-identities and promising to repent."},{"id":"a-hrc-52-crp-8-p0107","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"107","seq":108,"section":"C. Torture and other cruel, inhuman or degrading treatment","text":"Another emblematic case investigated by the Mission concerned a Libyan man in his\ntwenties who was abducted, tortured, and sexually harassed for wearing tattoos in 2022. The\nvictim was stopped on the streets in Tripoli by a group of armed and masked men, questioned\nabout his tattoo and adherence to Islam, and driven to an unidentified detention centre where\nhe was held together with others in a cell comparable to a “dog cage”. The victim described\nhow several men beat him with a stick on his entire body, told him to eat a big bowl of ice\ncubes, and repeatedly touched his genitalia over a two-day period. During the physical\ntorture, the victim was asked about the tattoos, his religious beliefs, and his sexual orientation.\nHe told the Mission that he now hides his tattoos and is weary about leaving his home after\nhis release from detention."},{"id":"a-hrc-52-crp-8-p0108","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"108","seq":109,"section":"C. Torture and other cruel, inhuman or degrading treatment","text":"Although most of the victims interviewed were male adults, the Mission also\ndocumented the torture, cruel, inhuman or degrading treatment of women. In one case, a\nwoman in her twenties was stopped in 2021 by ISA at a checkpoint in al-Marj and detained\nover allegations about her family members’ affiliation to Da’esh. In detention, she was\nrepeatedly hit on her back with a metal chair, beaten, and threatened with rape. An\ninterrogator called the victim a “whore”, sexually assaulted her, including by grabbing her\nbreasts, and threatened to falsely accuse her in the investigation report of having daily, sexual\nintercourse with an investigator."},{"id":"a-hrc-52-crp-8-p0109","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"109","seq":110,"section":"C. Torture and other cruel, inhuman or degrading treatment","text":"The Mission found reasonable grounds to believe that child detainees have also been\ntortured. In addition to the case of torture of a minor by Radaa recounted in paragraphs 117-\n118, the Mission made a finding of torture in detention of a 15-year boy in the east. The boy\nwas taken from his school by ISA in Benghazi in 2016 and detained without charge in\ndifferent locations until 2021 for allegedly communicating with a member of a “terrorist\norganization”. The boy was first taken to al-Nadja police station where he was instructed to\nundress and lie in his underwear on the ground and beaten with PPR pipes and electric wires.\nThe boy was also subjected to mock executions; he was told to kneel in front of a dug-out\nhole as interrogators placed a gun to his head and made to believe that a car would run over\nhim. When the victim’s father arrived at the police station, the interrogators beat up the father\nand son in front of each other. The victim described to the Mission how intimidating it was,\nhearing each other's screams. He also told the Mission that interrogators insulted his father\nin front of him and spit in his face."},{"id":"a-hrc-52-crp-8-p0110","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"110","seq":111,"section":"C. Torture and other cruel, inhuman or degrading treatment","text":"The child was subsequently transferred to al-Kwaifiya prison in the east of Libya.\nThere, he was moved between prison sections, and at times placed in solitary confinement\nand in cells with non-familial adult detainees. According to the victim, the treatment of\nprisoners deteriorated in 2019. Family visits were cancelled, punishments increased, and\nprivate belongings were confiscated. The victim explained that guards would come into\ndetainees’ cells at 10 o’clock at night and order them to go outside in the open air. When the\nguards were drunk, detainees would be forced to go out in the rain and roll in mud at night.\nThe victim reported inter alia overcrowding, insufficient amounts of food, deprivation of\nwater, and no access to education. There are reasonable grounds to believe that numerous\nchildren have been held at al-Kwaifiya prison. According to the evidence, the prison used to\nhave wings for child detainees."},{"id":"a-hrc-52-crp-8-p0111","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"111","seq":112,"section":"D. Sexual and gender-based violence","text":"The Mission’s investigations underscored that sexual and gender-based violence is\nwidely employed by Libyan State-affiliated actors, such as Radaa and ISA, as well as the\nLAAF to force confessions, punish, subjugate, terrify, and silence journalists, activists,\ndetainees, migrants, and women, including on the basis of persons’ actual or perceived sexual\norientation and gender identity.95 The Mission documented the use of sexual and gender-\nbased violence against both males and females."},{"id":"a-hrc-52-crp-8-p0112","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"112","seq":113,"section":"D. Sexual and gender-based violence","text":"Based on the collected evidence, acts of sexual and gender-based violence in the\nLibyan context included rape by sexual organ or an instrument, beating to the genitalia,\ntouching of the genitalia and breasts, threats of rape, threats of rape of family members, and\nforced undressing. Such acts also included interrogations about sexual preferences, sexual\nhistory, and sexual orientation, as well as the use of denigrating language and accusations of\na sexual nature."},{"id":"a-hrc-52-crp-8-p0113","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"113","seq":114,"section":"D. Sexual and gender-based violence","text":"In addition to cases of sexual violence recounted in section VII.C, the Mission\ndocumented the case of a young male journalist and advocate for women and the rights of\npersons of diverse sexual orientations and gender identities. The victim reported that he was\narbitrarily arrested and detained in the east of Libya for several days during the beginning of\n2019. While in detention, the victim, who was called an “an enemy of god”, suffered beatings\nto his genitalia, was hit with metal bars, and electrocuted. The victim was repeatedly\nthreatened to be raped and killed and told that his family would be burnt should he speak up\nafter his release from detention. The severe mental impact led him to consider suicide."},{"id":"a-hrc-52-crp-8-p0114","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"114","seq":115,"section":"D. Sexual and gender-based violence","text":"In another similar case, a woman activist advocating for women’s rights was\nsummoned by ISA in the east in 2020 for questioning. During the day-long interrogation, the\nvictim was asked about the human rights organization she established, its activities, including\non women’s rights and elections, the origin of her funding as well as her travels. The victim\ndescribed to the Mission being beaten, asked to remove her shirt and burned with a hot metal\nrod, insulted, and called “damaged”. The victim’s morality was questioned, and she described\nhaving been sexually harassed. Following her release, she received threats and pornographic\nmessages and images on her phone and Facebook account."},{"id":"a-hrc-52-crp-8-p0115","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"115","seq":116,"section":"D. Sexual and gender-based violence","text":"The Mission also documented the enforced disappearance, torture and sexual assault\nof Jaber Zain, for similar reasons as those of others mentioned above. Mr. Zain is a Sudanese\nmale who immigrated to Libya at the age of six and amassed a significant online following\nbecause of his posts and public talks on racism, freedom of religion, and women’s rights. Mr.\nZain was subjected to enforced disappearance for 20 months and arbitrarily detained for\nlonger than two years after his abduction in Tripoli on 25 September 2016 by armed members\nof the Second Special Support Forces of the Ministry of Interior in Tripoli. During his time\nin detention, Mr. Zain was interrogated about his writings, views on religion, relationship\nwith international organisations and embassies, and position on women. He was also accused\nof not being a Muslim and corrupting Libyan society. Mr. Zain was sexually assaulted, beaten\nwith sticks, gas pipes, fists, and knees, and interrogators threatened to rape his sisters. In one\nincident, interrogators attempted to rape him with a 12 centimetres long bullet. In May 2018,\nMr. Zain was brought before a judge and charged with “offending the State’s religion”,\n“trying to destroy the conservative Libyan society”, and “immoral practice”. Mr. Zain denied\nthe charges and was deported in November 2018."},{"id":"a-hrc-52-crp-8-p0116","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"116","seq":117,"section":"D. Sexual and gender-based violence","text":"In another emblematic case documented by the Mission, two young Libyan men,\nperceived to be gay, were held up and coerced by heavily armed men to unlock and provide\naccess to their phones. The two young men were taken to the Mitiga airport complex and\nhanded over to Radaa. There, a bearded man in traditional clothing – described as a sheikh –\nseverely tortured both victims and hurled foul language, denigrating their sexual orientation.\nOne of the victims was released the same day while the other was kept for four days. The\nman that was kept in detention informed the Mission that he was later ordered, under\ngunpoint, to undress the lower part of his body and raped by the guards. The victim was asked\nin detention for information about other gay men. Both survivors subsequently fled Libya."},{"id":"a-hrc-52-crp-8-p0117","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"117","seq":118,"section":"D. Sexual and gender-based violence","text":"The Mission also documented the torture and sexual assault of a gay young man by\nRadaa because of his homosexuality. In one incident in 2017, the then minor was contacted\nover the phone by a man who introduced himself as Radaa and requested his attendance at\nMitiga airport over photos seen on the phone of another person suggesting his homosexuality.\nThe minor appeared at Mitiga airport complex as requested, where he was taken into a\nseparate room and interrogated. During the interrogation, the victim was called “faggot”,\ngrabbed by the hair, slapped, and questioned about his sexual preferences. The victim begged\nthe interrogators to let him out so he could return to school but was told that that he did not\nneed an education and would “rot in jail”. The victim was also asked to identify other persons\nthat were gay. After a while, the interrogators blindfolded the victim and transferred him to\na nearby building. There, they hit the back of his knees, causing the victim to fall, and shaved\nhis head. They then proceeded to beat the victim with a hard plastic hose on his feet, tied his\nlegs, pulled out his toenails using a metal object, and flogged him hundreds of times. The\nvictim was forced to run in circles and accused of “disobeying the order of god”. The minor\nwas held by Radaa for approximately 10 to 12 hours, before being released."},{"id":"a-hrc-52-crp-8-p0118","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"118","seq":119,"section":"D. Sexual and gender-based violence","text":"The victim was detained again by Radaa in 2019. The victim was first brought to a man\nwho identified himself as a “sheikh” responsible for legal and religious affairs and lectured\nthe victim about religion. For approximately ten days, the victim was repeatedly sexually\nassaulted, including raped, and tortured in different rooms and holding cells by Radaa. During\nhis detention, the victim was shot at with ammunition while blindfolded. He also told the\nMission that he could feel a gun pointed at his head, had his jaw and cheekbones punched\nand kicked, and that he was beaten with hoses. The victim further described being forced to\nperform oral sex and was penetrated anally with another man’s sexual organ. He also shared\nthat he was touched on his genitalia several times."},{"id":"a-hrc-52-crp-8-p0119","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"119","seq":120,"section":"D. Sexual and gender-based violence","text":"Nearly all survivors interviewed refrained from lodging complaints out of fear of\nreprisals, arrest, or extortion. A case concerning a Libyan female journalist who reported\nbeing repeatedly raped and tortured during her detention highlighted the difficulties\nencountered by survivors of sexual violence. The victim was threatened that Radaa would\narrest her for prostitution and deem her “spoiled” if she complained that she had been raped.\nWhen the victim suspected that she had got pregnant she pretended to need blood tests to\nconfirm the pregnancy and self-administered medication to terminate it. Sexual relations\nbetween consenting adults, be it same-sex or sexual relations outside marriage,96 as well as\nabortion, are punishable by law. Furthermore, Libyan law provides for the exoneration of the\nperpetrator should he marry the victim and remain married to the victim for three years. 97"},{"id":"a-hrc-52-crp-8-p0120","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"120","seq":121,"section":"E. Arbitrary deprivation of life","text":"The Mission documented the arbitrary killing of hundreds of persons in Libya since\n2016 under different circumstances, including during hostilities and violent clashes. Most of\nthe killings investigated by the Mission occurred as part of larger-scale incidents that resulted\nin the deprivation of many lives. By example, the Mission made findings on extrajudicial\nkillings in Murzuq during February, March, and August 2019 at the backdrop of an LAAF\nmilitary operation supported by affiliated armed groups and resisted by local armed forces\nthat allegedly received support from the GNA.98 The Mission also made a finding of war\ncrimes in relation to killings by airstrike of students of the military academy in al-Hadaba,\nTripoli.99 As explained in section VII.B on enforced disappearance, the Mission further made\nfindings on extrajudicial killings and mass-graves in Tarhuna over 2019-2020.100"},{"id":"a-hrc-52-crp-8-p0121","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"121","seq":122,"section":"E. Arbitrary deprivation of life","text":"In addition to these incidents, the Mission documented a particular episode of killings\nas crimes against humanity committed near al-Abyar, approximately 50 kilometres east of\nBenghazi. On the morning of 26 October 2017, local authorities were alerted to the bodies of\n36 men at an execution site. The Mission believes that the men had been systematically\narrested and detained without due process by LAAF affiliated armed groups, specifically the\nTBZ. These violent abductions occurred at different times during 2017, from over a month\nto just the day before the bodies of all 36 victims were discovered. The Mission interviewed\na witness who lost two family members in this massacre and who informed the Mission that\nthe witness’ family was politically active in the area, including that the two family members\nultimately killed had peacefully taken part in the 2011 Libyan revolution. The witness\nelaborated upon years of harassment of the witness’ family by local military and militia\nforces, including arrest, detention, torture, and destruction of property. The witness was\nalerted of the two family members being arrested on or about the same day of the massacre\nitself. After checking with local security and military agencies for their loved ones, the family\nfinally learned of the death of their two family members upon a check at the hospital where\nthe corpses of al-Abyar massacre victims were held."},{"id":"a-hrc-52-crp-8-p0122","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"122","seq":123,"section":"E. Arbitrary deprivation of life","text":"The Mission also investigated the killing of Hanan Barassi in 2020 and found that she\nwas the victim of extrajudicial killing. Ms. Barassi was gunned down in broad daylight by\ntwo armed and masked men in the centre of Benghazi. She announced to her 70,000 followers\non the day before her killing that she would release information about Saddam Haftar, the\nson of Khalifa Haftar. Although Omar Mraja al-Megerhi is formally the head of TBZ,\nevidence provides that the group is controlled by Saddam Haftar."},{"id":"a-hrc-52-crp-8-p0123","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"123","seq":124,"section":"VIII. Exploitation of migrants","text":"More than 670,000 migrants from over 41 countries were present in Libya during the\nlast mandate extension period, and the number of migrants in Libya has been increasing since\n2021.101 Libya serves as a point of departure and transit for many of the migrants bound for\nEurope. All the migrants interviewed shared similar accounts of an abhorrent cycle of\nviolence. The cycle started with the migrants’ entry into Libya, often with the involvement\nof smugglers, and invariably involved their capture, re-capture, and repeated transfers to\nofficial or unofficial places of detention without recourse to judicial review. Racial\ndiscrimination against migrants was a persistent undercurrent throughout the cases\ndocumented by the Mission, as well."},{"id":"a-hrc-52-crp-8-p0124","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"124","seq":125,"section":"VIII. Exploitation of migrants","text":"The Mission interviewed more than 100 migrants over the course of its investigations,\nincluding in cases of alleged trafficking and deprivation of liberty for ransom in connection\nwith smuggling and trafficking. Based on this evidence, the Mission established that there\nare reasonable grounds to believe that migrants across Libya are victims of crimes against\nhumanity and that acts of murder, enforced disappearance, torture, enslavement, sexual\nslavery, rape, and other inhumane acts are committed in connection with their arbitrary\ndetention, during, for example, trafficking and interception. 102"},{"id":"a-hrc-52-crp-8-p0125","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"125","seq":126,"section":"VIII. Exploitation of migrants","text":"Notably, the exploitation of migrants, in the forms of trafficking, enslavement, sexual\nslavery, forced labour, imprisonment, extortion, theft of migrants’ private belongings, and\nsmuggling generated significant revenue for individuals, groups, and State actors. There are\nreasonable grounds to believe, in this regard, that such exploitation incentivized the\ncontinuation of the violations documented and facilitated the consolidation of power and\nwealth by the State and affiliated groups."},{"id":"a-hrc-52-crp-8-p0126","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"126","seq":127,"section":"VIII. Exploitation of migrants","text":"The cases investigated by the Mission during its last mandate extension confirmed\nthat there are reasonable grounds to believe that the mentioned underlying acts of crimes\nagainst humanity were committed in DCIM centres in Tariq al-Matar, Abu Salim, Ayn Zarah,\nAbu Isa, Gharyan, Tariq al-Sikka, Mabani, Salah Al-Din, and Az-Zawiya, as well as non-\nofficial places of detention in al-Shwarif, Bani Walid, Sabratah, Zuwara, and Sabha. The\nMission identified a particularly significant role played by the Stability Support Apparatus\n(SSA) in crimes against humanity through their cooperation with the LCG in Az-Zawiya, and\ntheir control of the detention centres of Abu Slim and Ayn Zarah."},{"id":"a-hrc-52-crp-8-p0127","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"127","seq":128,"section":"VIII. Exploitation of migrants","text":"The ongoing, systematic, and widespread character of the crimes documented by the\nMission strongly suggests that personnel and officials of the DCIM, at all levels of the\nhierarchy, are implicated. In addition, the Mission found reasonable grounds to believe that\nhigh-ranking staff of the LCG, SSA, and DCIM staff colluded with traffickers and smugglers,\nwhich are reportedly connected to militia groups,103 in the context of the interception and\ndeprivation of liberty of migrants."},{"id":"a-hrc-52-crp-8-p0128","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"128","seq":129,"section":"VIII. Exploitation of migrants","text":"The Mission’s investigations also uncovered evidence on collusion between the LCG\nand those in charge of al-Nasr detention centre in Az-Zawiya. Abd al-Rahman al-Milad, also\nknown as “Bija”, is the head of the regional unit of the LCG in Az-Zawiya. He is on the UN\nSecurity Council sanctions lists for involvement in trafficking and smuggling.104"},{"id":"a-hrc-52-crp-8-p0129","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"129","seq":130,"section":"VIII. Exploitation of migrants","text":"Libyan authorities, including the DCIM, the LCG and the SSA, and third States, for\ninstance Malta and Italy, have been on notice for years about the ongoing widespread and\nsystematic attack on migrants, constituted by violations occurring at sea, in detention centres,\nalong trafficking and smuggling routes, and in trafficking hubs.105 Nonetheless, in accordance\nwith memorandums of understanding between Libya and third States, the Libyan authorities\nhave continued their policy of intercepting and returning migrants to Libya, where their\nmistreatment resumes, in violation of the principle of non-refoulement. Based on the\nsubstantial evidence and reports before it, the Mission found grounds to believe that the\nEuropean Union and its member States, directly or indirectly, provided monetary, technical,\nand logistical support to the LCG and DCIM that was used in the context of interception and\ndetention of migrants. Evidence collected by the Mission also demonstrated that the EU\nand/or its member States supplied Libyan authorities with inter alia rubber boats for coastal\npatrolling, as well as SUV vehicles, busses, ambulances, and radio-satellite communication\ndevices."},{"id":"a-hrc-52-crp-8-p0130","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"130","seq":131,"section":"VIII. Exploitation of migrants","text":"Interviewees that escaped captivity and attempted to reach Europe eventually tried to\ncross the Mediterranean Sea. In the words of one migrant that was held in al-Maya, Ayn\nZarah, and Gharyan detention centres, “[o]ur concern is not dying in the water, but our\nconcern is to go back to the prison where we will be oppressed and tortured by guards”.\nLibya’s and European States’ immigration control must be exercised consistently with their\ninternational law obligations, especially the principle of non-refoulement, and have regard to\nthe Global Compact for Safe, Orderly and Regular Migration.."},{"id":"a-hrc-52-crp-8-p0131","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"131","seq":132,"section":"A. Arbitrary deprivation of liberty","text":"With a few exceptions, violations and abuses committed against migrants in Libya\nthat were documented by the Mission stemmed from or occurred in connection with their\ndeprivation of liberty without recourse to judicial review and access to asylum procedures.\nMigrants were detained in official places of detention under the nominal control of the DCIM\nand unofficial places of detention under the control of armed groups and criminal gangs\nengaged in smuggling and trafficking. They were taken into detention after they were\nintercepted at sea or following their smuggling or trafficking through the country’s border\ncrossings, in particular the southern frontier. The period of detention of migrants varied from\ndays to months. The deprivation of migrants’ liberty was arbitrary in that migrants were not\ncharged, convicted, or sentenced to imprisonment following a fair and public hearing, and\nthe absence of procedural safeguards and legal oversight. The detention of migrants in\ntrafficking hubs was inherently arbitrary, with the actors involved operating fully outside the\nscope of the law."},{"id":"a-hrc-52-crp-8-p0132","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"132","seq":133,"section":"A. Arbitrary deprivation of liberty","text":"Migrants described an ever-revolving door of capture, release, re-capture, escape, and\ninterception. Typically, migrants made their way out of places of detention following the\npayment of ransom, a successful escape, or en masse discharge, only to be captured again by\nthe same actor that had detained them or another group. As an intelligence officer in Az-\nZawiya told the Mission, “[t]he officers in the shelters ask the migrants’ families for ransom\nto release them, and sometimes […] arrests them again and transfers [them] to the same\nagency where they do the same”."},{"id":"a-hrc-52-crp-8-p0133","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"133","seq":134,"section":"A. Arbitrary deprivation of liberty","text":"Outside of being arrested individually or in small to medium-sized groups, it was\ncommon for migrants to be arrested and detained in large-scale raids of residential areas\nwhere migrants were present. For example, in the early morning hours of 1 October 2021, a\nlarge contingent of Government and Radaa security forces besieged an area of Gargaresh.\nUsing drones to spot migrants escaping to the sea and elsewhere, these forces conducted a\nransacking of the area that resulted in the arrest of an estimated 4000 migrants as well as the\nwidespread seizure of migrants’ property (such as money and mobile phones). Forces\nresorted to physical violence, including stabbings and gunshots, during the operation on\nGargaresh. Once arrested and boarded onto busses, the migrants were distributed among\ndetention centres in the vicinity, such as Gharyan, Tarik al-Sikka, Bir Ghanam, Ayn Zarah,\nand Abu Slim."},{"id":"a-hrc-52-crp-8-p0134","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"134","seq":135,"section":"A. Arbitrary deprivation of liberty","text":"In the aftermath of the Gargaresh raid, hundreds of migrants protested and camped in\nfront of the UN High Commissioner for Refugees’ office in Tripoli. The protest was\ndisbanded on 10 January 2022 when government security forces violently arrested hundreds\nof migrants, boarded them onto busses, and sent them to nearby detention facilities, primarily\nin Ayn Zarah. One affected migrant told the Mission that approximately 30 busses parked\nnearby, and the encamped migrants were told they had ten minutes to leave. After that time\nelapsed, the security forces attacked them physically and burned their tents prior to forcing\nthem onto the buses. The Mission documented the killing of a Sudanese migrant by security\nforces in the vicinity of the UN High Commissioner for Refugee’s office in Tripoli during\nthe sit-in."},{"id":"a-hrc-52-crp-8-p0135","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"135","seq":136,"section":"A. Arbitrary deprivation of liberty","text":"Another frequent method of arrest and detention of migrants involved their\ninterception at sea as they attempted to cross the Mediterranean Sea from departure points\noff the Libyan coast. An overwhelming number of interviewed migrants described to the\nMission that they had attempted to escape detention and cross into Europe several times,\nsome five to ten times over. Persons migrating to Europe were loaded, at times against their\nwill, onto varied kinds of boats. Some of the boats were barely seaworthy and overloaded by\nsmugglers and traffickers, ultimately resulting in their sinking at sea and a loss of life."},{"id":"a-hrc-52-crp-8-p0136","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"136","seq":137,"section":"A. Arbitrary deprivation of liberty","text":"During the process of LCG interception and disembarkation, migrants were exposed\nto a range of abusive tactics that could turn fatal. Migrants described to the Mission how LCG\nships made seemingly deliberate unsafe manoeuvres, causing migrant boats to capsize and\nmigrants to fall into the water and drown. The Mission also found reasonable grounds to\nbelieve that personnel on LCG ships shot at or near boats carrying migrants, causing migrants\nto jump into the water, seeking temporary safety. Migrants were often physically and verbally\nassaulted and threatened by LCG personnel and other security officials during their transfer\nonto LCG ships and forced return to Libya. The Mission also found reasonable grounds to\nbelieve that LCG personnel frequently stole migrants’ private property, such as phones and\nmoney, during interception."},{"id":"a-hrc-52-crp-8-p0137","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"137","seq":138,"section":"A. Arbitrary deprivation of liberty","text":"One witness told the Mission about an attempt by migrants to sail to Malta whereupon\nthey were intercepted by black helicopters that filmed them for about 20 minutes. A few\nhours later, an LCG ship arrived and started to load the estimated 108 migrants onto it, during\nwhich LCG personnel threatened to shoot any migrants that attempted to escape. A newborn\nbaby fell into the water during this process while the baby was “thrown” from the migrant\nboat to the ship. Once at the disembark point in Tripoli, they were met with a large contingent\nof security forces with their faces covered and wearing black uniforms, which a witness said\nmade it seem as though they were terrorists. After being boarded onto DCIM busses that\nawaited them, the migrants had further items taken from them, such as passports and rings.\nMigrants were subsequently split up by nationalities and taken to different detention centres.\nA witness mentioned that a captain approached the migrants and offered to release those that\ncould pay 100 to 200 United States dollars, a deal that the witness said was not even honoured\nfor those who did pay."},{"id":"a-hrc-52-crp-8-p0138","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"138","seq":139,"section":"A. Arbitrary deprivation of liberty","text":"Since 2016, EU member States and EU agencies have implemented a policy of\nreturning migrants and asylum seekers or refugees to Libya by increasing capacity-building\nand coordination support to Libyan actors, especially the LCG. Libya and third States, such\nas Italy and Malta, entered memorandum of understandings to this effect. In accordance with\nsuch memorandums of understanding, the Libyan authorities received support for the\ninterception and return of migrants to Libya if they attempted to arrive at European shores.\nUnder the 2020 Malta-Libya memorandum, for example, the Maltese government would\nfinance two coordination centres in Valletta and Tripoli to coordinate activities aimed at\nsuppressing irregular immigration across the Mediterranean."},{"id":"a-hrc-52-crp-8-p0139","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"139","seq":140,"section":"A. Arbitrary deprivation of liberty","text":"The European Union Naval Forces Operation’s mission and mandate was specifically\namended in June 2016 to include the provision of training and capacity-building to the LCG\nand Libyan Navy. Frontex has been critical in providing aerial surveillance through various\noperations. Those involved in the arbitrary deprivation of liberty of migrants must have\nknown that migrants detained were civilians, that they were arrested and detained solely on\nthe basis of their immigration, without considering their international legal status, and that\nthey were routinely subjected to violations and abuses in detention."},{"id":"a-hrc-52-crp-8-p0140","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"140","seq":141,"section":"A. Arbitrary deprivation of liberty","text":"Relatedly, the Mission noted the suspension and restriction of rescue operations\nconcerning migrants departing Libya by sea, carried out by medical, humanitarian and aid\norganizations. The Mission received substantial allegations of attacks against such\norganizations and individuals involved in rescue operations, such as legal action taken against\nthem and the confiscation of vessels and other lifesaving equipment."},{"id":"a-hrc-52-crp-8-p0141","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"141","seq":142,"section":"B. Torture and other cruel, inhuman or degrading treatment against","text":"There is overwhelming evidence that migrants were systematically tortured in the\nTariq al-Matar, Tariq al-Sikka, Abu Isa, and Gharyan DCIM-run detention centres, as well\nas in the Bani Walid and Sabratah trafficking hubs. Most migrants interviewed told the\nMission that they had been subjected to or witnessed acts that may amount to torture, cruel,\ninhuman or degrading treatment. Migrants frequently reported beatings with fists or objects,\nflogging, burning, stabbing, electrocution, and shooting with live bullets to instil fear, cause\npain, or punish them. Migrants also appeared to have suffered psychological torture from, for\nexample, having to watch the ill-treatment of relatives and others. A Sudanese migrant held\nat Bani Walid described the feeling among migrants that guards “treated dogs better than\n[them]”."},{"id":"a-hrc-52-crp-8-p0142","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"142","seq":143,"section":"B. Torture and other cruel, inhuman or degrading treatment against","text":"Both women and men were tortured and subjected to cruel, inhuman, or degrading\ntreatment. In a case representative of the brutal treatment of women migrants, a young\nEthiopian survivor of several incidents of rape in Bani Walid lost her unborn child because\nof the beatings she suffered in Ain Zawara."},{"id":"a-hrc-52-crp-8-p0143","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"143","seq":144,"section":"B. Torture and other cruel, inhuman or degrading treatment against","text":"Based on its investigation, torture and other forms of ill-treatment were frequently\ncommitted in the context of ransom demanded by traffickers. Numerous migrant survivors\ninformed the Mission that traffickers, including in Bani Walid, severely beat migrants that\ncould not pay them. In several cases documented by the Mission, traffickers burnt plastic\nonto the skin of migrants who could not pay ransom. In one incident investigated by the\nMission, a young Sudanese migrant was set on fire by traffickers when he could not pay the\nransom. The victim died from his injuries."},{"id":"a-hrc-52-crp-8-p0144","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"144","seq":145,"section":"B. Torture and other cruel, inhuman or degrading treatment against","text":"Migrant children were amongst those ill-treated when ransom was not paid.\nTraffickers forced child migrants to call their parents to pay ransom, under the threat that\ntheir child would otherwise be harmed. A migrant from Mali, and held in Sabratah as a child,\ntold the Mission that “every morning they beat you with a whip. Then they call you, one by\none, and you go to phone your parents. There you feel the smell of death”."},{"id":"a-hrc-52-crp-8-p0145","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"145","seq":146,"section":"B. Torture and other cruel, inhuman or degrading treatment against","text":"Forensic examinations arranged by the Mission attested to the ill-treatment of\nmigrants deprived of their liberty, and the immediate and long-term physical and emotional\nharm suffered. There are reasonable grounds to believe that migrants were denied medical\ntreatment while in detention. Considering that irregular entry and stay of migrants is\ncriminalized in Libya, migrant survivors risk prosecution and punishment if they approach\nLibyan authorities and medical facilities for whatever reason."},{"id":"a-hrc-52-crp-8-p0146","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"146","seq":147,"section":"B. Torture and other cruel, inhuman or degrading treatment against","text":"Cases of suicide by hanging or the consumption of chemical liquids such as shampoos\nwere reported to the Mission. In one of the incidents documented by the Mission, a boy,\nallegedly tortured and suffering from severe headaches, hung himself in Ayn Zarah. His\nlifeless body was left hanging in front of other migrants for at least one and a half-day before\nit was taken down. A witness said that guards ordered them not to take photos."},{"id":"a-hrc-52-crp-8-p0147","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"147","seq":148,"section":"B. Torture and other cruel, inhuman or degrading treatment against","text":"The Mission found reasonable grounds to believe that migrants were systematically\ndetained under inhumane conditions in both DCIM centres and places of detention controlled\nby traffickers. An overwhelming number of migrants testified to the lack of mattresses and\nsleeping accommodations, overcrowding, a severe shortage of lavatories, lavatories that were\nnever cleaned, the continued presence of crawling insects such as lice, the sharing of quarters\nwith detainees with infectious diseases, and inadequate quantities and quality of food and\nwater."},{"id":"a-hrc-52-crp-8-p0148","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"148","seq":149,"section":"B. Torture and other cruel, inhuman or degrading treatment against","text":"Migrants that were interviewed by the Mission described being starved in places of\ndetention. The DCIM centre in Abu Isa was called “one of the worst prisons” in this regard.\nA Sudanese migrant held there explained that “because of the lack of food, we sometimes do\nnot go to the toilet for 18 days”. Another migrant held at Bani Walid told the Mission that no\nfood was provided and that the “bones of many detainees were visible in their weak bodies”."},{"id":"a-hrc-52-crp-8-p0149","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"149","seq":150,"section":"C. Enslavement, sexual slavery, and forced labour","text":"The Mission found reasonable grounds to believe that migrants were enslaved in\nplaces of detention in Abu Slim, Az-Zawiya, Mabani, al-Shwarif, Bani Walid, Sabratah\nZuwara, and Sabha, some of which fall under the actual or nominal control of the DCIM. The\nMission also found reasonable grounds to believe that sexual slavery was committed in Bani\nWalid and Sabratah and that forced labour was committed in Tariq al-Matar and Ayn Zarah.\nEnslavement, sexual slavery, or forced labour were alleged to be committed in most places\nof detention investigated by the Mission but it proved difficult for the Mission to collect\ninformation about the precise details of the transactions that made up the violations. Often,\nmigrants themselves, who were frequently moved between groups, individuals, and\nlocations, were not aware that they had been sold or bought until after the fact, when\nconfronted with a new set of circumstances and abuse."},{"id":"a-hrc-52-crp-8-p0150","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"150","seq":151,"section":"C. Enslavement, sexual slavery, and forced labour","text":"The Mission considered that enslavement, including sexual slavery, had occurred\nwhen, for example, there was an element of ownership or there were actions imposing a\nsimilar deprivation of liberty. Forced labour could indicate enslavement. When the\nperpetrator also forced the victim to engage in acts of a sexual nature, the Mission considered\nsexual slavery to have been committed."},{"id":"a-hrc-52-crp-8-p0151","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"151","seq":152,"section":"C. Enslavement, sexual slavery, and forced labour","text":"The case of a survivor of sexual slavery from the Ivory Coast encapsulated the\nsuffering of migrants in Sabratah. The woman, in her thirties, was raped several times in\nSabratah while detained by traffickers and held for ransom. She became pregnant after she\nhad sexual intercourse with a man who agreed to help. She did it to “pay him back, to\nsurvive”. The woman told the Mission that she could now “heal talking about it” and that she\ntoday “could see the benefit of telling the [Mission] the pain […] to cry and liberate [herself]\nof the pain”. She said she “never wanted a baby in such a place. You regret having a baby in\nLibya. I had lost my dignity. My self-image. It is painful, deplorable. You see men suffer too.\nThere is no dignity in Libya. They did it to men with objects.”"},{"id":"a-hrc-52-crp-8-p0152","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"152","seq":153,"section":"C. Enslavement, sexual slavery, and forced labour","text":"In another case documented by the Mission, a child from Guinea was taken to\nSabratah and subjected to sexual slavery. She described women being told to undress and\nkeep their hands and feet apart and then raped. She told the Mission that “women are sexual\nobjects there. Some women are used as prostitutes but are not paid. They are like slaves”.\nThe girl was sodomised when she was sent to do domestic work for a man outside the building\nwhere migrants were kept. She and many other migrants interviewed by the Mission,\nrecounted that boys were taken to work and harmed if they claimed payment for their labour."},{"id":"a-hrc-52-crp-8-p0153","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"153","seq":154,"section":"C. Enslavement, sexual slavery, and forced labour","text":"The Mission collected evidence of women, men, boys, and girls being forced to work\nin factories producing ammunition, construction, cleaning services, and agriculture. Forced\nlabour was at times carried out in exchange for promises of subsequent release. In an\nemblematic case of enslavement and forced labour, a child from Mali was taken to a farm\nand made to work with the animals. The boy was told, when he confronted a man at the farm\nabout why he could not leave, that he had been bought by him."},{"id":"a-hrc-52-crp-8-p0154","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"154","seq":155,"section":"C. Enslavement, sexual slavery, and forced labour","text":"Further investigation is necessary to uncover the extent of the widescale nature of the\nviolations and their transboundary elements. More investigations are also needed to\nunderstand the details of the transactions around the sale and purchase of human beings in\nLibya, and precisely the actors involved."},{"id":"a-hrc-52-crp-8-p0155","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"155","seq":156,"section":"D. Sexual and gender-based violence against migrants","text":"In addition to the sexual and gender-based violence reported on in VIII.B and C, the\nMission made findings on rape and other acts of a sexual nature as crimes against humanity\nin places of detention in Mabani, al-Shwarif, Zuwarah, Sabha, Sabratah, and Bani Walid. The\nMission spoke to numerous survivors and witnesses of rape in both official and non-official\nplaces of detention."},{"id":"a-hrc-52-crp-8-p0156","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"156","seq":157,"section":"D. Sexual and gender-based violence against migrants","text":"Most of the survivors of the rape documented by the Mission were women and girls,\nbut men and boys were also found to have been raped. Rape cases investigated by the Mission\ninvolved the penetration by the male sexual organ. The Mission also received accounts of\nrape with unspecified objects. Based on the evidence, rape was committed for the exploitation\nand punishment of migrants and/or the gratification of the perpetrator."},{"id":"a-hrc-52-crp-8-p0157","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"157","seq":158,"section":"D. Sexual and gender-based violence against migrants","text":"Rape occurred under coercive circumstances, when victims were deprived of liberty\nand under the control of the perpetrators, and at times at gunpoint. In most cases, the\nperpetrators were guards belonging to either trafficking groups or personnel of State-\nauthorities. According to witnesses, migrants were raped in front of their children or taken\naway from their spouses to be raped. The Mission further found that migrants were in some\ninstances photographed and recorded while being raped and that the footage was used to\ndemand ransom from family members of the survivors. Migrant women also told the Mission\nthat they had sexual intercourse with guards and other detention officials in exchange for\nfood, water, or other basic amenities. In several cases, victims were promised to be released\nin exchange for sexual acts."},{"id":"a-hrc-52-crp-8-p0158","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"158","seq":159,"section":"D. Sexual and gender-based violence against migrants","text":"Victims interviewed were oftentimes raped routinely by either the same perpetrator or\ndifferent men over extended periods of time, and occasionally at different locations. As\ndescribed by a male witness of rape of women in Bani Walid, “during the nights, the guards\ncome in the dark with the torch and approach the ladies, pick any and rape her. They order\nus to sleep and cover ourselves with the mattress as they take the lady away”. In another case\ninvestigated by the Mission, an Eritrean victim reported that “drunk smugglers used to rape\nfemale migrants every day, except during Ramadan”. Several victims described to the\nMission that they were raped several times a week by different men. In the words of another\nEritrean survivor, “no one sees you as a human. From a little boy to an old man, they have\nthe right to beat and to rape us”."},{"id":"a-hrc-52-crp-8-p0159","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"159","seq":160,"section":"D. Sexual and gender-based violence against migrants","text":"Sexual violence against migrants was not limited to rape. The Mission found\nreasonable grounds to believe that women’s breasts were maimed in Bani Walid. Migrants\ndescribed having seen women’s breasts set on fire and their nipples connected to electrical\nwires causing burns."},{"id":"a-hrc-52-crp-8-p0160","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"160","seq":161,"section":"D. Sexual and gender-based violence against migrants","text":"Pregnancies are a common outcome of rape, and migrants reported having seen\nwomen give birth in detention without professional medical support and under highly\nunsanitary conditions. Migrant women also reported to the Mission that they had suffered\nmiscarriages without the assistance of professional medical support."},{"id":"a-hrc-52-crp-8-p0161","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"161","seq":162,"section":"D. Sexual and gender-based violence against migrants","text":"Migrant survivors faced insurmountable challenges in accessing safe and adequate\nsexual and reproductive health services and assistance programs that could offer them\nprotection and address the harm inflicted and consequential pregnancies and births. In a case\ndocumented by the Mission, a Sudanese asylum seeker was arrested after giving birth at a\npublic hospital. Despite her claim that the child was conceived through rape, the victim was\naccused of engaging in sexual relations outside marriage, an act criminalized in Libya."},{"id":"a-hrc-52-crp-8-p0162","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"162","seq":163,"section":"E. Murder","text":"The Mission received considerable information from migrants about the death of\nmigrants in Libya. Migrants reported deaths as an outcome of inter alia the torture that they\nwere subjected to, starvation, and drowning at sea. Migrants also reportedly died after being\nshot at by guards. Although it was difficult for the Mission to verify and establish the\ncircumstances of all incidents of deaths reported to it, the Mission found reasonable grounds\nto believe that murder was committed in both official and unofficial places of migrant\ndetention."},{"id":"a-hrc-52-crp-8-p0163","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"163","seq":164,"section":"E. Murder","text":"The Mission made findings of murder as crimes against humanity in places of\ndetention in Abu Salim, Az-Zawiya, Mabani, al-Shwarif, Bani Walid, and Zuwara. Two of\nthe incidents of murder took place in Abu Salim and Mabani in 2021. During these incidents,\nguards aimlessly fired live ammunition at migrants resulting in the loss of migrant lives."},{"id":"a-hrc-52-crp-8-p0164","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"164","seq":165,"section":"E. Murder","text":"The Mission received allegations of several killings and mass graves in Bani Walid.\nThe Mission found reasonable grounds to believe that migrants died and were buried at Bani\nWalid. Reported causes of death included medical negligence and gunfire. An Eritrean\nmigrant held in Bani Walid told to the Mission that “we used to sleep in the same place where\ndead bodies were scattered. We were adapted to the situation. Even when somebody dies, we\ncompete to take off their clothes”."},{"id":"a-hrc-52-crp-8-p0165","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"165","seq":166,"section":"IX. Attacks against judges and lawyers and challenges to the rule","text":"The Mission investigated attacks against legal professionals and identified challenges\nto the rule of law in Libya. Although the Libyan judiciary is relatively cohesive, the Mission\nfound reasonable grounds to believe that acts had been committed that undermined the\nindependence of the judiciary and curtailed the rule of law. An independent, impartial,\ncompetent and effective judicial system is essential if victims are to be able to seek and\nreceive remedies and accountability at the domestic level."},{"id":"a-hrc-52-crp-8-p0166","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"166","seq":167,"section":"IX. Attacks against judges and lawyers and challenges to the rule","text":"The Mission documented the alleged arbitrary detention, enforced disappearance and\nviolation of the right to life of several judges and prosecutors. The Mission also documented\ncases of detainees being denied access to lawyers and received reports of judges being\nreplaced to fix an outcome, sentences that were adapted to serve certain interests and cases\nthat were not brought to trial owing to tribal affiliations. Attacks against members of the legal\nprofession were reported in Benghazi, Tripoli, Sirte, and Sabha."},{"id":"a-hrc-52-crp-8-p0167","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"167","seq":168,"section":"IX. Attacks against judges and lawyers and challenges to the rule","text":"For example, the Mission documented the case of a lawyer in Tripoli who was\nlitigating civil cases, the majority of which were lawsuits against the Government for\ncompensation for victims of crimes committed by militias who were on the government\npayroll. He was also speaking out against child recruitment by militias. The victim was\nabducted from the streets in Tripoli in April 2019, detained and interrogated. The perpetrators\nagreed to release him on the condition that he did not proceed with the lawsuits and refrained\nfrom speaking publicly about child recruitment. The victim was released after one day. He\nsoon afterward left Libya and has never returned."},{"id":"a-hrc-52-crp-8-p0168","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"168","seq":169,"section":"IX. Attacks against judges and lawyers and challenges to the rule","text":"In another emblematic case from 2021, a female lawyer in Benghazi was kidnapped\nfrom the street near Ajdabiya Court, arbitrarily detained in inhumane conditions and\nsubjected to enforced disappearance for two days by the Internal Security Agency before\nbeing thrown on the street, handcuffed and blindfolded. In August 2022, another lawyer was\nharshly beaten by Radaa elements inside a Tripoli courtroom, in front of judges, kidnapped\nand then held by Radaa in Mitiga prison for about eight hours, before being released\nfollowing pressure from external entities."},{"id":"a-hrc-52-crp-8-p0169","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"169","seq":170,"section":"IX. Attacks against judges and lawyers and challenges to the rule","text":"The Mission found that there was no domestic legislation establishing protection\nmeasures for witnesses and victims. Nor was there a Libyan security or military force capable\nof providing security protection to the courts, prosecutors' offices and the judiciary in\naccordance with international practice. In fact, the Judicial Police operations room, which is\npart of the Judicial Police and tasked with providing judicial security, was implicated in\nattacks on judicial personnel."},{"id":"a-hrc-52-crp-8-p0170","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"170","seq":171,"section":"IX. Attacks against judges and lawyers and challenges to the rule","text":"Victims seeking justice through domestic avenues encountered considerable\ndifficulties. For example, those who sought to lodge complaints with the public prosecution\nin Tripoli, after having fled to territory outside the control of the LAAF, reported that\nprosecutors told them they lacked jurisdiction to investigate alleged TBZ crimes. It was\nfurther reported that no criminal cases were heard in Fazzan between 2011 and 2019 and that\npolice stations closed by 2 p.m."},{"id":"a-hrc-52-crp-8-p0171","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"171","seq":172,"section":"A. Military trials of civilians","text":"The LAAF has been operating a parallel military justice system in areas under its\ncontrol. The HOR, allied with the LAAF since 2014, enacted a law in 2016 extending the\npersonal and subject-matter jurisdiction of the military judiciary over civilians who are\nmembers of militias and those who commit “terrorist acts”. Trials of civilians before military\ncourts violate international human rights law, including the African Charter on Human and\nPeoples’ Rights, as they often do not satisfy the requirements of judicial independence,\nimpartiality, and competence under the right to a fair trial."},{"id":"a-hrc-52-crp-8-p0172","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"172","seq":173,"section":"A. Military trials of civilians","text":"The Mission investigated the case of Iftikhar Boudra, a civilian, who was tried and\nconvicted by a military court in east Libya. Ms. Boudra had been critical of LAAF leadership\non social media. Ms. Boudra and her husband were taken by ISA from their home in Benghazi\nin November 2018. While her husband was released, Ms. Boudra, was brought before a\nmilitary court and sentenced to death. The sentence was subsequently commuted to ten years\non appeal. The Mission received information that Ms. Boudra has been ill-treated in detention\nin al-Kwaifiya and that she is in bad health. The Mission obtained a list of 30 people that\nreceived the death penalty by military court in Benghazi."},{"id":"a-hrc-52-crp-8-p0173","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"173","seq":174,"section":"A. Military trials of civilians","text":"In another similar case, the Mission interviewed a former detainee accused of terrorism\nand belonging to Da’esh. The victim was detained from 2015 until 2019, after inter alia\ncriticizing Khalifa Haftar on social media. The victim was brought before a military court in\nmid-May and sentenced initially to three and a half years imprisonment. The trial took place\nover seven sessions and for the first three sessions the victim did not have legal\nrepresentation."},{"id":"a-hrc-52-crp-8-p0174","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"174","seq":175,"section":"A. Military trials of civilians","text":"The Mission received reports that defence attorneys for civilians brought before military\ncourts have been threatened and harassed, including by officers in military courts."},{"id":"a-hrc-52-crp-8-p0175","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"175","seq":176,"section":"X. Legal findings of crimes against humanity","text":"In addition to the findings of violations of international human rights law and\ninternational humanitarian law in relation to individual cases and incidents mentioned in\nsections VII through VIII, the Mission found reasonable grounds to believe that crimes\nagainst humanity were committed against Libyans and migrants throughout Libya in the\ncontext of arbitrary deprivation of liberty since the beginning of 2016."},{"id":"a-hrc-52-crp-8-p0176","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"176","seq":177,"section":"X. Legal findings of crimes against humanity","text":"In reaching its findings on crimes against humanity, the Mission applied the\ncommonly accepted definition of crimes against humanity under customary international law,\nmeaning criminal acts committed as part of a widespread or systematic attack against any\ncivilian population, with knowledge of the attack. Although the Mission referred to the\ndefinition in the Rome Statute, it did not adopt the organisational policy requirement (of the\n“attack” component of the chapeau) as formulated in Article 7(2)(a).106"},{"id":"a-hrc-52-crp-8-p0177","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"177","seq":178,"section":"X. Legal findings of crimes against humanity","text":"As part of the definition of crimes against humanity applied by the Mission,\nunderlying acts had to form part of a larger attack against a civilian population, without\nnecessarily being “limited to the use of armed force”. An attack was considered widespread\nif it involved “massive, frequent, large-scale action, carried out collectively with considerable\nseriousness and directed against a multiplicity of victims”. The requirement of a systematic\nattack was met where there was “organized action, following a regular pattern, on the basis\nof a common policy” that involved substantial public or private resources."},{"id":"a-hrc-52-crp-8-p0178","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"178","seq":179,"section":"X. Legal findings of crimes against humanity","text":"As for the underlying acts of crimes against humanity, the Mission gave regard to the\ndefinitions listed in the annex of the present report."},{"id":"a-hrc-52-crp-8-p0179","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"179","seq":180,"section":"A. Crimes against humanity committed against migrants","text":"Based on its evidentiary holdings, the Mission found reasonable grounds to believe\nthat the Ministry of the Interior, the DCIM together with armed groups in de facto control of\nmigrants deprived of liberty, committed crimes against humanity. This finding was made vis-\nà-vis migrants held in Tariq al-Matar, Abu Isa, Gharyan, Tariq al-Sikka, Az-Zawiyya, Salah\nal-Din, Mabani, and al-Shwarif. Furthermore, the Mission found reasonable grounds to\nbelieve that the SSA is responsible for crimes against humanity in Ayn Zarah and Abu Salim\nmigrant detention centres. The Mission also established reasonable grounds to believe that\ncrimes against humanity were committed in Bani Walid, Sabratah, Zuwara and Sabha."},{"id":"a-hrc-52-crp-8-p0180","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"180","seq":181,"section":"A. Crimes against humanity committed against migrants","text":"Specifically, the Mission found that there is an ongoing attack, consisting of a course\nof conduct based on the fulfilment of the actus reus requirements of the underlying acts of\nimprisonment and other inhumane acts against thousands of migrants. The victims of the\nattack and the underlying acts were civilians."},{"id":"a-hrc-52-crp-8-p0181","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"181","seq":182,"section":"A. Crimes against humanity committed against migrants","text":"The Mission further found reasonable grounds to believe that the attack was both\nwidespread and systematic. The extraordinarily high number of victims in detention centres,\nnumbering in the thousands located across a wide geographical area, demonstrated the\nwidespread nature of the attack. While it is not necessary for the attack to also be of a\nsystematic nature, the Mission found reasonable grounds to believe that the attack was\nsystematic too. In this regard, the Mission noted the multitude of underlying acts described\nin section VIII and committed by the DCIM, SSA, and other groups in control of detention\ncentres in the context of a policy, manifest in Libyan legislation, that criminalizes migration\nand denies individuals their rights to seek asylum. Migrants were not able, under the Libyan\ndomestic legal framework, to challenge the fact, duration, or conditions of detention."},{"id":"a-hrc-52-crp-8-p0182","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"182","seq":183,"section":"A. Crimes against humanity committed against migrants","text":"The Mission also found reasonable grounds to believe that traffickers and criminal\ngangs committed crimes against humanity against migrants in trafficking hubs in Bani Walid,\nSabratah, Zuwara, and Sabha. Thousands of migrants are smuggled into Libya every year\nvia Sabha and Kufra in the south and south-east of Libya respectively, and many end up in\nTripoli via the trafficking hub of Bani Walid after being sold to traffickers and/or in one of\nthe trafficking hubs on the coastline west of Tripoli, particularly Zuwara and Sabratah."},{"id":"a-hrc-52-crp-8-p0183","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"183","seq":184,"section":"A. Crimes against humanity committed against migrants","text":"The incidents identified by the Mission and detailed in section VIII were not isolated,\nbut clearly part of a broader initiative by criminal gangs and traffickers to profit from the\ncriminalization of migration and the extreme physical, psychological, and economic\nvulnerability of migrants and asylum seekers. The Mission identified a pattern of abduction,\nharbouring and transfer of migrants, many of whom were sold and subsequently exploited\nphysically and sexually, such that there exists a clearly identifiable non-accidental repetition\nof similar criminal conduct on a regular basis. The scale and systematicity of migrant\ntrafficking indicated that the criminal groups and networks of traffickers are acting with a\ncertain degree of organisation and coordination."},{"id":"a-hrc-52-crp-8-p0184","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"184","seq":185,"section":"A. Crimes against humanity committed against migrants","text":"Lawlessness in certain parts of the country, particularly in the south, where such\nnetworks exercise a certain degree of control, or benefit from cooperation from armed groups\nwho are in effective control of territory, renders migrants especially vulnerable to abduction\nand ransom."},{"id":"a-hrc-52-crp-8-p0185","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"185","seq":186,"section":"A. Crimes against humanity committed against migrants","text":"In addition, the Mission considered that sea interceptions and pullbacks amounted to\nimprisonment or other severe deprivation of physical liberty as crimes against humanity,\ncommitted as part of a widespread and systematic attack against migrants and refugees\nattempting to leave Libya."},{"id":"a-hrc-52-crp-8-p0186","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"186","seq":187,"section":"A. Crimes against humanity committed against migrants","text":"The arbitrary deprivation of liberty of the migrants, asylum seekers or refugees was\ncommitted against their will and they were denied the option to refuse or challenge their\ninterception at sea, return to and disembarkation in Libya, and detention. Migrants, asylum\nseekers or refugees were apprehended, detained, and disembarked in Libya solely to prevent\ntheir entry into Europe as a corollary of both European immigration policy and the economic\nagenda of migration in Libya via their subsequent detention and exploitation."},{"id":"a-hrc-52-crp-8-p0187","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"187","seq":188,"section":"A. Crimes against humanity committed against migrants","text":"The underlying acts that were found to be committed as part of crimes against\nhumanity against migrants in Libya since 2016 included imprisonment and other severe\ndeprivation of physical liberty, torture, murder, enslavement, sexual slavery, rape and other\nacts of sexual violence, as well as other inhumane acts."},{"id":"a-hrc-52-crp-8-p0188","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"188","seq":189,"section":"B. Crimes against humanity committed in the detention of Libyans","text":"As previously reported by the Mission, there are reasonable grounds to believe that\ncrimes against humanity were committed in Mitiga detention complex (Tripoli), as well as in\nGernada and al-Kwaifiya prisons (Benghazi). These places of detention hold thousands of\ndetainees. The Mission identified three separate widespread and systematic attacks\ncorresponding to each prison. They were considered separate due to the fragmentation of the\nState, the different actors involved and their spheres of power. Nonetheless, all three attacks\nshared the same anatomy and involved the same connected underlying acts with the same\nmotivation, nature, and modus operandi."},{"id":"a-hrc-52-crp-8-p0189","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"189","seq":190,"section":"B. Crimes against humanity committed in the detention of Libyans","text":"The ongoing “attack”, for the purposes of qualifying the violations as crimes against\nhumanity, were considered constituted by the actus reus of arbitrary detention, and of other\ninhumane acts."},{"id":"a-hrc-52-crp-8-p0190","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"190","seq":191,"section":"B. Crimes against humanity committed in the detention of Libyans","text":"Most of the detainees held at detention centres in Mitiga, Gernada, and al-Kwaifiya\nare civilians. Similarly, most detention cases documented by the Mission related to civilians.\nDetainees in these prisons are therefore the “civilian population” that is the object of the\nongoing attack. The Mission did not consider that the presence of conflict-related detainees\nand detainees detained based on vague allegations of ‘terrorism’ and tried by military courts\ndisturbed this characterization because conflict-related detainees were rendered hors de\ncombat at the time of the attack by virtue of their arbitrary detention and individuals brought\nbefore military courts remained civilians despite being subjected to military jurisdiction."},{"id":"a-hrc-52-crp-8-p0191","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"191","seq":192,"section":"B. Crimes against humanity committed in the detention of Libyans","text":"In terms of arbitrary detention, described in section VII.A, the Mission’s investigation\nrevealed a consistent modus operandi from the time of abduction to the time of detention.\nVictims were almost never informed of the reasons for their arrest or provided with\ninformation on the charges against them. Some detainees were imprisoned for years, without\nappearing before a judge and as discussed in paragraphs 88-89, release orders were frequently\nignored."},{"id":"a-hrc-52-crp-8-p0192","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"192","seq":193,"section":"B. Crimes against humanity committed in the detention of Libyans","text":"As illustrated in section VII, most of the individuals interviewed were victimized\nbecause of their dissent through the legitimate exercise of their rights, enshrined in the\nInternational Covenant on Civil and Political Rights, especially Article 19 (freedom of\nexpression). In many cases, their only transgression was the expression of a political opinion,\nthe holding of a religious belief, the challenging of social norms, or the exercise of other\nhuman rights guaranteed to them under international law. Others were detained based on their\nperceived affiliations to opposing groups or ideologies."},{"id":"a-hrc-52-crp-8-p0193","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"193","seq":194,"section":"B. Crimes against humanity committed in the detention of Libyans","text":"As part of the arbitrary detention was the consistent ill-treatment of detainees, as\nelaborated on in section VII.C. Not one of the victims interviewed had been held in acceptable\nconditions of detention."},{"id":"a-hrc-52-crp-8-p0194","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"194","seq":195,"section":"B. Crimes against humanity committed in the detention of Libyans","text":"The Mission established reasonable grounds to believe that at least the underlying acts\nof torture, murder, enforced disappearance, and persecution were committed in Libya since\n2016. On persecution, the Mission found that detainees were singled out for punishment\ninvolving prolonged arbitrary detention, enforced disappearance, torture, and other gross\nhuman rights violations on the grounds of their actual or perceived religious or political\nconvictions."},{"id":"a-hrc-52-crp-8-p0195","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"195","seq":196,"section":"XI. Responsibility","text":"A State is responsible for all acts that are attributable to it and constitute a breach of\nan international obligation.107 The Mission established that acts and conduct outlined in the\npresent report violated Libya’s international obligations under international treaty and\ncustomary law. In addition, under international customary law, acts are attributable to the\nState when they are committed by a State organ or persons or entities exercising elements of\ngovernmental authority. 108 In the case of conduct of non-State individuals or groups, the State\nstill incurs responsibility where these persons or groups act on the instruction of or under the\ndirection or control of the State, or when State agents acknowledge and adopt the conduct of\nnon-State groups.109 The State is also responsible when it fails to take all reasonable,\nnecessary measures to prevent the non-State actor from committing the acts and to protect its\npopulation from the conduct of non-State actors."},{"id":"a-hrc-52-crp-8-p0196","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"196","seq":197,"section":"XI. Responsibility","text":"In addition, the Mission collected reliable and consistent elements which indicate the\nresponsibility of some individuals for crimes against humanity in Libya. Those identified as\nlikely responsible for crimes against humanity consist of direct perpetrators and more senior\nofficials, such as military commanders or civilian leaders. These individuals could ultimately\nbe held criminally responsible if their acts were committed as part of the widespread or\nsystematic attack and they acted with knowledge that their conduct was part of such an attack."},{"id":"a-hrc-52-crp-8-p0197","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"197","seq":198,"section":"XI. Responsibility","text":"Assigning criminal responsibility to specific individuals requires an extensive,\nfocused investigation into, inter alia, the actions and states of mind of specific alleged\nperpetrators or other participants and will require additional fact-finding and investigation."},{"id":"a-hrc-52-crp-8-p0198","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"198","seq":199,"section":"XI. Responsibility","text":"Nonetheless, where evidence gathered by the Mission indicated, on the balance of\nprobabilities, that certain individuals committed crimes against humanity, these were duly\nrecorded in a preserved list. The list includes the names of suspects, information about the\npotential suspect’s position or role a summary of evidence compiled by the Mission relating\nto the potential suspect, examples of the underlying relevant allegations, and the Mission’s\ncharacterization of their possible liability. The list will be deposited, as part of the Mission’s\nevidentiary holdings, with the United Nations High Commissioner for Human Rights."},{"id":"a-hrc-52-crp-8-p0199","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"199","seq":200,"section":"A. Libyan State responsibility for crimes against humanity in Mitiga","text":"The Mission found reasonable grounds to believe that Radaa committed crimes\nagainst humanity in Mitiga prison. The Mission found that the State of Libya is responsible\nfor Radaa’s conduct, based on the doctrine of State responsibility."},{"id":"a-hrc-52-crp-8-p0200","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"200","seq":201,"section":"A. Libyan State responsibility for crimes against humanity in Mitiga","text":"Radaa was established by Abdel Raouf Kara in 2013 and mandated by Council of\nMinisters’ decision 224 of 2013 to ensure security and combat crime under the Ministry of\nthe Interior. Radaa,110 an established armed group, was integrated into and became\nsynonymous with DACOT."},{"id":"a-hrc-52-crp-8-p0201","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"201","seq":202,"section":"A. Libyan State responsibility for crimes against humanity in Mitiga","text":"DACOT was established by GNA Presidential Council decision in 2018 as an agency\nformally affiliated with the Ministry of the Interior.111 DACOT was given the competence to\ninter alia contribute to border security, counter criminalized organized crimes, secure\nelections, and cooperate to combat transboundary drug smuggling gangs.112"},{"id":"a-hrc-52-crp-8-p0202","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"202","seq":203,"section":"A. Libyan State responsibility for crimes against humanity in Mitiga","text":"In December of 2020, the Presidential Council reorganised DACOT in decision 578,\nseemingly giving Radaa remit rivalling that of the Ministry of the Interior while retaining the\ngroup’s oversight under the Presidency Council. Article 3 of decision 578 describes its\nmandate as encompassing combatting smuggling, organised crime, border protection, drug\ntrafficking and counterterrorism. Radaa controls Mitiga prison, where, as the Mission\nestablished, crimes against humanity are committed."},{"id":"a-hrc-52-crp-8-p0203","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"203","seq":204,"section":"A. Libyan State responsibility for crimes against humanity in Mitiga","text":"From 2019, offshoots of Radaa were absorbed into the Ministry of Justice (as the\nJudicial Security Apparatus) and into the Ministry of Defence (as the 444 Brigade). The\nJudicial Security Apparatus has since shadowed Libya’s official Judicial Police, asserting its\ncontrol over several State detention facilities and prisons."},{"id":"a-hrc-52-crp-8-p0204","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"204","seq":205,"section":"A. Libyan State responsibility for crimes against humanity in Mitiga","text":"Radaa is administratively under the nominal authority of the Presidency Council, and\nits members and equipment are funded by the Government of Libya. However, it maintains\nits own command structure and operates with a significant level of autonomy. Abdel Raouf\nKara remains the commander of Radaa."},{"id":"a-hrc-52-crp-8-p0205","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"205","seq":206,"section":"A. Libyan State responsibility for crimes against humanity in Mitiga","text":"Radaa is therefore to be considered either a State organ or an entity that has been\nempowered to exercise elements of governmental authority, making its acts attributable to\nthe State of Libya under international law."},{"id":"a-hrc-52-crp-8-p0206","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"206","seq":207,"section":"B. Libyan State responsibility for crimes against humanity in prisons in","text":"The Mission found that there are reasonable grounds to believe that the LAAF, given\nits overall authority over prisons in the east, committed crimes against humanity in Gernada\nand al-Kwaifiya prisons. These crimes have been perpetrated by members of the TBZ and\nthe ISA in the east."},{"id":"a-hrc-52-crp-8-p0207","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"207","seq":208,"section":"B. Libyan State responsibility for crimes against humanity in prisons in","text":"TBZ is a brigade under the LAAF. Officially, the group is controlled by Omar Mraja\nal-Megerhi pursuant to a decision of the General Command of the Armed Forces. There are\nreasonable grounds to believe, however, that TBZ is under the effective control of Saddam\nHaftar, the son of Khalifa Haftar. The brigade controls military barracks in Benghazi and its\noperational deployment spans most of the areas under the control of the LAAF. TBZ has\ncontrol over detention facilities in eastern Libya including military sections of prisons in al-\nKwaifiya and Gerrnada."},{"id":"a-hrc-52-crp-8-p0208","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"208","seq":209,"section":"B. Libyan State responsibility for crimes against humanity in prisons in","text":"The LAAF is a parallel armed force established by the HOR. In March 2015, the HOR\nestablished the post of “General Commander of the Armed Forces” with a wide mandate\nincorporating that of the Minister of Defence and appointing General Khalifa Haftar to the\npost. The LAAF maintains its own command structure and operates with a significant level\nof autonomy. However, the LAAF is funded by the Government of Libya and the salaries of\nmembers of the LAAF are disbursed by the Government in Tripoli."},{"id":"a-hrc-52-crp-8-p0209","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"209","seq":210,"section":"B. Libyan State responsibility for crimes against humanity in prisons in","text":"ISA is a civil institution of the Libyan State established by a Council of Ministers\ndecision. ISA has country-wide jurisdiction and is headquartered in Tariq al-Sikka in Tripoli.\nThe Mission understood that ISA branches operate under the influence of authorities in east\nand west Libya, depending on their location. Funding to ISA branches in the east is\nchannelled from the Government in Tripoli through the LAAF. ISA branches operating in\nthe east are headed by Major General Ousama Mohammed al-Dersi since November 2022.\nISA in the west is headed by General Lotfi al-Hariri since January 2021. The Mission\ncollected evidence suggesting increased cooperation between ISA operating in the east and\nwest."},{"id":"a-hrc-52-crp-8-p0210","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"210","seq":211,"section":"B. Libyan State responsibility for crimes against humanity in prisons in","text":"The Mission found reasonable grounds to believe that the LAAF and ISA are either\nto be considered State organs or entities that have been empowered to exercise elements of\ngovernmental authority, making its acts attributable to the State of Libya under international\nlaw."},{"id":"a-hrc-52-crp-8-p0211","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"211","seq":212,"section":"C. Libyan State responsibility for crimes against humanity against","text":"The DCIM was created as a governmental agency by virtue of decision 386 of 2014.\nIt is an official entity of the Libyan Ministry of the Interior responsible for migrant detention\ncentres across Libya."},{"id":"a-hrc-52-crp-8-p0212","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"212","seq":213,"section":"C. Libyan State responsibility for crimes against humanity against","text":"The DCIM’s jurisdiction is Libya-wide and on-land. Its core functions are to inter alia\noversee and run the country’s migrant detention centres, gather intelligence on human\nsmuggling, and set up operations relevant to human traffickers and migrant smugglers."},{"id":"a-hrc-52-crp-8-p0213","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"213","seq":214,"section":"C. Libyan State responsibility for crimes against humanity against","text":"The current head of the DCIM is Mohamed al-Khoja, appointed in January 2022 by\nthe Council of Ministers of the GNU through decision 742 of 2021. Mr. al-Khoja is in\neffective control of the Tariq al-Sikka detention centre.\nb.     Stability Support Apparatus"},{"id":"a-hrc-52-crp-8-p0214","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"214","seq":215,"section":"C. Libyan State responsibility for crimes against humanity against","text":"The Mission found reasonable grounds to believe that the SSA is responsible for\ncrimes against humanity committed in the migrant detention centres under their control, in\nparticular Abu Salim, Ayn Zarah, and Abu Isa, as well as crimes against humanity committed\nby its DCSIM in connection with violent sea interceptions off the coast of Zawiya, as the\nSSA has also become increasingly engaged in such activities.113"},{"id":"a-hrc-52-crp-8-p0215","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"215","seq":216,"section":"C. Libyan State responsibility for crimes against humanity against","text":"The SSA was established in January 2021 by GNA Presidential Council decision. 114\nThe SSA is made up of an alliance of armed groups and led by militia leader Abdel Ghani\nal-Kikli, also known as “Ghneiwa”. The SSA’s competence is broadly to protect the security\nof the State. It sits under the Presidential Council. Presidential Council decision 38\nguaranteed the SSA a source of “independent” income, with little to no oversight, through\nthe Presidential Council.115"},{"id":"a-hrc-52-crp-8-p0216","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"216","seq":217,"section":"C. Libyan State responsibility for crimes against humanity against","text":"One component of the SSA is the Department for Combatting Settlement and Illegal\nMigration (DCSIM). The DCSIM was established by the SSA in December 2021 for the\npurpose of formalizing its engagement in anti-migration efforts. While its mandate and the\nformal process behind its formation are unclear, the DCSIM effectively encroaches on the"},{"id":"a-hrc-52-crp-8-p0217","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"217","seq":218,"section":"DCIM. Other SSA-affiliated units include the Zawiya Refinery coast guard (also known as","text":"The Mission found reasonable grounds to believe that the SSA is to be considered\neither a State organ or an entity that has been empowered to exercise elements of\ngovernmental authority, making its acts attributable to the State of Libya under international\nlaw.\nc.     Libyan Coast Guard"},{"id":"a-hrc-52-crp-8-p0218","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"218","seq":219,"section":"DCIM. Other SSA-affiliated units include the Zawiya Refinery coast guard (also known as","text":"The most relevant Libyan actor in interceptions at sea is the Libyan Coast Guard, a\nbranch of the Libyan Navy under the Ministry of Defence."},{"id":"a-hrc-52-crp-8-p0219","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"219","seq":220,"section":"DCIM. Other SSA-affiliated units include the Zawiya Refinery coast guard (also known as","text":"Like many other Libyan State institutions, the LCG has apparently become\nintertwined with militias and armed groups and has worked in close coordination with the\nsmuggling and trafficking networks in Libya. For example, the Az-Zawiya Refinery Coast\nGuard, a branch of the LCG led by Abd Al-Rahman Milad, is reported to return migrants and\nrefugees intercepted at sea to the al-Nasr detention centre.116 The Mission found that crimes\nagainst humanity were committed at relevant detention centres and in relation to sea\ninterceptions, pullbacks, and returns."},{"id":"a-hrc-52-crp-8-p0220","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"220","seq":221,"section":"DCIM. Other SSA-affiliated units include the Zawiya Refinery coast guard (also known as","text":"The Mission found reasonable grounds to believe that the LCG is to be considered\neither a State organ or an entity that has been empowered to exercise elements of\ngovernmental authority, making its acts attributable to the State of Libya under international\nlaw."},{"id":"a-hrc-52-crp-8-p0221","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"221","seq":222,"section":"XII. Conclusions and recommendations","text":"Conduct and patterns of gross violations of international human rights law and\ninternational humanitarian law described in the present report continue unabated, and there\nis little evidence that meaningful steps are being taken to reverse this troubling trajectory and\nbring recourse to victims. Structural, fundamental reforms of the Libyan constitutional and\nlegislative framework, executive branch, and security sectors are necessary to uphold the rule\nof law and bring an end to the repression of fundamental human rights and freedoms of\nLibyans and the exploitation of migrants. Furthermore, Libyans and other persons, including\nmigrants, are in desperate need of accountability. Accountability should encompass the right\nto effective remedy for harm suffered by both the State and individuals at all levels of the\nhierarchy."},{"id":"a-hrc-52-crp-8-p0222","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"222","seq":223,"section":"XII. Conclusions and recommendations","text":"To that end, all of the Mission’s previous recommendations remain relevant and must\nbe implemented.\n223    The Mission also calls on the authorities of Libya:\n(a)    To investigate and prosecute individuals allegedly responsible for\nviolations and abuses of international humanitarian and human rights law and\ndomestic criminal law, in accordance with due process guarantees and the\nprinciple of legality. To this end, they should exclude amnesty for gross human\nrights violations and international crimes and provide a safe working\nenvironment for judges, lawyers and prosecutors;\n(b)    To abide by the pledge made to the Human Rights Council in 2022 to use\nthe findings and recommendations of the Mission as a baseline for Libya’s future\nreports to the Council under the universal periodic review and human rights\ntreaty bodies;\n(c)   To undertake effective disarmament, demobilization, reintegration and\nrehabilitation measures to establish integrated armed and security forces in\nkeeping with international standards and practices;\n(d)     To restructure the State security sector and subject it to an independent\ncivilian oversight mechanism that operates in accordance with international law\nstandards;\n(e)  To cease all military trials of civilians and halt the implementation of\njudgments issued by military courts against civilians;\n(f)     To end the criminalization of irregular entry and stay of migrants in Libya\nand immediately release arbitrarily detained migrants, including by amending\nLaw No. 19 on Combating Irregular Migration of 2010. Where migrant detention\nis justified, ensure that women and men are separated and are kept in humane\nand dignified conditions;\n(g)    To dismantle secret prisons and immediately release all persons\narbitrarily detained;\n(h)   To cooperate fully with the United Nations human rights system and\nimplement recommendations made by all United Nations special procedures\nmandate holders and facilitate their unhindered and safe access to all parts of\nLibya and places of detention, as requested;\n(i)   To cooperate fully with and facilitate unhindered and safe access to the\nInternational Criminal Court;\n(j)    To ensure the enjoyment of fundamental rights, including the free and\nsafe exchange of diverse opinions and information, including by refraining from\nengaging in smear campaigns against individuals and civil society;\n(k)    To protect and promote the rights of women, minorities, persons of\ndiverse sexual orientations and gender identities, civil society activists,\njournalists and human right defenders and encourage their participation in\npolitical and public life.\n(l)    To amend provisions of the Libyan Penal Code and the Publications Law\nto the extent necessary to align them with international human rights law;\n(m) To amend the Anti-Cybercrime Law, the Law on Civic Associations,\nmedia regulations, including decision No. 811 (2022), and the Publications Law\nto the extent necessary to align them with international human rights law;\n(n)    To remedy and abolish undue restrictions imposed on national and\ninternational civil society organizations in Libya, including the decision adopted\nby the Civil Society Commission in February 2023 on the licensing of civil society\norganizations operating in Libya and the advisory opinion by the Supreme\nJudicial Council of March 2023;\n(o)   To strengthen efforts to organize free, fair and transparent elections;\n(p)   To take remedial action to realize victims’ rights to truth, justice and\nreparations, and to that end:\n(i)    To develop and adopt a holistic national human rights plan of\naction that reflects international human rights law and standards and\naddresses all findings and recommendations made by the Mission and\ninternational human rights bodies;\n(ii)  To enact legislation and develop a system to protect victims and\nwitnesses from reprisal;\n(iii) To develop a comprehensive, inclusive, victim-centred and detailed\nroad map on transitional justice and accountability for Libya;\n(iv) To amend article 417 of the Code of Criminal Procedure to allow\nfor civil proceedings even in the absence of a criminal conviction.\n(q)    To eliminate all forms of discrimination against women, including by\ntaking appropriate measures to modify practices that marginalize women in\npublic and private spheres;\n(r)    To ensure that comprehensive legislation protects, prevents, and punishes\nviolence against women, bring the legal definition of rape in line with\ninternational law and standards and repeal provisions, such as article 424 of the\nLibyan Penal Code, that mitigate or absolve the perpetrator of responsibility for\nrape;\n(s)    To ensure that internally displaced persons can make voluntary and\ninformed decisions about the type of durable solutions they pursue, including\nreturn to their places of origin, and guarantee that internally displaced persons\nhave access to their rights and entitlements in their areas of displacement without\nany discrimination;\n(t)   To ensure that all unexploded ordnance is removed;\n(u)    To continue searching for the missing and remaining mass graves,\nincluding by using the Mission’s findings in that regard on Tarhuna, and, to that\nend, take steps to ratify the International Convention for the Protection of All\nPersons from Enforced Disappearance;\n(v)    To take steps to implement the national Durable Solutions Strategy and\nother relevant frameworks for the resolution of internal displacement, including\nby allocating the necessary funding and investing in the reconstruction of areas\nof origin of internally displaced persons;\n(w) To strengthen the independence of the National Human Rights Institute,\nincluding by implementing the Principles Relating to the Status of National\nHuman Rights Institutions.\n218. The Mission calls on the United Nations, the international community and third\nStates:\n(a)    To urge the Human Rights Council to establish an independent,\ninternational investigation mechanism and to call on the Office of the United\nNations High Commissioner for Human Rights to establish a distinct and\nautonomous mechanism with an ongoing mandate to monitor and report on\ngross human rights violations in Libya, with a view to supporting Libyan\nreconciliation efforts and assisting the Libyan authorities in achieving\ntransitional justice and accountability. In this regard, the Mission calls on the\nUnited Nations, the international community and third States to extend to the\nproposed mechanisms the resources necessary for them to undertake their tasks\nin an efficient and effective manner;\n(b)   To apply a strict human rights due diligence policy to their support to\nauthorities in Libya, especially with respect to the Libyan State security sector;\n(c)   To increase resources and other support to the United Nations Support\nMission in Libya to promote and protect human rights pursuant to Security\nCouncil resolution 2542 (2020);\n(d)    To assist Libya in developing and implementing a national human rights\naction plan by, inter alia, providing it with technical and capacity-building\nsupport;\n(e)   To exercise universal jurisdiction over international crimes committed in\nLibya, including over mercenaries and foreign fighters;\n(f)    To cooperate with the Office of the Prosecutor of the International\nCriminal Court investigation of the situation in Libya, including by surrendering\nindividuals for whom an arrest warrant has been issued;\n(g)   To abide by the customary international law principle of non-refoulement\nand cease all direct and indirect support to Libyan actors involved in crimes\nagainst humanity and gross human rights violations against migrants, such as\nthe Directorate for Combating Illegal Migration, the Stability Support\nApparatus and the Libyan Coast Guard;\n(h)   To regulate migration in accordance with international law and the\nGlobal Compact for Safe, Orderly and Regular Migration."},{"id":"a-hrc-52-crp-8-u0224","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":null,"seq":224,"section":"I. Definition of crimes against humanity","text":"219. Broadly, the definition of crimes against humanity in Article 7 of the Rome Statute to\nthe International Criminal Court (ICC) reflects that accepted in general international law. It\nis unknown which variant of this offence may ultimately be utilised in relation to crimes\ncommitted in Libya. For its part, the Mission based its investigations on the definition of\ncrimes against humanity under the Rome Statute, however it did not adopt the ICC’s State or\norganisational policy requirement (of the “attack” component of the chapeau) as formulated\nin Article 7(2)(a) as a distinct contextual element for two reasons. The first is that there are\nsome indications in ICC jurisprudence of a nascent shift away from such a requirement 117 and\nsecondly, considering the drafting history of the ICC Statute, the rationale underlying the\ninclusion of a policy element in the definition was to “help distinguish between what is of\nconcern to the international community on the one hand and, on the other, the sort of crimes\nthat should remain the exclusive concern of domestic jurisdictions”.118 This normative\nlimitation, effectively limiting the ICC’s jurisdiction, does not apply to the Mission.\nFurthermore, the Mission has also departed from the ICC in that it has not applied the\n“prolonged” requirement with respect to enforced disappearance as a crime against humanity.\n220. The prohibition of crimes against humanity is recognized as a principle of jus cogens\nand is universally applicable.119 Crimes against humanity entail gross human rights violations\nof a scale and level of organisation that shock the conscience of humanity.\n221. Article 7(1) of the ICC Statute, which largely reflects customary international law,\ndefines crimes against humanity as any of the following acts when committed as part of a\nwidespread or systematic attack directed against any civilian population, with knowledge of\nthe attack:\n(a)    Murder;\n(b)    Extermination;\n(c)    Enslavement;\n(d)    Deportation or forcible transfer of population;\n(e)    Imprisonment;\n(f)    Torture;\n(g)    Rape and forms of sexual violence;\n(h)    Persecution on political, racial, national, ethnic, cultural, religious, gender as\ndefined in paragraph 3, or other grounds;\n(i)    Enforced disappearance of persons;\n(j)    The crime of apartheid;","unnumbered":true},{"id":"a-hrc-52-crp-8-u0225","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":null,"seq":225,"section":"I. Definition of crimes against humanity","text":"(k)     Other inhumane acts of a similar character intentionally causing great\nsuffering, or serious injury to body or to mental or physical health.\n222. Pursuant to Article 7(2)(a) of the Statute, an “[a]ttack directed against any civilian\npopulation” means a course of conduct involving the multiple commission of acts referred to\nin paragraph 1 against any civilian population, pursuant to or in furtherance of a State or\norganizational policy to commit such attack.120","unnumbered":true},{"id":"a-hrc-52-crp-8-p0223","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"223","seq":226,"section":"A. Article 7 chapeau requirements","text":"An “attack” for the purposes of crimes against humanity has been described as “a\ncourse of conduct involving the commission of acts of violence”. 121 A “course of conduct”\nsignifies a “systemic aspect” to the attack, describing “a series or overall flow of events as\nopposed to a mere aggregate of random acts. The ‘multiple commission of acts’ sets a\nquantitative threshold involving a certain number of acts falling within the course of\nconduct”.122"},{"id":"a-hrc-52-crp-8-p0224","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"224","seq":227,"section":"A. Article 7 chapeau requirements","text":"The notion of “attack” encompasses any form of mistreatment of a civilian\npopulation123 that includes multiple commission of acts referred to in Article 7(1). 124 The\nattack need not necessarily be military in nature, and it may involve any form of violence\nagainst a civilian population.125 An attack may precede, outlast, or continue during an armed\nconflict, without necessarily being part thereof.126 It is an event in which the enumerated\ncrimes must form part.127\nb.     Directed against a civilian population"},{"id":"a-hrc-52-crp-8-p0225","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"225","seq":228,"section":"A. Article 7 chapeau requirements","text":"The International Criminal Tribunal for the former Yugoslavia (ICTY) held that “the\nemphasis is not on the individual victim but rather on the collective, the individual being\nvictimised not because of [their] individual attributes but rather because of [their]\nmembership of a targeted civilian population”128 Article 7 of the ICC Statute does not require\na separate finding that the civilian population was the primary object of the attack.”129"},{"id":"a-hrc-52-crp-8-p0226","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"226","seq":229,"section":"A. Article 7 chapeau requirements","text":"The term “civilian” refers to persons who are not members of any armed forces or\nother legitimate combatants.130 The term ‘civilian population’ means that the population must\nsimply be predominantly civilian in nature.131 Members of armed forces placed hors de\ncombat by sickness, wounds, detention, or any other cause, may also be victims of acts\namounting to crimes against humanity.132"},{"id":"a-hrc-52-crp-8-p0227","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"227","seq":230,"section":"A. Article 7 chapeau requirements","text":"Relevant factors include the means and methods used in the course of the attack; the\nnumber and status of the victims; the discriminatory nature, if any, of the attack, in terms of\na pattern related to the national, ethnic, racial or religious identity of victims; and the nature\nof the crimes committed in its course133 and evidence of the scale of the crimes committed in\nthe course of the attack.134\nc.     Widespread or systematic character of the attack"},{"id":"a-hrc-52-crp-8-p0228","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"228","seq":231,"section":"A. Article 7 chapeau requirements","text":"Under both the Rome Statute (Article 7(1)) and customary international law, the attack\nagainst the civilian population as a whole – as opposed to the individual underlying crimes -\nmust be either widespread or systematic in nature.135 Although the two criteria are disjunctive\nrather than cumulative, they are often difficult to separate since a widespread attack targeting\na large number of victims is generally predicated on some degree of coordination, planning\nor organisation."},{"id":"a-hrc-52-crp-8-p0229","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"229","seq":232,"section":"A. Article 7 chapeau requirements","text":"The term “widespread” refers to the large-scale nature of the attack, its geographic\nscope, and the number and multiplicity of civilians against whom the attack is directed.136 It\nmay be established by the cumulative effect of a multiplicity of smaller, discrete acts, or the\nsingular effect of an inhumane act of extraordinary magnitude.137"},{"id":"a-hrc-52-crp-8-p0230","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"230","seq":233,"section":"A. Article 7 chapeau requirements","text":"The ICC Trial Chamber III in Bemba held the term “widespread” to denote an attack\nthat is massive, frequent, carried out collectively with considerable seriousness and directed\nagainst a multiplicity of victims, 138 or “an attack carried out over a large geographical area or\nan attack in a small geographical area directed against a large number of civilians”. 139 Hence,\na key feature of the “widespread” standard is that it is intended to exclude isolated acts of\nviolence,140 such as “murder directed against individual victims by persons acting of their\nown volition rather than as part of a broader initiative”.141 The assessment as to whether an\nattack is widespread is “neither exclusively quantitative nor geographical, [and] must be\ncarried out on the basis of the individual facts”.142"},{"id":"a-hrc-52-crp-8-p0231","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"231","seq":234,"section":"A. Article 7 chapeau requirements","text":"“Systematic” refers to the “organised nature of the acts of violence and the\nimprobability of their random occurrence”143 in furtherance of a common policy, which\nfollows a regular pattern and results in a continuous commission of acts or as ‘patterns of\ncrimes’ such that the crimes constitute a non-accidental repetition of similar criminal conduct\non a regular basis.144 It requires “organized action, following a regular pattern, on the basis\nof a common policy and involves substantial public or private resources”."},{"id":"a-hrc-52-crp-8-p0232","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"232","seq":235,"section":"A. Article 7 chapeau requirements","text":"In determining whether an attack is systematic and to identify patterns of crimes, the\nfollowing are taken into account: (i) identical acts took place or similarities in criminal\npractices can be identified; (ii) the same modus operandi (and/or means or methods) was\nemployed or (iii) victims were treated in a similar manner across a wide geographic area.145\nFurther indicators of the systematic nature of an attack include that: (i) the violations are in\nline with an underlying political objective; (ii) there is an ideology to destroy, persecute or\nweaken a community, including on the basis of national/ethnic/racial or religious grounds;\n(iii) high-level political and/or military authorities are implicated in the definition and\nestablishment of a methodical plan to commit violations; (iv) propaganda, indoctrination or\npsychological oppression are used to create an environment in which crimes will occur; (v)\ncriminal acts are being perpetrated on a very large scale and follow a regular pattern making\nit improbable that the acts could occur randomly; (vi) there is a repeated and continuous\nco146mmission of inhumane acts linked to one another; and (vii) organized efforts are made\nto conceal the crimes committed.147"},{"id":"a-hrc-52-crp-8-p0233","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"233","seq":236,"section":"A. Article 7 chapeau requirements","text":"Neither the underlying attack nor the acts of the accused need be supported by any\nform of state or organisational plan or policy. Nor is a plan or policy a necessary element of\nproof that the underlying attack was systematic in character; 148 nonetheless may serve as\nevidence of the systematic character of the attack. This policy may be made by an organ of\nthe State but can also be formulated “by groups of persons who govern a specific territory or\nby any organisation with the capability to commit a widespread or systematic attack against\na civilian population”.149 A policy can therefore be “inferred by discernment of, inter alia,\nrepeated actions occurring according to a same sequence, or the existence of preparations or\ncollective mobilisation orchestrated and coordinated by that State or organisation” 150 or from\na variety of factors which taken together, establish that a policy existed."},{"id":"a-hrc-52-crp-8-p0234","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"234","seq":237,"section":"B. Applicable Underlying Acts","text":"The crime of murder under international criminal law requires unlawfully causing the\ndeath of a person. 151 The crime of murder can be caused by either an act or an omission. 152 In\nterms of the mental element, the perpetrator must either act with the subjective purpose of\ncausing such death or serious injury or awareness that the death would be the consequence\nof the relevant conduct.153\nb.     Enslavement"},{"id":"a-hrc-52-crp-8-p0235","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"235","seq":238,"section":"B. Applicable Underlying Acts","text":"The exercise of any or all of the powers ordinarily attaching to the right of ownership\nover a person amounts to enslavement,154 meaning “the use, enjoyment and disposal of a\nperson who is regarded as property, by placing him or her in a situation of dependence which\nentails his or her deprivation of any form of autonomy”. 155"},{"id":"a-hrc-52-crp-8-p0236","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"236","seq":239,"section":"B. Applicable Underlying Acts","text":"Thus, forced labour can amount to enslavement if it is accompanied by aggravating\ncircumstances that effectively destroy the juridical personhood of the victim. 156 Forced labour\ncan therefore rise to the level of enslavement, even without any additional evidence of\nmistreatment.157 To determine if forced labour reaches the threshold, the question is whether\n“the relevant persons had no choice as to whether they would work”. 158"},{"id":"a-hrc-52-crp-8-p0237","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"237","seq":240,"section":"B. Applicable Underlying Acts","text":"Relevant circumstances include detention or captivity; the degree of control exercised\nover the victim’s autonomy; freedom of choice or freedom of movement, including measures\ntaken to prevent or deter escape; fear of violence; abuse of power; duration, conditions and\nintensity of forced labour; victims’ vulnerability; subjection to cruel treatment and abuse; and\nintense control of sexuality.159"},{"id":"a-hrc-52-crp-8-p0238","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"238","seq":241,"section":"B. Applicable Underlying Acts","text":"The Elements of Crimes for Article 7(1)(c) require that “the perpetrator exercised any\nor all of the powers attaching to the right of ownership over one or more persons, such as by\npurchasing, selling, lending or bartering such a person or persons, or by imposing on them a\nsimilar deprivation of liberty”. This element reflects the jurisprudence of the ICC and the ad\nhoc international criminal tribunals on the crime of enslavement as a crime against\nhumanity.160","printed":"228"},{"id":"a-hrc-52-crp-8-p0239","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"239","seq":242,"section":"B. Applicable Underlying Acts","text":"In Katanga, Trial Chamber II understood the powers attaching to the right of\nownership as “the use, enjoyment and disposal of a person who is regarded as property, by\nplacing him or her in a situation of dependence which entails his or her deprivation of any\nform of autonomy”.161 Thus, the exertion of such powers can only be established on a case-\nby-case basis and the list of examples included in the Elements of Crimes is not exhaustive.162"},{"id":"a-hrc-52-crp-8-p0240","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"240","seq":243,"section":"B. Applicable Underlying Acts","text":"Further, the Elements of Crimes provide that “such deprivation of liberty may, in some\ncircumstances, include exacting forced labour or otherwise reducing a person to a servile\nstatus as defined in the Supplementary Convention on the Abolition of Slavery, the Slave\nTrade, and Institutions and Practices Similar to Slavery of 1956.163 It is also understood that\nthe conduct described in this element includes trafficking in persons, in particular women\nand children”.164"},{"id":"a-hrc-52-crp-8-p0241","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"241","seq":244,"section":"B. Applicable Underlying Acts","text":"The ICC explicitly recognised the following criteria in determining the exercise of\npowers attaching to the right of ownership: (i) control or restrictions of someone’s movement\nand, more generally, measures taken to prevent or deter escape; (ii) control of physical\nenvironment; (iii) psychological control or pressure; (iv) force, threat of force or coercion;\n(v) duration of the exercise of powers attaching to the right of ownership; (vi) assertion of\nexclusivity; (vii) subjection to cruel treatment and abuse; (viii) control of sexuality; (ix)\nforced labour or subjecting the person to servile status; and (x) the person’s vulnerability and\nthe socio-economic conditions in which the power is exerted.165"},{"id":"a-hrc-52-crp-8-p0242","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"242","seq":245,"section":"B. Applicable Underlying Acts","text":"Further, the imposition of a “similar deprivation of liberty” as required by the\nElements of Crimes may take various forms, encompassing ‘situations in which the victims\nmay not have been physically confined, but were otherwise unable to leave as they would\nhave nowhere else to go and fear for their lives.’166"},{"id":"a-hrc-52-crp-8-p0243","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"243","seq":246,"section":"B. Applicable Underlying Acts","text":"Nonetheless, previous ICC jurisprudence has identified several circumstances under\nwhich a deprivation of liberty may amount to the exercise of powers attached to the right of\nownership. In Ntaganda, Trial Chamber IV established that the accused committed sexual\nslavery since, following the abduction of a victim and the deprivation of their liberty that\nensued, he exercised powers attached to the right of ownership over the victim. The capture\nwas understood to be the demonstration of the accused’s initial exercise of powers attached\nto the rights of ownership over a person.167 However, without elaborating further on two other\nfemale victims that were also captured, the Trial Chamber considered that their capture was\nnot a deprivation of liberty tantamount to exercising powers attaching to the rights of\nownership over the victims.168"},{"id":"a-hrc-52-crp-8-p0244","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"244","seq":247,"section":"B. Applicable Underlying Acts","text":"Although monetary exchanges or commercial transactions are not a requirement for\nthe crime of enslavement, they are prime indicators of the exercise of powers attaching to the\nrights of ownership.169"},{"id":"a-hrc-52-crp-8-p0245","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"245","seq":248,"section":"B. Applicable Underlying Acts","text":"The crime of trafficking in persons and the crime of enslavement as a crime against\nhumanity partly overlap. Despite the differences in legal characterisation, both crimes rely\non the same underlying conduct.170 In this sense, insofar as human trafficking indicates the\npara. 342; Kunarac et al, Appeal Judgment, para. 119; SCSL, Taylor, Judgement, para. 447; SCSL,\nProsecutor v. Issa Hassan Sesay et al., SCSL-04-15-T, Trial Judgement, 2 March 2009, para. 199.\nexercise of powers attaching to a right of ownership, the conduct also fulfils the material\nelements of enslavement.\nc.     Imprisonment"},{"id":"a-hrc-52-crp-8-p0246","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"246","seq":249,"section":"B. Applicable Underlying Acts","text":"Imprisonment as a crime against humanity requires that an individual is arbitrarily\ndeprived of his or her liberty, and that this deprivation is done intentionally or in the\nreasonable knowledge that arbitrary deprivation of liberty is likely to occur. 171 Not every\ninfringement of liberty forms the material element of the underlying offence; the deprivation\nof liberty must be of similar gravity and seriousness as the other crimes enumerated as crimes\nagainst humanity.172 A deprivation of liberty amounts to imprisonment if it is arbitrary and\ntherefore illegal, with the term ‘arbitrary’ establishing the requirement that the deprivation\nbe without due process of law.173"},{"id":"a-hrc-52-crp-8-p0247","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"247","seq":250,"section":"B. Applicable Underlying Acts","text":"In assessing whether imprisonment constitutes a crime against humanity, relevant\nfactors are whether the initial arrest was unlawful by considering, for example, whether it\nwas based on a valid arrest warrant, whether the detainees were informed of the reasons for\ntheir detention, whether the detainees were ever formally charged, whether they were\ninformed of any procedural rights, and whether any period of detention was lawful.174"},{"id":"a-hrc-52-crp-8-p0248","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"248","seq":251,"section":"B. Applicable Underlying Acts","text":"The Working Group on Arbitrary Detention has classified secret detention as being\nper se arbitrary as it is clearly impossible to invoke any legal basis justifying the deprivation\nof liberty, and its very nature may result in indefinite periods of detention.175 The practice of\nsecret detention ipso facto violates the guarantees enshrined in Articles 9 (right to liberty)\nand 14 (right to a fair trial) of the International Covenant on Civil and Political Rights\n(ICCPR), or in most cases, automatically or inherently entails such consequences that amount\nto a violation. Under IHRL, every instance of secret detention by a state or de facto state\nauthority also amounts to a case of enforced disappearance176 and also violates the prohibition\nagainst torture and other forms of ill-treatment177 including because every instance of secret\ndetention is by definition incommunicado detention.178 Indefinite or prolonged solitary\nconfinement179 - in excess of 15 consecutive days180 - as a restriction or disciplinary sanction\nmay amount to torture or other cruel, inhuman or degrading treatment or punishment. 181\nConfinement under inhumane conditions can be included in the underlying acts of\n“imprisonment” and \"other inhumane acts\" and also meets the definition of a persecutory\nact.182\nd.     Torture"},{"id":"a-hrc-52-crp-8-p0249","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"249","seq":252,"section":"B. Applicable Underlying Acts","text":"Under the Rome Statute, torture as a crime against humanity means the intentional\ninfliction of severe pain and suffering, whether physical or mental, upon a person in the\ncustody or under the control of the accused.183 Under the Rome Statute, the crime against\nhumanity of torture does not require the act to be committed with a specific purpose, or by a\npublic official.184"},{"id":"a-hrc-52-crp-8-p0250","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"250","seq":253,"section":"B. Applicable Underlying Acts","text":"The material elements of this crime are (1) the infliction of severe pain and suffering,\nwhether physical or mental; and (2) that the infliction is on a person in the custody or under\nthe control of the accused. Although there is no definition of the threshold of “severe”, “an\nimportant degree of pain and suffering has to be reached”.185 The objective severity of the\nharm inflicted must be first assessed, before considering subjective criteria such as the\nphysical or mental effect on the victim.186 When assessing the seriousness of acts charged as\ntorture, one must “take into account all the circumstances of the case, including the nature\nand context of the infliction of pain, the premeditation and institutionalisation of the ill-\ntreatment, the physical condition of the victim, the manner and method used, and the position\nof inferiority of the victim. The extent that an individual has been mistreated over a prolonged\nperiod of time will also be relevant”.187 Intentionally subjecting persons to extremely\ninhumane conditions of detention can also constitute ‘other inhumane acts’ as a crime against\nhumanity.188"},{"id":"a-hrc-52-crp-8-p0251","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"251","seq":254,"section":"B. Applicable Underlying Acts","text":"Acts considered to amount to “severe pain or suffering” for the purpose of torture\ninclude: severe beatings, punches and kicks; rape, attempted rape and other forms of sexual\nviolence; electric shocks; and deprivation of sleep, food or water. 189 Examples of treatment\ncausing mental suffering include: mock executions, prolonged solitary confinement and\nthreats of death or violence and being forced to watch others being killed, tortured or raped. 190"},{"id":"a-hrc-52-crp-8-p0252","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"252","seq":255,"section":"B. Applicable Underlying Acts","text":"The very fact of being detained as a disappeared person, isolated from one’s family\nfor a long period is certainly a violation of the right to humane conditions of detention and\nthe prohibition of torture. 191 According to the Special Rapporteur on Torture, “to make\nsomeone disappear is a form of prohibited torture or ill-treatment, clearly as regards the\nrelatives of the disappeared person and arguably in respect of the disappeared person or\nhim/herself”.192 Under the Convention against Torture, \"torture\" means any act by which\nsevere pain or suffering, whether physical or mental, is intentionally inflicted on a person\nfor such purposes as obtaining from him or a third person information or a confession,\npunishing him for an act he or a third person has committed or is suspected of having\ncommitted, or intimidating or coercing him or a third person, or for any reason based on\ndiscrimination of any kind, when such pain or suffering is inflicted by or at the instigation\nof or with the consent or acquiescence of a public official or other person acting in an\nofficial capacity."},{"id":"a-hrc-52-crp-8-p0253","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"253","seq":256,"section":"B. Applicable Underlying Acts","text":"As to the mental element, Article 7(2)(e) of the ICC requires that the infliction of pain\nand suffering must be intentional. This means that Article 30 of the Rome Statute, which sets\nup a general requirement for the double elements of intent and knowledge, is not applicable\nhere.193 It is therefore sufficient that the perpetrator intended to inflict pain or suffering, and\nthat the victim endured severe pain or suffering.194\ne.     Rape, sexual slavery, enforced prostitution and other sexual violence"},{"id":"a-hrc-52-crp-8-p0254","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"254","seq":257,"section":"B. Applicable Underlying Acts","text":"Crimes against humanity encompass rape.195 International criminal law considers as\nrape any unjustified coercive invasion of the genital opening of the victim with a part of the\nperpetrator’s body. 196 This can include cavity searches that do not meet strict standards of\nlegality, necessity, and proportionality.197 Instances where female detainees are pressed into\n“consensual” sexual relations to avoid forced labour, or to receive food and other advantages,\nmay also amount to rape as defined under international law, because the perpetrators take\nadvantage of the coercive circumstances of detention and the resulting vulnerability of female\ndetainees.198"},{"id":"a-hrc-52-crp-8-p0255","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"255","seq":258,"section":"B. Applicable Underlying Acts","text":"The Rome Statute explicitly states that trafficking can amount to an international\ncrime in the form of enslavement and sexual slavery199 as crimes against humanity. Sexual\nslavery is a form of slavery, and its prohibition is a jus cogens norm. 200 Sexual slavery is part\nof the trafficking of women and girls for sexual exploitation.201 The crime of sexual slavery\nrequires the right of ownership over the victims. This element also constitutes the main\nrequirement of the broader crime of enslavement (see above). In Ongwen, Trial Chamber IX\nanalysed charges of both enslavement and sexual slavery, finding that the objective element\nof exercise of powers attaching to the right of ownership of the victims was fulfilled given\nthat the accused ‘deprived these women of their personal liberty, restricted and dictated their\nmovement, including by threats and subjecting them to armed guard, subjected them to forced\nlabour, and physically and psychologically abused them”.202"},{"id":"a-hrc-52-crp-8-p0256","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"256","seq":259,"section":"B. Applicable Underlying Acts","text":"Enforced prostitution is the act of forcing a person to engage in one or more acts of a\nsexual nature with another person, with the intent to obtain pecuniary or other advantage.203\nThe language and drafting history204 indicates that the ‘other advantage’ obtained through\nenforced prostitution does not necessarily need to be received by the perpetrator; it can be\nreceived or meant to be received by the victim or a third person."},{"id":"a-hrc-52-crp-8-p0257","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"257","seq":260,"section":"B. Applicable Underlying Acts","text":"The crime of “any other forms of sexual violence” is a broad category meant to cover\nacts of sexual violence that do not necessarily correspond to the other enumerated crimes,\nbut that are so serious that they may equally constitute a crime against humanity. The conduct\nmust be of a gravity comparable to the other offences in Article 7(1)(g). Gravity factors\ninclude publicity of the act(s), multiple perpetrators, repetition of the act(s), particular\nvulnerability of the victim, use of weapon, and long-term consequences of the act.205 It can\nbe physical or non-physical.206 The threat or fear of rape in the context of detention can\nconstitute sexual violence,207 as can forced nudity208 and body searches."},{"id":"a-hrc-52-crp-8-p0258","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"258","seq":261,"section":"B. Applicable Underlying Acts","text":"For the crimes of rape, sexual slavery, and enforced prostitution, Article 7(1)(g) of the\nRome Statute does not set out specific requirements for mens rea and therefore, Article 30\napplies. For the crime of sexual violence to be established, the Elements of Crimes require\nthat the perpetrator be “aware of the factual circumstances that established the gravity of the\nconduct”.209\nf.     Enforced disappearance"},{"id":"a-hrc-52-crp-8-p0259","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"259","seq":262,"section":"B. Applicable Underlying Acts","text":"Enforced disappearance as a crime against humanity entails the arrest, detention or\nabduction of a person, accompanied by a refusal to acknowledge it or to give information on\nthe whereabouts of the person.210 The detention and refusal to give information must have\nbeen by or with the authorisation, support or acquiescence of a State or political organisation,\nand the perpetrator must have “intended to remove [the victim] from the protection of the\nlaw for a prolonged period of time”.211 However, the wording ‘prolonged’ is a normative\nlimitation acting as a jurisdictional threshold212 for the ICC that does not bind the Mission,\nthus enforced disappearances of any duration have been included in this report.213"},{"id":"a-hrc-52-crp-8-p0260","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"260","seq":263,"section":"B. Applicable Underlying Acts","text":"Secret detention, the refusal to provide information/provision of false\ninformation/intimidation of those requesting information, and the concealment of victims’\ncorpses in mass graves, prolonging their enforced disappearance, evidences an intention to\nremove the persons from the protection of the law.\ng.     Persecution"},{"id":"a-hrc-52-crp-8-p0261","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"261","seq":264,"section":"B. Applicable Underlying Acts","text":"The actus reus of persecution as a crime against humanity is the gross or blatant\ndenial, on discriminatory grounds, of a fundamental right, laid down in international\ncustomary or treaty law, reaching the same level of gravity as and committed in connection\nwith one or more underlying acts. The requisite mens rea is the specific intent to discriminate\nagainst the victims on account of their racial or religious characteristics or political affiliation\nas well as knowledge of the widespread or systematic nature of the attack on civilians.214 The\nmens rea for persecutions “is the specific intent to cause injury to a human being because he\nbelongs to a particular community or group”. There is no requirement in law that the\nperpetrator possesses a ‘persecutory intent’ over and above a discriminatory intent. 215"},{"id":"a-hrc-52-crp-8-p0262","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"262","seq":265,"section":"B. Applicable Underlying Acts","text":"The targeted group does not only comprise persons who personally carry the\n(religious, racial or political) criteria of the group. The targeted group must be interpreted\nbroadly and may include such persons who are defined by the perpetrator as belonging to the\nvictim group due to their close affiliations or sympathies for the victim group such that the\nvictims are discriminated in fact for who or what they are on the basis of the perception of\nthe perpetrator. 216 Discrimination on the basis of a person’s political ideology satisfies the\nrequirement of ‘political’ grounds. 217 The targeting of inhabitants of areas perceived as\nsupporting an opposing group has been held to be persecutory.218\nh.     Other inhumane acts"},{"id":"a-hrc-52-crp-8-p0263","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"263","seq":266,"section":"B. Applicable Underlying Acts","text":"Under Article 7(1)(k) of the ICC Statute, other inhumane acts are considered a residual\ncategory of crimes against humanity such that acts not encompassed by the underlying acts\nprescribed in Article 7(1)(a) - (j) may be characterised as other inhumane acts, provided they\nfulfil the criteria set out in the Elements of Crimes."},{"id":"a-hrc-52-crp-8-p0264","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"264","seq":267,"section":"B. Applicable Underlying Acts","text":"Conduct may be characterised as an inhumane act if the act or its effect caused great\nsuffering or serious injury.219 Factors to be considered include “the nature of the act or\nomission, the context in which it occurs, its duration and/or repetition, the physical, mental\nand moral effects of the act on the victim, as well as the personal circumstances of the victim,\nincluding age, sex, and health”.220 Secondly, the inhumane act must be “of a character similar\nto any other act referred to in Article 7, paragraph 1, of the Statute” and assessed in light of\nthe nature and gravity of the acts.221"},{"id":"a-hrc-52-crp-8-p0265","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"265","seq":268,"section":"B. Applicable Underlying Acts","text":"Other inhumane acts encompass serious violations of customary international law and\nof human rights. 222 In this regard, the ICTY stated that “parameters for the interpretation of\n‘other inhumane acts’ can be identified in international standards on human rights […] the\ninfringement of which may amount, depending on the accompanying circumstances, to a\ncrime against humanity”.223 The violation must be sufficiently severe to distinguish it from\nan isolated deprivation of rights.224 For example, forced nudity has been recognized as an\ninhumane act that can give rise to crimes against humanity225 as has sexual molestation.226\nThe acts that rise to the level of inhumane acts should be determined on a case-by-case\nbasis.227"},{"id":"a-hrc-52-crp-8-p0266","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"266","seq":269,"section":"B. Applicable Underlying Acts","text":"With regard to the mental element, Article 7(1)(k) of the Rome Statute does not set\nout specific requirements, and therefore, Article 30 applies. The Elements of Crimes add that\nthe perpetrator must have been ‘aware of the factual circumstances that established the\ncharacter of the act’ such that the perpetrator was aware that he/she was committing a severe\nviolation of human rights and/or customary international law"},{"id":"a-hrc-52-crp-8-p0267","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"267","seq":270,"section":"C. The mental element for crimes against humanity","text":"As the Elements of Crimes under the Rome Statute state, it is required that, “the\nperpetrator knew that the conduct was part of or intended the conduct to be part of a\nwidespread or systematic attack against a civilian population”. Therefore, the required nexus\nbetween the acts of an accused and the attack consists of two elements: (a) the commission\nof an act which, by its nature or consequences, is objectively part of the attack; and (b)\nknowledge on the part of the accused that there is an attack on the civilian population and\nthat their acts are part thereof228 or are intended to be a part thereof."},{"id":"a-hrc-52-crp-8-p0268","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"268","seq":271,"section":"C. The mental element for crimes against humanity","text":"In relation to (a), the acts need not be committed in the midst of the attack to be\nsufficiently connected to it. 229 An act therefore committed before or after the main attack\ncould still be considered to be part of it, provided that the act was not isolated from it. 230 Acts\nare considered part of the attack if the acts share common features, such as nature,\nconsequences, characteristics, and targets231 and are consistent with the general motives and\na modus operandi.232 The requirements in (b) are not such that proof is required that the\nperpetrator had knowledge of all the attack’s details or characteristics;233 it is sufficient that\nthe perpetrator knew of the overall context within which his or her acts took place,234 which\ncould be evidenced by, for example, the perpetrator’s participation in the attack235 or in the\npreparation of the attack.236\nII     Definition of war crimes"},{"id":"a-hrc-52-crp-8-p0269","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"269","seq":272,"section":"C. The mental element for crimes against humanity","text":"War crimes encompass any serious violation of international humanitarian law\ncommitted in the course of an international or non-international armed conflict, which entails\nthe individual criminal responsibility of the person breaching that law.237"},{"id":"a-hrc-52-crp-8-p0270","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"270","seq":273,"section":"C. The mental element for crimes against humanity","text":"Article 8(2)(c) of the ICC Statute defines war crimes in the case of an armed conflict\nnot of an international character as serious violations of Article 3 common to the four Geneva\nConventions of 12 August 1949, including murder, cruel treatment and torture committed\nagainst persons taking no active part in the hostilities, including members of armed forces\nwho have laid down their arms and those placed hors de combat.238"},{"id":"a-hrc-52-crp-8-p0271","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"271","seq":274,"section":"C. The mental element for crimes against humanity","text":"To establish whether a crime qualifies as a “war crime”, certain pre-conditions must\nbe met:\n(a)    The existence of an armed conflict (international or non-international); and\n(b)    A nexus between the alleged violation and the armed conflict."},{"id":"a-hrc-52-crp-8-p0272","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"272","seq":275,"section":"C. The mental element for crimes against humanity","text":"The classification of a situation of armed violence under international law is an\nobjective legal test. A non-international armed conflict exists “whenever there is protracted\narmed violence between governmental authorities and organized armed groups or between\nsuch groups within a State”.239 This definition encompasses two core, cumulative criteria,\nwhich distinguish a non-international armed conflict from internal tensions or disturbances:\n(i) the intensity of the armed violence and (ii) the level of organization of the armed group(s)\ninvolved. ICTY jurisprudence reflects several indicative factors 240 to assess whether these\ncriteria have been met.241"},{"id":"a-hrc-52-crp-8-p0273","rec_id":"recjWsYJzrxQZhNld","symbol":"A/HRC/52/CRP.8","n":"273","seq":276,"section":"C. The mental element for crimes against humanity","text":"The armed conflict need not have been causal to the commission of the crime charged\nbut must have played a substantial part in the perpetrator’s ability to commit that crime. It is\nnot required that the alleged crimes occur at a time and in a place where fighting is taking\nplace. Relevant factors include whether the perpetrator was a combatant, whether the victim\nwas a non-combatant, whether the victim was a member of the opposing party, and whether\nthe act may be said to have served the ultimate goal of a military campaign.242"}]});